        integer :: have_warm_distribution=0
        real(8) :: distance_smallest_house_size
        real(8) :: stopping_rule_smallest_house_size=10.d0**(-3) 

        ! ITS OWN CAP RATHER THAN THE GLOBAL TENTH OF A PER CENT. burden50 sat
