    subroutine load_smi_prevalence_profile()

        ! Read the NSDUH SMI prevalence profile, ages 26 to 85. Built by
        ! data/make_mh_onset.py, which is also what code/simple reads. The file
        ! carries the shape and an implied onset alongside; only the prevalence
        ! column is used here, because this file derives onset from the note's
        ! identity rather than from a shape/level split.

        use Global_Vars

        implicit none

        integer :: age_1,i_1,ios_1
        real(8) :: shape_1,implied_1,prev_1
        character(len=400) :: header_1
        logical :: file_exists_1

        ! This routine is called more than once per run, so the allocation is
        ! guarded and the file is read once. Allocating unconditionally aborted
        ! the run on the second call.
        if (allocated(smi_prevalence_by_age)) return

        allocate(smi_prevalence_by_age(life_span))
        allocate(smi_onset_by_age(life_span))
        allocate(smi_onset_shape_by_age(life_span))

        smi_prevalence_by_age=0
        smi_onset_by_age=0
        smi_onset_shape_by_age=0

        inquire(file="../data/us_mh_onset_shape.csv",exist=file_exists_1)

        if (.NOT. file_exists_1) then

            inquire(file="us_mh_onset_shape.csv",exist=file_exists_1)

            if (.NOT. file_exists_1) then

                write(*,*) "us_mh_onset_shape.csv not found. stopping."
                stop

            end if

            open(unit=75,file="us_mh_onset_shape.csv",action='read')

        else

            open(unit=75,file="../data/us_mh_onset_shape.csv",action='read')

        end if

            read(75,'(A)') header_1

            do i_1=1,life_span

                read(75,*,iostat=ios_1) age_1,shape_1,implied_1,prev_1

                if (ios_1/=0) then

                    prev_1=smi_prevalence_by_age(max(i_1-1,1))
                    shape_1=smi_onset_shape_by_age(max(i_1-1,1))

                end if

                smi_prevalence_by_age(i_1)=prev_1
                ! KEPT, not discarded. The profile is still read, because it is
                ! what the calibrated level is judged against.
                smi_onset_shape_by_age(i_1)=shape_1

            end do

        close(75)

        ! The floor, from the profile itself rather than a hardcoded guess.
        lambda_m_floor=0

        do i_1=1,life_span-1

            if (smi_prevalence_by_age(i_1)>10.d0**(-12)) then

                lambda_m_floor=max(lambda_m_floor,&
                    1.d0-smi_prevalence_by_age(i_1+1)/max(smi_prevalence_by_age(i_1),10.d0**(-14)))

            end if

        end do

        ! A small margin, so onset is strictly positive rather than exactly zero
        ! at the steepest age.
        lambda_m_floor=lambda_m_floor+10.d0**(-3)

        write(*,*) "SMI prevalence, first and last=", &
            smi_prevalence_by_age(1), smi_prevalence_by_age(life_span)
        write(*,*) "lambda_m floor implied by the profile=", lambda_m_floor

    end subroutine

    subroutine build_smi_onset()

        ! eq:fonsetage. Given the observed prevalence profile and the recovery
        ! hazard, this is the onset that reproduces the profile exactly:
        !
        !     onset(j) = [ p(j+1) - p(j)(1-lambda_m) ] / (1 - p(j))
        !
        ! Called from recompute_derived_parameters, because it depends on
        ! lambda_m and lambda_m is calibrated.
        !
        ! IT CAN GO NEGATIVE, and that is information rather than an error. A
        ! negative value means the observed profile falls faster than the
        ! recovery hazard alone can explain, so no non negative onset reproduces
        ! it at that lambda_m. It is clamped at zero and counted; a large count
        ! means lambda_m has been pushed too low for the data, and the
        ! calibration should not be reading a fit through it silently.

        use Global_Vars

        implicit none

        integer :: j_1,clipped_1
        real(8) :: p_now_1,p_next_1,onset_1

        clipped_1=0

        if (smi_onset_from_shape==1) then

            ! The assigned shape, scaled by the calibrated level. No identity, so
            ! no floor under lambda_m and no clipping: onset is positive wherever
            ! the shape is.
            smi_onset_by_age=min(max(smi_onset_level*smi_onset_shape_by_age,0.d0),1.d0)

            write(*,*) "build_smi_onset: shape x level. level=", smi_onset_level, &
                " onset(1)=", smi_onset_by_age(1), " onset(30)=", smi_onset_by_age(30), &
                " max=", maxval(smi_onset_by_age), " lambda_m=", lambda_m, &
                " implied ergodic prevalence=", &
                smi_onset_by_age(1)/max(smi_onset_by_age(1)+lambda_m,10.d0**(-12))

            return

        end if

        do j_1=1,life_span

            p_now_1=smi_prevalence_by_age(j_1)

            if (j_1<life_span) then

                p_next_1=smi_prevalence_by_age(j_1+1)

            else

                p_next_1=p_now_1

            end if

            if (p_now_1>=1.d0-10.d0**(-8)) then

                smi_onset_by_age(j_1)=0
                cycle

            end if

            onset_1=(p_next_1-p_now_1*(1-lambda_m))/(1-p_now_1)

            if (onset_1<0.d0) then

                onset_1=0
                clipped_1=clipped_1+1

            end if

            smi_onset_by_age(j_1)=min(onset_1,1.d0)

        end do

        if (clipped_1>0) then

            write(*,*) "build_smi_onset: onset clipped at zero for ", &
                clipped_1, " ages; lambda_m too low for the profile. lambda_m=", lambda_m

        end if

        write(*,*) "build_smi_onset: lambda_m=", lambda_m, " onset(1)=", smi_onset_by_age(1), &
            " onset(30)=", smi_onset_by_age(30), " max=", maxval(smi_onset_by_age), &
            " implied ergodic prevalence=", smi_onset_by_age(1)/max(smi_onset_by_age(1)+lambda_m,10.d0**(-12))

    end subroutine


    subroutine load_mortality_profiles()

        ! Read the CDC and Baggett profiles once. The file has a header and sixty
        ! rows, ages 26 to 85, and the last row's shape is nan because the
        ! difference that defines it has no next age; it is read as zero, which
        ! is right, since the SUD's excess mortality has gone by 85.
        !
        ! IDEMPOTENT, because it is now called from two places. It has to run
        ! before build_mortality_multipliers, which lives in
        ! initialize_variables_and_grids, and the original call sat in
        ! GKKOC_intergenerational_employment_process, which runs after it.

        use Global_Vars

        implicit none

        integer :: age_1,i_1,ios_1,hold_i_1
        real(8) :: shape_1,rr_1,d1_1,d2_1,d3_1
        character(len=400) :: header_1
        logical :: file_exists_1

        if (mortality_profiles_loaded==1) return

        inquire(file="../data/us_mortality_multipliers.csv",exist=file_exists_1)

        if (.NOT. file_exists_1) then

            inquire(file="us_mortality_multipliers.csv",exist=file_exists_1)

            if (.NOT. file_exists_1) then

                write(*,*) "us_mortality_multipliers.csv not found. stopping."
                stop

            end if

            open(unit=74,file="us_mortality_multipliers.csv",action='read')

        else

            open(unit=74,file="../data/us_mortality_multipliers.csv",action='read')

        end if

            read(74,'(A)') header_1

            hold_i_1=0

            do i_1=1,life_span

                read(74,*,iostat=ios_1) age_1,shape_1,rr_1,d1_1,d2_1,d3_1

                if (ios_1/=0) then

                    shape_1=0
                    rr_1=1

                end if

                if (shape_1/=shape_1) shape_1=0
                if (rr_1/=rr_1) rr_1=1

                ! THE SUD MULTIPLIER IS FLAT AT ITS LEVEL, NOT SHAPED BY
                ! OVERDOSE. shape_sud in the csv is r(a)/max(r) with
                !
                !     r(a) = overdose hazard given SUD / all cause baseline
                !
                ! and make_mortality_multipliers.py says in as many words that
                ! overdose is only ABOUT HALF of SUD excess mortality, the rest
                ! running through liver disease, endocarditis, hepatitis, HIV,
                ! suicide and accidents. Applying overdose's profile to the whole
                ! penalty imposes a collapse the other half does not have, and
                ! the denominator makes it worse: all cause baseline mortality
                ! explodes with age, so r(a) falls two orders of magnitude
                ! largely because of what is underneath it rather than because
                ! the disorder becomes safe.
                !
                ! What it produced: a multiplier of 1.07 at data age 75, a
                ! disorder that raises a seventy five year old's chance of dying
                ! by seven per cent, against published all cause SMRs for the
                ! disorder of six to ten. Every household in the model started
                ! using at data age 69, where the shape collapses, and the use
                ! rate went from zero to ninety nine per cent in three years.
                !
                ! Flat at the level puts the multiplier at the literature's own
                ! number at every age. rr_homeless is still read from the file
                ! and still age varying: it is measured directly by Baggett et
                ! al. and nothing here touches it.
                shape_sud_profile(i_1)=1.d0
                rr_homeless_profile(i_1)=max(rr_1,1.d0)

                ! The row whose age is the hold age, found by reading the age
                ! column rather than assuming the file starts at 26.
                if (age_1==rr_homeless_hold_age) hold_i_1=i_1

            end do

        close(74)

        ! HOLD THE RELATIVE RISK FLAT ABOVE THE HOLD AGE. See the declaration of
        ! rr_homeless_hold_age for why the tail it replaces is not a measurement.
        if ((rr_homeless_hold_age>0) .AND. (hold_i_1>0) .AND. &
            (hold_i_1<life_span)) then

            do i_1=hold_i_1+1,life_span

                if (rr_homeless_old_level>0.d0) then

                    rr_homeless_profile(i_1)=rr_homeless_old_level

                else

                    rr_homeless_profile(i_1)=rr_homeless_profile(hold_i_1)

                end if

            end do

            write(*,*) "rr_homeless above data age", rr_homeless_hold_age, &
                "set to", rr_homeless_profile(life_span), &
                " (calibrated=", rr_homeless_old_level, ")"

        else if (rr_homeless_hold_age>0) then

            write(*,*) "rr_homeless_hold_age", rr_homeless_hold_age, &
                "is not an age in the file; profile left as read"

        end if

        mortality_profiles_loaded=1

        write(*,*) "mortality profiles loaded, shape_sud(1)=", shape_sud_profile(1), &
            " rr_homeless(1)=", rr_homeless_profile(1)

    end subroutine

    subroutine build_mortality_multipliers()

        ! Equation (25). Called whenever the level moves.

        use Global_Vars

        implicit none

        integer :: j_1

        do j_1=1,life_span

            kappa_phi_d_by_age(j_1)=1+(kappa_phi_d_level-1)*shape_sud_profile(j_1)

            ! THE EXCESS DEATH RISK FROM THE STREET IS FLAT IN AGE, on the
            ! author's instruction of 31 August. Not the MULTIPLIER, which is a
            ! different thing and the wrong one.
            !
            ! The multiplier route -- Baggett's ratios, or the flat 1.6 the
            ! note's external calibration table quotes from Meyer, Wyse and
            ! Logani -- makes the excess ANNUAL DEATH PROBABILITY proportional
            ! to baseline mortality, and baseline mortality rises elevenfold
            ! between 26 and 65. Measured on this life table, the excess risk
            ! from sleeping rough runs 1.00, 2.19 and 4.84 across 26, 45 and 65
            ! under Baggett, and 1.00, 2.62 and 11.34 under a flat 1.6. Since
            ! ninety four per cent of this model's homeless could afford rent
            ! and are CHOOSING the street, that gradient is the deterrent they
            ! choose against, and it is why the model puts ninety eight per cent
            ! of its homeless under 35 against twenty six in the HUD count.
            !
            ! Holding the excess RISK flat instead makes the multiplier fall
            ! with age -- 4.41 at 26 to 1.30 at 65 -- which is the only one of
            ! the three specifications that is age neutral in the thing the
            ! household actually trades off.
            if (homeless_death_risk_flat_in_age==1) then

                kappa_phi_h_by_age(j_1)=max(1.d0,1.d0+homeless_excess_death_risk/&
                    max(1.d0-actual_survival_probability(j_1),10.d0**(-12)))

            elseif (homeless_death_risk_flat_in_age==2) then

                ! THE NOTE'S OWN CALIBRATION: a flat MULTIPLIER of 1.6 from
                ! Meyer, Wyse and Logani, which is what external_calibration.tex
                ! says and what increased_risk_of_death_homeless already holds.
                ! Kept as a setting rather than argued about, because whether it
                ! shifts the age profile older or younger is a general
                ! equilibrium question and not an arithmetic one.
                kappa_phi_h_by_age(j_1)=1.d0+increased_risk_of_death_homeless

            else

                kappa_phi_h_by_age(j_1)=max(1.d0,rr_homeless_profile(j_1)/&
                    ((1-sud_share_of_homeless)+sud_share_of_homeless*kappa_phi_d_by_age(j_1)))

            end if

        end do

    end subroutine

    subroutine set_child_penalty_factors()

        ! THE FOUR CHILD CLASSES' PRODUCTIVITY FACTORS, in one place because
        ! two routines need them at different moments: the grid construction,
        ! which runs BEFORE recompute_derived_parameters and would otherwise
        ! build the blocks at the declaration value of one, and
        ! recompute_derived_parameters itself, which is what picks up a
        ! calibration step in either penalty.
        !
        ! Same two penalties and the same include_child_penalty switch the birth
        ! shift used, so at include_child_penalty = 0 every factor is one and the
        ! four classes are four identical copies of one economy. That is the
        ! replication null this construction is checked against.

        use Global_Vars

        implicit none

        child_penalty_factor(0)=1.d0
        child_penalty_factor(1)=(1.d0-penalty_child_addicted)**include_child_penalty
        child_penalty_factor(2)=(1.d0-penalty_child_homeless)**include_child_penalty
        child_penalty_factor(3)=child_penalty_factor(1)*child_penalty_factor(2)

    end subroutine

    subroutine recompute_derived_parameters()

        ! EVERY QUANTITY DERIVED FROM A CALIBRATED ONE, REBUILT IN ONE PLACE.
        !
        ! Eleven parameters the note calls calibrated were compile time
        ! constants. Freeing them is only half the job: a dozen more quantities
        ! were initialised FROM them in their declarations, which in Fortran
        ! happens once, so a freed parameter would move and everything computed
        ! from it would silently keep the starting value.
        !
        ! So the derived ones now start at zero and are built here, and this is
        ! called at initialisation and again after every calibration update.
        ! Anything derived from a calibrated parameter belongs in this routine
        ! and nowhere else.

        use Global_Vars

        implicit none

        ! The Cobb-Douglas weights. With change_utility_for_addicts and
        ! size_of_penalty both zero the disorder does not move them, so the two
        ! versions agree, which optimize_frac_spent_on_addiciton checks.
        relative_share_of_addiction_2=&
            change_utility_for_addicts*((1-perceived_probability_lower)*0.45+&
            perceived_probability_lower*0.44)+&
            (1-change_utility_for_addicts)*&
            (size_of_penalty*((0.39-relative_share_of_addiction_1))+relative_share_of_addiction_1)

        relative_share_of_addiction=relative_share_of_addiction_1

        call set_child_penalty_factors()

        ! GAMMA IS THE HOUSING WEIGHT AND HAS TO BE THE ONE THE UTILITY READS.
        ! These four lines built the weights from relative_share_of_housing_0, a
        ! PARAMETER fixed at 0.278, while the sweep calibrated
        ! relative_share_of_housing against the rent to income share. So the
        ! instrument could not move its own moment: gamma ran to its floor of
        ! 0.01 and the moment sat at 0.52 against a target of 0.268 for the whole
        ! run, and gamma's only remaining effect was as (1-gamma) on the
        ! consumption term of the executed branch.
        !
        ! It is a wiring error and not a modelling choice. The note defines gamma
        ! as the Cobb-Douglas share of the bundle that goes on housing, targeted
        ! at 26.8 per cent of expenditure net of drugs from the 2024 CEX, which is
        ! exactly housing_share_of_expenditure_data. Same object, same target; the utility
        ! was simply reading a different variable.
        !
        ! The nesting is unchanged, so the weights still sum to one: within the
        ! non-drug bundle gamma goes to housing and 1-gamma to consumption, and
        ! the bundle itself carries 1-theta.
        relative_share_of_housing_1=relative_share_of_housing*(1-relative_share_of_addiction_1)
        relative_share_of_housing_2=relative_share_of_housing*(1-relative_share_of_addiction_2)

        relative_share_of_consumption_1=(1-relative_share_of_housing)*(1-relative_share_of_addiction_1)
        relative_share_of_consumption_2=(1-relative_share_of_housing)*(1-relative_share_of_addiction_2)

        ! The Stone-Geary shifter. b is constant across every state and choice,
        ! so b_sud_ratio is one and the two are the same number; the line is kept
        ! so a robustness run can separate them in one place.
        addiction_scalar_2=b_sud_ratio*addiction_scalar_1

        ! PREFERENCES ARE THE SAME IN BOTH STATES, AND THIS CHECKS IT RATHER
        ! THAN ASSUMING IT. The _1 and _2 weights exist so that a robustness run
        ! can let the disorder move tastes, which an earlier version of this
        ! programme did. The benchmark does not: change_utility_for_addicts and
        ! size_of_penalty are both parameters fixed at zero, so the algebra above
        ! collapses _2 onto _1 and the housing and consumption weights follow,
        ! and b_sud_ratio is one so the Stone-Geary shifter does too.
        !
        ! That is an argument about four compile-time constants, and it is the
        ! kind of argument that stops being true without anyone noticing. The
        ! shares enter the addicted state's utility directly, so a divergence
        ! would not crash and would not look wrong in any moment -- it would
        ! quietly make the disordered a different kind of household, which is a
        ! claim the note does not make. This routine runs at initialisation and
        ! after every calibration update, so checking here checks every solve.
        if (abs(relative_share_of_addiction_2-relative_share_of_addiction_1)>10.d0**(-12) .OR. &
            abs(relative_share_of_housing_2-relative_share_of_housing_1)>10.d0**(-12) .OR. &
            abs(relative_share_of_consumption_2-relative_share_of_consumption_1)>10.d0**(-12) .OR. &
            abs(addiction_scalar_2-addiction_scalar_1)>10.d0**(-12)) then

            write(*,*) "PREFERENCES DIFFER ACROSS STATES, which the benchmark does not allow."
            write(*,*) "   addiction   _1=", relative_share_of_addiction_1,&
                " _2=", relative_share_of_addiction_2
            write(*,*) "   housing     _1=", relative_share_of_housing_1,&
                " _2=", relative_share_of_housing_2
            write(*,*) "   consumption _1=", relative_share_of_consumption_1,&
                " _2=", relative_share_of_consumption_2
            write(*,*) "   scalar      _1=", addiction_scalar_1,&
                " _2=", addiction_scalar_2
            write(*,*) "   change_utility_for_addicts=", change_utility_for_addicts,&
                " size_of_penalty=", size_of_penalty, " b_sud_ratio=", b_sud_ratio
            stop

        end if

        ! The SMI onset profile. Depends on lambda_m, which is calibrated, so it
        ! is rebuilt here rather than once at startup.
        if (allocated(smi_onset_by_age)) then

            call build_smi_onset()

        end if

        ! Recovery on the street, as a multiple of recovery while housed.
        probability_of_stopping_addiction_if_homeless=&
            mu_homeless*probability_of_stopping_addiction

        ! The employment margins with the disorder.
        probability_becoming_unemployed_if_addicted=&
            max(min(probability_becoming_unemployed*&
            multiple_of_probabilities_of_employment_if_addicted,1.d0),0.d0)

        probability_becoming_employed_if_addicted=&
            max(min(probability_becoming_employed/&
            multiple_find_if_addicted,1.d0),0.d0)

        ! Mortality with both. The note multiplies the two hazards; the code used
        ! to add the two excesses, which is not the same thing once either is
        ! large. See the age varying block for the rest of that repair.
        increased_risk_of_death_homeless_addicted=&
            (1+increased_risk_of_death_homeless)*(1+increased_risk_of_death_addicted)-1

        ! The voucher lottery.
        probability_of_voucher_benchmark_used_1=probability_of_voucher_benchmark_used

        probability_of_voucher_benchmark=&
            (1-perceived_probability_lower)*&
            (/real(probability_of_voucher_benchmark_used,8),&
            min(real(probability_of_voucher_benchmark_used*increased_prob_of_voucher_if_homeless,8),1.d0),&
            min(real(probability_of_voucher_benchmark_used*&
            increased_prob_of_voucher_if_homeless_and_addicted,8),1.d0)/)+&
            perceived_probability_lower*probability_of_voucher_benchmark_used*&
            (/real(probability_of_voucher_benchmark_used,8),&
            min(real(probability_of_voucher_benchmark_used*increased_prob_of_voucher_if_homeless,8),1.d0),&
            min(real(probability_of_voucher_benchmark_used*&
            increased_prob_of_voucher_if_homeless_and_addicted,8),1.d0)/)

        probability_of_voucher=probability_of_voucher_benchmark

    end subroutine

    subroutine clear_drug_market(time_period)

        ! See the block at drug_supply_elasticity for what this is and why the
        ! benchmark normalises while the counterfactuals clear.

        use Global_Vars

        implicit none

        integer, intent(in) :: time_period
        real(8) :: quantity_1,implied_price_1,gap_1,step_1
        logical :: shifter_exists_1

        ! Partial equilibrium holds prices fixed by definition, and the
        ! elasticity test perturbs this price on purpose, so neither may have it
        ! moved underneath them.
        if ((include_addiction==0) .OR. (partial_equilibrium==1) .OR. &
            (test_elasticity==1)) then

            distance_drug_market=0

            return

        end if

        quantity_1=model_drugs_consumed_by_users(time_period)

        if (quantity_1<=0) then

            write(*,*) "no drug use at all, the drug market is left alone"
            distance_drug_market=0

            return

        end if

        if (is_counterfactual==0) then

            ! Normalise: pick the shifter that puts the price at one here.
            drug_supply_shifter=1/(quantity_1**(drug_supply_curvature-1))

            price_of_addictive_good=price_of_addictive_good_benchmark
            distance_drug_market=0

            open(unit=73,file="drug_supply_shifter"//trim(benchmark_simulation)//".dat",&
                action='write',status='replace')
                write(73,'(F35.20)') drug_supply_shifter
            close(73)

            write(*,*) "drug quantity V=", quantity_1
            write(*,*) "drug_supply_shifter (normalised)=", drug_supply_shifter

        else

            inquire(file="drug_supply_shifter"//trim(benchmark_simulation)//".dat",&
                exist=shifter_exists_1)

            if (shifter_exists_1) then

                open(unit=73,file="drug_supply_shifter"//trim(benchmark_simulation)//".dat",&
                    action='read')
                    read(73,'(F35.20)') drug_supply_shifter
                close(73)

            else

                write(*,*) "no drug_supply_shifter from the benchmark. stopping."
                stop

            end if

            implied_price_1=drug_supply_shifter*(quantity_1**(drug_supply_curvature-1))

            gap_1=implied_price_1-price_of_addictive_good

            distance_drug_market=abs(gap_1)

            ! Secant where two usable points exist, damped step otherwise. The
            ! supply price rises in quantity and demand falls in price, so the
            ! gap is monotone in the price and the secant is well behaved; the
            ! clip is there for the first loops, before it is.
            step_1=price_of_addictive_good+drug_market_adjuster*gap_1

            if ((have_drug_price_secant==1) .AND. &
                (abs(gap_1-previous_drug_price_gap)>10.d0**(-10)) .AND. &
                (abs(price_of_addictive_good-previous_price_of_addictive_good)>10.d0**(-10))) then

                step_1=price_of_addictive_good-gap_1*&
                    (price_of_addictive_good-previous_price_of_addictive_good)/&
                    (gap_1-previous_drug_price_gap)

            end if

            ! THE SECANT DIVERGED ON UNIVERSAL TREATMENT FIRST, so it is now
            ! kept inside a trust region around the damped step and abandoned
            ! outright when the gap grew.
            !
            ! WHAT HAPPENED. universal_tf ran 47 loops without converging. The
            ! budget cleared at loop 37 and held, and the drug price then
            ! oscillated between 1.02 and 1.20 with distance_drug_market going
            ! 0.0198 at loop 32, 0.165, 0.346, 0.520 -- growing, not shrinking,
            ! and with no iteration cap on the loop above it would have run
            ! indefinitely. The other two arms converged cleanly at 7.1e-4 and
            ! 5.4e-4, so the tolerance is reachable and this was the iteration.
            !
            ! WHY THAT ARM. It is the only one carrying the full feedback loop: a
            ! household's drug choice sets its voucher status, which moves its
            ! income, which moves the budget and the price, which moves the drug
            ! choice. tf_rationed has the same loop on a far smaller eligible
            ! base and universal_hf has no condition at all. A secant amplifies
            ! when the gap it differences is noisy, and the quantity feeding it
            ! comes from a distribution solved only to 6e-4 with addiction on --
            ! so the secant was extrapolating off numerical noise.
            !
            ! TWO GUARDS, both cheap. If the gap grew, the previous step was
            ! wrong and its secant is worthless: take the damped step. And a
            ! secant step is never allowed further from the current price than
            ! four damped steps, which leaves the fast convergence the other
            ! arms got and removes the excursions.
            !
            ! THIS CHANGES NO EQUILIBRIUM CONDITION. The fixed point is still
            ! implied_price == price_faced to within stopping_rule_drug_market;
            ! only the path to it changes.
            if (have_drug_price_secant==1) then

                if (abs(gap_1)>abs(previous_drug_price_gap)) then

                    step_1=price_of_addictive_good+drug_market_adjuster*gap_1

                else

                    step_1=max(min(step_1,&
                        price_of_addictive_good+4*abs(drug_market_adjuster*gap_1)),&
                        price_of_addictive_good-4*abs(drug_market_adjuster*gap_1))

                end if

            end if

            ! AND A HARD CAP OF HALF A PER CENT A LOOP, on the author's
            ! instruction of 8 September: *"You might need to update the price
            ! more slowly. Like 0.5% at most"*.
            !
            ! The clamp this replaces allowed the price to DOUBLE or halve in one
            ! step, and the trust region above still allowed four damped steps --
            ! about twenty per cent at the gaps universal_tf was seeing. A cap
            ! this tight cannot oscillate: the price is a bounded monotone walk
            ! toward the supply curve, and the direction is all the secant is
            ! being trusted for.
            !
            ! IT COSTS LOOPS, and that is the trade. universal_tf's price sat
            ! near 1.10, so reaching it from 1.00 takes about twenty passes at
            ! this rate. The arms already run twenty-three to forty-five loops
            ! with the budget as the slow condition, so the price is unlikely to
            ! become the binding one -- but if a later arm exits on loop count
            ! rather than on the price having settled, this is the line to look
            ! at first.
            step_1=max(min(step_1,price_of_addictive_good*(1+max_drug_price_move)),&
                price_of_addictive_good*(1-max_drug_price_move))

            previous_price_of_addictive_good=price_of_addictive_good
            previous_drug_price_gap=gap_1
            have_drug_price_secant=1

            price_of_addictive_good=max(step_1,10.d0**(-6))

            write(*,*) "drug quantity V=", quantity_1
            write(*,*) "implied supply price=", implied_price_1
            write(*,*) "price_of_addictive_good=", price_of_addictive_good
            write(*,*) "distance_drug_market=", distance_drug_market

        end if

    end subroutine


    ! A NAMED RESUME SEED, WRITTEN BESIDE THE POSITIONAL STATE FILE.
    !
    ! WHY THIS EXISTS. calibration_state.dat is written POSITIONALLY and does
    ! not carry every calibrated parameter. A resume therefore silently leaves
    ! the missing ones at their compile-time defaults, and the run continues
    ! against a model nobody chose. On 16 September that reset
    ! multiple_find_if_addicted from 3.5264 to its floor of 1.0 and put the run
    ! in the 95-per-cent-participation corner within one block; kappa_find_smi
    ! was reset from 7.96 to 1.0 the same way, and three further runs tipped
    ! before the cause was found. Nothing in the log says a parameter was not
    ! restored, which is what makes it expensive: the run looks fine and is not.
    !
    ! WHAT THIS DOES. Every parameter that has a PARAM_HANDOVER case -- 78 real
    ! scalars -- is written by NAME on each save. Because the handover is
    ! applied AFTER the state file is read, copying resume_seed.txt to
    ! PARAM_HANDOVER.txt makes a resume exact regardless of what the positional
    ! file does or does not carry.
    !
    ! It is deliberately a SUPERSET of what the state file holds. Writing a
    ! parameter twice is harmless; omitting one is what caused the bug.
    subroutine write_resume_seed()

        use Global_Vars

        implicit none

        open(unit=81,file="resume_seed.tmp",action='write',status='replace')

        write(81,'(A,1X,ES24.16)') "addiction_onset_base", addiction_onset_base
        write(81,'(A,1X,ES24.16)') "addiction_scalar_1", addiction_scalar_1
        write(81,'(A,1X,ES24.16)') "addiction_scalar_max_rel_step", addiction_scalar_max_rel_step
        write(81,'(A,1X,ES24.16)') "bottom_productivity_level", bottom_productivity_level
        write(81,'(A,1X,ES24.16)') "consumption_penalty_homeless", consumption_penalty_homeless
        write(81,'(A,1X,ES24.16)') "cost_per_drug_test", cost_per_drug_test
        write(81,'(A,1X,ES24.16)') "discount_factor", discount_factor
        write(81,'(A,1X,ES24.16)') "discount_factor_impatient", discount_factor_impatient
        write(81,'(A,1X,ES24.16)') "drug_supply_elasticity", drug_supply_elasticity
        write(81,'(A,1X,ES24.16)') "extra_job_loss_if_homeless", extra_job_loss_if_homeless
        write(81,'(A,1X,ES24.16)') "financial_grid_expander_negative", financial_grid_expander_negative
        write(81,'(A,1X,ES24.16)') "financial_grid_expander_positive", financial_grid_expander_positive
        write(81,'(A,1X,ES24.16)') "h1_share_of_h2", h1_share_of_h2
        write(81,'(A,1X,ES24.16)') "homeless_excess_death_risk", homeless_excess_death_risk
        write(81,'(A,1X,ES24.16)') "homeless_job_penalty_pp", homeless_job_penalty_pp
        write(81,'(A,1X,ES24.16)') "housing_status_grid_expander", housing_status_grid_expander
        write(81,'(A,1X,ES24.16)') "increased_prob_if_homeless", increased_prob_if_homeless
        write(81,'(A,1X,ES24.16)') "increased_prob_of_voucher_if_homeless_and_addicted", increased_prob_of_voucher_if_homeless_and_addicted
        write(81,'(A,1X,ES24.16)') "kappa_find_smi", kappa_find_smi
        write(81,'(A,1X,ES24.16)') "kappa_phi_d_level", kappa_phi_d_level
        write(81,'(A,1X,ES24.16)') "kappa_phi_d_max_rel_step", kappa_phi_d_max_rel_step
        write(81,'(A,1X,ES24.16)') "kappa_uem", kappa_uem
        write(81,'(A,1X,ES24.16)') "kappa_x", kappa_x
        write(81,'(A,1X,ES24.16)') "kkk_s_deviation_bottom", kkk_s_deviation_bottom
        write(81,'(A,1X,ES24.16)') "kkk_s_deviation_top", kkk_s_deviation_top
        write(81,'(A,1X,ES24.16)') "kkk_sigma_scale", kkk_sigma_scale
        write(81,'(A,1X,ES24.16)') "labor_income_tax_rate", labor_income_tax_rate
        write(81,'(A,1X,ES24.16)') "lambda_addiction", lambda_addiction
        write(81,'(A,1X,ES24.16)') "lambda_m", lambda_m
        write(81,'(A,1X,ES24.16)') "largest_house_size", largest_house_size
        write(81,'(A,1X,ES24.16)') "max_food_cost", max_food_cost
        write(81,'(A,1X,ES24.16)') "max_rel_step_all", max_rel_step_all
        write(81,'(A,1X,ES24.16)') "max_ui_as_perc_of_avg_inc", max_ui_as_perc_of_avg_inc
        write(81,'(A,1X,ES24.16)') "merge_bottom_nodes", merge_bottom_nodes
        write(81,'(A,1X,ES24.16)') "merge_from_node", merge_from_node
        write(81,'(A,1X,ES24.16)') "money_cost_of_treatment", money_cost_of_treatment
        write(81,'(A,1X,ES24.16)') "mu_homeless", mu_homeless
        write(81,'(A,1X,ES24.16)') "multiple_find_if_addicted", multiple_find_if_addicted
        write(81,'(A,1X,ES24.16)') "multiple_of_probabilities_of_employment_if_addicted", multiple_of_probabilities_of_employment_if_addicted
        write(81,'(A,1X,ES24.16)') "newborn_endowment_scale", newborn_endowment_scale
        write(81,'(A,1X,ES24.16)') "omega_max_rel_step", omega_max_rel_step
        write(81,'(A,1X,ES24.16)') "penalty_child_addicted", penalty_child_addicted
        write(81,'(A,1X,ES24.16)') "penalty_child_homeless", penalty_child_homeless
        write(81,'(A,1X,ES24.16)') "persistence_employment_surviving", persistence_employment_surviving
        write(81,'(A,1X,ES24.16)') "persistence_fixed_employment_newborn", persistence_fixed_employment_newborn
        write(81,'(A,1X,ES24.16)') "probability_becoming_unemployed", probability_becoming_unemployed
        write(81,'(A,1X,ES24.16)') "probability_of_detection", probability_of_detection
        write(81,'(A,1X,ES24.16)') "probability_of_false_positive", probability_of_false_positive
        write(81,'(A,1X,ES24.16)') "probability_of_stopping_addiction", probability_of_stopping_addiction
        write(81,'(A,1X,ES24.16)') "probability_of_voucher_benchmark_used", probability_of_voucher_benchmark_used
        write(81,'(A,1X,ES24.16)') "relative_share_of_addiction_1", relative_share_of_addiction_1
        write(81,'(A,1X,ES24.16)') "relative_share_of_housing", relative_share_of_housing
        write(81,'(A,1X,ES24.16)') "relative_share_of_leisure", relative_share_of_leisure
        write(81,'(A,1X,ES24.16)') "replacement_rate_ui", replacement_rate_ui
        write(81,'(A,1X,ES24.16)') "rho_d", rho_d
        write(81,'(A,1X,ES24.16)') "rho_intergenerational", rho_intergenerational
        write(81,'(A,1X,ES24.16)') "rho_intergenerational_adjuster", rho_intergenerational_adjuster
        write(81,'(A,1X,ES24.16)') "rho_m", rho_m
        write(81,'(A,1X,ES24.16)') "rho_productivity", rho_productivity
        write(81,'(A,1X,ES24.16)') "rr_homeless_old_level", rr_homeless_old_level
        write(81,'(A,1X,ES24.16)') "rung_ratio_h3", rung_ratio_h3
        write(81,'(A,1X,ES24.16)') "rung_ratio_h4", rung_ratio_h4
        write(81,'(A,1X,ES24.16)') "sd_employment_surviving", sd_employment_surviving
        write(81,'(A,1X,ES24.16)') "sd_fixed_employment_newborn", sd_fixed_employment_newborn
        write(81,'(A,1X,ES24.16)') "sd_permanent_productivity", sd_permanent_productivity
        write(81,'(A,1X,ES24.16)') "size_homelessness", size_homelessness
        write(81,'(A,1X,ES24.16)') "smallest_house_size_adjuster", smallest_house_size_adjuster
        write(81,'(A,1X,ES24.16)') "smallest_rental_relative_to_lowest_income", smallest_rental_relative_to_lowest_income
        write(81,'(A,1X,ES24.16)') "smi_onset_level", smi_onset_level
        write(81,'(A,1X,ES24.16)') "ssi_floor_level", ssi_floor_level
        write(81,'(A,1X,ES24.16)') "ssi_floor_takeup", ssi_floor_takeup
        write(81,'(A,1X,ES24.16)') "theta_max_rel_step", theta_max_rel_step
        write(81,'(A,1X,ES24.16)') "unsecured_borrowing_limit", unsecured_borrowing_limit
        write(81,'(A,1X,ES24.16)') "unsecured_borrowing_rate", unsecured_borrowing_rate
        write(81,'(A,1X,ES24.16)') "utility_cost_of_treatment", utility_cost_of_treatment
        write(81,'(A,1X,ES24.16)') "value_of_life", value_of_life
        write(81,'(A,1X,ES24.16)') "weight_on_child", weight_on_child
        write(81,'(A,1X,ES24.16)') "y_grid_kappa", y_grid_kappa


        ! THE SWITCHES TOO, AND LEAVING THEM OUT WAS THE SAME BUG AGAIN.
        ! When this routine was written on 16 September it emitted only real(8)
        ! scalars, on the reasoning that integer switches do not change during a
        ! calibration. They do not -- but they are not at their SOURCE DEFAULTS
        ! either, and the hand-written seed had been setting them. Dropping them
        ! let use_pia_formula, restrict_borrowing_to_impatient,
        ! number_of_beta_types and ten others fall back to defaults, and n14 ran
        ! a different model: wealth over output read 0.711 at block 1 where the
        ! two runs before it read 3.661 from an identical cold start.
        ! The author spotted it -- "How can beta go so low all of a sudden??" --
        ! after I had twice explained it away as a cold-start transient.
        !
        ! A RESUME SEED IS ONLY SAFE IF IT IS COMPLETE. That is the whole point of
        ! the routine, and a filter on declared type is exactly the kind of
        ! plausible narrowing that reopens the hole.
        write(81,'(A,1X,ES24.16)') "adjust_taxes", dble(adjust_taxes)
        write(81,'(A,1X,ES24.16)') "child_penalty_off", dble(child_penalty_off)
        write(81,'(A,1X,ES24.16)') "endowment_is_a_transfer", dble(endowment_is_a_transfer)
        write(81,'(A,1X,ES24.16)') "fixed_productivity", dble(fixed_productivity)
        write(81,'(A,1X,ES24.16)') "freeze_updates_after_loop", dble(freeze_updates_after_loop)
        write(81,'(A,1X,ES24.16)') "homeless_death_risk_flat_in_age", dble(homeless_death_risk_flat_in_age)
        write(81,'(A,1X,ES24.16)') "include_unsecured_borrowing", dble(include_unsecured_borrowing)
        write(81,'(A,1X,ES24.16)') "include_voucher_exclusion", dble(include_voucher_exclusion)
        write(81,'(A,1X,ES24.16)') "max_age_to_choose_homelessness", dble(max_age_to_choose_homelessness)
        write(81,'(A,1X,ES24.16)') "measure_child_gap", dble(measure_child_gap)
        write(81,'(A,1X,ES24.16)') "number_of_beta_types", dble(number_of_beta_types)
        write(81,'(A,1X,ES24.16)') "persistent_income_risk", dble(persistent_income_risk)
        write(81,'(A,1X,ES24.16)') "restrict_borrowing_to_impatient", dble(restrict_borrowing_to_impatient)
        write(81,'(A,1X,ES24.16)') "rr_homeless_hold_age", dble(rr_homeless_hold_age)
        write(81,'(A,1X,ES24.16)') "use_pia_formula", dble(use_pia_formula)
        write(81,'(A,1X,ES24.16)') "use_unemployment_by_productivity", dble(use_unemployment_by_productivity)
        write(81,'(A,1X,ES24.16)') "voucher_conditional_on_clean", dble(voucher_conditional_on_clean)
        write(81,'(A,1X,ES24.16)') "voucher_conditional_on_clean_just_addicts", dble(voucher_conditional_on_clean_just_addicts)

        close(81)

        call rename("resume_seed.tmp","resume_seed.dat")

    end subroutine

    subroutine write_calibration_state()

        ! RESUMING AFTER A KILL. A calibration is days of wall clock and it used
        ! to lose all of it on a kill: the only memory of where the bisection had
        ! got to was three starting values edited into the declarations by hand,
        ! so a restart went back to whatever they last happened to say.
        !
        ! Every loop now writes the parameters the update block moves, together
        ! with the prices and the damping state, so a restart picks up where the
        ! last completed loop left off. The damping state matters as much as the
        ! parameters: drop it and a resumed run rings again from a full step, and
        ! the loops spent settling the first time are spent again.
        !
        ! Written to a temporary and renamed, because a kill during the write is
        ! the one moment when this file is being touched and a half written file
        ! that parses is worse than no file at all.
        !
        ! V3 ADDS EVERYTHING ELSE THE UPDATE BLOCK MOVES, which was most of it.
        ! v2 saved thirty eight items and the update block moves sixty. Among the
        ! twenty two missing were b, aleph, cbar, pi_V, theta, sigma_y, omega,
        ! delta_d, mu_homeless, the separation rate and the employment multiplier,
        ! together with the damping and bracket state of beta, delta_d, b and
        ! size_homelessness.
        !
        ! This is not a small loss on a restart, it is a WORSE state than a cold
        ! start. Measured: a resume put lambda back at 1.7585, where six loops had
        ! left it, and b back at its declared 0.2537, where loop zero had left it.
        ! Those two are calibrated against each other, so the model came back with
        ! a hazard tuned for a population that b no longer produces, and
        ! participation jumped from 0.0044 to 0.117 against a target of 0.0513.
        ! The container kills this run about every fifty minutes and a loop takes
        ! fifteen, so without this the sweep cannot accumulate three loops of
        ! progress before losing most of it again.
        !
        ! Deliberately NOT saved: rental_market_adjuster, which is set before it
        ! is read, and the three previous_* convergence checks, which only make
        ! the first resumed loop report a large distance against its own last
        ! value. Saving something set before use is how a resume starts differing
        ! from a run that was never killed.
        !
        ! V2 ADDED THE FOUR SMI PARAMETERS. They were wired into the update block
        ! and not into this file, so a resumed run picked the housing and drug
        ! parameters up where they left off and sent lambda_m, kappa_uem, rho_m
        ! and rho_d back to their declared values. That is worse than not
        ! resuming at all: the parameters that resume are the ones the SMI
        ! parameters have to be consistent with. The version tag is bumped so a
        ! v1 file is ignored rather than read short and misaligned.

        use Global_Vars

        implicit none

        open(unit=71,file="calibration_state.tmp",action='write',status='replace')

            write(71,'(A)') "calibration_state_v3"
            write(71,'(F30.15)') discount_factor
            write(71,'(F30.15)') discount_factor_on_child
            write(71,'(F30.15)') minimum_inheritance
            write(71,'(F30.15)') advantage_to_owning
            write(71,'(F30.15)') relative_share_of_housing
            write(71,'(F30.15)') relative_share_of_leisure
            write(71,'(F30.15)') largest_house_size
            write(71,'(F30.15)') smallest_rental_relative_to_lowest_income
            write(71,'(F30.15)') labor_income_tax_rate
            write(71,'(F30.15)') standard_deduction_as_percent_of_average_labor_income
            write(71,'(F30.15)') probability_of_becoming_addicted_if_experiment
            write(71,'(F30.15)') lambda_addiction
            write(71,'(F30.15)') price_of_addictive_good
            write(71,'(F30.15)') drug_supply_shifter
            write(71,'(F30.15)') utility_cost_of_treatment
            write(71,'(F30.15)') previous_utility_cost_of_treatment
            write(71,'(F30.15)') previous_treatment_take_up
            write(71,'(I10)') have_treatment_secant
            write(71,'(F30.15)') previous_onset_at_mean
            write(71,'(F30.15)') previous_sud_rate
            write(71,'(I10)') have_lambda_secant
            write(71,'(F30.15)') size_homelessness
            write(71,'(F30.15)') fixed_cost_to_moving
            write(71,'(F30.15)') housing_status_grid_expander
            write(71,'(F30.15)') smallest_house_size_adjuster
            write(71,'(F30.15)') largest_house_size_adjuster
            write(71,'(F30.15)') previous_gap_smallest_house_size
            write(71,'(F30.15)') previous_gap_largest_house_size
            write(71,'(I10)') have_gap_smallest_house_size
            write(71,'(I10)') have_gap_largest_house_size
            write(71,'(I10)') loop_count
            write(71,'(F30.15)') housing_price(1)
            write(71,'(F30.15)') rent(1,:)
            write(71,'(F30.15)') convexity_of_rental_company
            write(71,'(F30.15)') inheritance_amount
            write(71,'(F30.15)') lambda_m
            write(71,'(F30.15)') kappa_uem
            write(71,'(F30.15)') rho_m
            write(71,'(F30.15)') rho_d
            write(71,'(F30.15)') addiction_scalar_1
            write(71,'(F30.15)') addiction_scalar_adjuster
            write(71,'(F30.15)') previous_gap_addiction_scalar
            write(71,'(I10)') have_gap_addiction_scalar
            write(71,'(F30.15)') max_food_cost
            write(71,'(F30.15)') mu_homeless
            write(71,'(F30.15)') penalty_child_addicted
            write(71,'(F30.15)') penalty_child_addicted_adjuster

            write(71,'(F30.15)') previous_gap_penalty_child
            write(71,'(I10)') have_gap_penalty_child
            write(71,'(F30.15)') probability_becoming_unemployed
            write(71,'(F30.15)') probability_of_voucher_benchmark_used
            write(71,'(F30.15)') relative_share_of_addiction_1
            write(71,'(F30.15)') sd_permanent_productivity
            write(71,'(F30.15)') value_of_life
            write(71,'(F30.15)') value_of_life_at_bracket
            write(71,'(F30.15)') weight_on_child
            write(71,'(F30.15)') multiple_of_probabilities_of_employment_if_addicted
            write(71,'(F30.15)') discount_factor_adjuster
            write(71,'(F30.15)') discount_factor_lo
            write(71,'(F30.15)') discount_factor_hi
            write(71,'(F30.15)') discount_factor_lo_moment
            write(71,'(F30.15)') discount_factor_hi_moment
            write(71,'(F30.15)') previous_gap_discount_factor

            ! THE SHARES THE CHILD'S PENALTY IS APPLIED THROUGH, IN THEIR OWN
            ! FILE. Leaving them unbanked switched the intergenerational channel
            ! off at every restart: newborn_parent_share is built by the
            ! AGGREGATION, which runs after the distribution, so the first
            ! distribution of a fresh process used the declared default, all mass
            ! on clean and housed parents, which is the UNPENALISED draw. The
            ! trace showed exactly that, (1, 0, 0, 0) at the point the draw is
            ! mixed, while the previous process had measured 0.894 clean against
            ! 0.106 disordered.
            !
            ! NOT APPENDED TO calibration_state.dat, AND THAT WAS TRIED FIRST.
            ! The state record's write and read orders diverge at the tail: the
            ! writer ends at previous_gap_discount_factor and the reader at
            ! voucher_probability_adjuster, so the file carries records the
            ! reader never consumes. Four reads appended at the end therefore
            ! picked up those trailing values rather than hitting end of file,
            ! and resumed the shares as 0.0102 and 1e-15. A separate file cannot
            ! be misaligned by anything.
            open(unit=73,file="newborn_parent_share.dat",status='replace')
                ! THE WHOLE ARRAY, because it now resolves the dying mass by
                ! the parent's productivity node as well and four scalars can no
                ! longer carry it.
                write(73,'(F30.15)') newborn_parent_share
            close(73)

            write(71,'(I10)') have_gap_discount_factor
            write(71,'(F30.15)') size_homelessness_lo
            write(71,'(F30.15)') size_homelessness_hi
            write(71,'(F30.15)') size_homelessness_lo_moment
            write(71,'(F30.15)') size_homelessness_hi_moment
            write(71,'(F30.15)') value_of_life_trust
            write(71,'(F30.15)') previous_gap_value_of_life
            write(71,'(I10)') have_gap_value_of_life
            write(71,'(F30.15)') size_homelessness_adjuster
            write(71,'(F30.15)') previous_gap_size_homelessness
            write(71,'(I10)') have_gap_size_homelessness
            write(71,'(F30.15)') voucher_probability_adjuster
            write(71,'(F30.15)') previous_gap_voucher_probability
            write(71,'(I10)') have_gap_voucher_probability
            write(71,'(F30.15)') separation_rate_adjuster
            write(71,'(F30.15)') previous_gap_separation_rate
            write(71,'(I10)') have_gap_separation_rate
            write(71,'(F30.15)') employment_multiplier_adjuster
            write(71,'(F30.15)') previous_gap_employment_multiplier
            write(71,'(I10)') have_gap_employment_multiplier
            ! Appended last, so a state file written before the curvature became
            ! an instrument still reads: the tolerant reads below stop at the
            ! end of it and leave these at their declared values.
            write(71,'(F30.15)') housing_status_grid_expander_adjuster
            write(71,'(F30.15)') previous_gap_housing_status_grid_expander
            write(71,'(I10)') have_gap_housing_status_grid_expander
            write(71,'(F30.15)') relative_share_of_housing_adjuster
            write(71,'(F30.15)') previous_gap_relative_share_of_housing
            write(71,'(I10)') have_gap_relative_share_of_housing
            write(71,'(F30.15)') labor_income_tax_rate_adjuster
            write(71,'(F30.15)') previous_gap_labor_income_tax_rate
            write(71,'(I10)') have_gap_labor_income_tax_rate
            write(71,'(F30.15)') lambda_clamp
            write(71,'(F30.15)') previous_gap_lambda_addiction
            write(71,'(I10)') have_gap_lambda_addiction
            write(71,'(F30.15)') relative_share_of_leisure_adjuster
            write(71,'(F30.15)') previous_gap_relative_share_of_leisure
            ! AT THE TAIL, AND NOT WHERE IT READS BEST. calibration_state.dat is
            ! positional: an entry inserted in the middle shifts every value
            ! after it, and a checkpoint written before delta_h existed would be
            ! read one field out from that point on, silently. The tail is the
            ! only place a new field can go, because the read there is guarded by
            ! iostat and an older file simply runs out.
            write(71,'(I10)') have_gap_relative_share_of_leisure
            write(71,'(F30.15)') penalty_child_homeless
            write(71,'(F30.15)') penalty_child_homeless_adjuster
            write(71,'(F30.15)') previous_gap_penalty_child_homeless
            write(71,'(I10)') have_gap_penalty_child_homeless
            ! AT THE TAIL, for the reason the comment above gives.
            write(71,'(F30.15)') kkk_sigma_scale
            ! AND SO IS RHO, for the same reason. It is wired into the update
            ! block from 10 September, and V2's lesson is that a parameter in the
            ! update block and NOT in this file is worse than not resuming at
            ! all: the parameters that do resume are the ones it has to be
            ! consistent with. Its adjuster goes with it, or a resumed run rings
            ! again from a full step.
            write(71,'(F30.15)') rho_intergenerational
            write(71,'(F30.15)') rho_intergenerational_adjuster
            ! AT THE TAIL, for the reason the comment above gives. Until today
            ! kappa_find_smi had no update block, so there was nothing to
            ! checkpoint; now that it is calibrated on the SMI share of the
            ! homeless, a resume that reset it to its declared 1.0 would throw
            ! away every loop spent moving it.
            write(71,'(F30.15)') kappa_find_smi
            ! AND AT THE TAIL AGAIN. Without these two a resume resets the SMI
            ! channel to off and the loops spent moving it are gone; the
            ! adjuster goes with the level because it arrives through the
            ! handover, which is consumed on the first read.
            write(71,'(F30.15)') b_smi_multiple
            write(71,'(F30.15)') b_smi_multiple_adjuster

        close(71)

        call rename("calibration_state.tmp","calibration_state.dat")

        ! The named companion, so a resume never depends on positional coverage.
        call write_resume_seed()

    end subroutine

    subroutine read_calibration_state()

        ! The other half of the resume. Absent file means a fresh start, which is
        ! what a first run wants, so this is silent rather than an error. Delete
        ! calibration_state.dat to force one.

        use Global_Vars

        implicit none

        logical :: state_exists_1
        character(len=40) :: state_tag_1
        integer :: state_ios_1

        inquire(file="calibration_state.dat",exist=state_exists_1)

        if (.NOT. state_exists_1) then

            write(*,*) "no calibration_state.dat, starting from the declared values"

            return

        end if

        open(unit=72,file="calibration_state.dat",action='read')

            read(72,'(A)') state_tag_1

            if (trim(state_tag_1) .NE. "calibration_state_v3") then

                write(*,*) "calibration_state.dat is not version 3, ignoring it"
                close(72)

                return

            end if

            read(72,'(F30.15)') discount_factor
            read(72,'(F30.15)') discount_factor_on_child
            read(72,'(F30.15)') minimum_inheritance
            read(72,'(F30.15)') advantage_to_owning
            read(72,'(F30.15)') relative_share_of_housing
            read(72,'(F30.15)') relative_share_of_leisure
            read(72,'(F30.15)') largest_house_size
            read(72,'(F30.15)') smallest_rental_relative_to_lowest_income
            read(72,'(F30.15)') labor_income_tax_rate
            read(72,'(F30.15)') standard_deduction_as_percent_of_average_labor_income
            read(72,'(F30.15)') probability_of_becoming_addicted_if_experiment
            read(72,'(F30.15)') lambda_addiction
            read(72,'(F30.15)') price_of_addictive_good
            read(72,'(F30.15)') drug_supply_shifter
            read(72,'(F30.15)') utility_cost_of_treatment
            read(72,'(F30.15)') previous_utility_cost_of_treatment
            read(72,'(F30.15)') previous_treatment_take_up
            read(72,'(I10)') have_treatment_secant
            read(72,'(F30.15)') previous_onset_at_mean
            read(72,'(F30.15)') previous_sud_rate
            read(72,'(I10)') have_lambda_secant
            read(72,'(F30.15)') size_homelessness
            read(72,'(F30.15)') fixed_cost_to_moving
            read(72,'(F30.15)') housing_status_grid_expander
            read(72,'(F30.15)') smallest_house_size_adjuster
            read(72,'(F30.15)') largest_house_size_adjuster
            read(72,'(F30.15)') previous_gap_smallest_house_size
            read(72,'(F30.15)') previous_gap_largest_house_size
            read(72,'(I10)') have_gap_smallest_house_size
            read(72,'(I10)') have_gap_largest_house_size
            read(72,'(I10)') resumed_loop_count
            read(72,'(F30.15)') housing_price(1)
            read(72,'(F30.15)') rent(1,:)
            read(72,'(F30.15)') convexity_of_rental_company
            read(72,'(F30.15)') inheritance_amount
            read(72,'(F30.15)') lambda_m
            read(72,'(F30.15)') kappa_uem
            read(72,'(F30.15)') rho_m
            read(72,'(F30.15)') rho_d
            read(72,'(F30.15)') addiction_scalar_1
            read(72,'(F30.15)') addiction_scalar_adjuster
            read(72,'(F30.15)') previous_gap_addiction_scalar
            read(72,'(I10)') have_gap_addiction_scalar
            read(72,'(F30.15)') max_food_cost
            read(72,'(F30.15)') mu_homeless
            read(72,'(F30.15)') penalty_child_addicted
            ! A STATE FILE WRITTEN UNDER THE OLD CEILING MUST NOT SURVIVE THE NEW
            ! ONE. The banked value is 0.9, and without this clamp the solve that
            ! reads it runs a whole loop at the old penalty before the update at
            ! the end of it brings the parameter inside the cap.
            ! THE CEILING IS 0.6, NOT 0.4. delta_d is 57 per cent short at the
            ! leader and the simplex's vertex at 0.421 was SILENTLY CLAMPED to
            ! 0.4, so the point measured the base and the search learned
            ! nothing -- the same failure kappa_uem's arms had at 0.10 and 0.30.
            penalty_child_addicted=max(min(penalty_child_addicted,penalty_child_cap),0.d0)
            read(72,'(F30.15)') penalty_child_addicted_adjuster
            read(72,'(F30.15)') previous_gap_penalty_child
            read(72,'(I10)') have_gap_penalty_child
            read(72,'(F30.15)') probability_becoming_unemployed
            read(72,'(F30.15)') probability_of_voucher_benchmark_used
            read(72,'(F30.15)') relative_share_of_addiction_1
            read(72,'(F30.15)') sd_permanent_productivity
            read(72,'(F30.15)') value_of_life
            read(72,'(F30.15)') value_of_life_at_bracket
            read(72,'(F30.15)') weight_on_child
            read(72,'(F30.15)') multiple_of_probabilities_of_employment_if_addicted
            read(72,'(F30.15)') discount_factor_adjuster
            read(72,'(F30.15)') discount_factor_lo
            read(72,'(F30.15)') discount_factor_hi
            read(72,'(F30.15)') discount_factor_lo_moment
            read(72,'(F30.15)') discount_factor_hi_moment
            read(72,'(F30.15)') previous_gap_discount_factor
            read(72,'(I10)') have_gap_discount_factor
            read(72,'(F30.15)') size_homelessness_lo
            read(72,'(F30.15)') size_homelessness_hi
            read(72,'(F30.15)') size_homelessness_lo_moment
            read(72,'(F30.15)') size_homelessness_hi_moment

            ! READ TOLERANTLY FROM HERE ON, so a state file written before these
            ! fields existed still resumes instead of being thrown away. A short
            ! file leaves them at their declared values, which is what a fresh
            ! start would use anyway, and the alternative is a version bump that
            ! discards every loop already paid for.
            read(72,'(F30.15)',iostat=state_ios_1) value_of_life_trust

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_value_of_life

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_value_of_life

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) size_homelessness_adjuster

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_size_homelessness

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_size_homelessness

            end if


            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) voucher_probability_adjuster

            ! Its own file, so nothing in the state record can misalign it.
            open(unit=73,file="newborn_parent_share.dat",status='old',iostat=state_ios_1)
            if (state_ios_1==0) then
                read(73,'(F30.15)',iostat=state_ios_1) newborn_parent_share
                close(73)
            end if
            if (state_ios_1/=0) then
                ! Every parent clean and housed, spread over nodes by the
                ! unconditional distribution, which is what a newborn faces
                ! before any distribution has been solved.
                newborn_parent_share=0
                newborn_parent_share(:,0,1)=unconditional_employment_probability(:)
                write(*,*) "no banked newborn parent shares, so the first distribution is"
                write(*,*) "   built with no transmission and it rebuilds from loop two"
            end if
            write(*,*) "newborn_parent_share resumed: clean housed=", sum(newborn_parent_share(:,0,1)), &
                " disordered housed=", sum(newborn_parent_share(:,1,1))


            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_voucher_probability

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_voucher_probability

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) separation_rate_adjuster

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_separation_rate

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_separation_rate

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) employment_multiplier_adjuster

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_employment_multiplier

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_employment_multiplier

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) housing_status_grid_expander_adjuster

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_housing_status_grid_expander

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_housing_status_grid_expander

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) relative_share_of_housing_adjuster

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_relative_share_of_housing

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_relative_share_of_housing

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) labor_income_tax_rate_adjuster

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_labor_income_tax_rate

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_labor_income_tax_rate

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) lambda_clamp

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_lambda_addiction

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_lambda_addiction

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) relative_share_of_leisure_adjuster

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_relative_share_of_leisure

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_relative_share_of_leisure
                read(72,'(F30.15)',iostat=state_ios_1) penalty_child_homeless
                read(72,'(F30.15)',iostat=state_ios_1) penalty_child_homeless_adjuster
                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_penalty_child_homeless
                read(72,'(I10)',iostat=state_ios_1) have_gap_penalty_child_homeless
                read(72,'(F30.15)',iostat=state_ios_1) kkk_sigma_scale
                read(72,'(F30.15)',iostat=state_ios_1) rho_intergenerational
                read(72,'(F30.15)',iostat=state_ios_1) rho_intergenerational_adjuster

                ! A CHECKPOINT WRITTEN BEFORE RHO WAS CALIBRATED RUNS OUT HERE,
                ! and the iostat guard turns that into "leave it at its declared
                ! value" rather than into a misread. That is the whole reason new
                ! fields go at the tail.
                !
                ! AND THE DIRECTION OF THAT FAILURE IS THE SAFE ONE. A short read
                ! leaves the declarations standing: rho at 0.35, which is the
                ! assigned literature value and correct, and the adjuster at 0,
                ! which is HELD. So an old checkpoint resumes with the instrument
                ! OFF rather than with a garbage step.
                if (state_ios_1/=0) then
                    write(*,*) "calibration_state.dat predates rho_intergenerational;",&
                        " it starts at its declared", rho_intergenerational,&
                        " with the instrument held"
                end if

                if (state_ios_1==0) then

                    read(72,'(F30.15)',iostat=state_ios_1) kappa_find_smi

                    ! AND THE SAME SAFE DIRECTION. A checkpoint written before
                    ! kappa_find_smi was calibrated runs out here and leaves it
                    ! at its declared 1.0, which is no SMI finding penalty at
                    ! all -- the value every such checkpoint was solved under.
                    if (state_ios_1/=0) then
                        write(*,*) "calibration_state.dat predates kappa_find_smi;",&
                            " it starts at its declared", kappa_find_smi
                    else
                        kappa_find_smi=max(min(kappa_find_smi,100.d0),1.d0)
                    end if

                end if

                if (state_ios_1==0) then

                    read(72,'(F30.15)',iostat=state_ios_1) b_smi_multiple

                    ! SAFE DIRECTION AGAIN. A checkpoint written before the SMI
                    ! channel existed runs out here and leaves b_smi_multiple at
                    ! its declared 1.0, which is the channel OFF -- the value
                    ! every such checkpoint was solved under.
                    if (state_ios_1/=0) then
                        write(*,*) "calibration_state.dat predates b_smi_multiple;",&
                            " it starts at its declared", b_smi_multiple,&
                            " which is the SMI channel off"
                    else
                        b_smi_multiple=max(min(b_smi_multiple,10.d0),0.d0)

                        read(72,'(F30.15)',iostat=state_ios_1) b_smi_multiple_adjuster

                        if (state_ios_1/=0) then
                            write(*,*) "calibration_state.dat carries b_smi_multiple but",&
                                " not its adjuster; the bracket resumes HELD at",&
                                b_smi_multiple_adjuster
                        else
                            b_smi_multiple_adjuster=max(min(b_smi_multiple_adjuster,10.d0),0.d0)
                        end if

                    end if

                end if


            end if

            if (state_ios_1/=0) then

                write(*,*) "calibration_state.dat predates some damping state; anything missing",&
                    " starts from its declared value. The trust region",&
                    " starts at", value_of_life_trust_start, " and the homelessness adjuster at",&
                    size_homelessness_adjuster_start
                value_of_life_trust=value_of_life_trust_start
                previous_gap_value_of_life=0
                have_gap_value_of_life=0
                size_homelessness_adjuster=size_homelessness_adjuster_start
                previous_gap_size_homelessness=0
                have_gap_size_homelessness=0

            end if

            ! AND CLAMP WHAT WAS READ, because a checkpoint written before this
            ! floor existed carries the degenerate zero and would reinstate it
            ! on the next resume, silently, having just been told the floor is
            ! 0.01. The banked state at the time this was written held exactly
            ! that.
            if (size_homelessness<size_homelessness_floor) then
                write(*,*) "size_homelessness read as", size_homelessness,&
                    " which prices the street at minus infinity; raised to",&
                    size_homelessness_floor
                size_homelessness=size_homelessness_floor
            end if

        close(72)

        ! CLAMP THETA AND b INTO THEIR BAND ON RESUME. The bounds in the update
        ! rules only bite when an update runs, so a resumed state carrying the
        ! old out of band values would spend a whole loop on them first. A state
        ! written before the band existed carries theta at 0.667 and b at 0.99.
        if ((relative_share_of_addiction_1<theta_lo) .OR. &
            (relative_share_of_addiction_1>theta_hi)) then

            write(*,*) "theta out of band on resume:", relative_share_of_addiction_1, &
                " clamped into [", theta_lo, ",", theta_hi, "]"
            relative_share_of_addiction_1=max(min(relative_share_of_addiction_1,theta_hi),theta_lo)

        end if

        if ((addiction_scalar_1<b_lo) .OR. (addiction_scalar_1>b_hi)) then

            write(*,*) "b out of band on resume:", addiction_scalar_1, &
                " clamped into [", b_lo, ",", b_hi, "]"
            addiction_scalar_1=max(min(addiction_scalar_1,b_hi),b_lo)

        end if

        ! THE HANDOVER IS NOT READ HERE ANY MORE, AND MOVING IT WAS THE
        ! WHOLE BUG. It used to sit at the foot of this subroutine, which has
        ! TWO early returns above it: one when calibration_state.dat does not
        ! exist and one when it is not version 3. A container that had never
        ! run the model -- which is every freshly cloned worker, because the
        ! state file is not in the repository -- took the first of those and
        ! returned before the handover was ever opened. The run then solved at
        ! the values in the declarations, printed a full moments block, and
        ! looked in every respect like a measured point. Three archived points
        ! with different vectors re-ran to the same loss to four decimals with
        ! no HANDOVER line anywhere in their logs; the parameters had never
        ! reached the model. It is now apply_param_handover(), called by the
        ! caller straight after this returns, so it runs on both paths.

        write(*,*) "resumed from calibration_state.dat, written after loop", resumed_loop_count
        write(*,*) "relative_share_of_addiction_1=", relative_share_of_addiction_1
        write(*,*) "addiction_scalar_1=", addiction_scalar_1
        write(*,*) "lambda_addiction=", lambda_addiction
        write(*,*) "largest_house_size=", largest_house_size
        write(*,*) "smallest_rental_relative_to_lowest_income=", smallest_rental_relative_to_lowest_income
        write(*,*) "lambda_m=", lambda_m
        write(*,*) "kappa_uem=", kappa_uem
        write(*,*) "rho_m=", rho_m
        write(*,*) "rho_d=", rho_d

    end subroutine

    subroutine apply_param_handover()

        ! THE ONE SHOT SEED, SPLIT OUT OF read_calibration_state SO THAT IT RUNS
        ! WHETHER OR NOT THERE IS A STATE FILE TO RESUME FROM. See the note at
        ! the point it was taken from. Everything below is unchanged.

        use Global_Vars

        implicit none

        ! THE HANDOVER FILE, AND IT CONSUMES ITSELF.
        !
        ! Putting a value chosen outside the loop back into it means putting it
        ! into calibration_state.dat, which is written positionally: 128 of its
        ! lines differ between two runs, so no diff identifies a parameter's
        ! offset and it cannot be edited by hand. The model takes the value from
        ! a file instead, AFTER the state is read, and deletes the file as it
        ! does. One pass later the state carries it like any other parameter and
        ! the loop owns it again; a standing override would PIN a parameter
        ! rather than seed it, which is the opposite of what a handover is for.
        !
        ! One "name value" pair a line. Unknown names are reported and ignored
        ! rather than silently dropped, because a typo in a handover is
        ! indistinguishable from a parameter that would not move.
        open(unit=79,file="PARAM_HANDOVER.txt",action='read',status='old',iostat=handover_status)
        if (handover_status==0) then

            do

                read(79,*,iostat=handover_status) handover_name, handover_value
                if (handover_status/=0) exit

                select case (trim(handover_name))

                ! THE PERSISTENCE CHANNEL, AND THE SWITCH THAT OPENS IT. Both
                ! are handover parameters so that turning the instrument on
                ! costs no rebuild -- the same reason measure_child_gap was made
                ! one. The adjuster defaults to zero, which is HELD, so a run
                ! that does not ask for this is the model exactly as it was.
                case ("rho_intergenerational")
                    write(*,*) "HANDOVER rho_intergenerational:", rho_intergenerational, "->", handover_value
                    rho_intergenerational=max(min(handover_value,&
                        rho_intergenerational_cap),rho_intergenerational_floor)
                    if (rho_intergenerational .NE. handover_value) then
                        write(*,*) "HANDOVER CLAMPED rho_intergenerational: requested",&
                            handover_value, "outside [", rho_intergenerational_floor, ",",&
                            rho_intergenerational_cap, "]"
                    end if

                case ("rho_intergenerational_adjuster")
                    write(*,*) "HANDOVER rho_intergenerational_adjuster:",&
                        rho_intergenerational_adjuster, "->", handover_value
                    rho_intergenerational_adjuster=max(handover_value,0.d0)

                case ("b_smi_multiple_adjuster")
                    write(*,*) "HANDOVER b_smi_multiple_adjuster:",&
                        b_smi_multiple_adjuster, "->", handover_value
                    b_smi_multiple_adjuster=max(min(handover_value,10.d0),0.d0)

                case ("b_smi_multiple")
                    write(*,*) "HANDOVER b_smi_multiple:", b_smi_multiple, "->", handover_value
                    ! FLOORED, NOT CLAMPED SILENTLY. b enters as (b+q)^phi_q and
                    ! u = -1/X at sigma = 2, so b_smi_multiple at or below zero
                    ! sends flow utility to minus infinity for every SMI
                    ! household at q = 0, which is a crash rather than a corner.
                    ! The floor is 1e-6, six orders below anything the search
                    ! should reach, and it says so if it bites.
                    ! PROBE BUILD ONLY: the 1e-6 floor is removed so that
                    ! b_smi_multiple = 0 can be run. The shared source keeps the
                    ! floor. At exactly zero an abstaining SMI household's flow
                    ! utility is minus infinity, which is the author's question:
                    ! if abstaining is infinitely costly and the ratio still
                    ! misses 7.30, the households that do not buy are ones that
                    ! CANNOT buy.
                    if (handover_value<0.d0) then
                        write(*,*) "HANDOVER b_smi_multiple FLOORED from",&
                            handover_value, "to", 0.d0
                        b_smi_multiple=0.d0
                    else
                        b_smi_multiple=handover_value
                    end if

                case ("addiction_scalar_1")
                    write(*,*) "HANDOVER addiction_scalar_1:", addiction_scalar_1, "->", handover_value
                    ! A SILENT CLAMP MISLABELS A POINT. The point's identity is
                    ! the md5 of the vector REQUESTED, so if this clamp bites,
                    ! the file is named for a value the model never ran and the
                    ! archive quietly contains a lie. It has never bitten, and
                    ! the floor below it is now 1e-30, but it must say so if it
                    ! ever does.
                    if (handover_value>b_hi .or. handover_value<b_lo) then
                        write(*,*) "HANDOVER CLAMPED addiction_scalar_1: requested",&
                            handover_value, "outside [", b_lo, ",", b_hi, "] -- THIS POINT IS MISLABELLED"
                    end if
                    addiction_scalar_1=max(min(handover_value,b_hi),b_lo)

                case ("persistent_income_risk")
                    write(*,*) "HANDOVER persistent_income_risk:", persistent_income_risk, "->", handover_value
                    persistent_income_risk=nint(max(min(handover_value,1.d0),0.d0))
                case ("rho_productivity")
                    write(*,*) "HANDOVER rho_productivity:", rho_productivity, "->", handover_value
                    rho_productivity=max(min(handover_value,0.999d0),0.d0)

                ! rho_intergenerational's case is NOT here. Two sessions added
                ! one on 10 September, a few minutes apart, and git merged both
                ! without complaint -- two `case` labels for one string in one
                ! `select case`, which gfortran rejects outright. The surviving
                ! copy is beside the persistence block above, where it sits next
                ! to its own adjuster's case; the clamp is identical, [0, 0.999].
                case ("endowment_is_a_transfer")
                    write(*,*) "HANDOVER endowment_is_a_transfer:", endowment_is_a_transfer, "->", handover_value
                    endowment_is_a_transfer=nint(max(min(handover_value,1.d0),0.d0))
                case ("ssi_floor_takeup")
                    write(*,*) "HANDOVER ssi_floor_takeup:", ssi_floor_takeup, "->", handover_value
                    ssi_floor_takeup=max(min(handover_value,1.d0),0.d0)
                ! THE FLOOR'S LEVEL IS SETTABLE, and until now only its TAKE-UP
                ! was. The author, 3 September: *"maybe the floor is too low
                ! still if so many old are homeless.... Because if the ssi was
                ! high, no old would be homeless"*.
                !
                ! WHY THE TAKE-UP DIAL COULD NEVER TEST THAT. The benefit is
                ! max(PIA_i, takeup*ssi_floor_level) and takeup is clamped to
                ! [0,1], so the effective floor could never exceed 0.1774. On
                ! the grid this model runs, node 4's own PIA is 0.30015 and node
                ! 4 carries 39.8 per cent of the mass, so the floor was
                ! structurally incapable of reaching the households that are
                ! actually homeless in retirement -- it binds only on nodes 1 to
                ! 3, and node 3's gain at full take-up is 7 per cent. That is
                ! why 0.5 to 1.0 moved h_share5 by 0.005 in the wrong direction.
                !
                ! 0.1774 IS THE REAL BENEFIT RATE -- $943 a month in 2024 over
                ! the average wage index -- so a CALIBRATED value above it is a
                ! change to the policy environment and not a free parameter. It
                ! is made settable here so the mechanism can be MEASURED; what
                ! value the benchmark carries is the author's call.
                case ("ssi_floor_level")
                    write(*,*) "HANDOVER ssi_floor_level:", ssi_floor_level, "->", handover_value
                    ssi_floor_level=max(min(handover_value,5.d0),0.d0)
                case ("use_pia_formula")
                    write(*,*) "HANDOVER use_pia_formula:", use_pia_formula, "->", handover_value
                    use_pia_formula=nint(max(min(handover_value,1.d0),0.d0))
                case ("use_unemployment_by_productivity")
                    write(*,*) "HANDOVER use_unemployment_by_productivity:",&
                        use_unemployment_by_productivity, "->", handover_value
                    use_unemployment_by_productivity=nint(max(min(handover_value,1.d0),0.d0))
                ! THE PRODUCTIVITY PROCESS ITSELF. 1 is the quantile grid,
                ! 0 is the author's KKK_process. Nothing below it is shared:
                ! y_grid_kappa and bottom_productivity_level are inert under
                ! KKK, and s_deviation_bottom, the two persistences and the two
                ! innovation sds are inert under the quantile grid.
                case ("fixed_productivity")
                    write(*,*) "HANDOVER fixed_productivity:", fixed_productivity, "->", handover_value
                    fixed_productivity=max(min(nint(handover_value),1),0)

                ! THE KKK GRID'S WIDTH AT THE BOTTOM, which is what
                ! y_grid_kappa is on the quantile grid: the instrument for how
                ! much mass sits on the node too poor to rent. Widening it
                ! pushes mass off the bottom node -- 3.00 gives 0.621 per cent,
                ! 3.25 gives 0.318, 3.50 gives 0.155 -- against a design target
                ! of 0.198 from the homelessness bands.
                ! THE DISPERSION INSTRUMENT UNDER KKK, and the ONE number that
                ! reconciles the process with the SCF bottom half share. It
                ! multiplies both innovation sds, so the ratio between them --
                ! which is what sets the fanning out -- is untouched.
                case ("kkk_sigma_scale")
                    write(*,*) "HANDOVER kkk_sigma_scale:", kkk_sigma_scale, "->", handover_value
                    kkk_sigma_scale=max(min(handover_value,10.d0),0.1d0)

                case ("kkk_s_deviation_bottom")
                    write(*,*) "HANDOVER kkk_s_deviation_bottom:",&
                        kkk_s_deviation_bottom, "->", handover_value
                    kkk_s_deviation_bottom=max(min(handover_value,6.d0),1.d0)

                case ("kkk_s_deviation_top")
                    write(*,*) "HANDOVER kkk_s_deviation_top:",&
                        kkk_s_deviation_top, "->", handover_value
                    kkk_s_deviation_top=max(min(handover_value,6.d0),1.d0)

                ! THE FOUR NUMBERS OF THE TWO COMPONENT PROCESS. The defaults
                ! are the author's own: 0.5 and 0.309 for the fixed effect,
                ! 0.9 and 0.2 for the persistent component, which are the
                ! Guvenen, Karahan, Ozkan and Song "use it or lose it" values.
                ! They are here so a point file can move them, not because
                ! anything says they should be moved.
                case ("persistence_fixed_employment_newborn")
                    write(*,*) "HANDOVER persistence_fixed_employment_newborn:",&
                        persistence_fixed_employment_newborn, "->", handover_value
                    persistence_fixed_employment_newborn=max(min(handover_value,0.999d0),0.d0)

                case ("sd_fixed_employment_newborn")
                    write(*,*) "HANDOVER sd_fixed_employment_newborn:",&
                        sd_fixed_employment_newborn, "->", handover_value
                    sd_fixed_employment_newborn=max(min(handover_value,3.d0),10.d0**(-3))

                case ("persistence_employment_surviving")
                    write(*,*) "HANDOVER persistence_employment_surviving:",&
                        persistence_employment_surviving, "->", handover_value
                    persistence_employment_surviving=max(min(handover_value,0.999d0),0.d0)

                case ("sd_employment_surviving")
                    write(*,*) "HANDOVER sd_employment_surviving:",&
                        sd_employment_surviving, "->", handover_value
                    sd_employment_surviving=max(min(handover_value,3.d0),10.d0**(-3))

                case ("y_grid_kappa")
                    write(*,*) "HANDOVER y_grid_kappa:", y_grid_kappa, "->", handover_value
                    y_grid_kappa=max(min(handover_value,8.d0),1.d0)
                case ("bottom_productivity_level")
                    write(*,*) "HANDOVER bottom_productivity_level:", bottom_productivity_level, "->", handover_value
                    bottom_productivity_level=max(min(handover_value,1.d0),0.d0)
                case ("size_homelessness")
                    write(*,*) "HANDOVER size_homelessness:", size_homelessness, "->", handover_value
                    size_homelessness=max(min(handover_value,0.9d0),size_homelessness_floor)

                ! EXPOSED SO h_1 CAN BE SCANNED, 14 September.  The author:
                ! *"if you raise h1 towards 1% you will be able to get 46% of
                ! homeless being employed... You can raise it until you hit the
                ! 46% employed homeless"*.
                !
                ! h_1 could not be scanned at all before this.  tie_h1_to_h2 is a
                ! compile-time 1, so the tie OVERWRITES anything the handover puts
                ! in size_homelessness, and h1_share_of_h2 -- the multiplier the
                ! tie actually uses -- had no case here and was a hard-coded 0.01.
                ! Every run in the archive therefore sits at the same h_1, which is
                ! why the slope this bracket would rely on has never been measured.
                !
                ! Exposing the multiplier rather than untying is the smaller change:
                ! the ladder stays monotone by construction, since h_1 remains a
                ! fraction of the bottom rung.
                case ("h1_share_of_h2")
                    write(*,*) "HANDOVER h1_share_of_h2:", h1_share_of_h2, "->", handover_value
                    h1_share_of_h2=max(min(handover_value,0.9d0),10.d0**(-6))

                case ("smallest_rental_relative_to_lowest_income")
                    ! BOTH, because the ratio is what the bracket moves and the
                    ! size is what the model prices, and the size is only rebuilt
                    ! from the ratio before the first loop. A resumed run that
                    ! set one and not the other would carry the old dwelling.
                    write(*,*) "HANDOVER smallest_rental:",&
                        smallest_rental_relative_to_lowest_income, "->", handover_value
                    smallest_rental_relative_to_lowest_income=handover_value
                    smallest_house_size=handover_value

                case ("housing_status_grid_expander")
                    write(*,*) "HANDOVER housing_status_grid_expander:",&
                        housing_status_grid_expander, "->", handover_value
                    housing_status_grid_expander=handover_value

                case ("lambda_addiction")
                    write(*,*) "HANDOVER lambda_addiction:", lambda_addiction, "->", handover_value
                    lambda_addiction=handover_value

                case ("largest_house_size")
                    write(*,*) "HANDOVER largest_house_size:", largest_house_size, "->", handover_value
                    largest_house_size=handover_value

                case ("lambda_m")
                    write(*,*) "HANDOVER lambda_m:", lambda_m, "->", handover_value
                    lambda_m=max(min(handover_value,0.5d0),lambda_m_floor)

                case ("smi_onset_level")
                    write(*,*) "HANDOVER smi_onset_level:", smi_onset_level, "->", handover_value
                    smi_onset_level=max(min(handover_value,1.d0),10.d0**(-8))

                case ("zeta_DI")
                    write(*,*) "HANDOVER zeta_DI:", zeta_DI, "->", handover_value
                    zeta_DI=max(min(handover_value,1.d0),0.d0)

                ! psi AND ITS CAP. Bounded at 1 and at 5 times average income
                ! respectively: psi above one would pay a household more out of
                ! work than in it, which inverts the participation margin the
                ! model is built on, and a cap of five times average income is
                ! already far above any real benefit schedule.
                case ("replacement_rate_ui")
                    write(*,*) "HANDOVER replacement_rate_ui:", &
                        replacement_rate_ui, "->", handover_value
                    replacement_rate_ui=max(min(handover_value,1.d0),0.d0)

                case ("max_ui_as_perc_of_avg_inc")
                    write(*,*) "HANDOVER max_ui_as_perc_of_avg_inc:", &
                        max_ui_as_perc_of_avg_inc, "->", handover_value
                    max_ui_as_perc_of_avg_inc=max(min(handover_value,5.d0),0.d0)

                case ("merge_from_node")
                    write(*,*) "HANDOVER merge_from_node:", &
                        merge_from_node, "->", handover_value
                    merge_from_node=max(min(handover_value,4.d0),1.d0)

                case ("merge_bottom_nodes")
                    write(*,*) "HANDOVER merge_bottom_nodes:", &
                        merge_bottom_nodes, "->", handover_value
                    merge_bottom_nodes=max(min(handover_value,4.d0),1.d0)
                ! THE FROZEN PASS, settable per run so one binary serves both
                ! the ordinary descent and the diagnostic.
                case ("freeze_updates_after_loop")
                    write(*,*) "HANDOVER freeze_updates_after_loop:",&
                        freeze_updates_after_loop, "->", handover_value
                    freeze_updates_after_loop=&
                        int(max(min(handover_value,100000.d0),0.d0))

                case ("kappa_find_smi")

                    write(*,*) "HANDOVER kappa_find_smi:", &
                        kappa_find_smi, "->", handover_value
                    kappa_find_smi=max(min(handover_value,100.d0),1.d0)

                case ("kappa_uem")
                    write(*,*) "HANDOVER kappa_uem:", kappa_uem, "->", handover_value
                    kappa_uem=max(min(handover_value,100.d0),1.d0)

                case ("weight_on_child")
                    write(*,*) "HANDOVER weight_on_child:", weight_on_child, "->", handover_value
                    weight_on_child=max(min(handover_value,weight_on_child_cap),0.d0)

                ! THE LABOUR MARKET COST OF THE STREET. See the declaration for
                ! the arithmetic that makes this the instrument for the employed
                ! share of the homeless. The floor is zero, which is no penalty
                ! at all; the ceiling is 20, well past the 3.8 the steady state
                ! formula asks for, so the bracket is not clipped before it gets
                ! there.
                case ("increased_prob_if_homeless")
                    write(*,*) "HANDOVER increased_prob_if_homeless:", &
                        increased_prob_if_homeless, "->", handover_value
                    ! THE CEILING IS BELOW ONE NOW, AND THAT IS NOT A TASTE.
                    ! The job finding rate is multiplied by (1-x) rather than
                    ! divided by (1+x), so anything at or above one makes it
                    ! zero or NEGATIVE -- a negative probability that the
                    ! process verifier would catch only after a wasted solve.
                    ! The old ceiling of 20 was safe under division and is not
                    ! under multiplication.
                    increased_prob_if_homeless=max(min(handover_value,0.95d0),0.d0)

                case ("consumption_penalty_homeless")
                    write(*,*) "HANDOVER consumption_penalty_homeless:",&
                        consumption_penalty_homeless, "->", handover_value
                    ! CEILING BELOW ONE for the same reason as the line above:
                    ! consumption enters as c**((1-sigma)*(1-gamma)), so a scale
                    ! factor of zero or below is not a consumption level.
                    consumption_penalty_homeless=max(min(handover_value,0.95d0),0.d0)

                case ("extra_job_loss_if_homeless")
                    write(*,*) "HANDOVER extra_job_loss_if_homeless:",&
                        extra_job_loss_if_homeless, "->", handover_value
                    ! NO LOW CEILING HERE. This side is bounded by the separation
                    ! probability reaching one, which the clamp in
                    ! create_unemployment_process enforces, not by an algebraic
                    ! sign condition. At the calibrated separation rate of 0.0136
                    ! the clamp binds around 72.
                    extra_job_loss_if_homeless=max(min(handover_value,200.d0),0.d0)

                case ("homeless_job_penalty_pp")
                    write(*,*) "HANDOVER homeless_job_penalty_pp:",&
                        homeless_job_penalty_pp, "->", handover_value
                    ! Above probability_becoming_employed the finding rate is
                    ! already floored at zero and delta only raises separations,
                    ! so the useful range ends there; one is the hard bound.
                    homeless_job_penalty_pp=max(min(handover_value,1.d0),0.d0)

                ! THE EARNINGS PENALTY OF A SUBSTANCE USE DISORDER. It enters as
                ! rho_d**(sud*include_rho_d), so it is a multiplier on the wage
                ! of a household with the disorder and one means no penalty. The
                ! floor is 0.05 rather than zero because zero earnings for every
                ! addict is a corner, not a calibration, and the ceiling is one
                ! because a disorder that RAISES the wage is not on the table.
                case ("rho_d")
                    write(*,*) "HANDOVER rho_d:", rho_d, "->", handover_value
                    rho_d=max(min(handover_value,1.d0),0.05d0)

                ! rho_m, WHICH HAD NO HANDOVER AT ALL. Same ceiling and the same
                ! reason as rho_d: an illness that RAISES the wage is not on the
                ! table. The author's instruction of 2 September is that both sit
                ! at one and are not lowered, so this exists to make that
                ! settable and visible in a point file rather than buried in a
                ! declaration.
                ! THE UNSECURED BORROWING PARAMETERS, so the rate and the limit
                ! can be revisited without another model change. The author named
                ! 5.5 per cent after quoting a figure that was a debt-to-income
                ! QUANTITY rather than a rate, so this one in particular is
                ! expected to move.
                case ("include_unsecured_borrowing")
                    write(*,*) "HANDOVER include_unsecured_borrowing:", &
                        include_unsecured_borrowing, "->", handover_value
                    include_unsecured_borrowing=max(min(nint(handover_value),1),0)

                case ("unsecured_borrowing_limit")
                    write(*,*) "HANDOVER unsecured_borrowing_limit:", &
                        unsecured_borrowing_limit, "->", handover_value
                    unsecured_borrowing_limit=max(min(handover_value,3.d0),0.d0)

                case ("unsecured_borrowing_rate")
                    write(*,*) "HANDOVER unsecured_borrowing_rate:", &
                        unsecured_borrowing_rate, "->", handover_value
                    unsecured_borrowing_rate=max(min(handover_value,0.40d0),0.d0)

                case ("restrict_borrowing_to_impatient")
                    write(*,*) "HANDOVER restrict_borrowing_to_impatient:", &
                        restrict_borrowing_to_impatient, "->", handover_value
                    restrict_borrowing_to_impatient=max(min(nint(handover_value),1),0)

                case ("rho_m")
                    write(*,*) "HANDOVER rho_m:", rho_m, "->", handover_value
                    rho_m=max(min(handover_value,1.d0),0.05d0)

                ! THE SUPPLY ELASTICITY, and the curvature that follows from it.
                ! Both paths must be given the same value: the benchmark writes
                ! the shifter from it and the arms read that shifter back.
                ! Whether a failed test leads to exclusion. The state slice
                ! exists either way; this decides whether anyone enters it.
                case ("include_voucher_exclusion")
                    write(*,*) "HANDOVER include_voucher_exclusion:", &
                        include_voucher_exclusion, "->", handover_value
                    include_voucher_exclusion=max(min(nint(handover_value),1),0)

                case ("drug_supply_elasticity")
                    write(*,*) "HANDOVER drug_supply_elasticity:", &
                        drug_supply_elasticity, "->", handover_value
                    drug_supply_elasticity=max(handover_value,10.d0**(-2))
                    drug_supply_curvature=1+1/drug_supply_elasticity
                    write(*,*) "  drug_supply_curvature is now", drug_supply_curvature

                ! THE COUNTERFACTUAL'S STARTING DRUG PRICE, and nothing else.
                !
                ! WHY IT EXISTS. Correcting probability_of_false_positive to
                ! 0.005 moves universal treatment first into a regime where the
                ! market clears far below the benchmark price: at the end of its
                ! run the implied supply price was 0.1323 against a price still
                ! walking down through 0.6696. The author's cap of half a per
                ! cent a loop cannot cross that gap from 1.0 inside
                ! max_counterfactual_loops, so the arm exited on LOOP COUNT with
                ! distance_drug_market at 0.54 -- a hundred times its tolerance
                ! -- while the budget and the moments both converged. Three of
                ! the four conditions looked immaculate and the market never
                ! cleared, and it printed a welfare number of +12.7 per cent
                ! that reads perfectly plausibly.
                !
                ! THIS IS AN INITIAL GUESS AND NOTHING MORE. It changes no
                ! equilibrium condition, and it deliberately does NOT touch
                ! max_drug_price_move, which the author set at 0.005 on 8
                ! September after the secant oscillated. The fixed point is
                ! still implied_price == price_faced to within
                ! stopping_rule_drug_market; only where the walk starts moves.
                !
                ! COUNTERFACTUAL ONLY. On the benchmark path the price IS the
                ! normalisation -- drug_supply_shifter is computed from it and
                ! written out for the arms to read -- so seeding it there would
                ! silently redefine the numeraire and every arm would clear
                ! against the wrong supply curve. is_counterfactual is a
                ! compile-time parameter, so the benchmark build cannot reach
                ! the assignment at all.
                ! PINNING THE DRUG PRICE ON PURPOSE, which is how the
                ! market's fixed point gets found when the joint iteration
                ! cannot find it.
                !
                ! At 0 the price never moves, so the economy converges to ITS
                ! OWN fixed point at whatever drug_price_start set -- measured
                ! at nine loops to CF MOMENTS distance 4.9e-5. The
                ! distance_drug_market printed once it has settled is then the
                ! TRUE gap at that price, not a transient. Two such probes
                ! bracket the crossing and a third lands on it.
                !
                ! That is the quasi-static route round the deadlock recorded in
                ! CALIBRATION_STATE.md: the economy needs about nine loops to
                ! settle at a price and the joint solver gives it one, so the
                ! gap never stops being a transient and the 0.5 per cent clip
                ! keeps binding. Pinning removes the moving target.
                !
                ! A handover rather than a rebuild because each probe needs a
                ! different price and the same binary should serve them all.
                case ("drug_market_adjuster")
                    write(*,*) "HANDOVER drug_market_adjuster:",&
                        drug_market_adjuster, "->", handover_value
                    drug_market_adjuster=max(min(handover_value,2.d0),0.d0)

                case ("drug_price_start")
                    if (is_counterfactual==1) then
                        write(*,*) "HANDOVER drug_price_start:", &
                            price_of_addictive_good, "->", handover_value
                        price_of_addictive_good=max(min(handover_value,5.d0),10.d0**(-4))
                    else
                        write(*,*) "HANDOVER drug_price_start IGNORED on the benchmark", &
                            " path, where the price is the normalisation:", handover_value
                    end if

                ! THE TWO PER PARAMETER CAPS THAT HAD NO HANDOVER, added on
                ! the author's instruction of 13 September naming three rates at
                ! once -- omega_c and the drug death rate at 0.05 per cent a
                ! loop, b at 0.5.  omega_max_rel_step was already settable and
                ! these two were not, so two thirds of a single instruction
                ! needed a rebuild to apply.  The floor of 1e-5 and ceiling of 1
                ! are max_rel_step_all's, for the same reason: a cap of zero
                ! freezes a parameter silently, and a cap above one lets a step
                ! change a parameter's sign.
                case ("kappa_phi_d_max_rel_step")
                    write(*,*) "HANDOVER kappa_phi_d_max_rel_step:", &
                        kappa_phi_d_max_rel_step, "->", handover_value
                    kappa_phi_d_max_rel_step=max(min(handover_value,1.d0),10.d0**(-5))

                ! FIVE ADJUSTERS ARE READ FROM calibration_state.dat WITHOUT AN
                ! IOSTAT GUARD, so a resume OVERWRITES whatever the source sets
                ! and the run is calibrating with an adjuster nobody chose. On
                ! 16 September smallest_house_size_adjuster was set to 0.05 in
                ! the source to open h_2 on the author's *"set h2 to get 5-7%
                ! cost burdened"*; the resume handed back 0 from line 27 of the
                ! state file and a re-arm lifted it to 0.001, forty times slower
                ! than h_2's own 1 per cent cap allows, so h_2 could not travel
                ! from 0.41 per cent toward 6 in any tractable number of blocks.
                !
                ! A HANDOVER IS THE ONLY WAY TO SET THESE, because the handover
                ! is applied AFTER the state file is read. This case closes that
                ! trap for h_2's adjuster; the other four are left alone because
                ! nothing currently needs them and an unused case is one more
                ! thing to keep true.
                case ("multiple_find_max_rel_step")

                    multiple_find_max_rel_step=max(min(handover_value,1.d0),10.d0**(-5))

                case ("smallest_rental_max_rel_step")

                    smallest_rental_max_rel_step=max(min(handover_value,1.d0),10.d0**(-5))

                case ("max_food_cost_max_rel_step")

                    max_food_cost_max_rel_step=max(min(handover_value,1.d0),10.d0**(-5))

                case ("kappa_find_smi_max_rel_step")

                    kappa_find_smi_max_rel_step=max(min(handover_value,1.d0),10.d0**(-5))

                ! RELEASED 18 September, on the author's instruction: *"you can
                ! adjust pi_v a bit more to hit to the target"*. It needs a
                ! handover case rather than an edit to its declaration because
                ! voucher_probability_adjuster IS WRITTEN TO AND READ FROM
                ! calibration_state.dat, so a resume restores the pinned zero
                ! whatever the declaration says. The handover is applied AFTER
                ! the state is read, which is the only place a release takes.
                !
                ! WHY THE PIN NO LONGER HOLDS. It was pinned on 17 September on
                ! the author's own reading that pi_V is stable, and the n32 path
                ! quoted at its declaration backs that up -- overshoot to 0.291
                ! at block 8, then 0.266 from block 16 onward. That was the stock
                ! refilling. At kappa 4 it is NOT refilling: n71 reads 0.30474 at
                ! block 113, flat, 14.6 per cent over target. The reason for the
                ! pin was that the moment settles on its own, and in this economy
                ! it does not.
                case ("voucher_probability_adjuster")

                    voucher_probability_adjuster=max(min(handover_value,100.d0),0.d0)

                case ("max_food_cost_adjuster")

                    max_food_cost_adjuster=max(min(handover_value,100.d0),0.d0)

                case ("utility_cost_of_treatment_adjuster")

                    utility_cost_of_treatment_adjuster=max(min(handover_value,100.d0),0.d0)

                case ("kappa_find_smi_adjuster")

                    kappa_find_smi_adjuster=max(min(handover_value,100.d0),0.d0)

                case ("multiple_find_adjuster")

                    multiple_find_adjuster=max(min(handover_value,100.d0),0.d0)

                case ("smallest_house_size_adjuster")
                    write(*,*) "HANDOVER smallest_house_size_adjuster:",&
                        smallest_house_size_adjuster, "->", handover_value
                    smallest_house_size_adjuster=max(handover_value,0.d0)

                case ("addiction_scalar_max_rel_step")
                    write(*,*) "HANDOVER addiction_scalar_max_rel_step:", &
                        addiction_scalar_max_rel_step, "->", handover_value
                    addiction_scalar_max_rel_step=max(min(handover_value,1.d0),10.d0**(-5))

                ! THE GLOBAL PER LOOP CAP ON EVERY PARAMETER.
                case ("max_rel_step_all")
                    write(*,*) "HANDOVER max_rel_step_all:", &
                        max_rel_step_all, "->", handover_value
                    max_rel_step_all=max(min(handover_value,1.d0),10.d0**(-5))

                ! HOW FAR THETA MAY MOVE IN ONE LOOP. Settable so the cap can
                ! be tightened mid calibration without a rebuild.
                case ("omega_max_rel_step")
                    write(*,*) "HANDOVER omega_max_rel_step:", &
                        omega_max_rel_step, "->", handover_value
                    omega_max_rel_step=max(min(handover_value,1.d0),10.d0**(-5))

                case ("theta_max_rel_step")
                    write(*,*) "HANDOVER theta_max_rel_step:", &
                        theta_max_rel_step, "->", handover_value
                    theta_max_rel_step=max(min(handover_value,1.d0),10.d0**(-5))

                ! THE CHILD GAP SWITCH, for omega_c in the final round.
                case ("measure_child_gap")
                    write(*,*) "HANDOVER measure_child_gap:", &
                        measure_child_gap, "->", handover_value
                    measure_child_gap=max(min(nint(handover_value),1),0)

                ! THE SUD MORTALITY LEVEL, WHICH IS SETTABLE BUT WAS NOT
                ! HANDABLE. It is assigned at 8, the midpoint of the 6 to 10
                ! range the literature gives for all cause standardised
                ! mortality ratios in opioid use disorder, and it is the knob on
                ! what the disorder COSTS a household: survival is raised to the
                ! power of the multiplier, so the whole continuation value is
                ! what a using household puts at risk. That makes it the natural
                ! instrument for who is willing to use, and therefore for the
                ! average income of users, which the model puts at 0.31 of
                ! average against 0.74 in NSDUH.
                !
                ! The clamp is wide on purpose, 1 to 30, rather than the
                ! literature's 6 to 10. A search that cannot leave the range
                ! cannot report that the range is where the answer is not, and
                ! that is a finding worth being able to reach. 1 is no excess
                ! mortality at all, which is the floor the specification allows.
                !
                ! No rebuild is needed here: apply_param_handover runs before
                ! initialize_variables_and_grids, which is the one place
                ! build_mortality_multipliers is called from and where
                ! survival_probability is built out of it.
                case ("kappa_phi_d_level")
                    write(*,*) "HANDOVER kappa_phi_d_level:", kappa_phi_d_level, "->", handover_value
                    kappa_phi_d_level=max(min(handover_value,30.d0),1.d0)

                ! THE LAST TWO INTERNALLY CALIBRATED PARAMETERS THAT COULD NOT
                ! BE HANDED IN. The paper calibrates twenty four parameters
                ! internally; the search could set twenty one of them, so the
                ! food stamp ceiling and the recovery ratio were being carried
                ! at whatever the declaration said while their moments were
                ! counted as misses. A parameter that owns a moment and cannot
                ! be set is a parameter that cannot be calibrated.
                case ("max_food_cost")
                    write(*,*) "HANDOVER max_food_cost:", max_food_cost, "->", handover_value
                    max_food_cost=max(handover_value,0.d0)

                ! THE BASE RECOVERY HAZARD, MADE SETTABLE 11 September so that the
                ! disorder rate can be moved without moving the decision to use.
                !
                ! Three measured points show every instrument that makes drugs
                ! RISKIER -- value_of_life, addiction_onset_base -- lowers the
                ! MEASURED disorder rate, because households respond by not using
                ! at all. lambda_d and b are nearly collinear as a result, ratio
                ! 0.406, 0.400, 0.411 across those points, so two targets on them
                ! cannot both be hit from the extensive margin.
                !
                ! Recovery is the other side of the flow balance: in steady state
                ! onset*users = recovery*disordered, so this sets the STOCK of
                ! disordered given the FLOW of users. It is the natural candidate
                ! for the missing instrument.
                !
                ! The homeless rate follows automatically: it is computed at run
                ! time as mu_homeless times this, so the calibrated ratio is
                ! preserved. Behaviour-neutral at its declared 0.025.
                case ("probability_of_stopping_addiction")
                    write(*,*) "HANDOVER probability_of_stopping_addiction:",&
                        probability_of_stopping_addiction, "->", handover_value
                    probability_of_stopping_addiction=&
                        max(min(handover_value,1.d0),10.d0**(-6))

                case ("mu_homeless")
                    write(*,*) "HANDOVER mu_homeless:", mu_homeless, "->", handover_value
                    mu_homeless=max(min(handover_value,1.d0),0.d0)

                ! THE INSTRUMENTS THAT RAN AWAY AT THE CORNER, so a good
                ! starting point can be handed in rather than hand edited into a
                ! positional checkpoint. Measured against their own declared
                ! values after loops run at 75 per cent participation:
                ! lambda 33x, the treatment cost 106x, kappa_uem 23x and the
                ! employment multiplier 6x. A one per cent per loop trust region
                ! only makes sense from a sensible start, and these were not one.
                case ("money_cost_of_treatment")
                    write(*,*) "HANDOVER money_cost_of_treatment:", money_cost_of_treatment, "->", handover_value
                    money_cost_of_treatment=max(handover_value,0.d0)

                ! THE CEILING WAS 10 AND IT SILENTLY ATE FIVE HOURS OF SEARCH.
                !
                ! three_step's bound was raised 8 -> 20 on the author's
                ! instruction to open the parameters pinned at their bounds, and
                ! THIS clamp was not raised with it, so every handover above 10
                ! arrived as exactly 10. The trace says so precisely: the
                ! elasticity of tau_u to this parameter is -1.71 from 9.03 to
                ! 10.185 and +0.045 from 10.185 to 14.74. The break is AT 10, not
                ! near it.
                !
                ! It was read as a discrete policy function between treads --
                ! plausible, since take up IS an integer choice over a discrete
                ! state space -- and that reading was wrong. A clamp and a
                ! staircase look identical from the outside, and the way to tell
                ! them apart is to check the clamp, which is cheap, before
                ! theorising about the policy function, which is not. Every other
                ! driven instrument was swept for the same defect and none of
                ! them is at its ceiling.
                !
                ! 20 MATCHES three_step's BOUND, which is the point: one number
                ! in one place. Take up should reach zero well before it, since
                ! the lowest value of a whole period of life in this economy is
                ! about 5.4 utils and this is subtracted from a single period's
                ! flow utility.
                case ("utility_cost_of_treatment")
                    write(*,*) "HANDOVER utility_cost_of_treatment:",&
                        utility_cost_of_treatment, "->", handover_value
                    utility_cost_of_treatment=max(min(handover_value,20.d0),0.d0)

                case ("probability_becoming_unemployed")
                    write(*,*) "HANDOVER probability_becoming_unemployed:",&
                        probability_becoming_unemployed, "->", handover_value
                    probability_becoming_unemployed=&
                        max(min(handover_value,1.d0),10.d0**(-6))

                case ("multiple_of_probabilities_of_employment_if_addicted")
                    write(*,*) "HANDOVER employment multiplier:",&
                        multiple_of_probabilities_of_employment_if_addicted,&
                        "->", handover_value
                    multiple_of_probabilities_of_employment_if_addicted=&
                        max(min(handover_value,20.d0),1.d0)

                case ("multiple_find_if_addicted")
                    write(*,*) "HANDOVER multiple_find_if_addicted:",&
                        multiple_find_if_addicted, "->", handover_value
                    multiple_find_if_addicted=&
                        max(min(handover_value,100.d0),1.d0)

                case ("financial_grid_expander_positive")
                    write(*,*) "HANDOVER financial_grid_expander_positive:",&
                        financial_grid_expander_positive, "->", handover_value
                    financial_grid_expander_positive=max(min(handover_value,6.d0),1.d0)
                case ("rung_ratio_h3")
                    write(*,*) "HANDOVER rung_ratio_h3:", rung_ratio_h3, "->", handover_value
                    rung_ratio_h3=max(min(handover_value,6.d0),1.01d0)
                case ("rung_ratio_h4")
                    write(*,*) "HANDOVER rung_ratio_h4:", rung_ratio_h4, "->", handover_value
                    rung_ratio_h4=max(min(handover_value,9.d0),1.02d0)
                case ("newborn_endowment_scale")
                    write(*,*) "HANDOVER newborn_endowment_scale:",&
                        newborn_endowment_scale, "->", handover_value
                    newborn_endowment_scale=max(min(handover_value,50.d0),0.d0)

                case ("value_of_life")
                    write(*,*) "HANDOVER value_of_life:", value_of_life, "->", handover_value
                    value_of_life=max(min(handover_value,10.d0**(4)),10.d0**(-2))

                ! THE CONDITIONALITY EXPERIMENT'S FIVE HANDLES, added 8 September so
                ! Phase 1 runs as vectors rather than as five separate binaries.
                ! All five are inert while voucher_conditional_on_clean is 0,
                ! which is the benchmark, so adding them changes no number.
                case ("voucher_conditional_on_clean")
                    write(*,*) "HANDOVER voucher_conditional_on_clean:",&
                        voucher_conditional_on_clean, "->", handover_value
                    voucher_conditional_on_clean=&
                        max(min(nint(handover_value),1),0)

                case ("voucher_conditional_on_clean_just_addicts")
                    write(*,*) "HANDOVER voucher_conditional_on_clean_just_addicts:",&
                        voucher_conditional_on_clean_just_addicts, "->", handover_value
                    voucher_conditional_on_clean_just_addicts=&
                        max(min(nint(handover_value),1),0)

                ! A PROBABILITY, so the clamp is [0,1] and not a bound picked for
                ! this parameter. 1 means the test never misses, 0 that it never
                ! detects, and both are admissible ends of the experiment.
                case ("probability_of_detection")
                    write(*,*) "HANDOVER probability_of_detection:",&
                        probability_of_detection, "->", handover_value
                    probability_of_detection=max(min(handover_value,1.d0),0.d0)

                case ("probability_of_false_positive")
                    write(*,*) "HANDOVER probability_of_false_positive:",&
                        probability_of_false_positive, "->", handover_value
                    probability_of_false_positive=max(min(handover_value,1.d0),0.d0)

                ! CLAMPED BELOW AT ZERO ONLY. The author asked for the cost of
                ! testing all eligibles, and the Arkansas figure the default comes
                ! from is one point in a wide range, so an upper bound here would
                ! be a guess constraining the very thing the experiment varies.
                ! THE AGGREGATE EXTERNALITY'S PRICE. Zero switches it off, in the
                ! benchmark and in the arms alike, which is the only way to run
                ! the comparison: switched off in the arms alone it would price
                ! two economies on two different criteria.
                ! A HANDOVER CASE SO THE ARM COSTS NO REBUILD, for the same
                ! reason kappa_x and rho_intergenerational have one. It is an
                ! integer switch, so anything non-zero reads as on.
                case ("internalise_homelessness_cost")
                    write(*,*) "HANDOVER internalise_homelessness_cost:",&
                        internalise_homelessness_cost, "->", nint(handover_value)
                    internalise_homelessness_cost=max(min(nint(handover_value),1),0)

                ! PIN OR RELEASE OMEGA_C WITHOUT A REBUILD. This flag gates
                ! BOTH the omega_c = 0 counterfactual and the bracket's update,
                ! so at 1 omega_c stays exactly where the handover put it.
                !
                ! Needed for the author's own sequence, 18 September: *"run the
                ! whole model with the pinned parameters and just choose deltad
                ! to match the odds ratio. That would be then pinned when we
                ! look for omegac"*. The delta_d stage runs at omega_c = 0, and
                ! at omega_c = 0 the measured gap is zero by construction, so a
                ! live bracket reads a gap of 0 against a target of 0.18343 and
                ! steps omega_c straight off zero. Pinning is the only way to
                ! hold that stage at the economy it is supposed to measure.
                case ("omega_c_is_pinned")
                    write(*,*) "HANDOVER omega_c_is_pinned:",&
                        omega_c_is_pinned, "->", nint(handover_value)
                    omega_c_is_pinned=max(min(nint(handover_value),1),0)

                case ("frozen_stop_tolerance")
                    write(*,*) "HANDOVER frozen_stop_tolerance:",&
                        frozen_stop_tolerance, "->", handover_value
                    frozen_stop_tolerance=max(handover_value,0.d0)

                case ("frozen_stop_after_blocks")
                    write(*,*) "HANDOVER frozen_stop_after_blocks:",&
                        frozen_stop_after_blocks, "->", nint(handover_value)
                    frozen_stop_after_blocks=max(nint(handover_value),0)

                case ("freeze_all_but_omega_c")
                    write(*,*) "HANDOVER freeze_all_but_omega_c:",&
                        freeze_all_but_omega_c, "->", nint(handover_value)
                    freeze_all_but_omega_c=max(min(nint(handover_value),1),0)

                case ("kappa_x")
                    write(*,*) "HANDOVER kappa_x:", kappa_x, "->", handover_value
                    kappa_x=max(handover_value,0.d0)

                ! THE CHILD EXTERNALITY'S SWITCH. It already exists and is
                ! already used for omega's own counterfactual; it simply had no
                ! way in from a point vector.
                case ("child_penalty_off")
                    write(*,*) "HANDOVER child_penalty_off:", child_penalty_off, "->", handover_value
                    child_penalty_off=max(min(nint(handover_value),1),0)

                case ("adjust_taxes")
                    write(*,*) "HANDOVER adjust_taxes:", adjust_taxes, "->", handover_value
                    adjust_taxes=max(min(nint(handover_value),1),0)

                case ("cost_per_drug_test")
                    write(*,*) "HANDOVER cost_per_drug_test:",&
                        cost_per_drug_test, "->", handover_value
                    cost_per_drug_test=max(handover_value,0.d0)

                case ("penalty_child_addicted")
                    write(*,*) "HANDOVER penalty_child_addicted:",&
                        penalty_child_addicted, "->", handover_value
                    penalty_child_addicted=max(min(handover_value,penalty_child_cap),0.d0)

                ! BLOCK A, SO IT CAN BE PINNED WHILE A LATER BLOCK IS SWEPT.
                ! Income, hours, wealth and the tax rate are upstream of every
                ! other moment, and while block C was being swept they were
                ! running at whatever the corner had left them: labour supply
                ! 0.4567 against 0.400, wealth over output 4.23 against 3. A
                ! block cannot be held if the handover cannot name it.
                case ("financial_grid_expander_negative")
                    write(*,*) "HANDOVER financial_grid_expander_negative:",&
                        financial_grid_expander_negative, "->", handover_value
                    financial_grid_expander_negative=min(max(handover_value,1.0d0),6.0d0)

                case ("discount_factor")
                    write(*,*) "HANDOVER discount_factor:", discount_factor, "->", handover_value
                    discount_factor=min(max(handover_value,0.5d0),1.05d0)

                case ("max_age_to_choose_homelessness")
                    write(*,*) "HANDOVER max_age_to_choose_homelessness:",&
                        max_age_to_choose_homelessness, "->", handover_value
                    max_age_to_choose_homelessness=&
                        max(min(nint(handover_value),life_span),1)

                case ("addiction_onset_base")
                    write(*,*) "HANDOVER addiction_onset_base:",&
                        addiction_onset_base, "->", handover_value
                    addiction_onset_base=max(min(handover_value,1.d0),0.d0)

                case ("rr_homeless_old_level")
                    write(*,*) "HANDOVER rr_homeless_old_level:",&
                        rr_homeless_old_level, "->", handover_value
                    rr_homeless_old_level=max(min(handover_value,50.d0),0.d0)

                case ("rr_homeless_hold_age")
                    write(*,*) "HANDOVER rr_homeless_hold_age:",&
                        rr_homeless_hold_age, "->", handover_value
                    rr_homeless_hold_age=max(min(nint(handover_value),85),0)

                case ("homeless_death_risk_flat_in_age")
                    write(*,*) "HANDOVER homeless_death_risk_flat_in_age:",&
                        homeless_death_risk_flat_in_age, "->", handover_value
                    homeless_death_risk_flat_in_age=max(min(nint(handover_value),2),0)

                case ("homeless_excess_death_risk")
                    write(*,*) "HANDOVER homeless_excess_death_risk:",&
                        homeless_excess_death_risk, "->", handover_value
                    homeless_excess_death_risk=max(min(handover_value,0.5d0),0.d0)

                case ("number_of_beta_types")
                    write(*,*) "HANDOVER number_of_beta_types:",&
                        number_of_beta_types, "->", handover_value
                    number_of_beta_types=max(min(nint(handover_value),2),1)

                case ("discount_factor_impatient")
                    write(*,*) "HANDOVER discount_factor_impatient:",&
                        discount_factor_impatient, "->", handover_value
                    discount_factor_impatient=max(min(handover_value,0.999d0),0.5d0)

                case ("relative_share_of_leisure")
                    write(*,*) "HANDOVER relative_share_of_leisure:",&
                        relative_share_of_leisure, "->", handover_value
                    relative_share_of_leisure=min(max(handover_value,0.01d0),1000.d0)

                case ("labor_income_tax_rate")
                    write(*,*) "HANDOVER labor_income_tax_rate:",&
                        labor_income_tax_rate, "->", handover_value
                    labor_income_tax_rate=max(min(handover_value,2.d0),0.d0)

                case ("relative_share_of_housing")
                    write(*,*) "HANDOVER relative_share_of_housing:",&
                        relative_share_of_housing, "->", handover_value
                    relative_share_of_housing=min(max(handover_value,0.01d0),0.9d0)

                case ("sd_permanent_productivity")
                    write(*,*) "HANDOVER sd_permanent_productivity:",&
                        sd_permanent_productivity, "->", handover_value
                    sd_permanent_productivity=max(min(handover_value,3.d0),10.d0**(-2))

                case ("penalty_child_homeless")
                    write(*,*) "HANDOVER penalty_child_homeless:",&
                        penalty_child_homeless, "->", handover_value
                    penalty_child_homeless=max(min(handover_value,0.6d0),0.d0)

                case ("increased_prob_of_voucher_if_homeless_and_addicted")

                    write(*,*) "HANDOVER increased_prob_of_voucher_if_homeless_and_addicted:",&

                        increased_prob_of_voucher_if_homeless_and_addicted, "->", handover_value

                    increased_prob_of_voucher_if_homeless_and_addicted=&

                        max(min(handover_value,1.d0),0.d0)


                case ("probability_of_voucher_benchmark_used")
                    write(*,*) "HANDOVER voucher probability:",&
                        probability_of_voucher_benchmark_used, "->", handover_value
                    probability_of_voucher_benchmark_used=&
                        max(min(handover_value,1.d0),10.d0**(-5))

                case ("relative_share_of_addiction_1")
                    write(*,*) "HANDOVER relative_share_of_addiction_1:",&
                        relative_share_of_addiction_1, "->", handover_value
                    relative_share_of_addiction_1=max(min(handover_value,theta_hi),theta_lo)
                    call apply_gamma_tie()

                case default
                    write(*,*) "HANDOVER IGNORED, unknown name: ", trim(handover_name)

                end select

            end do

            close(79,status='delete')

            ! BANK THE HANDOVER BEFORE THE FIRST SOLVE, OR IT CAN BE LOST. The
            ! file is deleted as it is read, and calibration_state.dat is only
            ! rewritten at the END of a loop. A run that is killed part way
            ! through its first solve therefore loses the handover entirely: the
            ! file is gone, the state still holds the old value, and the next
            ! launch resumes at the value the handover was meant to replace with
            ! nothing anywhere saying so. That happened to h_2, which was handed
            ! 0.0015, killed mid solve, and came back at 0.0048.
            call write_calibration_state()
            write(*,*) "handover banked into calibration_state.dat before the first solve"

        end if

        ! APPLIED LAST, AFTER THE STATE FILE AND AFTER THE HANDOVER, so neither
        ! can put an adjuster back. The state file is read first, the handover
        ! second, and this third; anything else would leave a resumed run with
        ! live instruments it was launched to hold still.
        if (freeze_all_but_omega_c==1) then

            addiction_scalar_adjuster=0.d0
            advantage_to_owning_adjuster=0.d0
            convexity_of_rental_company_adjuster=0.d0
            discount_factor_adjuster=0.d0
            discount_factor_impatient_adjuster=0.d0
            discount_factor_on_child_adjuster=0.d0
            ! drug_market_adjuster IS NOT FROZEN, AND IT USED TO BE. It is a
            ! MARKET CLEARING instrument, not a calibration adjuster: in
            ! clear_drug_market the counterfactual's price step is
            !     step_1 = price_of_addictive_good + drug_market_adjuster*gap_1
            ! so zeroing it pins the drug price and the market can never clear.
            !
            ! MEASURED, 19 September, on the omega_c = 1 plus internalisation
            ! arm: price_of_addictive_good printed 1.00000000 on all nineteen
            ! loops while distance_drug_market sat at 0.634 against a rule of
            ! 5e-3. The secant branch cannot rescue it either -- it needs two
            ! distinct prices and there is only ever one. The arm would have run
            ! to its 80 loop cap without converging.
            !
            ! THE BENCHMARK IS UNAFFECTED EITHER WAY. With is_counterfactual = 0
            ! clear_drug_market normalises the shifter, sets the price to the
            ! benchmark's own and sets distance_drug_market to zero without ever
            ! reading the adjuster -- n90 printed "drug_supply_shifter
            ! (normalised)=" on all twenty seven blocks. So this changes no
            ! calibration result and n90 stands.
            !
            ! rent_to_price_adjuster below stays frozen: distance_rent_to_price
            ! is a calibration target on the data's rent to price ratio, which
            ! is a different object from distance_rental_market.
            employment_multiplier_adjuster=0.d0
            fixed_cost_to_moving_adjuster=0.d0
            housing_status_grid_expander_adjuster=0.d0
            inheritance_amount_adjuster=0.d0
            kappa_find_smi_adjuster=0.d0
            kappa_phi_d_level_adjuster=0.d0
            kappa_uem_adjuster=0.d0
            kkk_sigma_scale_adjuster=0.d0
            labor_income_tax_rate_adjuster=0.d0
            lambda_addiction_adjuster=0.d0
            lambda_m_adjuster=0.d0
            largest_house_size_adjuster=0.d0
            max_food_cost_adjuster=0.d0
            max_initial_endowment_adjuster=0.d0
            minimum_inheritance_adjuster=0.d0
            money_cost_of_treatment_adjuster=0.d0
            mu_homeless_adjuster=0.d0
            multiple_find_adjuster=0.d0
            newborn_endowment_adjuster=0.d0
            onset_base_adjuster=0.d0
            penalty_child_addicted_adjuster=0.d0
            penalty_child_homeless_adjuster=0.d0
            probability_of_becoming_addicted_adjuster=0.d0
            relative_share_of_housing_adjuster=0.d0
            relative_share_of_leisure_adjuster=0.d0
            rent_to_price_adjuster=0.d0
            rho_d_adjuster=0.d0
            rho_intergenerational_adjuster=0.d0
            rho_m_adjuster=0.d0
            scaling_of_ss_adjuster=0.d0
            sd_permanent_productivity_adjuster=0.d0
            separation_rate_adjuster=0.d0
            size_homelessness_adjuster=0.d0
            smallest_house_size_adjuster=0.d0
            smi_onset_level_adjuster=0.d0
            standard_deduction_adjuster=0.d0
            utility_cost_of_treatment_adjuster=0.d0
            utility_improvement_adjuster=0.d0
            value_of_life_adjuster=0.d0
            voucher_probability_adjuster=0.d0

            write(*,*) "FROZEN: every adjuster zeroed except weight_on_child's.",&
                " Only omega_c is calibrated; delta_d is held by hand."

        end if

    end subroutine


    subroutine write_calibration_distribution()

    ! THE DISTRIBUTION IS THE OTHER HALF OF A WARM START, and it is the
    ! expensive half.
    !
    ! A resumed run that recovers the parameters still pays 655 sweeps to
    ! rebuild the distribution from the age one cross section, and those
    ! sweeps are most of a loop. The converged distribution of the last
    ! completed loop is a far better guess for the next parameter vector than
    ! a freshly initialised one, because consecutive vectors differ by a
    ! damped step.
    !
    ! Written on the same schedule as the parameters and to a temporary first,
    ! for the same reason. It is a large file, so it is written once per loop
    ! and not once per sweep.

    use Global_Vars

    implicit none

    integer :: dist_index_1
    character*1 :: string_used_1

    do dist_index_1=1,2

        write(string_used_1,'(i1)') dist_index_1

        open(unit=73,file="calibration_distribution"//trim(string_used_1)//".tmp",&
            action='write',status='replace')
            write(73,'(F30.28)') distribution_stationary(dist_index_1)%vector_transition_real(1,:,:,:,:,:,:)
        close(73)

        call rename("calibration_distribution"//trim(string_used_1)//".tmp",&
            "calibration_distribution"//trim(string_used_1)//".dat")

    end do

    ! THE SHAPE STAMP, AND WHY THE WARM START IS WORTHLESS WITHOUT IT. The two
    ! files are a bare list of numbers with nothing in them that says what shape
    ! they were written at, and the reader fills an array of whatever shape the
    ! build it is running in happens to have. So a run at a different asset grid
    ! reads them anyway. If the new array is SMALLER the read succeeds and
    ! silently loads a distribution that is the first fraction of each slice of
    ! another one, which is not a distribution: an asset grid cut from forty
    ! positive points to twenty five loaded a warm start summing to 45.7 against
    ! the 51.4 it was written with, took 2445 sweeps to grind back from it, and
    ! the moments it then reported were compared against another build's and read
    ! as evidence about the grid. They were evidence about this bug. If the new
    ! array is LARGER the read hits end of file and the run dies outright, which
    ! is the same bug wearing a louder coat.
    !
    ! So the count of elements is written beside them, and a warm start whose
    ! count does not match is refused.
    open(unit=73,file="calibration_distribution_shape.tmp",action='write',status='replace')
        write(73,*) size(distribution_stationary(1)%vector_transition_real(1,:,:,:,:,:,:))
    close(73)

    call rename("calibration_distribution_shape.tmp","calibration_distribution_shape.dat")

    end subroutine

    subroutine read_calibration_distribution()

    ! Loads the warm start if it is there, and records that it did, because the
    ! caller has to skip initialize_feasible_distribution when it did. Both
    ! files have to be present: half a warm start is two distributions from
    ! different loops, which is not a distribution of anything.

    use Global_Vars

    implicit none

    integer :: dist_index_1,stamped_size_1,actual_size_1
    logical :: exists_1,exists_2,exists_3
    character*1 :: string_used_1

    have_warm_distribution=0

    inquire(file="calibration_distribution1.dat",exist=exists_1)
    inquire(file="calibration_distribution2.dat",exist=exists_2)
    inquire(file="calibration_distribution_shape.dat",exist=exists_3)

    if (.NOT. (exists_1 .AND. exists_2)) then

        write(*,*) "no warm start distribution, initialising from the age one cross section"

        return

    end if

    ! THE SHAPE HAS TO MATCH. See write_calibration_distribution for what
    ! happens when it does not, which is that nothing happens: the read
    ! succeeds and the distribution is wrong. An unstamped pair is refused
    ! rather than trusted, because a pair from before the stamp existed cannot
    ! be told apart from a pair written at another grid.
    actual_size_1=size(distribution_stationary(1)%vector_transition_real(1,:,:,:,:,:,:))

    if (.NOT. exists_3) then

        write(*,*) "WARM START REFUSED: the distribution files carry no shape stamp, &
            &so the grid they were written at is unknown. Initialising from the age &
            &one cross section."

        return

    end if

    open(unit=74,file="calibration_distribution_shape.dat",action='read')
        read(74,*) stamped_size_1
    close(74)

    if (stamped_size_1/=actual_size_1) then

        write(*,*) "WARM START REFUSED: written at", stamped_size_1, &
            "elements, this build wants", actual_size_1, &
            ". Initialising from the age one cross section."

        return

    end if

    do dist_index_1=1,2

        write(string_used_1,'(i1)') dist_index_1

        open(unit=74,file="calibration_distribution"//trim(string_used_1)//".dat",action='read')
            read(74,'(F30.28)') distribution_stationary(dist_index_1)%vector_transition_real(1,:,:,:,:,:,:)
        close(74)

        distribution_guess(dist_index_1)%vector_transition_real(1,:,:,:,:,:,:)=&
            distribution_stationary(dist_index_1)%vector_transition_real(1,:,:,:,:,:,:)

    end do

    have_warm_distribution=1

    write(*,*) "warm start distribution loaded, sum=", &
        sum(distribution_guess(1)%vector_transition_real(1,:,:,:,:,:,:))+&
        sum(distribution_guess(2)%vector_transition_real(1,:,:,:,:,:,:))

    end subroutine

    subroutine calibrating_model()
    
        use Global_Vars
        
        implicit none
        
        logical :: file_exists
        
        real(8) :: mass_at_top_financial,a,b,c,d
        ! The value a parameter held before its bracket moved it, so the
        ! global governor can cap the relative step. See max_rel_step_all.
        real(8) :: cap_old_1
        real(8) :: sud_smi_ratio_1=0
        real(8) :: mean_drug_quantity_1,onset_at_mean_1,onset_step_1,treatment_step_1,&
            separation_step_1,b_move_1,lambda_move_1
        character*1 :: string_used
        integer :: last_period_of_life,addiction_index
        ! Its own name and not the file's shared i: the projection below runs
        ! inside the beta-type pass loop, where i is live.
        integer :: i_beta_floor
        integer, dimension(1) :: index_drug_1
                                
        simulation_ended=0

        ! Pick up where a killed run left off, if it left anything.
        call read_calibration_state()

        ! AND THEN THE HANDOVER, UNCONDITIONALLY. This call is the fix for the
        ! defect described in apply_param_handover: the seed must be applied on
        ! a first run in a fresh container exactly as it is on a resume, or a
        ! point measured on such a container is a point measured at the
        ! declared values with the vector it was asked for thrown away.
        call apply_param_handover()

        ! THE SMOOTH HAZARD NEEDS THE TABULATED EXPECTATION. With the hoist off
        ! the two continuations are never formed separately, so there is nothing
        ! to price the drug risk against and the household would face a hazard
        ! rising in v that it does not respond to, which is the defect this was
        ! meant to fix wearing a different hat. Stop rather than run: a model
        ! that still produces numbers is exactly how this would go unnoticed.
        if ((smooth_addiction_hazard==1) .AND. (hoist_expectation==0)) then

            write(*,*) "smooth_addiction_hazard needs hoist_expectation=1. stopping."
            stop

        end if

        call cpu_time(simulation_start_time)
        
        lump_sum_transfer(1)=0
        
        model_average_owner_occupied_unit_size(1)=calibrated_stationary_housing_price*&
            average_owner_occupied_house_size_calibrated
            
        model_average_rental_unit_size(1)=0.116

        loop_count=0  

        ! THE FIRST BLOCK'S FREEZE, AFTER THE HANDOVER AND BEFORE THE FIRST
        ! LOOP. After, so a point file can still hand a value in for a frozen
        ! parameter; before, so nothing has moved yet when it is applied.
        call apply_first_block_freeze()

        model_bequests(1)=2.5238247842094039
        
        model_drug_threshold(1)=drug_threshold_guess
        model_average_income(1)=average_labor_income_calibrated
        model_average_income_plus_assets(1)=average_labor_income_calibrated
        model_average_income_plus_all_assets(1)=average_labor_income_calibrated
        model_average_labour_income(1)=average_labor_income_calibrated
        call set_newborn_age_transfer(1)
        call set_renter_floor(1)
        model_average_labour_income_by_employment(1,:)=average_labor_income_by_employment_calibrated
        median_income(1)=median_income_calibrated
        model_average_financial(1)=average_financial_calibrated
        model_average_net_wealth(1)=average_net_wealth_calibrated
        
        call allocate_matrix()
        
        call initialize_variables_and_grids()
        call GKKOC_intergenerational_employment_process(1)
        call initialize_financial_grid(1)
                
        call initialize_feasible_distribution(1)
            
        if (use_old_results==1) then
        
            call upload_vars(1)
            
        else
        
            housing_price(1)=calibrated_stationary_housing_price
                    
            if (fix_rent==0) then
                rent(1,:)=rent_to_housing_price*housing_price(1)*1.05
            else
                ! FIXED RENT STILL HAS TO BE SET. rent has no initialiser, so
                ! guarding the assignments that would move it also removed the
                ! one that gave it a value, and it ran on whatever was in memory.
                rent(1,:)=rent_calibrated(:)
            end if
                                          
            risk_free_rate(1)=calibrated_risk_free_rate
            mortgage_interest_rate(1)=risk_free_rate(1)+mortgage_interest_gap
            
            model_average_labour_income(1)=average_labor_income_calibrated
            call set_newborn_age_transfer(1)
            call set_renter_floor(1)
        call set_renter_floor(1)
            total_housing_demand(1)=calibrated_housing_stock
            
            total_rental_demand(1,:)=total_rental_supply_calibrated
            total_rental_supply(1,:)=total_rental_supply_calibrated
            
        end if
                
        call function_of_utility_advantage_from_homeowning(1)
                                               
        call set_SS_benefits(1)
        
        call function_of_utility_advantage_from_homeowning(1)
        call initialize_financial_grid(1)
                
        distance_value_function=1
        distance_lambda_m=1
        distance_kappa_uem=1
        distance_kappa_find_smi=1
        distance_b_smi_multiple=1
        distance_rho_m=1
        distance_rho_d=1
        distance_discount_factor=1

        ! The convexity of the rental company is not calibrated, its adjuster is
        ! zero, and its distance was assigned in exactly one place: the branch
        ! taken when the parameters are held fixed. On the calibrating path it
        ! was never written at all, so the loop condition was testing
        ! uninitialised memory against 1e-3 and the sweep could not terminate.
        distance_convexity_of_rental_company=0

        distance_discount_factor_on_child=1
        distance_minimum_inheritance=1
        distance_advantage_to_owning=1
        distance_relative_share_of_housing=1
        distance_relative_share_of_leisure=1
        distance_standard_deduction=1
        distance_housing_status_grid_expander=1
        distance_largest_house_size=1
        distance_probability_of_becoming_addicted=1
        distance_lambda_addiction=1
        distance_utility_cost_of_treatment=1
        distance_relative_share_of_addiction_1=1
        distance_addiction_scalar=1
        distance_value_of_life=1
        distance_max_food_cost=1
        distance_voucher_probability=1
        distance_separation_rate=1
        distance_employment_multiplier=1
        distance_rent_to_price=1
        distance_smallest_house_size=1
        distance_rental_market=1
        distance_fixed_cost_to_moving=1
        distance_average_labor_income=1
        distance_inheritance_amount=1
        distance_size_homelessness=1
        
        do i=1,2
        
            value_function_guess(i)%vector_youngest_real(:,:,:,:,:)=0
            value_function(i)%vector_transition_real(1,:,:,:,:,:,:)=0
            
        end do
                                                          
        write(*,*) "mortgage_deductibility=", mortgage_deductibility
        write(*,*) "mortgage_interest_rate=", mortgage_interest_rate(1)
        write(*,*) "risk_free_rate=", risk_free_rate(1)
        write(*,*) "property_tax(1)=", property_tax(1)
        write(*,*) "infinite_elasticity_of_rental_supply=", infinite_elasticity_of_rental_supply
        write(*,*) "life_span=", life_span
        write(*,*) "retirement_span=", retirement_span    
        write(*,*) "discount_factor=", discount_factor
        write(*,*) "discount_factor_on_child=", discount_factor_on_child
        write(*,*) "minimum_inheritance=", minimum_inheritance
        write(*,*) "size_homelessness=", size_homelessness
        write(*,*) "labor_income_tax_rate=", labor_income_tax_rate
        write(*,*) "curvature_of_labor_income_taxes=", curvature_of_labor_income_taxes
        write(*,*) "rent_to_housing_price=", rent_to_housing_price
        write(*,*) "personal_deduction=", personal_exemption
        write(*,*) "standard_deduction=", standard_deduction      
        write(*,*) "rent=",rent(1,:)
        write(*,*) "lump_sum_transfer=", lump_sum_transfer(1)
        write(*,*) "minimum_downpayment=", minimum_downpayment
        write(*,*) "max_amortization_years=", max_amortization_years
        write(*,*) "model_average_owner_occupied_unit_size(1)=", model_average_owner_occupied_unit_size(1)
        write(*,*) "smallest_house_size=", smallest_house_size
        write(*,*) "housing_size(index_of_smallest_house_hhld_can_buy)=", housing_size(max(min(index_of_smallest_house_hhld_can_buy,housing_status_grid_size-1),lowest_housing_grid_point))
        write(*,*) "c_1=", c_1
        write(*,*) "c_min=", c_min
        write(*,*) "cutoff_housing_investment=", cutoff_housing_investment
        write(*,*) "infinite_elasticity_of_rental_supply=", infinite_elasticity_of_rental_supply
        write(*,*) "calibration"
        write(*,*) "advantage_to_owning=", advantage_to_owning
        write(*,*) "unconditional_employment_probability=", unconditional_employment_probability
                
        if (use_old_results==0) then
                    
            if (fix_rent==0) then
                rent(1,:)=housing_price(1)*himmelberg_etal_rent_to_price
            else
                rent(1,:)=rent_calibrated(:)
            end if
            
        end if
        
        ! TRACKS THE RENT rather than repeating its value. Hardcoded, this
        ! silently kept the old level after p_r was renormalised.
        model_average_rent(1)=rent(1,0)
        
        call set_smallest_house_size()
        
        call function_of_utility_advantage_from_homeowning(1)
                 
        write(*,*) "rent=", rent(1,:)
                  
        write(*,*) "property_tax=", property_tax
        write(*,*) "max_debt_to_income_ratio=", max_debt_to_income_ratio
        write(*,*) "max_debt_to_income_ratio_below_80=", max_debt_to_income_ratio_below_80
        write(*,*) "smallest_house_size=", smallest_house_size
        write(*,*) "housing_size(smallest_house_to_buy)=", housing_size(max(min(index_of_smallest_house_hhld_can_buy,housing_status_grid_size-1),lowest_housing_grid_point))
        write(*,*) "lowest_housing_grid_point=", lowest_housing_grid_point
        write(*,*) "employment_grid=", employment_grid(1,:)
        write(*,*) "value_of_initial_assets=", value_of_initial_assets
        write(*,*) "initial_endowment=", initial_endowment      
        write(*,*) "standard_deduction=", standard_deduction
        write(*,*) "personal_exemption=", personal_exemption
        write(*,*) "model_average_labour_income=", model_average_labour_income(1)
        write(*,*) "average_labor_income_calibrated=", average_labor_income_calibrated
        write(*,*) "weight_on_labor_income=", weight_on_labor_income
        write(*,*) "inheritance_amount=", inheritance_amount
        write(*,*) "relative_share_of_leisure=", relative_share_of_leisure
        
        INQUIRE(FILE="total_rental_demand"//trim(long_run_simulation)//".dat", EXIST=file_exists)
                
!        if ((re_calibrate_management_costs==1) .AND. (zero_elasticity==0) .AND. &
!            (infinite_elasticity_of_rental_supply==0) .AND. (file_exists)) then
!        
!            open(unit=39,file="total_rental_demand"//trim(long_run_simulation)//".dat",action='read')
!                read(39,'(F15.12)') total_rental_demand(1,:)
!            close(39)
!            
!            do j=0,have_two_rental_markets
!                        
!                call solve_elasticity_of_rental_housing(1,convexity_of_rental_company(j),j)
!                        
!                rental_management_costs=&
!                    (rent(1,j)-housing_price(1)*&
!                    (risk_free_rate(1)+housing_depreciation_rate+property_tax(1)+&
!                    property_tax_on_rental_housing)/(1+risk_free_rate(1)))/&
!                    ((total_rental_demand_segmented(1,j)**&
!                    (convexity_of_rental_company(j)-1))*convexity_of_rental_company(j))
!                    
!            end do
!        
!            open(unit=27,file="rental_management_costs"//trim(file_number)//".dat",status='replace')
!                write(27,'(F30.29)') rental_management_costs
!            close(27)
!            
!            open(unit=27,file="convexity_of_rental_company"//trim(file_number)//".dat",status='replace')
!                write(27,'(F15.12)') convexity_of_rental_company
!            close(27)
!                                    
!        end if
        
        write(*,*) "rental_management_costs=", rental_management_costs
        write(*,*) "file_number=", file_number
        write(*,*) "fraction_to_repay=", fraction_to_repay         
        write(*,*) "prepayment_penalty_starts_from=", prepayment_penalty_starts_from
        write(*,*) "file_number=", file_number
        write(*,*) "empirical_housing_supplpy_elasticity=", empirical_housing_supplpy_elasticity
        write(*,*) "replacement_rate_ui=", replacement_rate_ui
        write(*,*) "size_homelessness=", size_homelessness
        write(*,*) "model_average_financial=", model_average_financial(1)
        write(*,*) "model_average_net_wealth=", model_average_net_wealth(1)
        write(*,*) "relative_share_of_addiction=", relative_share_of_addiction_2
        write(*,*) "relative_share_of_consumption_2=", relative_share_of_consumption_2
        write(*,*) "relative_share_of_housing_2=", relative_share_of_housing_2
        write(*,*) "relative_share_of_addiction_2=", relative_share_of_addiction_2
        write(*,*) "relative_share_of_consumption_1=", relative_share_of_consumption_1
        write(*,*) "relative_share_of_housing_1=", relative_share_of_housing_1
        write(*,*) "relative_share_of_addiction_1=", relative_share_of_addiction_1
        write(*,*) "sum 2=", relative_share_of_consumption_2+relative_share_of_housing_2+relative_share_of_addiction_2
        write(*,*) "sum 1=", relative_share_of_consumption_1+relative_share_of_housing_1+relative_share_of_addiction_1
        write(*,*) "model_ss_benefits=", model_ss_benefits
        write(*,*) "price_of_addictive_good=", price_of_addictive_good
        write(*,*) "hello1"
        write(*,*) "expected_age_non_addicted=", expected_age_non_addicted+25
        write(*,*) "expected_age_homeless=", expected_age_homeless+25
        write(*,*) "expected_age_addicted=", expected_age_addicted+25
        write(*,*) "expected_age_homeless_and_addicted=", expected_age_homeless_and_addicted+25
                
        previous_average_labor_income=model_average_labour_income(1)
        previous_median_income=median_income(1)
        previous_average_net_wealth=model_average_net_wealth(1)
        previous_inheritance_amount=inheritance_amount
        
        write(*,*) "adjusted_probability=", adjusted_probability(:)
        write(*,*) "probability_of_voucher=", probability_of_voucher
        write(*,*) "addiction_scalar_1=", addiction_scalar_1
        
        do i=1,employment_grid_size
            write(*,*) "employment_grid(",i,")=", employment_grid(1,i)
        end do
        
        do i=1,employment_grid_size
            write(*,*) "employment_grid(",i,")=", employment_grid(30,i)
        end do
        
        write(*,*) "increased_risk_of_death_addicted=", increased_risk_of_death_addicted
        write(*,*) "multiple_of_probabilities_of_employment_if_addicted=", multiple_of_probabilities_of_employment_if_addicted
        write(*,*) "relative_share_of_addiction_2=", relative_share_of_addiction_2
        write(*,*) "relative_share_of_addiction_1=", relative_share_of_addiction_1
        write(*,*) "size_of_penalty=", size_of_penalty
        write(*,*) "voucher_probabilities=", voucher_probabilities(0,1,1,:)
        write(*,*) "voucher_probabilities=", voucher_probabilities(1,1,1,:)
        write(*,*) "voucher_probabilities_benchmark=", voucher_probabilities_benchmark(0,1,1,:)
        write(*,*) "voucher_probabilities_benchmark=", voucher_probabilities_benchmark(1,1,1,:)
        
        write(*,*) "increased_risk_of_death_addicted*(1-sum(actual_survival_probability)/life_span)=", &
            increased_risk_of_death_addicted*(1-sum(actual_survival_probability)/life_span)
            
        do i=1,bins_drug_spending_relative_to_average
        
            drug_spending_relative_to_average(i)=(i-1)/(real(bins_drug_spending_relative_to_average)/real(100))
        
        end do
        
        index_drug_1(1)=min(max(minloc(drug_spending_relative_to_average(:)-0.5,1,&
            mask=drug_spending_relative_to_average(:)-0.5>0),1),&
            bins_drug_spending_relative_to_average) 

        ! THE WARM START IS READ HERE AND NOT WITH THE PARAMETERS, because it
        ! writes into distribution_stationary and distribution_guess and those do
        ! not exist until allocate_matrix has run. Reading it beside
        ! read_calibration_state, which only moves scalars, wrote into unallocated
        ! derived type components and segfaulted before the first line of output.
        ! The symptom was a binary that had just run fine crashing on startup, and
        ! the only thing that had changed was that a previous loop had left a
        ! checkpoint on disk for it to read.
        call apply_gamma_tie()

        call read_calibration_distribution()

        ! THE SWEEP'S GRID, READ RATHER THAN COMPILED IN, so a container that
        ! rebuilds mid sweep resumes on the points that are left: the driver
        ! rewrites this file with the remainder before each launch, and
        ! loop_count then indexes it from one either way.
        if (sweep_addiction_scalar==1) then

            open(unit=77,file="B_SWEEP_GRID.txt",action='read',status='old',iostat=sweep_points)
            if (sweep_points/=0) then
                write(*,*) "B SWEEP: no B_SWEEP_GRID.txt, nothing to sweep"
                stop
            end if
            sweep_points=0
            do
                if (sweep_points>=max_sweep_points) exit
                read(77,*,end=7701) sweep_b_grid(sweep_points+1)
                sweep_points=sweep_points+1
            end do
7701        close(77)

            if (sweep_points==0) then
                write(*,*) "B SWEEP COMPLETE: the grid file is empty"
                stop
            end if

            addiction_scalar_1=sweep_b_grid(1)
            write(*,*) "B SWEEP: ", sweep_points, " points, starting at b=",&
                addiction_scalar_1

        end if

        ! THE RENTAL MARKET IS NOT SCORED, on the author's instruction of 14
        ! September: *"Rental market can be in the model, but the rent is pinned
        ! at 1 and does not need to clear the market at all. You can ignore the
        ! rental price clearing the market."*
        !
        ! IT WAS THE FIRST TERM OF THIS TEST AND IT HAD NO INSTRUMENT. fix_rent
        ! is 1 and rent_calibrated is 1.0, so the rent never moves; but
        ! distance_rental_market went on being computed as
        ! maxval|rental demand - rental supply| and scored against a rule of 2e-2,
        ! which nothing in the model could close. That is the exact failure this
        ! file documents elsewhere -- a live distance whose parameter cannot move
        ! -- sitting in the first line of the convergence test.
        !
        ! IT IS STILL COMPUTED AND STILL PRINTED, because how far the rental
        ! market is from clearing at a pinned rent is worth seeing. It simply no
        ! longer holds the loop open. distance_rent_to_price needs no change: it
        ! is already (1-fix_rent)*abs(...), which is zero.
        do while(((distance_discount_factor>stopping_rule_discount_factor) .OR. &
            ((freeze_to_three_block==0) .AND. (distance_discount_factor_on_child>stopping_rule_discount_factor_on_child)) .OR. &
            (distance_minimum_inheritance>stopping_rule_minimum_inheritance) .OR. &
            (distance_advantage_to_owning>stopping_rule_advantage_to_owning) .OR. &
            (distance_relative_share_of_housing>stopping_rule_relative_share_of_housing) .OR. &
            ((freeze_to_three_block==0) .AND. (distance_relative_share_of_leisure>stopping_rule_relative_share_of_leisure)) .OR. &
            (distance_convexity_of_rental_company>stopping_rule_convexity_of_rental_company) .OR. &
            (distance_housing_status_grid_expander>stopping_rule_housing_status_grid_expander) .OR. &
            (distance_largest_house_size>stopping_rule_largest_house_size) .OR. &
            (distance_probability_of_becoming_addicted>&
             stopping_rule_probability_of_becoming_addicted) .OR. &
            (distance_lambda_addiction>stopping_rule_lambda_addiction) .OR. &
            (distance_drug_market>stopping_rule_drug_market) .OR. &
            ((hold_theta==0) .AND. (distance_relative_share_of_addiction_1>stopping_rule_relative_share_of_addiction_1)) .OR. &
            (distance_addiction_scalar>stopping_rule_addiction_scalar) .OR. &
            (distance_value_of_life>stopping_rule_value_of_life) .OR. &
            (distance_max_food_cost>stopping_rule_max_food_cost) .OR. &
            (distance_voucher_probability>stopping_rule_voucher_probability) .OR. &
            (distance_separation_rate>stopping_rule_separation_rate) .OR. &
            (distance_employment_multiplier>stopping_rule_employment_multiplier) .OR. &
            (distance_utility_cost_of_treatment>stopping_rule_utility_cost_of_treatment) .OR. &
            (distance_kappa_phi_d_level>stopping_rule_kappa_phi_d_level) .OR. &
            (distance_multiple_find>stopping_rule_multiple_find) .OR. &
            (distance_rent_to_price>stopping_rule_rent_to_price) .OR. &
            ((smallest_house_size_adjuster>0) .AND. (distance_smallest_house_size>stopping_rule_smallest_house_size)) .OR. &
            (distance_fixed_cost_to_moving>stopping_rule_fixed_cost_to_moving) .OR. &
            (distance_standard_deduction>stopping_rule_standard_deduction) .OR. &
            (distance_inheritance_amount>stopping_rule_inheritance_amount) .OR. &
            (distance_size_homelessness>stopping_rule_size_homelessness) .OR. &
            (distance_average_labor_income>stopping_rule_average_labor_income) .OR. &
            (distance_median_income>stopping_rule_median_income) .OR. &
            (distance_average_net_wealth>stopping_rule_average_net_wealth) .OR. &
            (distance_drug_threshold>stopping_rule_drug_threshold) .OR. &
            (distance_lambda_m>stopping_rule_lambda_m) .OR. &
            (distance_kappa_uem>stopping_rule_kappa_uem) .OR. &
            (distance_kappa_find_smi>stopping_rule_kappa_find_smi) .OR. &
            (distance_b_smi_multiple>stopping_rule_b_smi_multiple) .OR. &
            (distance_rho_m>stopping_rule_rho_m) .OR. &
            (distance_rho_d>stopping_rule_rho_d) .OR. &
            (distance_mu_homeless>stopping_rule_mu_homeless) .OR. &
            (distance_weight_on_child>stopping_rule_weight_on_child) .OR. &
            (distance_penalty_child_addicted>stopping_rule_penalty_child_addicted) .OR. &
            (distance_penalty_child_homeless>stopping_rule_penalty_child_homeless) .OR. &
            (distance_labor_income_tax_rate>stopping_rule_labor_income_tax_rate) .OR. &
            (distance_sd_permanent_productivity>stopping_rule_sd_permanent_productivity) .OR. &
            (distance_smi_onset_level>stopping_rule_smi_onset_level) .OR. &
            (distance_newborn_endowment>stopping_rule_newborn_endowment) .OR. (loop_count<1)) &
            .AND. ((frozen_stop_after_blocks==0) .OR. &
                   (loop_count<2*frozen_stop_after_blocks)) &
            .AND. ((frozen_stop_tolerance<=0.d0) .OR. &
                   (block_move>=frozen_stop_tolerance)))
                        
            ! SIGMA_Y, on the share of productivity held by the bottom half.
            ! The share FALLS in sigma_y, so a model share above target means
            ! the distribution is too equal and sigma_y has to rise. The grid is
            ! rebuilt from sigma_y at the top of every loop, so the new value is
            ! in force for the solve that follows.
            ! THE DISPERSION INSTRUMENT IS WHICHEVER GRID IS LIVE, and the two
            ! share the moment, the target and the distance slot -- so the long
            ! do while above needs no new term and exactly one of them steps.
            !
            ! sd_permanent_productivity builds the QUANTILE grid and nothing
            ! else. Under fixed_productivity=0 it moves no moment at all, and
            ! left to run it would step a number that changes nothing while the
            ! distance never fell under its stopping rule: the calibration would
            ! never terminate.
            if ((calibrate_sd_permanent_productivity==1) .AND. (loop_count>=1)&
                .AND. (fixed_productivity==0)) then

                write(*,*) "bottom half's share of productivity, pooled 26-65 =",&
                    model_bottom_half_earnings_share,&
                    " target =", bottom_half_earnings_share_data
                write(*,*) "kkk_sigma_scale=", kkk_sigma_scale,&
                    " sd of log y at age 1 =", sd_log_y_newborn

                cap_old_1=kkk_sigma_scale
                kkk_sigma_scale=max(min(kkk_sigma_scale+kkk_sigma_scale_adjuster*&
                    (model_bottom_half_earnings_share-bottom_half_earnings_share_data),&
                    10.d0),0.1d0)
                ! cap_step_rel, NOT cap_step: sigma_y gets its own two per cent
                ! rather than the global tenth of one, for the reason recorded
                ! at kkk_sigma_scale_max_rel_step.
                kkk_sigma_scale=cap_step_rel(kkk_sigma_scale,cap_old_1,&
                    kkk_sigma_scale_max_rel_step)

                ! LIVE AGAIN, and retired only if BOTH sigma_y instruments are
                ! off -- the freeze flag no longer decides it, because the two
                ! adjusters are split.
                distance_sd_permanent_productivity=&
                    merge(0.d0,&
                    abs(model_bottom_half_earnings_share-bottom_half_earnings_share_data),&
                    (kkk_sigma_scale_adjuster<=0.d0) .AND.&
                    (sd_permanent_productivity_adjuster<=0.d0))

                write(*,*) "kkk_sigma_scale=", kkk_sigma_scale,&
                    " distance=", distance_sd_permanent_productivity

            end if

            if ((calibrate_sd_permanent_productivity==1) .AND. (loop_count>=1)&
                .AND. (fixed_productivity==1)) then

                write(*,*) "bottom half's share of productivity =",&
                    model_bottom_half_earnings_share,&
                    " target =", bottom_half_earnings_share_data
                write(*,*) "sd_permanent_productivity=", sd_permanent_productivity

                sd_permanent_productivity=max(min(sd_permanent_productivity+&
                    sd_permanent_productivity_adjuster*&
                    (model_bottom_half_earnings_share-bottom_half_earnings_share_data),&
                    3.d0),10.d0**(-2))

                ! LIVE AGAIN, and retired only if BOTH sigma_y instruments are
                ! off -- the freeze flag no longer decides it, because the two
                ! adjusters are split.
                distance_sd_permanent_productivity=&
                    merge(0.d0,&
                    abs(model_bottom_half_earnings_share-bottom_half_earnings_share_data),&
                    (kkk_sigma_scale_adjuster<=0.d0) .AND.&
                    (sd_permanent_productivity_adjuster<=0.d0))

                write(*,*) "sd_permanent_productivity=", sd_permanent_productivity,&
                    " distance_sd_permanent_productivity=", distance_sd_permanent_productivity

            end if

            ! OMEGA'S MOMENT, measured before the baseline so that every statistic
            ! the rest of this loop reads describes the baseline and not this.
            ! Switching the child term off means setting its weight to zero, which
            ! is exactly what the moment describes.
            ! NOT DURING A SWEEP, for two reasons. It costs a full extra value
            ! function solve and distribution convergence on every pass, about a
            ! third of the pass, and nothing in a sweep of b reads it. Worse, it
            ! leaves its own converged distribution behind for the baseline solve
            ! to start from, so the number the sweep is measuring would carry the
            ! counterfactual's path in it. That path dependence is the fault
            ! already recorded against omega's own moment; there is no reason to
            ! feed it into a curve meant to isolate b.
            if ((calibrate_weight_on_child==1) .AND. (omega_c_is_pinned==0)&
                .AND. (include_child_in_continuation==1)&
                .AND. (loop_count>=1) .AND. (sweep_addiction_scalar==0)) then

                ! OMEGA_C IS THE SWITCH, NOT child_penalty_off.
                !
                ! child_penalty_off zeroes expected_child_value, which is the
                ! INHERITED PENALTY alone. Since the child entered the parent's
                ! FLOW utility as well -- the (xi-1) term carrying the child's
                ! own bundle, which omega_c also multiplies -- that switch now
                ! prices half the parameter: the counterfactual left the flow
                ! term live and reported only the continuation channel.
                !
                ! On the author's instruction of 11 September, *"omega_c should
                ! price both at once"*. Setting weight_on_child to zero does
                ! exactly that, because omega_c multiplies both terms and
                ! nothing else. child_penalty_off keeps its own meaning as a
                ! rung of the channel shutdown ladder and is untouched here.
                weight_on_child_saved=weight_on_child
                weight_on_child=0.d0

                ! SAYS WHICH SLOT THE CHILD PENALTY COMES FROM AND GOES BACK TO.
                ! Without it this solve reads the benchmark's penalty and leaves
                ! its own behind for the benchmark to pick up.
                solving_omega_counterfactual=1

                call solve_value_function_and_policy_functions(1)
                call converge_to_stationary_equilibrium(1)
                call stationary_equilibrium_statistics(1)

                ! model_total_drug_users IS BUILT IN govt_revenues_calc, NOT IN
                ! stationary_equilibrium_statistics. Both counterfactual blocks
                ! called only the latter, so the variable still held the BASELINE
                ! count when it was read back: the ratio was exactly one and
                ! omega came out as exactly 0.0000000000000000, at every value of
                ! omega_c, which is what a variable that was never updated looks
                ! like. The main path calls the two in this order, and so must
                ! anything that wants a fresh count.
                call govt_revenues_calc(1)

                drug_users_without_child=model_total_drug_users(1)

                solving_omega_counterfactual=0

                weight_on_child=weight_on_child_saved

                ! WHETHER THE COUNTERFACTUAL'S OWN DISTRIBUTION SETTLED, which
                ! decides whether its sign can be read at all. The counterfactual
                ! re-solves the distribution from the baseline's, and the sweep
                ! cap is two hundred; a solve that leaves on the cap has moved
                ! part of the way to the counterfactual and the gap it reports is
                ! a partial adjustment rather than the moment.
                !
                ! IT IS PRINTED BECAUSE THE SIGN CAME OUT WRONG ONCE, AND THE
                ! PRINT ANSWERED IT. At loop 3 of a cold run, removing the
                ! penalty CUT use by 75 per cent where the mechanism says it
                ! should raise it: the term is zero for a clean housed parent and
                ! negative otherwise, so removing it makes the disordered states
                ! cheaper and use should rise. That could have been the
                ! counterfactual's own distribution stopping half way, since it
                ! re-solves from the baseline's under the sweep cap.
                !
                ! IT WAS NOT. Measured once participation came down: 61 sweeps,
                ! reached 7.2e-5 against a stopping rule of 6e-4, capped = 0. The
                ! counterfactual converges properly and the sign is now the right
                ! one, +0.93 against a target of +0.18, which says omega is too
                ! large rather than that anything is broken. The gap RISES in
                ! omega, so the update lowers it, which is the documented
                ! direction. The print stays: it is two numbers a loop and it is
                ! the difference between reading that gap and guessing at it.
                ! RECORDED, NOT ONLY PRINTED. The update block runs later and in
                ! another scope, so the flag has to be carried rather than
                ! recomputed: loop_count_dist belongs to whatever solved last.
                omega_counterfactual_capped=merge(1,0,loop_count_dist>=max_distribution_sweeps)

                write(*,*) "omega counterfactual: drug users with the child penalty off =",&
                    drug_users_without_child, " counterfactual distribution sweeps =",&
                    loop_count_dist, " reached =", distance_distribution_reached,&
                    " capped =", omega_counterfactual_capped

            end if

            ! THE PRIMING SOLVE, WITHOUT WHICH THE CHILD TERM IS NEVER LIVE.
            !
            ! compute_expected_child_value runs at the top of the solve and
            ! returns zero while age one is still the sentinel, so the FIRST
            ! solve of a run always faces a zero child term. The design assumed a
            ! second pass would pick it up, which the calibration loop provides
            ! and a point run does not. The consequence was total rather than
            ! partial: nineteen points carrying MOMENT omega every one reported a
            ! use gap of exactly 0.0000000000000000, because switching off a term
            ! that is already zero is a no-op, and weight_on_child multiplied
            ! nothing at 0.02, 0.5 and 0.7 alike.
            !
            ! So solve once to fill age one, which lets the next call compute the
            ! term for real, then solve again with it live. It costs one extra
            ! solve on the first pass of a run and nothing after that.
            ! THE PRIMING SOLVE IS GONE, SUBSUMED BY GUESS AND VERIFY.
            !
            ! It existed because the child penalty used to be computed at the TOP
            ! of a solve, when age one was still the sentinel, so a throwaway
            ! solve was needed to fill it. The author's algorithm removes the
            ! need: *"you start with V(1)=0 as a guess, and compute the VF and
            ! check if they agree. if not, you update the guess to the solved
            ! v(1), and continue"*. expected_child_value_own is zero at
            ! declaration, so the first pass of the loop below IS the priming
            ! solve and its output is the second pass's guess. One solve saved
            ! per run and the code now says what the algorithm is.

            ! ================= THE TWO TYPES =================
            ! Half the households are patient and half impatient, and a
            ! household never switches, so the two share prices and the
            ! government budget and nothing else. The whole chain -- solve,
            ! distribution, statistics -- runs once per type, and the moment
            ! accumulators are NOT reset on the second pass.
            !
            ! WHY THAT GIVES THE MIXTURE AND NOT THE SECOND TYPE. Every
            ! targeted moment in this model is a ratio or a share. Each type's
            ! distribution carries unit mass, so summing both passes doubles
            ! the numerator and the denominator of every one of them and the
            ! ratio is exactly the fifty-fifty mixture. No weighting is needed
            ! and none is applied. A LEVEL would come out doubled, which is why
            ! it is worth checking that no targeted moment is one.
            discount_factor_patient_saved=discount_factor

            do current_beta_type=1,number_of_beta_types

            accumulating_beta_types=current_beta_type-1
            mass_passes=current_beta_type
            if (current_beta_type==1) discount_factor=discount_factor_patient_saved
            if (current_beta_type==2) discount_factor=discount_factor_impatient

            ! THE FLOOR IS PER PASS NOW. set_renter_floor reads current_beta_type,
            ! so it has to run after the type is set and before anything that
            ! loops on renter_floor_by_age. Harmless when
            ! restrict_borrowing_to_impatient is zero: it recomputes the same
            ! array both passes.
            call set_renter_floor(1)

            ! AND THE WARM DISTRIBUTION HAS TO BE PROJECTED ONTO IT. From loop
            ! three onward initialize_feasible_distribution is skipped and the
            ! patient pass starts from the IMPATIENT pass's converged
            ! distribution, which carries mass at negative indices the patient
            ! pass no longer visits. That mass would sit untouched in the array
            ! and still be picked up by the full-slice sum() calls that form
            ! sum_of_distribution, inflating the denominator of every share.
            !
            ! Zeroing it is safe because this is only the ITERATION'S STARTING
            ! GUESS: converge_to_stationary_equilibrium runs to 6e-4 from
            ! whatever it is handed, so a projection changes the path and not
            ! the fixed point. lbound is read off the array rather than
            ! recomputed because the owner slabs start at 1 and have no negative
            ! region to clear.
            if ((include_unsecured_borrowing==1) .AND. &
                (restrict_borrowing_to_impatient==1) .AND. &
                (number_of_beta_types>1) .AND. (current_beta_type==1)) then

                do i_beta_floor=1,size(distribution_guess)

                    ! distribution_guess is the OPERATIVE one: the iteration
                    ! zeroes distribution_implied every sweep and rebuilds it
                    ! from the guess, and sum(distribution_guess) feeds both the
                    ! convergence distance and the Aitken step. Phantom mass at
                    ! an index the patient pass never visits would sit in that
                    ! sum. distribution_stationary is cleared with it because
                    ! every moment's denominator is a full-slice sum over it.
                    if (lbound(distribution_guess(i_beta_floor)%&
                        vector_transition_real,3)<negative_financial_grid_size) then

                        distribution_guess(i_beta_floor)%vector_transition_real&
                            (:,:,lbound(distribution_guess(i_beta_floor)%&
                            vector_transition_real,3):negative_financial_grid_size-1,&
                            :,:,:,:)=0

                    end if

                    if (lbound(distribution_stationary(i_beta_floor)%&
                        vector_transition_real,3)<negative_financial_grid_size) then

                        distribution_stationary(i_beta_floor)%vector_transition_real&
                            (:,:,lbound(distribution_stationary(i_beta_floor)%&
                            vector_transition_real,3):negative_financial_grid_size-1,&
                            :,:,:,:)=0

                    end if

                end do

            end if

            ! GUESS AND VERIFY: solve, recompute the child penalty from the V(1)
            ! this solve produced, and solve again until the guess and the
            ! computed value agree. At fixed parameters this is an ordinary
            ! contraction; across calibration loops the previous loop's converged
            ! penalty is the next one's guess, so it costs several passes on the
            ! first loop and one or two afterwards.
            child_value_pass=0

            do

                child_value_pass=child_value_pass+1
                expected_child_value_guessed=expected_child_value_own

                call solve_value_function_and_policy_functions(1)

                if (include_child_in_continuation==0) exit

                child_value_distance=maxval(abs(expected_child_value_own-&
                    expected_child_value_guessed))/&
                    max(maxval(abs(expected_child_value_own)),1.d0)

                write(*,*) "CHILD V PASS", child_value_pass,&
                    " guessed vs computed, relative =", child_value_distance,&
                    " rule =", stopping_rule_child_value

                if (child_value_distance<=stopping_rule_child_value) then

                    write(*,*) "CHILD V CONVERGED after", child_value_pass,&
                        "passes, relative =", child_value_distance
                    exit

                end if

                if (child_value_pass>=max_child_value_passes) then

                    write(*,*) "CHILD V DID NOT CONVERGE in", max_child_value_passes,&
                        "passes, relative =", child_value_distance,&
                        " -- the penalty handed to the household is NOT the one its own",&
                        " value function implies, and nothing downstream of it is a fixed point"
                    exit

                end if

            end do
                            
            ! A LOADED WARM START MUST NOT BE OVERWRITTEN. The initialisation
            ! puts everyone at age one with no assets, which is the right guess
            ! only when there is no better one on disk. Once a loop has run and
            ! converged, distribution_stationary is the better guess and the
            ! flag is cleared, so this reverts to the old behaviour from the
            ! second loop of a resumed run onwards.
            !
            ! A SWEEP IS EXEMPT, and it has to be. re_do_simulation_with_fixed_
            ! parameters is normally a single re-run of a finished calibration,
            ! where paying for a cold distribution once is nothing; a sweep is
            ! one pass per grid point, and forcing the age one cross section on
            ! every one of them costs the 655 sweeps this file warns about at
            ! each. Measured: forty eight minutes without a single completed
            ! pass, against seven for a calibration loop. Consecutive points
            ! differ in b alone, so the previous point's converged distribution
            ! is the better guess, exactly as it is between calibration loops.
            if (((loop_count<3) .OR. ((re_do_simulation_with_fixed_parameters==1)&
                .AND. (sweep_addiction_scalar==0))) .AND. &
                (have_warm_distribution==0)) then

                call initialize_feasible_distribution(1)

            end if

            have_warm_distribution=0
            
            ! THIS IS THE OPERATIVE DISTRIBUTION TOLERANCE. 2e-4, and it is
            ! already loose.
            !
            ! There used to be a second reset just above, to 1e-8, in both arms of
            ! an if whose branches were identical; it has been removed because it
            ! was dead, being overwritten here on the same pass. Both together
            ! meant the declared value never reached the iteration.
            !
            ! Worth stating plainly since it was got wrong once: there is no
            ! speed left in this number. The 655 sweeps a loop takes are what
            ! reaching 2e-4 costs, not what reaching 1e-8 would cost. Loosening
            ! it further trades directly against the moments, which are shares
            ! read to three and four decimals.
            ! AND THE FIXED-PARAMETER PASS GETS THE TIGHT ONE. 6e-4 is the
            ! right trade inside a calibration loop that runs it hundreds of
            ! times; it is the wrong one for a single re-run whose whole purpose
            ! is to read the equilibrium exactly.
            !
            ! IT ALSO EXPLAINS SOMETHING WE WATCHED ALL DAY. At 6e-4 each block
            ! stops short and carries the residual into the next, so the
            ! distribution converges ACROSS blocks rather than within them --
            ! pi_V reading 0.087, 0.184, 0.252, 0.293 at nearly fixed parameters
            ! is that residual unwinding, not economics. A fixed-parameter pass
            ! at 1e-8 converges it in one go and there is no transient to read
            ! through.
            if (include_addiction==1) then

                if (re_do_simulation_with_fixed_parameters==1) then

                    stopping_rule_stationary_distribution=10.d0**(-8)

                else

                    stopping_rule_stationary_distribution=6*10.d0**(-4)

                end if

            end if
            
            if (load_test_distribution==0) then
            
                call converge_to_stationary_equilibrium(1)
                
            else
            
                do i=1,2
    
                    write(string_used,'(i1)') i
                                   
                    open(unit=10,file="distribution_stationary"//trim(string_used)//trim(old_results)//".dat",action='read')
                        read(10,'(F30.28)') distribution_stationary(i)%vector_transition_real(1,:,:,:,:,:,:)
                    close(10)
                    
                end do
                
            end if
            
            ! CAPTURE THE PREVIOUS LOOP'S VALUES ONCE, ON THE FIRST PASS.
            !
            ! These four are the damping anchors: the block near the end of the
            ! iteration blends the new value with the previous one at
            ! weight_on_labor_income and its siblings. "Previous" means the
            ! previous CALIBRATION LOOP. Unguarded, this sits inside
            ! `do current_beta_type=1,number_of_beta_types` and so ran again on
            ! the second pass -- and by then model_average_labour_income holds
            ! what the FIRST pass left, which is a raw mass-weighted SUM, because
            ! the division by model_total_workers is guarded to the LAST pass and
            ! pass one skips it.
            !
            ! The blend downstream therefore averaged a true per-worker mean with
            ! an undivided sum, inflating the denominator by roughly (1+W)/2 for
            ! W the first type's worker mass. That is the factor of seventeen
            ! that has been chased all evening: aleph read 2.61 against a target
            ! of 80, and two lines in the SAME point implied 0.6 and 10.2 for the
            ! same quantity.
            !
            ! It is not confined to a printed moment. set_SS_benefits multiplies
            ! benefits by this, and the next iteration's solve reads it as
            ! avg_income_to_use_1 and as the standard deduction, so a corrupted
            ! value walks into the household's budget constraint.
            !
            ! At ONE beta type the division happens on the only pass and the
            ! guard below is always true, so nothing measured at one type moves.
            ! That matches the symptom: aleph sits still at one type and swings
            ! at two.
            if (accumulating_beta_types==0) then

                previous_average_labor_income=model_average_labour_income(1)
                previous_median_income=median_income(1)
                previous_average_net_wealth=model_average_net_wealth(1)

                previous_inheritance_amount=inheritance_amount

            end if
            
            call stationary_equilibrium_statistics(1)
            call stationary_equilibirum_homeownership_rate(1)
            call govt_revenues_calc(1)
            call calculate_aggregate_consumption(1)
            call calculate_welfare(1)

            ! The childhood half, which needs the adult half already averaged.
            call calculate_childhood_utility(1)

            ! THE LATCH'S OWN INVARIANTS, checked on the solved value function.
            ! See verify_recovered_block for why these two and not others.
            if (recovered_block_checked==0) then
                call verify_recovered_block(1)
                recovered_block_checked=1
            end if
            call calculate_household_housing_spending(1)
            call calculate_welfare_by_characteristics(1)
                        
            call calculate_homeownership_by_characteristics(1)            
            call stationary_equilibrium_wealth_distribution_of_old(1)

            end do

            ! Back to the patient value, which is the one the calibration owns,
            ! and back to resetting accumulators so nothing downstream inherits
            ! the suppression.
            cap_old_1=discount_factor
            discount_factor=discount_factor_patient_saved
            discount_factor=cap_step(discount_factor,cap_old_1)
            mass_passes=number_of_beta_types
            accumulating_beta_types=0
            current_beta_type=1
            
            if (loop_count>0) then
            
                if ((include_bequests==1) .AND. (residual_bequests_to_government==0)) then
            
                    if (inheritance_function_of_productivity==0) then
            
                        if (include_bequests_in_govt_constraint==0) then
                        
                            call calculate_updated_inheritance_amounts(1)
                                        
                        end if
                        
                        distance_inheritance_amount=maxval((1-include_bequests_in_govt_constraint)*&
                            abs(previous_inheritance_amount-inheritance_amount))
                        
                        inheritance_amount=inheritance_amount_weight*inheritance_amount+&
                            (1-inheritance_amount_weight)*previous_inheritance_amount
                            
                    else
                    
                        distance_inheritance_amount=&
                            abs(model_bequests(1)-value_of_initial_assets-model_total_inheritance(1))
                        
                        inheritance_amount=inheritance_amount+&
                             inheritance_amount_adjuster*&
                             (model_bequests(1)-value_of_initial_assets-model_total_inheritance(1))
                    
                    end if
                        
                else
                    
                    distance_inheritance_amount=0
                    
                end if
                    
            else
            
                distance_inheritance_amount=1
            
            end if
                             
            if (re_do_simulation_with_fixed_parameters==1) then
            
                distance_discount_factor=0
                distance_discount_factor_on_child=0
                distance_minimum_inheritance=0
                distance_housing_status_grid_expander=0
                distance_largest_house_size=0
                distance_probability_of_becoming_addicted=0
                distance_lambda_addiction=0
                distance_utility_cost_of_treatment=0
                distance_relative_share_of_addiction_1=0
                distance_addiction_scalar=0
                distance_value_of_life=0
                distance_max_food_cost=0
                distance_voucher_probability=0
                distance_separation_rate=0
                distance_employment_multiplier=0
                distance_rent_to_price=0
                distance_smallest_house_size=0
                distance_advantage_to_owning=0
                distance_relative_share_of_housing=0
                distance_relative_share_of_leisure=0
                distance_standard_deduction=0
                distance_convexity_of_rental_company=0
                distance_fixed_cost_to_moving=0
                distance_size_homelessness=0
                distance_lambda_m=0
                distance_kappa_uem=0
                distance_kappa_find_smi=0
                distance_rho_m=0
                distance_rho_d=0
                        
            else
            
                if ((freeze_updates_after_loop>0) .AND. &
                    (loop_count>freeze_updates_after_loop)) then
                    write(*,*) "FROZEN PASS: every parameter update is held from",&
                        " loop", freeze_updates_after_loop,&
                        " -- the model is now iterating at FIXED parameters"
                end if

                if ((loop_count>aftr_how_mny_lps_start_update) .AND. &
                    ((freeze_updates_after_loop<=0) .OR. &
                    (loop_count<=freeze_updates_after_loop))) then
            
                    write(*,*) "discount_factor=", discount_factor
                                            
                    ! RETARGETED ONTO WEALTH OVER OUTPUT. This used to be driven
                    ! by the mortgage share of gross housing wealth against the
                    ! SCF's 0.345, and with include_ownership at zero that moment
                    ! is not merely dead, it is NOT A NUMBER: mortgages and gross
                    ! housing wealth are both identically zero, so the ratio is
                    ! 0/0. The consequence was worse than a frozen parameter.
                    ! beta + adjuster*NaN is NaN, and min(max(NaN,0),1.3) collapses
                    ! to zero under gfortran, so the discount factor was SET TO
                    ! ZERO at the end of the first calibration loop and every loop
                    ! after the first solved a completely myopic household. The
                    ! distance was NaN too, and NaN > tolerance is false, so the
                    ! convergence test read the broken parameter as converged and
                    ! said nothing.
                    !
                    ! The note has always said beta is chosen to reproduce wealth
                    ! over output in the national accounts, and the model
                    ! counterpart was already being computed and printed two lines
                    ! below the update that ignored it. That is what it targets now.
                    !
                    ! SIGN. Wealth rises with patience, so a model below target
                    ! calls for a higher beta: the update is minus the adjuster
                    ! times (model minus data), which is the same convention as
                    ! every other parameter in this loop.
                    wealth_to_output_model_1=model_total_net_wealth(1)/model_GDP_incl_imput_rent(1)

                    if (wealth_to_output_model_1 .NE. wealth_to_output_model_1) then

                        ! A MOMENT THAT IS NOT A NUMBER MUST NOT MOVE A PARAMETER
                        ! AND MUST NOT BE READ AS CONVERGED. Leave beta where it
                        ! is and force the distance large so the loop stays open
                        ! and the failure is visible.
                        write(*,*) "wealth over output is NaN: beta held at", discount_factor
                        distance_discount_factor=1

                    else

                        gap_discount_factor_1=wealth_to_output_model_1-wealth_to_output_data

                        ! The usual sign flip ratchet. Wealth over output is very
                        ! sensitive to beta close to one, so a fixed step
                        ! overshoots and then oscillates.
                        if (have_gap_discount_factor==1) then

                            ! GUARDED AS AT 47275 AND IN damp_on_flip. The damping
                            ! branch is max(adj*damping,floor), which at adj=0 is the
                            ! FLOOR, so a pinned adjuster comes back to life on the
                            ! first sign flip and then grows to its start value. The
                            ! growth branch, min(0*growth,start)=0, is harmless.
                            if ((gap_discount_factor_1*previous_gap_discount_factor)<0 &
                                .AND. (discount_factor_adjuster>0.d0)) then

                                discount_factor_adjuster=&
                                    max(discount_factor_adjuster*discount_factor_damping,&
                                    discount_factor_adjuster_floor)

                            else

                                discount_factor_adjuster=&
                                    min(discount_factor_adjuster*discount_factor_growth,&
                                    discount_factor_adjuster_start)

                            end if

                        end if

                        previous_gap_discount_factor=gap_discount_factor_1
                        have_gap_discount_factor=1

                        ! BRACKET AND BISECT, for the same reason the homelessness
                        ! size does it. Wealth over output is very nearly a step
                        ! function in beta near the knife edge where beta*(1+r)
                        ! reaches one: measured here, beta of 0.957 gave 0.78 and
                        ! beta of 0.968 gave 20.79, so a twenty six fold move in
                        ! the moment across eleven thousandths of the parameter.
                        ! A proportional adjuster cannot land inside a window that
                        ! narrow, however hard it is damped; it can only straddle
                        ! it. Bisection halves the window every solve regardless
                        ! of how steep the schedule is.
                        !
                        ! Wealth over output RISES with beta, so a model below
                        ! target makes this beta the low endpoint and a model
                        ! above target makes it the high one.
                        if (wealth_to_output_model_1<wealth_to_output_data) then

                            if (discount_factor_lo<0) then

                                discount_factor_lo=discount_factor
                                discount_factor_lo_moment=wealth_to_output_model_1

                            else if ((discount_factor>discount_factor_lo) .AND. &
                                (wealth_to_output_model_1<discount_factor_lo_moment-10.d0**(-5))) then

                                ! Raised patience and wealth fell. Something else
                                ! moved under the bracket, so its endpoints are no
                                ! longer comparable.
                                write(*,*) "beta BRACKET DISCARDED: raised to ", discount_factor, &
                                    " and wealth over output fell from ", discount_factor_lo_moment, &
                                    " to ", wealth_to_output_model_1
                                discount_factor_lo=-1
                                discount_factor_hi=-1
                                discount_factor_lo_moment=-1
                                discount_factor_hi_moment=-1

                            else if (discount_factor>discount_factor_lo) then

                                discount_factor_lo=discount_factor
                                discount_factor_lo_moment=wealth_to_output_model_1

                            end if

                        else

                            if (discount_factor_hi<0) then

                                discount_factor_hi=discount_factor
                                discount_factor_hi_moment=wealth_to_output_model_1

                            else if ((discount_factor<discount_factor_hi) .AND. &
                                (wealth_to_output_model_1>discount_factor_hi_moment+10.d0**(-5))) then

                                write(*,*) "beta BRACKET DISCARDED: lowered to ", discount_factor, &
                                    " and wealth over output rose from ", discount_factor_hi_moment, &
                                    " to ", wealth_to_output_model_1
                                discount_factor_lo=-1
                                discount_factor_hi=-1
                                discount_factor_lo_moment=-1
                                discount_factor_hi_moment=-1

                            else if (discount_factor<discount_factor_hi) then

                                discount_factor_hi=discount_factor
                                discount_factor_hi_moment=wealth_to_output_model_1

                            end if

                        end if

                        distance_discount_factor=(1-freeze_beta_bisection)*abs(gap_discount_factor_1)

                        ! THE AUTHOR'S RULE, AND NO BISECTION. Their instruction of
                        ! 13 September: *"i dont want any bisections and any
                        ! secants ... parameter = parameter + adjuster*(model_moment
                        ! - data_moment), where adjuster is such that it updates in
                        ! the right direction, and does not update too fast"*.
                        !
                        ! DIRECTION. A more patient household saves more, so wealth
                        ! over output RISES in beta. The moment above target
                        ! therefore wants beta DOWN, which is the minus here --
                        ! equivalently a negative adjuster in the author's form.
                        !
                        ! The bisection this replaces kept a bracket in
                        ! discount_factor_lo/hi and halved it. Those two are still
                        ! written and restored with the calibration state, so a
                        ! resumed run is unaffected; nothing reads them now.
                        !
                        ! WHAT IS LOST, STATED PLAINLY. The bracket could report
                        ! "the moment jumps across this window, so no beta gets
                        ! closer" and zero its own distance. A gap step cannot say
                        ! that, so if wealth over output is a STEP in beta here, the
                        ! loop will keep pushing at the discontinuity instead of
                        ! declaring it. That is visible -- beta will sit against a
                        ! bound with the gap not closing -- and the bound warning
                        ! below still fires.
                        cap_old_1=discount_factor
                        discount_factor=min(max(discount_factor-discount_factor_adjuster*&
                            gap_discount_factor_1,0.5d0),1.05d0)
                        discount_factor=cap_step(discount_factor,cap_old_1)

                        write(*,*) "wealth_to_output_model=", wealth_to_output_model_1, &
                            " against ", wealth_to_output_data
                        write(*,*) "discount_factor_adjuster=", discount_factor_adjuster

                        ! A PINNED PARAMETER IS A RESULT, NOT A DETAIL. If beta
                        ! sits on a bound the target is not reachable by patience
                        ! alone and the number in the table would be a bound
                        ! rather than a calibration.
                        if ((discount_factor<=0.5d0+10.d0**(-8)) .OR. &
                            (discount_factor>=1.05d0-10.d0**(-8))) then

                            write(*,*) "beta IS PINNED AT A BOUND", discount_factor, &
                                " and wealth over output is ", wealth_to_output_model_1, &
                                " against ", wealth_to_output_data

                        end if

                    end if
                                         
                    write(*,*) "discount_factor=", discount_factor
                    write(*,*) "distance_discount_factor=", distance_discount_factor
                    write(*,*) "model_total_net_wealth(1)/model_GDP_incl_imput_rent(1)=", &
                        model_total_net_wealth(1)/model_GDP_incl_imput_rent(1)
                    write(*,*) "model_fraction_of_homeowners_with_mortgage(1)=", &
                        model_fraction_of_homeowners_with_mortgage(1)
                    write(*,*) "(model_mortgages(1)/model_gross_housing_wealth(1))=", &
                        (model_mortgages(1)/&
                        max(model_gross_housing_wealth(1),10.d0**(-14)))
                                            
                    write(*,*) "discount_factor_on_child=", discount_factor_on_child

                    ! A DISTANCE WHOSE PARAMETER CANNOT MOVE MUST NOT BE IN THE
                    ! CONVERGENCE TEST.
                    !
                    ! Both adjusters below are zero, so the parameter is frozen,
                    ! but the distance was still computed from a model moment and
                    ! still tested against 1e-3 in the loop condition. A frozen
                    ! parameter will not walk its moment onto its target, so the
                    ! sweep could not terminate however well everything else fit.
                    ! Guard on the adjuster, which is the same discipline the
                    ! homeownership blocks below already use.
                    if (discount_factor_on_child_adjuster==0) then

                        distance_discount_factor_on_child=0

                    else if (target_HO_of_old==1) then

                        discount_factor_on_child=min(max(discount_factor_on_child-&
                            discount_factor_on_child_adjuster*(model_homeownership_by_age_group(1,5)-&
                            homeownership_rate_of_old_data),0.005),10000.d0) 
                            
                        distance_discount_factor_on_child=&
                            abs(model_homeownership_by_age_group(1,5)-homeownership_rate_of_old_data)
                            
                        write(*,*) "model_homeownership_by_age_group=", model_homeownership_by_age_group(1,5)
                        
                    else
                    
                        ! THIS BRANCH CANNOT STEER, AND MUST NOT PRETEND TO. It
                        ! updated the parameter from model_median_assets_to_income(1)
                        ! over model_median_assets_to_income(3): the array has size
                        ! num_percentiles=1, so index 3 is out of bounds, and it is
                        ! assigned NOWHERE in this file, so index 1 is the zero it
                        ! was initialised to. A run that entered here would walk
                        ! discount_factor_on_child by 0/garbage and report a
                        ! distance made of the same. Dead today only because
                        ! discount_factor_on_child_adjuster=0; stop rather than
                        ! run, for the reason the smooth-hazard guard gives: a
                        ! model that still produces numbers is exactly how this
                        ! would go unnoticed.
                        write(*,*) "discount_factor_on_child is switched on with"
                        write(*,*) "target_HO_of_old=0, but its alternative moment"
                        write(*,*) "model_median_assets_to_income is never computed."
                        write(*,*) "Compute the moment or set target_HO_of_old=1."
                        stop
                    
                    end if
                            
                    write(*,*) "discount_factor_on_child=", discount_factor_on_child

                    write(*,*) "minimum_inheritance=", minimum_inheritance
                
                    minimum_inheritance=min(max(minimum_inheritance+minimum_inheritance_adjuster*&
                        (model_fraction_leaving_bequests(1)-fraction_leaving_bequests_data),0.d0),150.d0)

                    if (minimum_inheritance_adjuster==0) then

                        distance_minimum_inheritance=0

                    else

                        distance_minimum_inheritance=&
                            abs(model_fraction_leaving_bequests(1)-fraction_leaving_bequests_data)

                    end if

                    write(*,*) "minimum_inheritance=", minimum_inheritance
                    write(*,*) "model_fraction_leaving_bequests=", model_fraction_leaving_bequests(1)
                                                                 
                    if (advantage_to_owning_adjuster>0) then
                    
                        write(*,*) "advantage_to_owning=", advantage_to_owning
                    
                        advantage_to_owning=min(max(advantage_to_owning-advantage_to_owning_adjuster*&
                            (model_homeownership_rate(1)-SCF_homeownership_rate),0.d0),10000.d0) 
                                                                    
                        distance_advantage_to_owning=abs(model_homeownership_rate(1)-SCF_homeownership_rate)
                        
                        write(*,*) "advantage_to_owning=", advantage_to_owning
                        write(*,*) "distance_advantage_to_owning=", distance_advantage_to_owning
                        write(*,*) "model_homeownership_rate(1)=", model_homeownership_rate(1)
                        
                        distance_rent_to_price=0
                        
                    else
                        
                        distance_advantage_to_owning=0
                        distance_rent_to_price=0
                            
                    end if
                        
                    write(*,*) "relative_share_of_housing=", relative_share_of_housing 
                    
                    if (target_renters_rent_to_income==1) then
                                        
                        ! Raising gamma makes housing worth more against
                        ! consumption and the drug, so the household buys more of
                        ! it and the rent to income ratio RISES. A model above
                        ! target therefore calls for a smaller gamma.
                        !
                        ! THE DAMPING GOES ON THIS BRANCH, because this is the one
                        ! that runs: target_renters_rent_to_income is one. It was
                        ! first put on the else, where it compiled, printed
                        ! nothing and did nothing, and the only way to see that
                        ! was that its adjuster never appeared in the log beside
                        ! the other eight.
                        call damp_on_flip(relative_share_of_housing_adjuster,&
                            val_hous_expend_num(1)/max(val_hous_expend_den(1),10.d0**(-14))-housing_share_of_expenditure_data,&
                            previous_gap_relative_share_of_housing,have_gap_relative_share_of_housing,&
                            relative_share_of_housing_adjuster_start,damp_adjuster_floor,&
                                flips_relative_share_of_housing)
                        write(*,*) "relative_share_of_housing_adjuster=", relative_share_of_housing_adjuster
                        ! THE GLOBAL CAP APPLIES HERE TOO. This assignment sits on
                        ! an `if (...) X=&` line, so the pass that wrapped the other
                        ! parameters in cap_step could not match it and gamma was
                        ! left as the ONE calibrated parameter with no per loop cap.
                        cap_old_1=relative_share_of_housing
                        if (tie_gamma_to_theta==0) relative_share_of_housing=&
                            min(max(relative_share_of_housing-relative_share_of_housing_adjuster*&
                            (val_hous_expend_num(1)/max(val_hous_expend_den(1),10.d0**(-14))-housing_share_of_expenditure_data),0.01),0.9) 
                        relative_share_of_housing=&
                            cap_step_rel(relative_share_of_housing,cap_old_1,&
                            relative_share_of_housing_max_rel_step)
                                                                     
                        ! WHILE THE TIE IS ON, gamma is not being calibrated and its
                        ! moment is not a miss: it is whatever 0.28*(1-theta)
                        ! gives. A live distance would keep the joint loop running
                        ! on a bracket that is switched off.
                        if (tie_gamma_to_theta==1) distance_relative_share_of_housing=0
                        ! AND A PINNED GAMMA RETIRES ITS TERM, the same way
                        ! every other zero adjuster in the convergence test
                        ! does. Without this a zero adjuster leaves a live
                        ! distance against a parameter that cannot move, and
                        ! the uncapped do-while never exits.
                        if (tie_gamma_to_theta==0) distance_relative_share_of_housing=&
                            merge(0.d0,&
                            abs(val_hous_expend_num(1)/max(val_hous_expend_den(1),10.d0**(-14))-housing_share_of_expenditure_data),&
                            relative_share_of_housing_adjuster<=0.d0)
                                    
                        ! THE LABEL SAID "all" AND THE VARIABLE IS THE RENTERS
                        ! SERIES, and the other print of that label further down
                        ! the loop really is the all households one. Two different
                        ! quantities under one name, differing by more than a
                        ! factor of two, and a reading keyed on the label picked
                        ! whichever came first: it made gamma's moment look like
                        ! 0.45 against a target of 0.268 when it is 0.19, which
                        ! reverses which way gamma has to move.
                        write(*,*) "model_avg_housing_spending_renters=", &
                            model_avg_housing_spending_renters(1)
                            
                    else
                    
                        if (tie_gamma_to_theta==0) relative_share_of_housing=&
                            min(max(relative_share_of_housing-relative_share_of_housing_adjuster*&
                            (mass_of_renters_at_housing_spending(1,1)-SW_renters_spend_over_X_on_hous_2),0.01),0.9) 
                                                                     
                        distance_relative_share_of_housing=&
                            abs(mass_of_renters_at_housing_spending(1,1)-SW_renters_spend_over_X_on_hous_2)
                                    
                        write(*,*) "mass_of_renters_at_housing_spending(1,1)=", mass_of_renters_at_housing_spending(1,1)
                    
                    end if
                                                 
                    write(*,*) "relative_share_of_housing=", relative_share_of_housing 
                    write(*,*) "distance_relative_share_of_housing=", distance_relative_share_of_housing
                                        
                    write(*,*) "relative_share_of_housing=", relative_share_of_housing 
                                    
                    ! MULTIPLICATIVE, BECAUSE THE PARAMETER AND ITS MOMENT ARE NOT ON
                    ! THE SAME SCALE. The moment is a share of hours, bounded in
                    ! [0,1], so the gap can never exceed 0.4 in magnitude, while
                    ! the weight sits around 6.5. An additive step of
                    ! adjuster times gap is therefore at most 0.2 on a parameter
                    ! of 6.5, about three per cent a loop, and it does not care
                    ! how far away the moment is.
                    !
                    ! Measured: 6.786, 6.598, 6.411, falling 0.19 a loop while
                    ! labour supply sat at 0.025 against a target of 0.4. Not
                    ! stuck, and not a corner either — only two per cent of
                    ! households choose zero hours, so there is no grid to blame.
                    ! Just a rule that would need about thirty more loops, six
                    ! hours of wall clock, to cover ground a proportional step
                    ! covers in four.
                    !
                    ! Normalising the gap by the target makes the step
                    ! proportional to the parameter, which is what a scale-free
                    ! weight calls for, and the damping keeps it from ringing once
                    ! it arrives. Direction is unchanged: a model below target
                    ! still lowers the weight.
                    call damp_on_flip(relative_share_of_leisure_adjuster,&
                        model_labor_supply(1)/model_total_hours(1)-avg_labor_supply_data,&
                        previous_gap_relative_share_of_leisure,have_gap_relative_share_of_leisure,&
                        relative_share_of_leisure_adjuster_start,damp_adjuster_floor,&
                            flips_relative_share_of_leisure)
                    write(*,*) "relative_share_of_leisure_adjuster=", relative_share_of_leisure_adjuster
                    cap_old_1=relative_share_of_leisure
                    relative_share_of_leisure=&
                        min(max(relative_share_of_leisure*&
                        (1+relative_share_of_leisure_adjuster*&
                        (model_labor_supply(1)/model_total_hours(1)-avg_labor_supply_data)/&
                        max(avg_labor_supply_data,10.d0**(-12))),0.01),1000.d0) 
                    relative_share_of_leisure=cap_step(relative_share_of_leisure,cap_old_1)
                                                                 
                    distance_relative_share_of_leisure=&
                        (1-freeze_relative_share_of_leisure)*&
                        abs(model_labor_supply(1)/model_total_hours(1)-avg_labor_supply_data)
                                
                    write(*,*) "model_labor_supply(1)/model_total_hours(1)=", &
                        model_labor_supply(1)/model_total_hours(1)

                    ! LABELLED WITH THE PARAMETER THEY ACTUALLY CARRY. These two
                    ! printed the LEISURE weight under the HOUSING label and then
                    ! repeated the housing distance, so the log showed
                    ! relative_share_of_housing taking two different values a line
                    ! apart, one of them 7.85 against a parameter bounded at 0.9.
                    ! It also corrupts export_moments.py, which takes the last
                    ! printed value for a label, so the housing weight in the
                    ! paper would have been the leisure weight.
                    write(*,*) "relative_share_of_leisure=", relative_share_of_leisure
                    write(*,*) "distance_relative_share_of_leisure=", distance_relative_share_of_leisure
                                             
                    write(*,*) "housing_status_grid_expander=", housing_status_grid_expander
                        
                    if (calibrate_size_of_smallest_house_hhld_can_buy==1) then

                        ! RETARGETED ONTO THE SIZE DISTRIBUTION. This used to be
                        ! bracketed on the homeownership rate against the SCF's
                        ! 0.659, which is a dead moment now: include_homeownership
                        ! is zero, so model_homeownership_rate is identically zero
                        ! and the update drove the expander with a constant gap of
                        ! -0.659 every iteration. The expander sets the curvature
                        ! of the grid between the smallest and largest sizes, so
                        ! the share in the LARGEST size is what it actually
                        ! identifies.
                        !
                        ! THE LARGEST SIZE CARRIES THIS MOMENT, not the expander.
                        ! Three shares have two free numbers in them, so two size
                        ! parameters identify them and a third would be chasing the
                        ! same target: h0 takes the smallest share, h2 the largest,
                        ! and the middle follows. The expander is SET at its
                        ! starting curvature. It was tried on this moment first and
                        ! it cannot reach it, because what empties the largest unit
                        ! is the LEVEL of h2 rather than the curvature between h0
                        ! and h2: raising the expander from 1.8 to 2.17 moved the
                        ! largest share from 6 per cent to zero rather than towards
                        ! 62.7.
                        ! ZEROED AT ONE RENTAL for the same reason: the single
                        ! unit's share is 1.0 by construction, so this gap would be
                        ! a constant 0.373 driving largest_house_size forever.
                        gap_house_size_1=merge(&
                            model_housing_size_dist(1,housing_status_grid_size-1)-&
                            housing_size_dist_data(2),0.d0,housing_status_grid_size>2)

                        if (have_gap_largest_house_size==1) then

                            ! GUARDED AS AT 47275 AND IN damp_on_flip; see the note
                            ! on the discount factor's copy of this ratchet.
                            if ((gap_house_size_1*previous_gap_largest_house_size)<0 &
                                .AND. (largest_house_size_adjuster>0.d0)) then

                                largest_house_size_adjuster=&
                                    max(largest_house_size_adjuster*house_size_adjuster_damping,&
                                    house_size_adjuster_floor)

                            else

                                largest_house_size_adjuster=&
                                    min(largest_house_size_adjuster*house_size_adjuster_growth,&
                                    largest_house_size_adjuster_start)

                            end if

                        end if

                        previous_gap_largest_house_size=gap_house_size_1
                        have_gap_largest_house_size=1

                        write(*,*) "largest_house_size_adjuster=", largest_house_size_adjuster

                        cap_old_1=largest_house_size
                        largest_house_size=&
                            min(max(largest_house_size+largest_house_size_adjuster*&
                            gap_house_size_1,0.02d0),1.d0)
                        largest_house_size=cap_step(largest_house_size,cap_old_1)

                        ! A RETIRED BRACKET MUST RETIRE ITS DISTANCE TOO.
                        distance_largest_house_size=merge(0.d0,&
                            abs(model_housing_size_dist(1,housing_status_grid_size-1)-&
                            housing_size_dist_data(2)),&
                            largest_house_size_adjuster<=0.d0)

                        write(*,*) "largest_house_size=", largest_house_size
                        write(*,*) "distance_largest_house_size=", distance_largest_house_size

                        ! THE CURVATURE, ON THE MIDDLE CATEGORY'S SHARE, which
                        ! is h_3's own moment and nobody else's.
                        !
                        ! Each rung of the ladder now answers to one moment. h_2
                        ! is the cheapest dwelling and is set by the employed
                        ! share of the homeless, because the price of that rung
                        ! is what decides whether a working household can be
                        ! housed at all. h_4 is set by the share at the top size.
                        ! That leaves h_3, and the share living in the middle
                        ! unit is the moment left over for it.
                        !
                        ! This used to run on the SMALLEST category's share. With
                        ! largest_house_size holding the top share the two are
                        ! the same fixed point, because the three shares add to
                        ! one, so nothing about the calibrated ladder moves. What
                        ! moves is the attribution: the smallest category's share
                        ! is not h_2's moment any more, and pointing the curvature
                        ! at it was aiming a rung at a share the rung below owns.
                        !
                        ! THE SIGN FLIPS WITH THE MOMENT. Raising the expander
                        ! pulls h_3 down toward h_2 (h_3 = h_2 + (h_4-h_2)/2**e),
                        ! so the middle unit gets cheaper and takes households off
                        ! the bottom rung: share(0) falls and share(1) rises. The
                        ! old update added the gap, which is right for a moment
                        ! that falls in e; this one subtracts it.
                        ! INDEX 1 IS OUT OF BOUNDS AT ONE RENTAL. This array is
                        ! dimensioned 0:housing_status_grid_size-1, which is 0:0
                        ! once h_3 and h_4 are gone, and this line read index 1.
                        ! The index is clamped so the access is legal and the gap
                        ! is forced to zero below two rungs, so the expander
                        ! cannot be driven by a rung that does not exist.
                        gap_housing_status_grid_expander=merge(&
                            model_housing_size_dist(1,min(1,housing_status_grid_size-1))-&
                            housing_size_dist_data(1),0.d0,housing_status_grid_size>2)

                        call damp_on_flip(housing_status_grid_expander_adjuster,&
                            gap_housing_status_grid_expander,&
                            previous_gap_housing_status_grid_expander,&
                            have_gap_housing_status_grid_expander,&
                            housing_status_grid_expander_adjuster_start,&
                            housing_status_grid_expander_floor,&
                                flips_housing_status_grid_expander)

                        housing_status_grid_expander=&
                            min(max(housing_status_grid_expander-&
                            housing_status_grid_expander_adjuster*&
                            gap_housing_status_grid_expander,1.d0),5.d0)

                        ! SAME CLAMP AS THE GAP ABOVE. This second index-1 read
                        ! was missed when the gap was fixed and the bounds build
                        ! caught it: the array is 0:housing_status_grid_size-1,
                        ! which is 0:0 at one rental. The distance is forced to
                        ! zero below two rungs so the convergence test cannot be
                        ! held open by a rung that does not exist.
                        distance_housing_status_grid_expander=merge(&
                            abs(model_housing_size_dist(1,min(1,housing_status_grid_size-1))-&
                            housing_size_dist_data(1)),0.d0,housing_status_grid_size>2)

                        write(*,*) "housing_status_grid_expander=", housing_status_grid_expander, &
                            " distance_housing_status_grid_expander=", &
                            distance_housing_status_grid_expander

                        distance_rent_to_price=0
                                                
                    else
                    
                        distance_housing_status_grid_expander=0
                        distance_rent_to_price=0
                        
                    end if
                    
                    if ((calibrate_size_of_smallest_house_hhld_can_buy==0) .AND. &
                        (advantage_to_owning_adjuster==0)) then
                        
                        write(*,*) "rent(1)/housing_price=", rent(1,:)/housing_price(1)
                        
                        distance_rent_to_price=(1-fix_rent)*abs(model_homeownership_rate(1)-SCF_homeownership_rate)
                            
                        if (fix_rent==0) then
                            rent(1,:)=rent(1,:)-rent_to_price_adjuster*&
                                (model_homeownership_rate(1)-SCF_homeownership_rate)
                        end if
                        
                        write(*,*) "rent(1)/housing_price=", rent(1,:)/housing_price(1)
                        write(*,*) "distance_rent_to_price=", distance_advantage_to_owning
                        write(*,*) "model_homeownership_rate(1)=", model_homeownership_rate(1)
                        
                    else
                    
                        write(*,*) "rent(1)=", rent(1,:)
                    
                        if (fix_rent==0) then
                            rent(1,:)=rent(1,:)-rent_to_price_adjuster*&
                                (rent(1,:)/housing_price(1)-rent_to_housing_price)
                        end if
                            
                        write(*,*) "rent(1)=", rent(1,:)
                            
                    end if
                    
                    write(*,*) "size_of_smallest_house_hhld_can_buy=", size_of_smallest_house_hhld_can_buy
                    write(*,*) "housing_status_grid_expander=", housing_status_grid_expander
                    write(*,*) "housing_size(index_of_smallest_house_hhld_can_buy)=", &
                        housing_size(max(min(index_of_smallest_house_hhld_can_buy,housing_status_grid_size-1),lowest_housing_grid_point))
                    write(*,*) "model_fraction_of_homeowners_with_mortgage(1)=", model_fraction_of_homeowners_with_mortgage(1)
                    
                    if ((mortgage_deductibility>0) .OR. (property_tax_deductibility>0)) then
                    
                        write(*,*) "govt_spending_on_mortgage_interest_deductions(1)/model_GDP_incl_imput_rent(1)=", &
                            100*(govt_spending_on_mortgage_interest_deductions(1)/model_GDP_incl_imput_rent(1))
                            
                    end if
                    
                    write(*,*) "smallest_rental_relative_to_lowest_income=", smallest_rental_relative_to_lowest_income                    
                    
                    if (calibrate_smallest_house_size==1) then

                        ! THE SMALLEST RENTAL TARGETS THE SHARE LIVING IN THE
                        ! SMALLEST UNIT. It used to target the employed share of
                        ! the homeless, and that target could not be had at the
                        ! same time as the homelessness RATE, because both were
                        ! being asked of this one parameter and they wanted
                        ! values six to eight times apart. The run measured it:
                        !
                        !   h_2      room as a share    homelessness   employed
                        !            of poorest income      rate       share
                        !   0.0158        45.9%           0.0075        0.934
                        !   0.0048        13.0%           0.00045       0.978
                        !   0.0015         5.3%           0.0000068     0.499
                        !
                        ! The 0.50 employed share needs 0.0015, where the
                        ! cheapest room costs five per cent of the poorest
                        ! household's income and essentially nobody is priced out
                        ! of housing, so homelessness collapses to six hundred
                        ! times below target and h_1 cannot recover it: making
                        ! the street relatively worse cannot put people on it
                        ! when a room is nearly free.
                        !
                        ! The size distribution's bottom rung is the moment this
                        ! parameter can actually carry, and it agrees with the
                        ! homelessness rate about where h_2 belongs. Measured
                        ! across the run, the share on the smallest rung rises
                        ! monotonically in h_2 -- 0.004 at 0.0015, 0.048 at
                        ! 0.0048, 0.236 at 0.0144, 0.398 at 0.0169 -- and crosses
                        ! its target of 0.132 near h_2 = 0.011, which is also
                        ! where the homelessness rate wants it.
                        !
                        ! THE SIGN IS UNCHANGED, and that is not luck: the share
                        ! rises in h_2 and the update subtracts the gap, so a
                        ! share below target raises h_2, which is the direction
                        ! the table above shows.
                        !
                        ! THE EMPTY SET GUARD IS GONE WITH THE OLD MOMENT. The
                        ! size distribution is taken over HOUSED households, who
                        ! are never absent, so there is no conditional mean over
                        ! a vanishing population to protect against here. Leaving
                        ! the guard in would have frozen h_2 at exactly the point
                        ! it is needed, since homelessness is near zero now.
                        write(*,*) "model_housing_size_dist=", model_housing_size_dist(1,:)
                        write(*,*) "housing_size_dist_data=", housing_size_dist_data
                        write(*,*) "smallest_rental_relative_to_lowest_income=", &
                            smallest_rental_relative_to_lowest_income

                        ! THE COST BURDEN, NOT THE SMALLEST UNIT'S SHARE.
                        !
                        ! The author, 11 September: "smallest_rental_relative_to_
                        ! lowest_income should target the 8% spending over 50% of
                        ! their expendigures on rent....not share in smallest unit",
                        ! which restates the instruction of 30 August already
                        ! recorded beside severe_cost_burden_data: "the smallest
                        ! unit's share is a statement about a grid the model chose,
                        ! so matching it disciplines the grid rather than the
                        ! economy; the share of households paying more than half
                        ! their income for shelter is a fact about the world".
                        !
                        ! The target moved then and the BRACKET did not, so h_2's
                        ! 0.08 was printed as a moment with nothing driving it while
                        ! this parameter chased housing_size_dist_data(0) = 0.132065,
                        ! the very grid statistic the instruction retired.
                        !
                        ! SIGN IS UNCHANGED AND directions_table AGREES: a bigger
                        ! cheapest rental costs more, so more households pay over
                        ! half of their outlays for it, so the model share RISES in
                        ! this parameter and a model above target calls for a
                        ! SMALLER rung. The update subtracts the gap, as before.
                        ! RETARGETED 17 September to the renters' 30 per cent
                        ! cut. The sign is unchanged and the reasoning above
                        ! carries over unaltered: a bigger cheapest rental costs
                        ! more, so more renters pay over 30 per cent of income
                        ! for it, so the model share RISES in h_2 and a model
                        ! above target calls for a SMALLER rung.
                        gap_house_size_1=&
                            mass_of_renters_at_housing_spending(1,1)-&
                            renter_burden_30_data

                        if (have_gap_smallest_house_size==1) then

                            ! GUARDED, AND THIS IS THE ONE THAT BIT. h_2 is pinned
                            ! on the author's instruction -- *"i dont think h2 should
                            ! be adjusted"*, *"just set h2=0.142 and pin it"* -- with
                            ! the adjuster at zero. n20 held it for 119 blocks because
                            ! its burden-50 gap never changed sign. n22's arc flipped
                            ! it, max(0*damping,1e-3) returned the floor, growth took
                            ! the adjuster to 4.6e-2 in twenty-three blocks and
                            ! smallest_rental drifted 0.142 to 0.1422 and climbing.
                            if ((gap_house_size_1*previous_gap_smallest_house_size)<0 &
                                .AND. (smallest_house_size_adjuster>0.d0)) then

                                smallest_house_size_adjuster=&
                                    max(smallest_house_size_adjuster*house_size_adjuster_damping,&
                                    house_size_adjuster_floor)

                            else

                                smallest_house_size_adjuster=&
                                    min(smallest_house_size_adjuster*house_size_adjuster_growth,&
                                    smallest_house_size_adjuster_start)

                            end if

                        end if

                        previous_gap_smallest_house_size=gap_house_size_1
                        have_gap_smallest_house_size=1

                        write(*,*) "smallest_house_size_adjuster=", smallest_house_size_adjuster

                        cap_old_1=smallest_rental_relative_to_lowest_income
                        smallest_rental_relative_to_lowest_income=&
                            min(max(smallest_rental_relative_to_lowest_income-smallest_house_size_adjuster*&
                            gap_house_size_1,smallest_rental_floor),10.d0) 
                        smallest_rental_relative_to_lowest_income=&
                            cap_step_rel(smallest_rental_relative_to_lowest_income,&
                            cap_old_1,smallest_rental_max_rel_step)
                                                                     
                        distance_smallest_house_size=&
                            abs(val_burden50_expend_all(1)/&
                            max(val_mass_expend_all(1),10.d0**(-14))-&
                            severe_cost_burden_data)

8801                    continue
                                                         
                    else
                    
                        distance_smallest_house_size=0
                    
                    end if
                    
                    write(*,*) "smallest_rental_relative_to_lowest_income=", smallest_rental_relative_to_lowest_income
                    write(*,*) "mass_of_renters_at_housing_spending=", &
                        mass_of_renters_at_housing_spending(1,target_30_perc*1+(1-target_30_perc)*2)
                        
                    write(*,*) "labor_income_tax_rate=", labor_income_tax_rate

                    ! THE PLUS IS CORRECT AND THE NAME IS NOT. labor_income_tax_rate
                    ! is the RETENTION SCALE in the tax function
                    !
                    !     tax = y - labor_income_tax_rate * y**curvature
                    !
                    ! so it multiplies income KEPT, not income taken. Raising it
                    ! lowers the average effective tax rate, which is why an
                    ! average tax above target is met by raising this number. Its
                    ! declared value of 0.75 only makes sense read that way; as a
                    ! marginal rate it would be absurd. Anyone auditing signs from
                    ! the variable names will read this one as inverted and be
                    ! wrong, which is why the note is here rather than nowhere.
                    ! GUARDED ON THE ADJUSTER.  With the tax removed this block
                    ! must not compute a live distance from a moment whose
                    ! parameter cannot move.
                    if (labor_income_tax_rate_adjuster<=0.d0) then

                        distance_labor_income_tax_rate=0

                    else
                    call damp_on_flip(labor_income_tax_rate_adjuster,&
                        model_average_labour_income_tax(1)-average_labor_income_tax_data,&
                        previous_gap_labor_income_tax_rate,have_gap_labor_income_tax_rate,&
                        labor_income_tax_rate_adjuster_start,damp_adjuster_floor,&
                            flips_labor_income_tax_rate)
                    write(*,*) "labor_income_tax_rate_adjuster=", labor_income_tax_rate_adjuster
                    cap_old_1=labor_income_tax_rate
                    labor_income_tax_rate=max(min(labor_income_tax_rate+labor_income_tax_rate_adjuster*&
                        (model_average_labour_income_tax(1)-average_labor_income_tax_data),2.d0),0.d0)
                    labor_income_tax_rate=cap_step(labor_income_tax_rate,cap_old_1)

                    distance_labor_income_tax_rate=&
                        abs(model_average_labour_income_tax(1)-average_labor_income_tax_data)

                    write(*,*) "average labour income tax rate =", model_average_labour_income_tax(1),&
                        " against ", average_labor_income_tax_data,&
                        " distance_labor_income_tax_rate=", distance_labor_income_tax_rate

                    end if

                    if ((labor_income_tax_rate_adjuster>0.d0) .AND.&
                        ((labor_income_tax_rate<=10.d0**(-8)) .OR. (labor_income_tax_rate>=2.d0-10.d0**(-8)))) then

                        write(*,*) "the retention scale IS PINNED AT A BOUND", labor_income_tax_rate,&
                            " and the average labour income tax rate is ", model_average_labour_income_tax(1),&
                            " against ", average_labor_income_tax_data

                    end if
                        
                    write(*,*) "labor_income_tax_rate=", labor_income_tax_rate
                                                            
                    if (mortgage_deductibility==1) then
                    
                        write(*,*) "fraction_using_MID(1)=", fraction_using_MID(1)
                        write(*,*) "standard_deduction_as_percent_of_average_labor_income=", &
                            standard_deduction_as_percent_of_average_labor_income
                    
                        standard_deduction_as_percent_of_average_labor_income=&
                            max(min(standard_deduction_as_percent_of_average_labor_income+&
                            standard_deduction_adjuster*&
                            (100*(govt_spending_on_mortgage_interest_deductions(1)/model_GDP_incl_imput_rent(1))-&
                            MID_to_GDP_data),1.d0),0.d0)
                            
                        distance_standard_deduction=&
                            abs(100*(govt_spending_on_mortgage_interest_deductions(1)/model_GDP_incl_imput_rent(1)))
                            
                        write(*,*) "standard_deduction_as_percent_of_average_labor_income=", &
                            standard_deduction_as_percent_of_average_labor_income
                        write(*,*) "distance_standard_deduction=", distance_standard_deduction
                    
                    else
                        
                        distance_standard_deduction=0
                        standard_deduction_as_percent_of_average_labor_income=0 !0.08
                    
                    end if
                                        
                    if (fixed_cost_to_moving_adjuster>0)  then
                    
                        write(*,*) "fixed_cost_to_moving=", fixed_cost_to_moving
                                
!                        fixed_cost_to_moving=max(min(fixed_cost_to_moving-fixed_cost_to_moving_adjuster*&
!                            (model_years_in_same_rental(1,2)-average_years_in_same_rental_data),1.d0),0.d0)
!                            
!                        distance_fixed_cost_to_moving=abs(model_years_in_same_rental(1,2)-average_years_in_same_rental_data)
                            
                        write(*,*) "fixed_cost_to_moving=", fixed_cost_to_moving
                        write(*,*) "distance_fixed_cost_to_moving=", distance_fixed_cost_to_moving
                    
                    else
                    
                        distance_fixed_cost_to_moving=0
                    
                    end if
                                        
                    ! LAMBDA on the substance use disorder rate.
                    write(*,*) "model_fraction_addicted(1)=", model_fraction_addicted(1)
                    write(*,*) "sud_rate_data=", sud_rate_data
                    write(*,*) "probability_of_becoming_addicted_if_experiment=", &
                        probability_of_becoming_addicted_if_experiment

                    if (smooth_addiction_hazard==1) then

                        ! LAMBDA IS BRACKETED THROUGH THE ONSET AT THE MEAN
                        ! QUANTITY, not directly, and that is what makes the
                        ! bracket transferable.
                        !
                        ! lambda is a hazard per unit of drug, so its scale is
                        ! whatever the model's consumption units happen to be and
                        ! an adjuster tuned at one calibration would be wrong at
                        ! the next. The onset a mean user faces,
                        ! 1-exp(-lambda vbar), is a probability whatever the
                        ! units, it is monotone in lambda, and it is the same
                        ! object the flat hazard was: so the update runs on it
                        ! with the step and the bracket the flat hazard already
                        ! used, and lambda is recovered by inverting at the
                        ! model's own mean. Nothing is left to depend on a guess
                        ! about scale except the very first backward pass.
                        !
                        ! Sign is unchanged: a higher hazard means more of the
                        ! people who use acquire the disorder, so prevalence
                        ! rises in it and the update subtracts the gap.
                        mean_drug_quantity_1=model_drugs_used_by_users_on_average(1)

                        if (mean_drug_quantity_1>0) then

                            ! THROUGH THE FUNCTION, not the bare exponential. This
                            ! drives the SECANT that calibrates lambda_addiction, so
                            ! with addiction_onset_base live the bare form would have
                            ! it solving for a hazard the model does not use.
                            onset_at_mean_1=addiction_onset_hazard(mean_drug_quantity_1)

                            ! SECANT ON THE ONSET, NOT A FIXED STEP, and the
                            ! first step comes from the flow balance rather than
                            ! from the adjuster.
                            !
                            ! An equilibrium is hours, so the number of loops IS
                            ! the calibration time and a fixed step that has to
                            ! creep is the wrong instrument. Two things fix it.
                            !
                            ! THE FIRST STEP IS ANALYTIC. In the stationary
                            ! distribution the disorder is a two state flow
                            ! balance: onset times the mass using equals recovery
                            ! times the mass carrying it, so prevalence is very
                            ! nearly proportional to the onset at a given share
                            ! who use. Scaling the onset by the ratio of target
                            ! to model prevalence therefore lands close on the
                            ! first try, where the fixed step would have taken
                            ! twenty loops to cover the same ground when the
                            ! model came in at nine times the data.
                            !
                            ! AFTER THAT IT IS A SECANT. Two (onset, prevalence)
                            ! pairs give the local slope, which is what the
                            ! proportionality above only approximates once the
                            ! share who use responds to the hazard as well. The
                            ! step is clipped to a factor of four either way so a
                            ! flat or noisy secant cannot throw lambda across the
                            ! bracket, and it falls back to the proportional rule
                            ! whenever the two prevalences are too close to
                            ! divide by.
                            ! AND THE SECANT IS ONLY READ WHEN ITS SLOPE HAS THE SIGN THE
                            ! MODEL GUARANTEES. Prevalence rises in the onset hazard with
                            ! everything else held fixed, so a measured slope that is
                            ! negative is not news about the model, it is a reading taken
                            ! through another instrument's move. This loop is Gauss-Seidel:
                            ! b moved in the same pass, and when it moves participation by
                            ! more than the hazard moves conversion the difference in
                            ! prevalence carries b's sign, not lambda's.
                            !
                            ! WHAT WAS ACTUALLY MEASURED ON THE RUN THIS GUARD WAS ADDED
                            ! FOR, since the first reading of it was wrong and the wrong
                            ! reading is the more tempting one. Prevalence fell from 5.79e-4
                            ! to 7.31e-6 while b cut participation thirteenfold in the same
                            ! loop, and it looked as though the secant had inverted. It had
                            ! not. onset_at_mean is recomputed each loop at the MODEL'S OWN
                            ! mean quantity, and that mean collapsed from 1.09e-2 to 1.19e-3
                            ! along with participation, so the onset fell from 1.19e-3 to
                            ! 1.30e-4 even though lambda QUADRUPLED, from 0.1095 to 0.4381,
                            ! which is its clamp. The slope came out at +1.86, the secant
                            ! was not rejected, and it asked for an onset of 0.0685 that the
                            ! clamp cut to four times the current one. Lambda was pushing as
                            ! hard as it is allowed to, in the right direction, the whole
                            ! time.
                            !
                            ! So the collapse was b's alone, and b's damping is what fixes
                            ! it. The lesson lambda carries is a different one: a hazard
                            ! clipped to a factor of four a loop cannot hold prevalence
                            ! while another instrument moves the population it acts on by a
                            ! factor of thirteen. Damping b is what makes lambda's clamp
                            ! sufficient.
                            !
                            ! The slope test stays, because a contaminated slope CAN come
                            ! out negative and there is nothing to be gained from stepping
                            ! on it. It is a safeguard against a case that can arise and not
                            ! a fix for one that did. A rejected secant falls back to the
                            ! proportional rule, which cannot point the wrong way: it scales
                            ! the hazard by target over model and both are positive.
                            !
                            ! WORTH KNOWING WHEN READING THE SECANT AT ALL: because the two
                            ! onsets are measured at two different mean quantities, the
                            ! slope is not a clean derivative of prevalence in the hazard.
                            ! It mixes in the change in how much users buy. That is a
                            ! consequence of calibrating the onset at the mean rather than
                            ! calibrating lambda directly, which is deliberate and is
                            ! explained above, but it means the secant is an approximation
                            ! and should be read as one.
                            ! THE AUTHOR'S RULE, AND NO SECANT. Their instruction of
                            ! 13 September: *"i dont want any bisections and any
                            ! secants"*, then the rule -- parameter + adjuster times
                            ! (model moment - data moment), capped per loop.
                            !
                            ! THE DIRECTION IS MEASURED AND IT IS THE OPPOSITE OF THE
                            ! OBVIOUS ONE. Single parameter, loop 1, 11 September, with
                            ! nothing else moving:
                            !
                            !     onset 0.0428 -> 0.0550   lambda_d -49.0%   e = -2.68
                            !     onset 0.0428 -> 0.0350   lambda_d +74.3%   e = -2.76
                            !
                            ! Monotone, negative both sides, the same slope either way.
                            ! RAISING THE ONSET HAZARD LOWERS THE DISORDER RATE: making
                            ! use riskier deters people from using at all, and the
                            ! extensive margin beats the conversion margin. So the
                            ! disorder rate FALLS in the onset, the adjuster is POSITIVE
                            ! in the author's form, and the step ADDS the gap -- a
                            ! disorder rate above target raises the onset.
                            !
                            ! Getting this backwards is not hypothetical. An earlier
                            ! round assumed the naive sign, rejected negative secant
                            ! slopes as contamination, and fell back to a proportional
                            ! rule that raised the onset whenever the disorder rate was
                            ! low -- which lowered it further. Over nineteen loops that
                            ! took lambda_d from +2.0 per cent to -33 and dragged
                            ! participation from -0.9 to -34 with it.
                            !
                            ! WHAT GOES WITH THE SECANT. The slope estimate, the
                            ! proportional first step, the lambda_clamp trust region and
                            ! the move_factor bound all go: the per-loop ceiling is
                            ! cap_step now, which is what the rule asks for.
                            ! previous_onset_at_mean and previous_sud_rate are still
                            ! maintained so the calibration state file is unchanged.
                            previous_onset_at_mean=onset_at_mean_1
                            previous_sud_rate=model_fraction_addicted(1)
                            have_lambda_secant=1

                            ! THE ONSET TARGETS SUD PER USER, NOT SUD PER HEAD, AND IT
                            ! FALLS WHEN THAT RATIO IS TOO HIGH. The author, 16
                            ! September: *"SUD has to be about 41% of b"*, then *"so the
                            ! onset show be lower if you have SUD over 41.3% of drug
                            ! users"*. 0.0368/0.0890 = 0.4135, so the 41 per cent is the
                            ! ratio of the two targets and is computed from them here
                            ! rather than typed, so it follows if either target moves.
                            !
                            ! WHY THE SIGN WAS WRONG BEFORE. This line read
                            ! onset + adjuster*(model_fraction_addicted - sud_rate_data),
                            ! a PLUS on the LEVEL, which raised the onset whenever the
                            ! disorder rate was high. That implements "raising the onset
                            ! deters use, and the extensive margin beats the conversion
                            ! margin", measured as an elasticity near -2.7 and recorded
                            ! above. The comment immediately below that measurement
                            ! already says why it cannot be trusted: prevalence is a two
                            ! state flow balance, so at a given share who use it RISES in
                            ! the onset, and a negative measured slope "is not news about
                            ! the model, it is a reading taken through another
                            ! instrument's move" -- b moved in the same Gauss-Seidel pass.
                            ! The code and its own comments had been contradicting each
                            ! other in this block.
                            !
                            ! ON THE RATIO THE AMBIGUITY DISAPPEARS. The extensive margin
                            ! cancels out of SUD-per-user, so only the conversion margin
                            ! is left and the sign is the intuitive one: too many users
                            ! converting means the hazard is too high.
                            onset_step_1=onset_at_mean_1-onset_base_adjuster*&
                                (model_fraction_addicted(1)/&
                                max(model_total_drug_users(1),10.d0**(-14))-&
                                sud_rate_data/participation_rate_data)

                            onset_at_mean_1=max(min(onset_step_1,0.2d0),1.d0*10.d0**(-5))

                            ! THE BASE MOVES AND LAMBDA_D STAYS AT ZERO. The author,
                            ! 11 September: "lambda_d should be 0, only the base
                            ! changes, so the probability of SUD is flat for any v>0".
                            !
                            ! The hazard is base + (1 - exp(-lambda_d v)) above v=0 and
                            ! zero at v=0, so lambda_d = 0 makes it exactly flat: a
                            ! household that uses at all faces the base, and using MORE
                            ! carries no extra risk. The vector already hands
                            ! lambda_addiction in at 0, so that is where a run starts --
                            ! and this line then drove it off zero on the first update,
                            ! turning the hazard into a dose-response every loop and
                            ! leaving the base doing nothing. The specification was the
                            ! starting point and the loop undid it.
                            !
                            ! Everything above is unchanged and needs no change: the
                            ! secant, the clamp and the analytic first step all work on
                            ! onset_at_mean_1, which is read through
                            ! addiction_onset_hazard() and therefore IS the base once
                            ! lambda_d is zero. So this is a secant on the base.
                            !
                            ! THE CONSEQUENCE, STATED BECAUSE IT IS A MODELLING CHOICE
                            ! AND NOT A DETAIL: addiction_onset_hazard_slope is
                            ! lambda_d exp(-lambda_d v), so at lambda_d = 0 the marginal
                            ! risk of one more unit of the drug is ZERO. All of the
                            ! disorder risk sits on the extensive margin. A household
                            ! deciding how MUCH to use weighs no health risk at all;
                            ! only the decision to use at all carries one.
                            ! THE SAME SHARED COOLDOWN b USES. See its
                            ! declaration: these two act on one margin, and
                            ! throttling only one of them buys nothing.
                            ! ITS OWN COUNTER, 16 September. THE SHARED ONE MADE THIS
                            ! BRACKET UNREACHABLE. The counter is incremented and reset
                            ! inside b's section at lines 47470 and 47482, which run
                            ! AFTER this check, so the onset saw 0,1,2,3,4 and then b
                            ! stepped and reset it to 0. It never observed the cooldown
                            ! expiring and could not fire, ever. n03 proves it: across
                            ! 277 blocks "DIAG onset at the mean quantity" printed
                            ! exactly ONE distinct value, and every cooldown line in the
                            ! log reads "b HELD", never "onset HELD".
                            !
                            ! The disorder rate's 36 per cent gap was therefore not a
                            ! hard moment, it was a dead instrument. The shared counter
                            ! was added to stop the onset stepping every block while the
                            ! model needed four to settle; it overshot to never.
                            blocks_since_onset_step=blocks_since_onset_step+1

                            if (blocks_since_onset_step<b_step_cooldown) then

                                write(*,*) "onset HELD: ", blocks_since_onset_step,&
                                    " of", b_step_cooldown, " cooldown blocks since",&
                                    " the last drug-block step. The disorder rate reads",&
                                    model_fraction_addicted(1)
                                lambda_addiction=0.d0

                            else

                            blocks_since_onset_step=0

                            cap_old_1=addiction_onset_base
                            addiction_onset_base=onset_at_mean_1
                            ! ON THE DRUG BLOCK'S RATE. It owns the disorder rate,
                            ! which sat at -91 per cent on the global cap.
                            addiction_onset_base=cap_step_rel(addiction_onset_base,&
                                cap_old_1,drug_block_max_rel_step)

                            lambda_addiction=0.d0

                            write(*,*) "model_drugs_used_by_users_on_average(1)=", mean_drug_quantity_1
                            write(*,*) "onset_at_the_mean_quantity=", onset_at_mean_1
                            ! LAMBDA_D'S INSTRUMENT, PRINTED AT LAST.  This is the
                            ! parameter that actually moves the disorder rate --
                            ! probability_of_becoming_addicted_if_experiment sits in
                            ! the else branch below and never executes, which is why
                            ! it is frozen at its seed in every log.  Before this
                            ! line, addiction_onset_base appeared exactly ONCE in a
                            ! thirty-loop log, on the handover, so there was no way
                            ! to tell whether it was stuck, crawling or against its
                            ! [0,1] bounds.  Every claim made about lambda_d today
                            ! was guesswork for want of one write statement.
                            write(*,*) "addiction_onset_base=", addiction_onset_base,&
                                " distance_lambda_addiction=",&
                                abs(model_fraction_addicted(1)-sud_rate_data),&
                                merge(" RAISED: lambda_d is below target ",&
                                      " LOWERED: lambda_d is above target",&
                                      model_fraction_addicted(1)<sud_rate_data)

                            ! closes the shared cooldown gate opened above
                            end if

                        else

                            write(*,*) "no drug use at all, lambda left where it is"

                        end if

                        distance_lambda_addiction=&
                            abs(model_fraction_addicted(1)-sud_rate_data)

                        ! The flat hazard is not calibrated alongside it. Two
                        ! parameters on one moment is not identification, it is a
                        ! race, and with the smooth form on the flat number is
                        ! read only where the household abstains, where it is
                        ! multiplied by zero.
                        distance_probability_of_becoming_addicted=0

                        write(*,*) "lambda_addiction=", lambda_addiction
                        write(*,*) "distance_lambda_addiction=", distance_lambda_addiction

                    else

                        cap_old_1=probability_of_becoming_addicted_if_experiment
                        probability_of_becoming_addicted_if_experiment=&
                            max(min(probability_of_becoming_addicted_if_experiment-&
                            probability_of_becoming_addicted_adjuster*&
                            (model_fraction_addicted(1)-sud_rate_data),0.2d0),1.d0*10.d0**(-5))
                        probability_of_becoming_addicted_if_experiment=cap_step(probability_of_becoming_addicted_if_experiment,cap_old_1)

                        distance_probability_of_becoming_addicted=&
                            abs(model_fraction_addicted(1)-sud_rate_data)

                        distance_lambda_addiction=0

                        write(*,*) "probability_of_becoming_addicted_if_experiment=", &
                            probability_of_becoming_addicted_if_experiment
                        write(*,*) "distance_probability_of_becoming_addicted=", &
                            distance_probability_of_becoming_addicted

                    end if

                    ! THE UTILITY COST OF TREATMENT, on take up given a SUD.
                    !
                    ! Sign: a higher cost means fewer households take treatment,
                    ! so take up FALLS in it and the update adds the gap. Same
                    ! secant as lambda and rent, for the same reason: the number
                    ! of loops is the calibration time.
                    !
                    ! Take up is bounded in [0,1] and the cost is in utils, so
                    ! the fallback step is a fixed one on the gap rather than a
                    ! proportional rule, which would be meaningless at a take up
                    ! of zero.
                    if (include_treatment==1) then

                        write(*,*) "model_treatment_take_up(1)=", model_treatment_take_up(1)
                        write(*,*) "treatment_take_up_data=", treatment_take_up_data
                        write(*,*) "utility_cost_of_treatment=", utility_cost_of_treatment

                        ! THE SIGN. Take up FALLS in the cost: the cost is
                        ! subtracted from flow utility in the period treatment is
                        ! taken, so raising it makes treatment less attractive.
                        ! The step therefore has to move the cost AGAINST the
                        ! gap, not with it. Written with a plus, as it was, a
                        ! take up below target raised the cost, which lowered take
                        ! up further, which raised the cost again: measured over
                        ! thirteen iterations the cost ratcheted from 0.020 to
                        ! 0.151 in exact steps of adjuster*(0.24-0) = 0.012 while
                        ! take up sat at zero throughout. The secant below cannot
                        ! rescue it, because a take up that never moves fails the
                        ! guard on its own change and the fallback runs every
                        ! time. This is the same error as the kappa_uem update,
                        ! which was also copied from a moment that runs the other
                        ! way.
                        treatment_step_1=utility_cost_of_treatment-&
                            utility_cost_of_treatment_adjuster*&
                            (treatment_take_up_data-model_treatment_take_up(1))

                        ! THE SECANT AND THE TRUST STEP ARE BOTH GONE, on the
                        ! author's instruction of 13 and 14 September: no secants,
                        ! and every internally calibrated parameter moves by the
                        ! gap step with a per-cent ceiling. The step above is that
                        ! rule; treatment_cost_max_rel_step is the ceiling, one per
                        ! cent. previous_utility_cost_of_treatment and
                        ! previous_treatment_take_up are still maintained so the
                        ! checkpoint format does not change.
                        previous_utility_cost_of_treatment=utility_cost_of_treatment
                        previous_treatment_take_up=model_treatment_take_up(1)
                        have_treatment_secant=1
                        ! RAISED 10 -> 20 WITH THE HANDOVER CLAMP, so the two
                        ! ceilings on this parameter cannot disagree.
                        !
                        ! THE COMMENT HERE USED TO SAY THIS BRACKET WAS DORMANT,
                        ! "the adjuster is zero and three_step drives the parameter
                        ! from outside". That stopped being true when
                        ! freeze_to_three_block went to 0:
                        ! utility_cost_of_treatment_adjuster is
                        ! (1-freeze_to_three_block)*5e-2, so the bracket is live and
                        ! has been running every loop of the full calibration.
                        !
                        ! FIVE PER CENT A LOOP, NOT THE GLOBAL HALF A PER CENT. The
                        ! author, 11 September: "The utility cost of treatment has to
                        ! be adjusted much faster. Maybe 5% each iteration". cap_step
                        ! was the binding constraint, not the adjuster -- it allows
                        ! max_rel_step_all, which is 5e-3 here -- so the parameter
                        ! crawled 14.31 -> 14.41 over nine loops against a take up
                        ! 192 per cent out. cap_step_rel applies the identical cap at
                        ! the rate named, and it is named only here, so no other
                        ! parameter's step changes.
                        cap_old_1=utility_cost_of_treatment
                        utility_cost_of_treatment=max(min(treatment_step_1,20.d0),0.d0)
                        utility_cost_of_treatment=cap_step_rel(utility_cost_of_treatment,&
                            cap_old_1,treatment_cost_max_rel_step)

                        ! ZEROED WHEN THE ADJUSTER IS ZERO, OR THE LOOP CANNOT EXIT.
                        ! utility_cost_of_treatment_adjuster is 0, so the step below
                        ! cannot move the parameter, so this distance can never fall
                        ! below its stopping rule -- and it sits in the do while
                        ! condition, so the calibration loop ran to its iteration cap
                        ! on every point and stopped with the OTHER distances wherever
                        ! they happened to be, rather than converged.
                        !
                        ! tau_u is owned externally by next_batch.py through
                        ! utility_cost_of_treatment, so the moment is not abandoned;
                        ! it is calibrated across points instead of inside the loop.
                        ! This is the same shape as freeze_fitted_internals: an
                        ! adjuster at zero must take its distance out of the
                        ! convergence test with it.
                        distance_utility_cost_of_treatment=&
                            merge(0.d0,abs(model_treatment_take_up(1)-treatment_take_up_data),&
                            utility_cost_of_treatment_adjuster<=0.d0)

                        write(*,*) "utility_cost_of_treatment=", utility_cost_of_treatment
                        write(*,*) "distance_utility_cost_of_treatment=", &
                            distance_utility_cost_of_treatment

                        ! SAY SO WHEN THE COST CAN GO NO LOWER, the way the
                        ! lambda_m floor does. At a cost of zero treatment is free
                        ! in utils and still costs the household its drug
                        ! spending, since taking it forces abstention. So a take
                        ! up of zero here is not a failure of this update: it says
                        ! the benefit side is too small, which is g, mu_H, pi_r
                        ! and the abstention itself, and no value of bar_tau^u
                        ! reaches the target.
                        if ((utility_cost_of_treatment<=0.d0) .AND. &
                            (model_treatment_take_up(1)<treatment_take_up_data)) then

                            write(*,*) "utility_cost_of_treatment IS AT ITS FLOOR 0 and take up is ",&
                                model_treatment_take_up(1), " against a target of ", treatment_take_up_data
                            write(*,*) "   treatment is declined even when free, so the target is out of",&
                                " reach on the benefit side, not on the cost."

                        end if

                    ! ========= y_u, THE INCOME OF DRUG USERS ===================
                    ! kappa_phi_d_level, TWO-SIDED, bounded 2 to 9 and capped at
                    ! half a per cent a loop.
                    !
                    ! WIRED 11 September. y_u carried a data value and a comment
                    ! naming kappa_phi_d_level as its instrument, and nothing
                    ! connected them: no adjuster, no distance, no update. The level
                    ! was set by hand from the vector, so y_u was a target the loop
                    ! never moved toward.
                    !
                    ! THE SIGN, and it is measured rather than argued. The mortality
                    ! penalty is the price of using, so a high one leaves only the
                    ! most desperate willing to pay it. Taking the level 8.0 -> 6.5
                    ! moved y_u 0.333 -> 0.533. y_u below target therefore calls for
                    ! a LOWER level, and the step kappa - adjuster*(target - model)
                    ! is negative-going exactly then.
                    !
                    ! HALF A PER CENT A LOOP, on the author's instruction: "after
                    ! that let it adjust slowly, not more than 0.5% per iteration".
                    ! That is what plain cap_step gives, since max_rel_step_all is
                    ! 5e-3 whenever freeze_to_three_block is 0, so this bracket uses
                    ! cap_step and NOT the cap_step_rel that the treatment cost
                    ! needed. The reason for going slowly is in the measurement
                    ! above: one step of 8.0 -> 6.5, nineteen per cent, doubled
                    ! participation and the disorder rate in a single loop.
                    !
                    ! READ THE MOMENT ONLY WHERE b IS NEAR TARGET. The author: "you
                    ! first have to get the users right". y_u is the users' income
                    ! over average income, so when nearly everyone uses, the users
                    ! ARE the population and the ratio approaches one for reasons
                    ! that have nothing to do with the composition this parameter
                    ! acts on. No gate on b is imposed here, because none was asked
                    ! for and the half-per-cent cap is the author's chosen answer to
                    ! it -- the bracket moves slowly enough for b's own instrument to
                    ! keep up. If it turns out to chase a contaminated ratio anyway,
                    ! the fix is a gate like the one omega_c already has, which
                    ! refuses to PIN while the economy around the ratio is wrong.
                    if ((kappa_phi_d_level_adjuster>0) .AND. &
                        (abs(model_total_drug_users(1)-participation_rate_data)<=&
                        kappa_gate_b_tolerance*participation_rate_data)) then

                        write(*,*) "KAPPA GATE OPEN: b=", model_total_drug_users(1),&
                            " is within", kappa_gate_b_tolerance,&
                            " of", participation_rate_data, "-- y_u is a composition"
                        write(*,*) "model y_u income of drug users =",&
                            model_avg_income_drug_users(1)/&
                            max(model_average_income(1),10.d0**(-14)),&
                            " target =", drug_user_income_data
                        write(*,*) "kappa_phi_d_level=", kappa_phi_d_level

                        ! HOLD INSIDE THE BAND. b being near target is what makes
                        ! y_u a composition at all, so this test only runs with the
                        ! gate already open; inside the band the parameter keeps its
                        ! value and the distance still reports the real gap, for the
                        ! same reason the gate-shut branch below does.
                        if ((model_avg_income_drug_users(1)/&
                            max(model_average_income(1),10.d0**(-14))>=yu_band_lo)&
                            .AND. (model_avg_income_drug_users(1)/&
                            max(model_average_income(1),10.d0**(-14))<=yu_band_hi)) then

                            distance_kappa_phi_d_level=&
                                abs(model_avg_income_drug_users(1)/&
                                max(model_average_income(1),10.d0**(-14))-&
                                drug_user_income_data)

                            write(*,*) "Y_U IN BAND: y_u=",&
                                model_avg_income_drug_users(1)/&
                                max(model_average_income(1),10.d0**(-14)),&
                                " within [", yu_band_lo, ",", yu_band_hi,&
                                "] -- kappa_phi_d HELD at", kappa_phi_d_level

                        else

                        cap_old_1=kappa_phi_d_level
                        kappa_phi_d_level=max(min(kappa_phi_d_level-&
                            kappa_phi_d_level_adjuster*&
                            (drug_user_income_data-model_avg_income_drug_users(1)/&
                            max(model_average_income(1),10.d0**(-14))),&
                            kappa_phi_d_level_hi),kappa_phi_d_level_lo)
                        ! cap_step_rel, NOT cap_step: the death risk gets its
                        ! own rate rather than the global one. It is 0.05 per
                        ! cent a loop, from the author's instruction of 13
                        ! September; the rate itself lives at
                        ! kappa_phi_d_max_rel_step and this comment names no
                        ! number so the two cannot drift apart again.
                        kappa_phi_d_level=cap_step_rel(kappa_phi_d_level,cap_old_1,&
                            kappa_phi_d_max_rel_step)

                        distance_kappa_phi_d_level=&
                            abs(model_avg_income_drug_users(1)/&
                            max(model_average_income(1),10.d0**(-14))-&
                            drug_user_income_data)

                        write(*,*) "kappa_phi_d_level=", kappa_phi_d_level,&
                            " distance_kappa_phi_d_level=", distance_kappa_phi_d_level,&
                            merge(" LOWERED: y_u is below target ",&
                                  " RAISED:  y_u is above target ",&
                                  model_avg_income_drug_users(1)/&
                                  max(model_average_income(1),10.d0**(-14))<&
                                  drug_user_income_data)

                        ! SAY SO AT EITHER BOUND, rather than letting a railed
                        ! parameter look like a converging one.
                        if ((kappa_phi_d_level<=kappa_phi_d_level_lo) .OR.&
                            (kappa_phi_d_level>=kappa_phi_d_level_hi)) then
                            write(*,*) "kappa_phi_d_level IS AT A BOUND:",&
                                kappa_phi_d_level, " in [", kappa_phi_d_level_lo,&
                                ",", kappa_phi_d_level_hi, "]. y_u is",&
                                model_avg_income_drug_users(1)/&
                                max(model_average_income(1),10.d0**(-14)),&
                                " against", drug_user_income_data,&
                                ". The literature range cannot reach the target and",&
                                " the shortfall is not this parameter's to close."
                        end if

                        end if

                    elseif (kappa_phi_d_level_adjuster>0) then

                        ! LIVE BUT WAITING: the adjuster is on and the gate is
                        ! shut because b is outside its tolerance. The parameter
                        ! must NOT step -- y_u is not a composition at a fixed
                        ! count right now -- but it must also NOT read as
                        ! converged, so the distance is still computed from the
                        ! moment. Setting it to zero here would be the defect
                        ! ENGINE.md records as having cost a whole calibration: a
                        ! parameter that cannot move reporting distance 0 lets the
                        ! outer do-while exit on a target nobody is hitting.
                        distance_kappa_phi_d_level=&
                            abs(model_avg_income_drug_users(1)/&
                            max(model_average_income(1),10.d0**(-14))-&
                            drug_user_income_data)

                        write(*,*) "KAPPA GATE SHUT: b=", model_total_drug_users(1),&
                            " is outside", kappa_gate_b_tolerance, " of",&
                            participation_rate_data, "-- kappa_phi_d HELD at",&
                            kappa_phi_d_level, ", distance still",&
                            distance_kappa_phi_d_level

                    else

                        distance_kappa_phi_d_level=0

                    end if

                    ! ===== sud_homeless, THE SUD SHARE OF THE HOMELESS =========
                    ! multiple_find_if_addicted, TWO-SIDED, bounded [1,100].
                    !
                    ! OPENED 11 September on the author's instruction, reversing
                    ! their earlier "score it, but dont adjust it" of the same day.
                    !
                    ! THE SIGN IS INVERTED RELATIVE TO THE PARAMETER'S NAME, which
                    ! is why it is spelled out at both the declaration and here. The
                    ! parameter DIVIDES the finding probability, so raising it makes
                    ! the addicted find work LESS easily and puts MORE of them on the
                    ! street. The author wants the finding rate to RISE because there
                    ! are too many homeless with a disorder, and that means this
                    ! parameter FALLS. The step is
                    ! multiple - adjuster*(model - target), negative-going exactly
                    ! when the model is above target, which is the current case:
                    ! 0.2698 against 0.217.
                    ! GATED ON b, 16 September, on the author's *"Let's find get b
                    ! right, and only then move find if addicted"*.
                    !
                    ! WITHOUT THE GATE IT RUNS AWAY, and n12 showed it doing so. The
                    ! SUD share of the homeless is a COMPOSITION, and composition is
                    ! meaningless when the population it is composed of has nearly
                    ! vanished. Raising this parameter cuts the addicted's job-finding
                    ! rate, which drives people out of use; fewer users means fewer
                    ! addicted among the homeless; so the rule raises it again. In n12
                    ! it climbed 3.53 -> 5.56 in 22 blocks at its 2 per cent cap every
                    ! single block, participation fell 0.094 -> 0.013, and its OWN
                    ! moment went the wrong way, 0.217 target against 0.052 model and
                    ! widening. A positive feedback, not a search.
                    !
                    ! THE SPEEDS MADE IT WORSE AND THAT WAS MINE. This runs at 2 per
                    ! cent a block with no cooldown; b's instrument runs at 0.6 per
                    ! cent behind a five-block cooldown, so 0.12 per cent a block. b
                    ! moves SEVENTEEN TIMES SLOWER and cannot correct what this does.
                    ! The 2 per cent was set on 15 September at the author's request to
                    ! update it faster, when b ran at 0.5 per cent with no cooldown and
                    ! the ratio was four-fold; slowing b after n02's collapse is what
                    ! opened the gap to seventeen, and I did not check it against the
                    ! other instruments.
                    !
                    ! SAME GATE, SAME TOLERANCE AS kappa's, which exists for the mirror
                    ! image of this: read a composition only where b is near target.
                    if ((multiple_find_adjuster>0) .AND. &
                        (abs(model_total_drug_users(1)-participation_rate_data)>&
                        kappa_gate_b_tolerance*participation_rate_data)) then

                        write(*,*) "MULTIPLE_FIND GATE SHUT: b=", model_total_drug_users(1),&
                            " is outside", kappa_gate_b_tolerance, " of",&
                            participation_rate_data, " -- multiple_find_if_addicted HELD at",&
                            multiple_find_if_addicted

                    else if (multiple_find_adjuster>0) then

                        write(*,*) "model SUD share of the homeless =",&
                            model_fraction_homeless_and_addicted(1),&
                            " target =", sud_share_of_homeless
                        write(*,*) "multiple_find_if_addicted=", multiple_find_if_addicted

                        cap_old_1=multiple_find_if_addicted
                        multiple_find_if_addicted=max(min(multiple_find_if_addicted-&
                            multiple_find_adjuster*&
                            (model_fraction_homeless_and_addicted(1)-&
                            sud_share_of_homeless),&
                            multiple_find_hi),multiple_find_lo)
                        ! ON THE DRUG BLOCK'S RATE, not the global one.  It owns the
                        ! SUD share of the homeless, which sat at -82 per cent while
                        ! the global cap let this move 0.1 per cent a loop.
                        multiple_find_if_addicted=&
                            cap_step_rel(multiple_find_if_addicted,cap_old_1,&
                            multiple_find_max_rel_step)

                        distance_multiple_find=&
                            abs(model_fraction_homeless_and_addicted(1)-&
                            sud_share_of_homeless)

                        write(*,*) "multiple_find_if_addicted=", multiple_find_if_addicted,&
                            " distance_multiple_find=", distance_multiple_find,&
                            merge(" LOWERED: finding rate RISES ",&
                                  " RAISED:  finding rate FALLS ",&
                                  model_fraction_homeless_and_addicted(1)>&
                                  sud_share_of_homeless)

                        ! THE FLOOR IS ECONOMIC, NOT NUMERICAL. At 1.0 the addicted
                        ! find work as easily as anyone, so there is no penalty left
                        ! to remove and the remaining gap belongs to something else.
                        if (multiple_find_if_addicted<=multiple_find_lo) then
                            write(*,*) "multiple_find_if_addicted IS AT ITS FLOOR 1.0:",&
                                " the addicted already find work as easily as anyone",&
                                " and the SUD share of the homeless is still",&
                                model_fraction_homeless_and_addicted(1),&
                                " against", sud_share_of_homeless,&
                                ". The rest of the gap is not the finding margin's."
                        end if

                    else

                        distance_multiple_find=0

                    end if

                    ! MU_H, on the model's own increase in recovery from housing.
                    ! The ratio FALLS in mu_H, since mu_H is how good recovery on
                    ! the street is, so the step moves mu_H with the gap: a model
                    ! ratio above target means the street is too bad and mu_H rises.
                    if ((model_recovery_homeless(1)>0) .AND. (model_recovery_housed(1)>0)) then

                        write(*,*) "model recovery housed, homeless =",&
                            model_recovery_housed(1), model_recovery_homeless(1)
                        write(*,*) "model recovery ratio =",&
                            model_recovery_housed(1)/max(model_recovery_homeless(1),10.d0**(-14)),&
                            " target =", milby_recovery_ratio_data
                        write(*,*) "mu_homeless=", mu_homeless

                        cap_old_1=mu_homeless
                        mu_homeless=max(min(mu_homeless+mu_homeless_adjuster*&
                            (model_recovery_housed(1)/max(model_recovery_homeless(1),10.d0**(-14))-&
                            milby_recovery_ratio_data),1.d0),10.d0**(-3))
                        mu_homeless=cap_step_rel(mu_homeless,cap_old_1,mu_homeless_max_rel_step)

                        distance_mu_homeless=&
                            abs(model_recovery_housed(1)/max(model_recovery_homeless(1),10.d0**(-14))-&
                            milby_recovery_ratio_data)

                        write(*,*) "mu_homeless=", mu_homeless,&
                            " distance_mu_homeless=", distance_mu_homeless

                    else

                        ! No homeless household carries the disorder, so the
                        ! gradient has no denominator. Say so rather than dividing.
                        write(*,*) "mu_homeless HELD: no homeless household carries the disorder, so",&
                            " the recovery gradient cannot be measured this iteration"

                    end if

                    ! OMEGA, on how much drug use rises when the child term is off.
                    ! Use rises in the gap, and a LARGER omega means the parent
                    ! already internalises more, so switching the term off changes
                    ! more and the measured gap RISES in omega. A model gap above
                    ! target therefore calls for a smaller omega.
                    ! THE BASELINE HAS TO EXIST FOR THE GAP TO BE A GAP. With a
                    ! baseline using mass of 2.3e-4 the ratio came back as 325
                    ! against a target of 0.18 and omega went to zero in one step,
                    ! which is a statement about the denominator rather than about
                    ! how much a parent internalises. A tenth of the participation
                    ! rate the model is trying to reproduce is the floor.
                    ! AND THE COUNTERFACTUAL HAS TO HAVE SETTLED. A solve that
                    ! left on the sweep cap is a partial adjustment towards the
                    ! counterfactual, so the ratio it gives is somewhere between
                    ! the baseline's own count and the moment, with no way to
                    ! tell how far along. Stepping omega_c on it moves the
                    ! parameter by an amount that depends on the sweep cap.
                    if ((calibrate_weight_on_child==1) .AND. (drug_users_without_child>0)&
                        .AND. (model_total_drug_users(1)>&
                        10.d0**(-1)*participation_rate_data)&
                        .AND. (omega_counterfactual_capped==0)) then

                        ! THE RATIO IS PRINTED BECAUSE COMPARABILITY IS THE OTHER
                        ! HALF OF THIS QUESTION AND IT IS NOT YET GUARDED. In the
                        ! stylized model the baseline and the counterfactual
                        ! settled on different branches and the gap became a
                        ! statement about the branch: participation 0.0956 against
                        ! 0.2390, a factor of 2.5. A window would catch that -- but
                        ! this block has a RECORDED legitimate reading of +0.93,
                        ! which is a factor of 1.93, so any window tight enough to
                        ! be useful is close enough to a real measurement to risk
                        ! rejecting it. That is a threshold to MEASURE rather than
                        ! to pick, so for now the number is put where it can be
                        ! read and the bracket is left alone.
                        write(*,*) "drug users, baseline and child term off =",&
                            model_total_drug_users(1), drug_users_without_child,&
                            " ratio =", drug_users_without_child/&
                            max(model_total_drug_users(1),10.d0**(-14))

                        child_use_gap_1=drug_users_without_child/max(model_total_drug_users(1),10.d0**(-14))-1

                        write(*,*) "model child use gap =",&
                            child_use_gap_1, " target =", child_use_gap_data
                        write(*,*) "weight_on_child=", weight_on_child

                        ! The step is taken on a clamped gap for the same reason
                        ! theta's is: the sign is informative long before the
                        ! magnitude is.
                        cap_old_1=weight_on_child
                        weight_on_child=max(min(weight_on_child-weight_on_child_adjuster*&
                            max(min(child_use_gap_1-child_use_gap_data,1.d0),-1.d0),&
                            weight_on_child_cap),0.d0)
                        ! cap_step_rel, NOT cap_step: omega_c gets its own rate
                        ! rather than the global one, the same way theta does.
                        weight_on_child=cap_step_rel(weight_on_child,cap_old_1,&
                            omega_max_rel_step)

                        distance_weight_on_child=abs(child_use_gap_1-child_use_gap_data)

                        write(*,*) "weight_on_child=", weight_on_child,&
                            " distance_weight_on_child=", distance_weight_on_child

                        ! LANDED. Pin it, stop the counterfactual, and say so
                        ! loudly: a pinned parameter has to be distinguishable
                        ! from one that is still searching, and this one takes a
                        ! whole solve a loop with it when it goes.
                        if ((distance_weight_on_child<&
                            omega_c_pin_tol*abs(child_use_gap_data)) .AND.&
                            (abs(model_total_drug_users(1)/&
                            max(participation_rate_data,10.d0**(-12))-1.d0)<&
                            omega_c_pin_econ_tol) .AND.&
                            (abs(model_fraction_addicted(1)/&
                            max(sud_rate_data,10.d0**(-12))-1.d0)<&
                            omega_c_pin_econ_tol)) then

                            omega_c_is_pinned=1
                            distance_weight_on_child=0

                            write(*,*) "OMEGA_C PINNED: the child use gap is",&
                                child_use_gap_1, " against a target of",&
                                child_use_gap_data, ", inside the 3 per cent the",&
                                " author asked for. omega_c is held at",&
                                weight_on_child, " for the rest of the run and the",&
                                " counterfactual stops, which returns a full solve",&
                                " a loop to the other brackets. Drug use is",&
                                model_total_drug_users(1), " against",&
                                participation_rate_data, " and the disorder rate",&
                                model_fraction_addicted(1), " against",&
                                sud_rate_data, ", both inside ten per cent, so the",&
                                " ratio was measured in the right economy."

                        else if (distance_weight_on_child<&
                            omega_c_pin_tol*abs(child_use_gap_data)) then

                            ! THE RATIO IS RIGHT AND THE ECONOMY IS NOT. Say so
                            ! rather than pinning: omega_c's moment is a ratio of
                            ! two user counts and can sit on target while the
                            ! counts themselves are far wrong.
                            write(*,*) "OMEGA_C NOT PINNED: the child use gap is",&
                                child_use_gap_1, " and inside three per cent of",&
                                child_use_gap_data, ", BUT drug use is",&
                                model_total_drug_users(1), " against",&
                                participation_rate_data, " and the disorder rate",&
                                model_fraction_addicted(1), " against",&
                                sud_rate_data, ". The ratio is right in the wrong",&
                                " economy, so omega_c keeps searching."

                        end if

                    else if ((calibrate_weight_on_child==1) .AND. (omega_c_is_pinned==1)) then

                        write(*,*) "omega_c is PINNED at", weight_on_child,&
                            " and its counterfactual is off, so no gap is measured."
                        distance_weight_on_child=0

                    else if (calibrate_weight_on_child==1) then

                        ! WHICH GUARD HELD IT. One message for three causes made
                        ! a capped counterfactual indistinguishable from an empty
                        ! one in the log, and they call for opposite responses: an
                        ! empty baseline means the economy is wrong, a capped
                        ! counterfactual means the SOLVE is unfinished and the
                        ! economy may be fine.
                        if (omega_counterfactual_capped==1) then
                            write(*,*) "omega HELD: the counterfactual left on the",&
                                " distribution sweep cap of ", max_distribution_sweeps,&
                                ", so its user count ", drug_users_without_child,&
                                " is a partial adjustment rather than the moment.",&
                                " No step is taken and the bracket stays live."
                        else
                            write(*,*) "omega HELD: baseline users ", model_total_drug_users(1),&
                                " and users with the child term off ", drug_users_without_child,&
                                ": one of the two is too small for the gap to mean anything"
                        end if
                        ! THE DISTANCE STAYS AT ONE, which keeps the do-while term
                        ! live. Zeroing it here would retire the bracket on a loop
                        ! where the moment could not be measured, which reads as
                        ! convergence.
                        distance_weight_on_child=1

                    end if

                    ! DELTA_D, on the ratio of child disorder rates.
                    if (calibrate_penalty_child_addicted==1) then

                        child_sud_num_1=0
                        child_sud_den_1=0

                        do child_node_index_1=1,employment_grid_size

                            child_sud_num_1=child_sud_num_1+&
                                sum(newborn_parent_share(:,1,1)*newborn_employment_probability(child_node_index_1,:,1,1))/max(sum(newborn_parent_share(:,1,1)),10.d0**(-14))*&
                                percent_addicted_by_employment(1,child_node_index_1)

                            child_sud_den_1=child_sud_den_1+&
                                sum(newborn_parent_share(:,0,1)*newborn_employment_probability(child_node_index_1,:,0,1))/max(sum(newborn_parent_share(:,0,1)),10.d0**(-14))*&
                                percent_addicted_by_employment(1,child_node_index_1)

                        end do

                        if (child_sud_den_1>10.d0**(-10)) then

                            child_sud_ratio_model_1=child_sud_num_1/max(child_sud_den_1,10.d0**(-14))

                            ! SCAN THE PENALTY AND PRINT THE RATIO AT EACH VALUE.
                            !
                            ! THE ARRAY IS RESTORED BY REGENERATING IT AT THE
                            ! ORIGINAL PENALTY, not by copying it.  The
                            ! subroutine is deterministic in the penalty and the
                            ! grid, so the regenerated array is identical to the
                            ! one that was there, and no second copy of a large
                            ! array has to be carried.  Getting this wrong would
                            ! leave the solve running on a placement built at
                            ! whatever the last scan value happened to be, which
                            ! is exactly the class of silent corruption
                            ! TRANSITION_LESSONS section 7 is about.
                            if (scan_penalty_child==1) then

                                penalty_saved=penalty_child_addicted
                                scan_found=0
                                scan_prev=-1
                                scan_pen_prev=0
                                scan_solved=penalty_child_addicted
                                scan_best=-1
                                scan_best_pen=penalty_child_addicted

                                write(*,*) "PENALTY SCAN target ratio =",&
                                    child_sud_ratio_data, " current penalty =",&
                                    penalty_saved

                                do scan_index=0,scan_points

                                    penalty_child_addicted=scan_lo+&
                                        (scan_hi-scan_lo)*dble(scan_index)/dble(scan_points)

                                    call create_newborn_employment_probability()

                                    scan_num=0
                                    scan_den=0

                                    do child_node_index_1=1,employment_grid_size

                                        scan_num=scan_num+&
                                            sum(newborn_parent_share(:,1,1)*newborn_employment_probability(child_node_index_1,:,1,1))/max(sum(newborn_parent_share(:,1,1)),10.d0**(-14))*&
                                            percent_addicted_by_employment(1,child_node_index_1)

                                        scan_den=scan_den+&
                                            sum(newborn_parent_share(:,0,1)*newborn_employment_probability(child_node_index_1,:,0,1))/max(sum(newborn_parent_share(:,0,1)),10.d0**(-14))*&
                                            percent_addicted_by_employment(1,child_node_index_1)

                                    end do

                                    if (scan_den>10.d0**(-10)) then
                                        scan_ratio=scan_num/max(scan_den,10.d0**(-14))
                                    else
                                        scan_ratio=-1
                                    end if

                                    write(*,*) "PENALTY SCAN penalty=",&
                                        penalty_child_addicted, " ratio=", scan_ratio

                                    ! the crossing, by linear interpolation
                                    ! between this point and the last
                                    if ((scan_index>0) .AND. (scan_found==0) .AND.&
                                        (scan_ratio>0) .AND. (scan_prev>0)) then
                                        if (((scan_prev-child_sud_ratio_data)*&
                                             (scan_ratio-child_sud_ratio_data))<=0) then
                                            scan_solved=scan_pen_prev+&
                                                (penalty_child_addicted-scan_pen_prev)*&
                                                (child_sud_ratio_data-scan_prev)/&
                                                max(scan_ratio-scan_prev,10.d0**(-12))
                                            scan_found=1
                                        end if
                                    end if
                                    ! THE ARGMAX, TRACKED ON EVERY POINT.
                                    if (scan_ratio>scan_best) then
                                        scan_best=scan_ratio
                                        scan_best_pen=penalty_child_addicted
                                    end if

                                    scan_prev=scan_ratio
                                    scan_pen_prev=penalty_child_addicted

                                end do

                                ! SOLVE FOR THE CROSSING AND SET THE PENALTY.
                                !
                                ! The author, 13 September: *"you can also
                                ! calibrate delta_d exactly the same as we did in
                                ! the stylized model"*.  There the penalty was
                                ! not searched for at all -- the odds ratio is
                                ! smooth and monotone in it, so the curve was
                                ! scanned once and the crossing read off, and
                                ! 0.56972 returned 2.0000 to four decimals.
                                !
                                ! The same holds here: the eleven scan blocks of
                                ! the 13 September run are monotone throughout,
                                ! 1.05 at a penalty of zero rising to 1.85 at
                                ! 0.60.  So the crossing is interpolated between
                                ! the two adjacent scan points that bracket the
                                ! target and the penalty is SET to it, rather
                                ! than crawled toward at half a per cent a loop.
                                !
                                ! IF THE SCAN DOES NOT BRACKET THE TARGET the
                                ! penalty is left where it was and a line says
                                ! so.  Silently clamping to the end of the range
                                ! would report a solved penalty that is nothing
                                ! of the kind.
                                if (scan_found==1) then
                                    penalty_child_addicted=scan_solved
                                    write(*,*) "PENALTY SCAN SOLVED: penalty=",&
                                        scan_solved, " gives ratio=",&
                                        child_sud_ratio_data
                                else

                                    ! NO CROSSING: TAKE THE BEST POINT IN RANGE.
                                    !
                                    ! Leaving the penalty where it was is what
                                    ! stranded delta_d at 0.99 -- a value meaning
                                    ! the child of an addicted parent keeps one
                                    ! hundredth of their productivity draw, which
                                    ! is not a credible parameter and was never
                                    ! chosen: it was seeded there and the fallback
                                    ! declined to move it.  The author, 15
                                    ! September: *"it cannot be 0.99"*, and *"you
                                    ! also have scan the full delta_d to get the
                                    ! best odds ratio"*.
                                    !
                                    ! The scan still reports honestly that it did
                                    ! not reach the target.  What changes is that
                                    ! it now returns the best available point
                                    ! rather than an arbitrary one.
                                    penalty_child_addicted=scan_best_pen
                                    write(*,*) "PENALTY SCAN did NOT bracket",&
                                        child_sud_ratio_data, " over [",&
                                        scan_lo, ",", scan_hi,&
                                        "] -- BEST IN RANGE: penalty=",&
                                        scan_best_pen, " ratio=", scan_best,&
                                        " (was", penalty_saved, ")"
                                end if
                                call create_newborn_employment_probability()

                                write(*,*) "PENALTY SCAN penalty now =",&
                                    penalty_child_addicted

                            end if

                            gap_penalty_child_1=child_sud_ratio_model_1-child_sud_ratio_data

                            if (have_gap_penalty_child==1) then

                                ! AN ADJUSTER AT ZERO IS PINNED. Same rule as
                                ! damp_on_flip, written out inline, and the same
                                ! resurrection: max(0*damping, floor) is the
                                ! floor, so penalty_child_addicted -- declared
                                ! zero and commented "EXTERNALLY SET ... it
                                ! stopped being calibrated" -- would start
                                ! moving on the first sign flip.
                                if ((gap_penalty_child_1*previous_gap_penalty_child)<0 &
                                    .AND. (penalty_child_addicted_adjuster>0.d0)) then

                                    penalty_child_addicted_adjuster=&
                                        max(penalty_child_addicted_adjuster*penalty_child_adjuster_damping,&
                                        penalty_child_adjuster_floor)

                                else

                                    penalty_child_addicted_adjuster=&
                                        min(penalty_child_addicted_adjuster*penalty_child_adjuster_growth,&
                                        penalty_child_adjuster_start)

                                end if

                            end if

                            previous_gap_penalty_child=gap_penalty_child_1
                            have_gap_penalty_child=1

                            write(*,*) "child SUD ratio model =", child_sud_ratio_model_1,&
                                " target =", child_sud_ratio_data
                            write(*,*) "penalty_child_addicted=", penalty_child_addicted

                            ! A NINETY PER CENT CUT TO THE CHILD'S PRODUCTIVITY
                            ! IS NOT A PENALTY, IT IS A DIFFERENT MODEL. The cap
                            ! was 0.9 and the parameter sat on it, which
                            ! multiplies the child's productivity by a tenth and
                            ! lands every child of a parent with the disorder in
                            ! the bottom nodes of the grid. Two things follow and
                            ! both were visible in the output without the cause
                            ! being visible.
                            !
                            ! It manufactures a population of very low
                            ! productivity households who work and cannot afford
                            ! even the cheapest room, which is most of why the
                            ! employed share of the homeless would not come down
                            ! however far h_2 fell.
                            !
                            ! And it drives its OWN moment the wrong way. The
                            ! bottom of the grid has essentially no drug use, so
                            ! pushing the child further down lowers the child's
                            ! SUD rate; the ratio read 0.0027 against a target of
                            ! 3, the update read that as too low and raised the
                            ! penalty again, and it ran to the cap on the wrong
                            ! side of a relationship that is not monotone.
                            !
                            ! Forty per cent is the ceiling. penalty_child_homeless
                            ! is 0.31 and already inside it.
                            penalty_child_addicted=&
                                max(min(penalty_child_addicted-penalty_child_addicted_adjuster*&
                                gap_penalty_child_1,penalty_child_cap),0.d0)

                            distance_penalty_child_addicted=abs(gap_penalty_child_1)

                            write(*,*) "penalty_child_addicted=", penalty_child_addicted,&
                                " distance_penalty_child_addicted=", distance_penalty_child_addicted

                            ! The newborn draw is built from this penalty, so it
                            ! has to be rebuilt now rather than at the next setup,
                            ! which never runs again.
                            call create_newborn_employment_probability()

                            if ((penalty_child_addicted<=10.d0**(-8)) .OR. &
                                (penalty_child_addicted>=penalty_child_cap-10.d0**(-8))) then

                                write(*,*) "delta_d IS PINNED AT A BOUND", penalty_child_addicted,&
                                    " and the child SUD ratio is ", child_sud_ratio_model_1,&
                                    " against ", child_sud_ratio_data

                            end if

                        else

                            write(*,*) "child SUD ratio has an empty denominator: delta_d held at",&
                                penalty_child_addicted
                            distance_penalty_child_addicted=1

                        end if

                    else

                        distance_penalty_child_addicted=0

                    end if

                    ! DELTA_H, on the ratio of child homelessness rates. It
                    ! mirrors delta_d above: that one weights the newborn
                    ! productivity draw by the disorder rate at each node and
                    ! varies the parent's DISORDER at housed, this one weights by
                    ! the homelessness rate at each node and varies the parent's
                    ! HOMELESSNESS at clean. The third index is 1 for housed and
                    ! 2 for homeless, because the penalty's exponent is h_index-1.
                    if (calibrate_penalty_child_homeless==1) then

                        child_homeless_num_1=0
                        child_homeless_den_1=0

                        do child_node_index_1=1,employment_grid_size

                            child_homeless_num_1=child_homeless_num_1+&
                                sum(newborn_parent_share(:,0,2)*newborn_employment_probability(child_node_index_1,:,0,2))/max(sum(newborn_parent_share(:,0,2)),10.d0**(-14))*&
                                percent_homeless_by_employment(1,child_node_index_1)

                            child_homeless_den_1=child_homeless_den_1+&
                                sum(newborn_parent_share(:,0,1)*newborn_employment_probability(child_node_index_1,:,0,1))/max(sum(newborn_parent_share(:,0,1)),10.d0**(-14))*&
                                percent_homeless_by_employment(1,child_node_index_1)

                        end do

                        if (child_homeless_den_1>10.d0**(-10)) then

                            child_homeless_ratio_model_1=&
                                child_homeless_num_1/max(child_homeless_den_1,10.d0**(-14))

                            gap_penalty_child_homeless_1=&
                                child_homeless_ratio_model_1-child_homeless_ratio_data

                            ! ONE MOMENT, ONE INSTRUMENT, AND THE MODEL REFUSES
                            ! RATHER THAN AVERAGING. Two adjusters positive on
                            ! one target is one object with two names: the pair
                            ! is not identified, and the search would walk a
                            ! ridge while both distances fell. Stopping is the
                            ! honest failure; a warning that the run then ignores
                            ! is how a mis-specified calibration produces numbers.
                            if ((rho_intergenerational_adjuster>0.d0) .AND. &
                                (penalty_child_homeless_adjuster>0.d0)) then

                                write(*,*) "TWO INSTRUMENTS ON ONE MOMENT: both",&
                                    " rho_intergenerational_adjuster and",&
                                    " penalty_child_homeless_adjuster are positive",&
                                    " and both step the child homelessness odds",&
                                    " ratio. Set exactly one of them."
                                stop

                            end if

                            if (rho_intergenerational_adjuster>0.d0) then

                                ! RHO IS THE INSTRUMENT, on the author's
                                ! instruction of 10 September.
                                !
                                ! SIGN. A larger rho transmits MORE of the
                                ! homeless parent's low productivity to the
                                ! child, so the exposed child is poorer,
                                ! homelessness falls in productivity, and the
                                ! ratio RISES in rho. Same sign as the penalty
                                ! below it, so the update has the same form: a
                                ! model ratio ABOVE target calls for a SMALLER
                                ! rho, which is what subtracting the gap does.
                                call damp_on_flip(rho_intergenerational_adjuster,&
                                    gap_penalty_child_homeless_1,&
                                    previous_gap_penalty_child_homeless,&
                                    have_gap_penalty_child_homeless,&
                                    rho_intergenerational_adjuster_start,damp_adjuster_floor,&
                                        flips_rho_intergenerational)

                                rho_intergenerational_step_1=rho_intergenerational-&
                                    rho_intergenerational_adjuster*gap_penalty_child_homeless_1
                                ! LEFT AS THE ONLY trust_step CALLS, and only
                                ! because both parameters are HELD today. If either
                                ! is ever given an adjuster it must take the plain
                                ! gap step with a per-cent cap like everything else
                                ! -- see the note at value_of_life.
                                call trust_step(rho_intergenerational_step_1,&
                                    rho_intergenerational,&
                                    move_factor(child_homeless_ratio_model_1,&
                                    child_homeless_ratio_data,escape_factor),10.d0**(-3))
                                rho_intergenerational=&
                                    max(min(rho_intergenerational_step_1,&
                                    rho_intergenerational_cap),rho_intergenerational_floor)

                                write(*,*) "rho_intergenerational=", rho_intergenerational

                                if ((rho_intergenerational<=rho_intergenerational_floor+10.d0**(-8))&
                                    .OR. (rho_intergenerational>=rho_intergenerational_cap-10.d0**(-8))) then

                                    write(*,*) "rho_intergenerational IS PINNED AT A BOUND",&
                                        rho_intergenerational, " and the child homelessness odds",&
                                        " ratio is ", child_homeless_ratio_model_1,&
                                        " against ", child_homeless_ratio_data

                                end if

                            else

                                ! delta_h IS PINNED AT ZERO AND NOTHING MAY TOUCH IT.
                                ! The author, 14 September: *"delta_h should be 0 and
                                ! pinned at 0, not adjusted at all"*.
                                !
                                ! A DECLARED ZERO ADJUSTER IS NOT ENOUGH HERE, which
                                ! is why this guard wraps the whole update and not
                                ! just the step. damp_on_flip takes the adjuster by
                                ! reference and resets it toward
                                ! penalty_child_homeless_adjuster_start, which is
                                ! 5e-2 -- so a sign flip in the gap could revive a
                                ! parameter that is meant to be frozen, and nothing
                                ! would say so.
                                if (penalty_child_homeless_adjuster<=0.d0) then

                                    penalty_child_homeless_step_1=penalty_child_homeless

                                else

                                call damp_on_flip(penalty_child_homeless_adjuster,&
                                    gap_penalty_child_homeless_1,&
                                    previous_gap_penalty_child_homeless,&
                                    have_gap_penalty_child_homeless,&
                                    penalty_child_homeless_adjuster_start,damp_adjuster_floor,&
                                        flips_penalty_child_homeless)

                                ! SIGN, STATED RATHER THAN INFERRED. The penalty
                                ! shifts the child DOWN the productivity grid, since
                                ! shifted_log adds log(penalty) and the penalty is
                                ! below one, and homelessness FALLS in productivity.
                                ! So the child's homelessness rate, and the ratio with
                                ! it, RISES in the penalty: a model ratio below target
                                ! calls for a larger penalty, which is what
                                ! subtracting the gap does.
                                penalty_child_homeless_step_1=penalty_child_homeless-&
                                    penalty_child_homeless_adjuster*gap_penalty_child_homeless_1
                                call trust_step(penalty_child_homeless_step_1,&
                                    penalty_child_homeless,&
                                    move_factor(child_homeless_ratio_model_1,&
                                    child_homeless_ratio_data,escape_factor),10.d0**(-3))
                                penalty_child_homeless=&
                                    max(min(penalty_child_homeless_step_1,0.4d0),0.d0)

                                end if

                            end if

                            ! GUARDED ON THE ADJUSTER, which is the standing rule
                            ! in this file and which this block was breaking.
                            ! penalty_child_homeless_adjuster is zero, so nothing
                            ! moves delta_h, yet the distance was written anyway and
                            ! it sits in the do-while at the convergence test. It
                            ! read 4.4995 against its stopping rule for the whole of
                            ! stage 1, so THAT RUN COULD NEVER HAVE CONVERGED however
                            ! well every other moment did. A frozen parameter holding
                            ! the loop open for ever is the exact failure the rule
                            ! exists to prevent.
                            if (penalty_child_homeless_adjuster>0.d0) then
                                distance_penalty_child_homeless=&
                                    abs(gap_penalty_child_homeless_1)
                            else
                                distance_penalty_child_homeless=0
                            end if

                            write(*,*) "child homelessness ratio model =",&
                                child_homeless_ratio_model_1,&
                                " target =", child_homeless_ratio_data
                            write(*,*) "penalty_child_homeless=", penalty_child_homeless,&
                                " distance_penalty_child_homeless=",&
                                distance_penalty_child_homeless

                            ! The newborn draw is built from this penalty too, so
                            ! it is rebuilt here for the same reason delta_d's is.
                            call create_newborn_employment_probability()

                        else

                            write(*,*) "child homelessness ratio has an empty denominator:",&
                                " delta_h held at", penalty_child_homeless
                            distance_penalty_child_homeless=1

                        end if

                    else

                        distance_penalty_child_homeless=0

                    end if


                    else

                        distance_utility_cost_of_treatment=0

                    end if

                    ! THE ELEVEN, FREED AND BRACKETED.
                    !
                    ! Each on the moment its row in the note's internal table
                    ! names. Signs are stated rather than left to be inferred,
                    ! because a wrong sign here shows up as a moment walking
                    ! away rather than as an error.
                    !
                    ! theta, the weight on drugs, on drug spending over income
                    ! averaged across users, light and heavy together, which is
                    ! the population the moment below is taken over. More weight,
                    ! more spending, so the update
                    ! adds the gap the other way round: subtract model minus
                    ! data.
                    ! THE MOMENT IS A WEIGHTED AVERAGE OVER BOTH KINDS OF USER.
                    !
                    ! It used to be the ratio for the experimenters alone, who are
                    ! the users WITHOUT a disorder, since the code keeps the two
                    ! groups disjoint. So a target meant for users as a whole was
                    ! being asked of the lighter half of them.
                    !
                    ! Now each group's own drug to income ratio is formed first and
                    ! the two are averaged with their shares of the using
                    ! population as weights, which is the object the data number is.
                    ! A GROUP WITH NO INCOME HAS NO RATIO.
                    !
                    ! Households carrying the disorder are largely out of work with
                    ! no assets, so their measured income can be numerically zero
                    ! while they still spend on the drug out of the consumption
                    ! floor. Dividing one by the other gave a group ratio of
                    ! 1,815,832 on the first iteration, which then swamped the
                    ! weighted average. The 1e-12 guard stopped a crash and
                    ! produced a meaningless number instead, which is worse.
                    !
                    ! So a group ratio is only formed when that group's income is a
                    ! real quantity, taken as a thousandth of average labour income
                    ! times its mass. When it is not, the pooled ratio over both
                    ! groups is used for that iteration, which is well behaved
                    ! because the denominator is dominated by the group that does
                    ! earn, and the log says so rather than passing it off as the
                    ! weighted average.
                    ! A TENTH OF AVERAGE INCOME PER HOUSEHOLD, not a thousandth.
                    ! At a thousandth the guard passed on a group whose income per
                    ! head was still near zero, and the ratio it then formed was
                    ! 1,815,823. A group whose average income is below a tenth of
                    ! the mean has no meaningful drug to income ratio, whatever the
                    ! numerator is.
                    income_floor_1=10.d0**(-1)*model_average_labour_income(1)

                    ! EACH ACCUMULATOR IS ALREADY A RATIO. It is divided by its
                    ! group's total income where the distribution is summed, and
                    ! dividing it again here is what produced 62 and 1,204,097 for
                    ! a share the budget constraint caps at one. A negative value
                    ! is the sentinel for a group with no income at all.
                    drug_share_experimenters_1=&
                        model_experimenters_total_drug_spending_to_total_income(1)
                    drug_share_addicted_1=&
                        model_addicted_total_addiction_spending_to_total_income(1)

                    ! A GROUP COUNTS ONLY IF ITS RATIO MEANS SOMETHING, and a group
                    ! that fails is dropped from the average rather than replaced
                    ! by a pooled ratio. Pooling put the failing group back in
                    ! through the numerator.
                    use_experimenters_1=(model_mass_experimenters(1)>0) .AND. &
                        (drug_share_experimenters_1>=0) .AND. &
                        (model_experimenters_total_income(1)>&
                        income_floor_1*model_mass_experimenters(1))
                    use_addicts_1=(model_mass_addicts(1)>0) .AND. &
                        (drug_share_addicted_1>=0) .AND. &
                        (model_addicted_total_income(1)>&
                        income_floor_1*model_mass_addicts(1))

                    ! ONE DEFINITION, in weighted_drug_share_now, so the value
                    ! the sweep records and the value the bracket moves on cannot
                    ! drift apart. The tests below survive only to say WHICH group
                    ! was dropped, which the function has no business printing.
                    drug_share_weighted_1=weighted_drug_share_now()

                    if (use_experimenters_1 .AND. (.NOT. use_addicts_1)) then

                        write(*,*) "drug share: the group with a disorder has no income to speak of,",&
                            " so the moment is the experimenters alone this iteration"

                    else if (use_addicts_1 .AND. (.NOT. use_experimenters_1)) then

                        write(*,*) "drug share: the experimenters have no income to speak of,",&
                            " so the moment is the group with a disorder alone this iteration"

                    end if

                    write(*,*) "drug share, experimenters and with a SUD =",&
                        drug_share_experimenters_1, drug_share_addicted_1
                    write(*,*) "drug share, weighted by their population shares =",&
                        drug_share_weighted_1, " target =", drug_spending_share_data

                    if (drug_share_weighted_1>=0) then

                        write(*,*) "relative_share_of_addiction_1=", relative_share_of_addiction_1

                        ! A TRUST REGION ON THE GAP AND ON THE STEP. The share
                        ! cannot exceed one, so a gap above one is a measurement
                        ! failure rather than a signal about theta, and the raw gap
                        ! of 109 moved theta from 0.44 to its floor in one step
                        ! while the next iteration undid it. Clamping the gap keeps
                        ! the sign and drops the magnitude; halving or doubling per
                        ! iteration is still fast and cannot land on a bound.
                        drug_share_gap_1=max(min(drug_share_weighted_1-&
                            drug_spending_share_data,1.d0),-1.d0)

                        ! ABSOLUTE BOUNDS, not only a trust region. The trust
                        ! region bounds each STEP and lets the level walk
                        ! anywhere, which is how theta reached 0.667: two thirds
                        ! of the utility bundle on the drug, against a quarter on
                        ! consumption and six per cent on housing. That is not a
                        ! preference anyone would defend, and it was reached while
                        ! the drug first order condition still had its sign
                        ! inverted. The stylized model uses 0.20 and the note says
                        ! the two share this parameter, so the band is set around
                        ! that.
                        ! THETA MAY NOT RISE WHILE THE GRADIENT IS INVERTED.
                        !
                        ! The drug spending share and the income gradient pull
                        ! theta opposite ways, and only one of them is the fact
                        ! the model exists to produce. Measured: as b rose and
                        ! participation fell from 76.6 per cent to 14.6, the
                        ! average user went from 0.85 of mean income to 1.54 and
                        ! the average household with the disorder to 1.87, while
                        ! the spending share FELL from 9.6 per cent to 5.9
                        ! against a target of 16.2. Those are the same fact:
                        ! the share is spending over INCOME, so users who are
                        ! rich carry a small share however much they buy, and
                        ! the update reads that as a reason to raise theta.
                        !
                        ! Raising it is the wrong direction. theta_hi is the
                        ! break point above which mortality stops reversing the
                        ! gradient, so a bracket pressing upward through it is
                        ! walking further into the region where the mechanism
                        ! does not work, chasing a share it cannot reach from
                        ! there. The guard lets theta FALL on the share as
                        ! before and refuses to let it RISE while the average
                        ! household with the disorder is richer than the mean.
                        if ((model_average_income_addicted(1)>&
                            model_average_labour_income(1)) .AND.&
                            (drug_share_gap_1<0)) then

                            write(*,*) "THETA HELD: the gradient is inverted, income of the",&
                                " disordered over the mean is",&
                                model_average_income_addicted(1)/&
                                max(model_average_labour_income(1),10.d0**(-12)),&
                                " and the share asks theta HIGHER. Refusing: the ceiling is",&
                                " the break point where mortality stops reversing the",&
                                " gradient, so raising theta chases a share that cannot be",&
                                " reached from above it."

                        elseif (abs(model_total_drug_users(1)-participation_rate_data)>&
                                kappa_gate_b_tolerance*participation_rate_data) then

                            ! THE SAME GATE kappa_phi_d HAS, AND FOR THE SAME
                            ! REASON.  The author, 15 September: *"when b is close
                            ! to 0.089, then you can adjust theta to match 0.16"*.
                            !
                            ! The drug spending moment is a MASS-WEIGHTED MEAN OF
                            ! HOUSEHOLD RATIOS over the addicted and the
                            ! experimenters, so it moves with the MIX of those two
                            ! groups as well as with theta.  While b refills the mix
                            ! swings hard: measured on 15 September, at b = 0.0147
                            ! the addicts were 16 per cent of users against about 40
                            ! per cent at b on target, and since addicts carry a mean
                            ! ratio near 0.47 against the experimenters' 0.10, the
                            ! mix alone moved the moment further than theta does.  A
                            ! theta step taken there is reading the refill.
                            write(*,*) "THETA GATE SHUT: b=", model_total_drug_users(1),&
                                " is outside", kappa_gate_b_tolerance, " of",&
                                participation_rate_data, "-- theta HELD at",&
                                relative_share_of_addiction_1

                        else

                            ! The proposed step, then the relative cap, then the
                            ! absolute band. In that order: capping first and
                            ! clamping second means a theta pressed against
                            ! theta_hi still reports pinned rather than capped.
                            theta_proposed_1=relative_share_of_addiction_1-&
                                relative_share_of_addiction_adj*drug_share_gap_1
                            theta_capped_1=max(min(theta_proposed_1,&
                                relative_share_of_addiction_1*(1+theta_max_rel_step)),&
                                relative_share_of_addiction_1*(1-theta_max_rel_step))
                            if (abs(theta_capped_1-theta_proposed_1)>&
                                10.d0**(-12)*max(abs(theta_proposed_1),1.d0)) then
                                write(*,*) "THETA CAPPED: the share asked for",&
                                    theta_proposed_1, " and the per loop cap of",&
                                    theta_max_rel_step, " allows", theta_capped_1
                            end if
                            cap_old_1=relative_share_of_addiction_1
                            relative_share_of_addiction_1=&
                                max(min(theta_capped_1,theta_hi),theta_lo)
                            ! theta_max_rel_step is 0.001 and max_rel_step_all is
                            ! 0.005, so this never binds while theta's own cap is
                            ! the tighter of the two. It is here so that raising
                            ! theta_max_rel_step by handover cannot silently put
                            ! theta outside the global rule.
                            relative_share_of_addiction_1=&
                                cap_step(relative_share_of_addiction_1,cap_old_1)

                        end if

                        call apply_gamma_tie()

                        distance_relative_share_of_addiction_1=&
                            abs(drug_share_weighted_1-drug_spending_share_data)

                        write(*,*) "relative_share_of_addiction_1=", relative_share_of_addiction_1
                        write(*,*) "distance_relative_share_of_addiction_1=",&
                            distance_relative_share_of_addiction_1

                        ! THETA ON ITS CEILING IS A RESULT, NOT A STUCK SEARCH,
                        ! and it has to be said out loud or it reads as neither.
                        ! The ceiling is the break point above which mortality
                        ! stops reversing the income gradient, so a calibration
                        ! pressed against it is reporting that it cannot reach
                        ! the drug spending share while keeping the poor as the
                        ! users. That is the fact the paper exists to explain, so
                        ! losing it silently is the worst outcome available.
                        if ((relative_share_of_addiction_1>=theta_hi*(1-10.d0**(-9)))&
                            .AND. (drug_share_weighted_1<drug_spending_share_data)) then

                            write(*,*) "THETA PINNED AT ITS CEILING: theta=",&
                                relative_share_of_addiction_1, " and the drug share is",&
                                drug_share_weighted_1, " against a target of",&
                                drug_spending_share_data, &
                                ". The update wants theta HIGHER and the ceiling is the",&
                                " break point above which mortality stops reversing the",&
                                " income gradient. Check the gradient before trusting",&
                                " any other moment: income of users over average is",&
                                model_avg_income_drug_users(1)/&
                                max(model_average_labour_income(1),10.d0**(-12)),&
                                " and of the disordered",&
                                model_average_income_addicted(1)/&
                                max(model_average_labour_income(1),10.d0**(-12))

                        end if

                    else

                        write(*,*) "drug share HELD: neither using group has income worth dividing by,",&
                            " so theta is not moved on a moment that does not exist"
                        distance_relative_share_of_addiction_1=1

                    end if

                    ! b, the Stone-Geary endowment, on participation. A LARGER b
                    ! deters use, since the marginal value of the first unit is
                    ! theta/b, so participation FALLS in b and the update adds
                    ! the gap. Multiplicative, because b is of order 1e-8 and an
                    ! additive step in it is meaningless.
                    write(*,*) "addiction_scalar_1=", addiction_scalar_1
                    ! NO GUARD ON PARTICIPATION BEING POSITIVE. Zero participation
                    ! is exactly the state b has to move out of, and the gap is
                    ! normalised by the target so it cannot be worse than minus
                    ! one however empty the model is. Skipping the update there
                    ! left the model parked at the corner it needed to leave.
                    ! ALL USERS, NOT THE EXPERIMENTERS ALONE.
                    !
                    ! participation_rate_data is NSDUH's svyrdudany in (1,2,3),
                    ! which is ANY drug use disorder INCLUDING MILD: the data
                    ! appendix calls it "whether a household uses" and quotes
                    ! the conversion the model implies as 3.68/8.90 = 41.3 per
                    ! cent, which only reads that way if 8.90 is the whole user
                    ! population. model_exprimenters is the users WITHOUT the
                    ! disorder, so bracketing b on it asked the model for 8.90
                    ! per cent mild users PLUS 3.68 per cent disordered ones,
                    ! 12.58 per cent in total against a survey figure of 8.90,
                    ! and it put the disordered share of users at 29.3 per cent
                    ! where the survey says 41.3.
                    !
                    ! model_total_drug_users is exactly the sum: the log prints
                    ! model_fraction_addicted+model_exprimenters beside it and
                    ! the two agree to the last digit.
                    gap_addiction_scalar_1=model_total_drug_users(1)-participation_rate_data

                    ! COOLDOWN. b steps at most once every b_step_cooldown
                    ! blocks, because the model needs about four to settle after
                    ! a step. See the note beside the declaration.
                    blocks_since_drug_step=blocks_since_drug_step+1

                    if (blocks_since_drug_step<b_step_cooldown) then

                        write(*,*) "b HELD: ", blocks_since_drug_step, " of",&
                            b_step_cooldown, " cooldown blocks since the last drug-block",&
                            " step -- letting the extensive margin settle.",&
                            " Participation reads", model_total_drug_users(1)
                        distance_addiction_scalar=abs(gap_addiction_scalar_1)

                    else

                    blocks_since_drug_step=0

                    if (have_gap_addiction_scalar==1) then

                        if ((gap_addiction_scalar_1*previous_gap_addiction_scalar)<0) then

                            addiction_scalar_adjuster=max(addiction_scalar_adjuster*&
                                addiction_scalar_damping,addiction_scalar_floor)

                        else

                            addiction_scalar_adjuster=min(addiction_scalar_adjuster*&
                                addiction_scalar_growth,addiction_scalar_adjuster_start)

                        end if

                    end if

                    previous_gap_addiction_scalar=gap_addiction_scalar_1
                    have_gap_addiction_scalar=1

                    ! ABSOLUTE BOUNDS ON b TOO, and they matter more than
                    ! theta's because b sets the ABSTENTION CORNER. The static
                    ! split buys nothing when x <= b*(w_c/w_v), so with b at 0.99
                    ! and theta at 0.667 the corner sat at 0.40 against a poorest
                    ! household's total consumption of 0.45: the bottom of the
                    ! distribution was one per cent of its consumption away from
                    ! being priced out of the drug entirely. At theta of 0.2 the
                    ! same b would put the corner at about 4b, which is above
                    ! every household in the model. The stylized model uses 0.009.
                    ! THE AUTHOR'S RULE, ADDITIVE, AND NO MOVE FACTOR. Their
                    ! instruction of 13 September: parameter + adjuster times
                    ! (model moment - data moment), capped per loop.
                    !
                    ! WHAT THIS REPLACES. b used to move MULTIPLICATIVELY, by
                    ! b*(1 + a*gap/target), and was bounded by move_factor rather
                    ! than by a flat per cent. Both are gone: the step is now
                    ! additive in the gap and the only ceiling is cap_step_rel's
                    ! half a per cent below.
                    !
                    ! DIRECTION. b is the curvature of the drug bundle and sets
                    ! the abstention corner, so a larger b prices more households
                    ! out and PARTICIPATION FALLS IN b. Too many users therefore
                    ! wants b UP, which is the plus here -- a positive adjuster in
                    ! the author's form. The old multiplicative rule had the same
                    ! sign, so this changes the size of the step and not its
                    ! direction.
                    !
                    ! MAGNITUDE. b sits near 0.02 and a typical participation gap
                    ! is of order 0.01, so an adjuster of 0.2 asks for 0.002 --
                    ! about a tenth of b, which the half a per cent cap then
                    ! trims. The cap is expected to bind while the gap is wide and
                    ! to stop binding as it closes, which is the behaviour wanted.
                    cap_old_1=addiction_scalar_1
                    addiction_scalar_1=max(min(addiction_scalar_1+&
                        addiction_scalar_adjuster*gap_addiction_scalar_1,&
                        b_hi),b_lo)
                    ! cap_step_rel, NOT cap_step: b gets its own half a per
                    ! cent rather than the global one per cent, the same way
                    ! theta, omega_c and kappa_phi_d get theirs.
                    addiction_scalar_1=cap_step_rel(addiction_scalar_1,cap_old_1,&
                        addiction_scalar_max_rel_step)
                    distance_addiction_scalar=abs(gap_addiction_scalar_1)
                    write(*,*) "addiction_scalar_adjuster=", addiction_scalar_adjuster
                    write(*,*) "addiction_scalar_1=", addiction_scalar_1
                    write(*,*) "distance_addiction_scalar=", distance_addiction_scalar

                    ! closes the settle gate opened above
                    end if

                    ! aleph, on the model implied value of a statistical life.
                    ! A larger aleph makes life worth more, so the VSL rises in
                    ! it and the update subtracts the gap.
                    ! THE MOMENT IS SCALE FREE, so the comparison is too. The
                    ! model's value of life is a sum of V/MU_c and carries the
                    ! numeraire with it; dividing by average labour income turns
                    ! it into the multiple the data number is quoted as, and
                    ! nothing in the block then depends on what a unit of the
                    ! model is worth.
                    if (model_average_labour_income(1)>0) then

                        model_vsl_ratio_1=model_value_of_life(1)/&
                            model_average_labour_income(1)

                        write(*,*) "model_value_of_life(1)=", model_value_of_life(1),&
                            " over average labour income =", model_vsl_ratio_1,&
                            " target =", vsl_data

                        ! NO TRUST REGION. The author, 14 September: *"Make all the
                        ! updates of internally calibrated parameters follow my
                        ! method of updating it up or down by some %."*  A trust
                        ! region is a SECOND ceiling, multiplicative and moving, on
                        ! top of cap_step's flat one, and two ceilings mean the log
                        ! cannot say which bound a step.
                        !
                        ! WHAT IT WAS FOR, AND WHY cap_step COVERS IT. The worry was
                        ! scale: the adjuster is ten and the gap is in the same
                        ! units as the parameter, so an early gap of 88 asks for a
                        ! move of 885 and any starting value below that lands on a
                        ! clamp. cap_step already refuses that -- it allows one per
                        ! cent of the current value and nothing more -- so the
                        ! overshoot the trust region existed to prevent cannot
                        ! happen either way. The trust machinery is left declared
                        ! and still read from and written to the state file, so no
                        ! checkpoint format changes; nothing reads it now.
                        !
                        ! DIRECTION. The value of life RISES in aleph, so a ratio
                        ! above target wants aleph DOWN, which is the minus here.
                        gap_value_of_life_1=model_vsl_ratio_1-vsl_data

                        previous_gap_value_of_life=gap_value_of_life_1
                        have_gap_value_of_life=1

                        value_of_life_step_1=value_of_life-value_of_life_adjuster*&
                            gap_value_of_life_1
                        cap_old_1=value_of_life
                        value_of_life=max(min(value_of_life_step_1,10.d0**(4)),10.d0**(-2))
                        value_of_life=cap_step_rel(value_of_life,cap_old_1,&
                            value_of_life_max_rel_step)
                        distance_value_of_life=abs(model_vsl_ratio_1-vsl_data)

                    else

                        write(*,*) "aleph HELD: average labour income is zero, so the",&
                            " value of life has no multiple to be quoted as"
                        distance_value_of_life=1

                    end if
                    write(*,*) "value_of_life=", value_of_life
                    write(*,*) "distance_value_of_life=", distance_value_of_life

                    ! NOBODY MAY PREFER TO BE DEAD, and this is a CONSTRAINT, not
                    ! a moment. The author, 13 September: *"you also need to make
                    ! sure that no one has a negative value of life"*.
                    !
                    ! WHY IT MATTERS FOR THIS PAPER IN PARTICULAR, and it is not
                    ! a tidiness point. aleph is added to a CRRA goods term that
                    ! is negative and unbounded below, so the value of a period
                    ! of life FALLS with consumption. If any mass sits below
                    ! zero, those households prefer not to be alive -- and then
                    ! an eightfold mortality multiplier on drug use is a BENEFIT
                    ! to exactly the poorest households, which are the ones the
                    ! model selects into use. The selection into drug use would
                    ! be a defect of the utility function rather than the
                    ! mechanism the paper is about.
                    !
                    ! THE CORRECTION IS EXACT AND THAT IS WHY IT IS DONE THIS WAY.
                    ! val_life_1 = val_ugoods_1 + value_of_life, one for one, so
                    ! raising aleph by (margin - the minimum) puts the worst-off
                    ! household exactly at the margin, holding behaviour fixed.
                    ! Behaviour does move, so it is re-checked every loop and
                    ! converges from above in a pass or two.
                    !
                    ! IT IS NOT PUT THROUGH cap_step. A step cap is for a SEARCH,
                    ! and this is a constraint the model has to satisfy at every
                    ! iterate rather than approach at half a per cent a loop. A
                    ! capped floor would leave households preferring death for as
                    ! many loops as it took to walk there.
                    !
                    ! AND WHEN IT BINDS, aleph IS NOT FREE, so its moment must
                    ! not be scored. This is the rule kappa_phi_d's history
                    ! records -- a moment cannot be chased while its driver is
                    ! being moved by something else -- and leaving
                    ! distance_value_of_life live under a binding floor is the
                    ! documented way for the outer do while never to terminate.
                    ! AND THE MASS THERE HAS TO BE REAL, WHICH THIS TEST USED
                    ! TO IGNORE. The condition was on val_life_min_any alone --
                    ! the WORST value anywhere in the state space, however little
                    ! mass sits on it -- and val_neg_life_mass was computed,
                    ! printed, and never tested.
                    !
                    ! MEASURED 14 September: at aleph 100, 110 and 120 the mass
                    ! below zero is 2e-9, 1.9e-9 and 3.9e-9 out of a population
                    ! of 51.4 -- about four parts in a hundred billion, the same
                    ! unreachable grid corner each time, with only the DEPTH of
                    ! the deficit shrinking as aleph rises. The floor chased it
                    ! all the way to aleph 123 and lifted aleph by 23 per cent in
                    ! one step, which pinned the VSL moment near 192 against a
                    ! target of 80 and, through participation, put y_u out of
                    ! reach as well.
                    !
                    ! The author's requirement is *"you also need to make sure
                    ! that no one has a negative value of life"*. That is about
                    ! households, not numerical dust at a grid corner the
                    ! distribution never visits. One in a million is still a
                    ! strict reading and is three thousand times smaller than the
                    ! genuinely negative mass at aleph 95, 0.108 per cent, which
                    ! this still catches.
                    if ((val_life_min_any(1)<value_of_life_floor_margin) .AND. &
                        (val_neg_life_mass(1)>val_neg_life_mass_tol*sum_of_distribution)) then

                        write(*,*) "VALUE OF LIFE FLOOR BINDS: the worst-off household",&
                            " values a period of life at", val_life_min_any(1),&
                            " and", val_neg_life_mass(1), " of mass is below zero"
                        ! THE PRINT THAT SAID "aleph X -> Y" IS GONE.  It
                        ! described the rule this block replaced and assigned
                        ! nothing, but it reported an aleph of 83 beside an aleph
                        ! that was actually 60, and it was read as evidence that
                        ! the author's instruction had not taken.  The line below,
                        ! VALUE OF LIFE CONSTRAINT, is the one that acts.

                        ! THE FLOOR STEPS NOW; IT USED TO ASSIGN, and that is what
                        ! collapsed every run seeded at aleph 60 today.  Measured in
                        ! run60b: the floor took aleph 60.060 -> 122.515 in ONE
                        ! assignment, +104 per cent, while every ordinary instrument
                        ! in the same loop obeyed its cap -- b +0.50, theta -0.10,
                        ! kappa_phi_d +0.10, gamma +0.22.  Aleph at 122 doubles the
                        ! price of death, drug use fell 98 per cent by loop 4 and the
                        ! VSL moment overshot to 225, which its own bracket can then
                        ! only claw back at 0.1 per cent a loop.
                        !
                        ! The constraint is unchanged -- a household that prefers
                        ! death still raises aleph, and it still pins the VSL moment
                        ! for the loop.  What changes is that it APPROACHES the
                        ! constraint at the same rate as everything else instead of
                        ! being thrown across it in one step.  The author, 14
                        ! September: *"No parameter should move fast. Especially big
                        ! ones like aleph"*.
                        ! THE CONSTRAINT IS ENFORCED THROUGH THE PRODUCTIVITY FLOOR,
                        ! NOT THROUGH ALEPH.  The author, 14 September: *"to get a
                        ! positive value of life for every household you need to
                        ! adjust the smallest productivity i think"*, and *"aleph
                        ! should [not] be chosen for anything else other than
                        ! VSL=80"*.
                        !
                        ! WHY THIS IS THE RIGHT LEVER.  A household prefers death
                        ! when its consumption is low enough that the flow value of
                        ! living is negative.  Raising aleph fixes that by making
                        ! life worth more -- but aleph is the price of death for
                        ! EVERYONE, so it also destroys the drug block: the floor's
                        ! own demand at this seed is 122.5 against a VSL target that
                        ! wants 60, and every collapsed run today came from that.
                        ! bottom_productivity_level instead raises what the poorest
                        ! households actually HAVE, and the block that applies it
                        ! rescales the upper nodes so the mean is preserved. It is a
                        ! redistribution toward the bottom, not a repricing of life.
                        !
                        ! IT IS FREE TO TAKE THIS JOB: bottom_productivity_level has
                        ! no adjuster and no bracket anywhere in the file, only a
                        ! declaration and a handover case.
                        !
                        ! THE RATE IS 1 PER CENT, NOT 0.1.  It has to travel: 0.11075
                        ! at the seed against a floor that looks like it needs 0.2 to
                        ! 0.35, so 0.1 per cent a loop would be six hundred loops.
                        ! Flagged rather than buried -- it is the one parameter above
                        ! the author's 0.1 per cent rule, and it is a constraint
                        ! rather than a moment.
                        bpl_old_1=bottom_productivity_level
                        bottom_productivity_level=min(bottom_productivity_level*&
                            (1.d0+bottom_productivity_floor_rate),1.d0)
                        write(*,*) "VALUE OF LIFE CONSTRAINT: raising the smallest",&
                            " productivity", bpl_old_1, "->", bottom_productivity_level,&
                            " because", val_neg_life_mass(1), " of mass values life",&
                            " below zero and the worst is at", val_life_min_any(1)
                        write(*,*) "VALUE OF LIFE CONSTRAINT: aleph is NOT touched and",&
                            " the VSL moment IS scored -- aleph answers only to VSL=80"

                    end if

                    ! cbar, the food stamp floor, on food stamps over OUTPUT.
                    ! A higher floor pays more out, so the share rises in it and
                    ! the update subtracts the gap.
                    !
                    ! THE DENOMINATOR IS OUTPUT, AND IT MUST BE THE SAME ONE THE
                    ! MOMENT IS PRINTED WITH. food_stamps_share_data is 0.42 per
                    ! cent of GDP, so the moment above divides by model_output,
                    ! and this update divided by model_average_labour_income --
                    ! two different equations on one target. Whichever loop ran
                    ! last would move max_food_cost to satisfy the one the report
                    ! does not score. The denominator is named once here and once
                    ! at the moment; if one changes the other has to.
                    ! GUARDED ON THE ADJUSTER NOW.  Unguarded, a retired
                    ! max_food_cost still had its distance computed from a live
                    ! moment while the parameter could not move, which is the
                    ! failure mode ENGINE.md records as having cost a whole
                    ! calibration.  Note also the inner floor of 1e-4 below: the
                    ! update could never have reached zero on its own.
                    if ((max_food_cost_adjuster<=0.d0) .OR. (model_output(1)<=0)) then

                        distance_max_food_cost=0

                    else
                        write(*,*) "max_food_cost=", max_food_cost
                        cap_old_1=max_food_cost
                        max_food_cost=max(min(max_food_cost-max_food_cost_adjuster*&
                            (govt_spending_on_food_stamps(1)/model_output(1)-&
                            food_stamps_share_data),1.d0),10.d0**(-4))
                        max_food_cost=cap_step_rel(max_food_cost,cap_old_1,max_food_cost_max_rel_step)
                        ! PRINT THE RATIO THIS UPDATE COMPARES, which is now the
                        ! same ratio the moments block prints.
                        write(*,*) "govt_spending_on_food_stamps/model_output=", &
                            govt_spending_on_food_stamps(1)/model_output(1)

                        distance_max_food_cost=&
                            abs(govt_spending_on_food_stamps(1)/model_output(1)-food_stamps_share_data)
                        write(*,*) "max_food_cost=", max_food_cost
                        write(*,*) "distance_max_food_cost=", distance_max_food_cost
                    end if

                    ! pi_V, the voucher lottery, on recipients over the income
                    ! eligible. Coverage rises in it, so subtract the gap.
                    !
                    ! GUARDED ON THE ADJUSTER, like max_food_cost's.  This block
                    ! was unguarded: it wrote a LIVE distance every loop while a
                    ! zero adjuster meant the parameter could not move, and the
                    ! only thing standing between that and a calibration that
                    ! never terminates was the freeze guard on its do while term.
                    ! Now that the term is scored unconditionally, the guard has
                    ! to be here instead, and it is the better place for it: the
                    ! rule is that a distance is written exactly when its
                    ! parameter can move.
                    if (voucher_probability_adjuster<=0.d0) then

                        distance_voucher_probability=0

                    else

                    write(*,*) "probability_of_voucher_benchmark_used=", probability_of_voucher_benchmark_used
                    call damp_on_flip(voucher_probability_adjuster,&
                        model_eligibles_getting_voucher(1)-voucher_coverage_data,&
                        previous_gap_voucher_probability,have_gap_voucher_probability,&
                        voucher_probability_adjuster_start,damp_adjuster_floor,&
                            flips_voucher_probability)
                    write(*,*) "voucher_probability_adjuster=", voucher_probability_adjuster
                    cap_old_1=probability_of_voucher_benchmark_used
                    probability_of_voucher_benchmark_used=&
                        max(min(probability_of_voucher_benchmark_used-voucher_probability_adjuster*&
                        (model_eligibles_getting_voucher(1)-voucher_coverage_data),1.d0),10.d0**(-5))
                    probability_of_voucher_benchmark_used=cap_step_rel(probability_of_voucher_benchmark_used,cap_old_1,pi_V_max_rel_step)
                    distance_voucher_probability=&
                        abs(model_eligibles_getting_voucher(1)-voucher_coverage_data)
                    write(*,*) "probability_of_voucher_benchmark_used=", probability_of_voucher_benchmark_used
                    write(*,*) "distance_voucher_probability=", distance_voucher_probability

                    end if

                    ! bar pi^eu, the separation rate, on the unemployment rate.
                    ! Unemployment rises in it, so subtract the gap.
                    write(*,*) "probability_becoming_unemployed=", probability_becoming_unemployed
                    call damp_on_flip(separation_rate_adjuster,&
                        model_fraction_unemployed(1)-unemployment_rate_data,&
                        previous_gap_separation_rate,have_gap_separation_rate,&
                        separation_rate_adjuster_start,damp_adjuster_floor,&
                            flips_separation_rate)
                    write(*,*) "separation_rate_adjuster=", separation_rate_adjuster
                    separation_step_1=probability_becoming_unemployed-&
                        separation_rate_adjuster*&
                        (model_fraction_unemployed(1)-unemployment_rate_data)
                    ! NO TRUST STEP. See the note at value_of_life: cap_step is
                    ! the one ceiling now, and a second moving one only obscures
                    ! which bound a step. Unemployment RISES in the separation
                    ! rate, so a rate above target wants it down -- the minus
                    ! above.
                    cap_old_1=probability_becoming_unemployed
                    probability_becoming_unemployed=&
                        max(min(separation_step_1,1.d0),10.d0**(-6))
                    probability_becoming_unemployed=cap_step_rel(probability_becoming_unemployed,cap_old_1,pi_eu_max_rel_step)
                    distance_separation_rate=abs(model_fraction_unemployed(1)-unemployment_rate_data)
                    write(*,*) "probability_becoming_unemployed=", probability_becoming_unemployed
                    write(*,*) "distance_separation_rate=", distance_separation_rate

                    ! kappa_ued, the employment multiplier for the SUD, on the
                    ! unemployment rate GIVEN a SUD. It multiplies the
                    ! separation rate and divides the job finding rate, so
                    ! unemployment among those with the disorder rises in it.
                    write(*,*) "multiple_of_probabilities_of_employment_if_addicted=", &
                        multiple_of_probabilities_of_employment_if_addicted
                    ! THE GAP IS sud_homeless NOW, NOT unemployment given a SUD.
                    ! Sign: raising the multiplier costs the addicted more jobs,
                    ! which makes them poorer and puts MORE of them on the street,
                    ! so sud_homeless RISES in it.  The step is
                    ! multiple - adjuster*(model - target), which is positive-going
                    ! exactly when the model is BELOW target, the current case:
                    ! 0.0814 against 0.217.
                    call damp_on_flip(employment_multiplier_adjuster,&
                        model_fraction_homeless_and_addicted(1)-sud_share_of_homeless,&
                        previous_gap_employment_multiplier,have_gap_employment_multiplier,&
                        employment_multiplier_adjuster_start,damp_adjuster_floor,&
                            flips_employment_multiplier)
                    write(*,*) "employment_multiplier_adjuster=", employment_multiplier_adjuster
                    cap_old_1=multiple_of_probabilities_of_employment_if_addicted
                    multiple_of_probabilities_of_employment_if_addicted=&
                        max(min(multiple_of_probabilities_of_employment_if_addicted-&
                        employment_multiplier_adjuster*&
                        (model_fraction_homeless_and_addicted(1)-sud_share_of_homeless),&
                        20.d0),1.d0)
                    multiple_of_probabilities_of_employment_if_addicted=cap_step(multiple_of_probabilities_of_employment_if_addicted,cap_old_1)
                    ! A RETIRED BRACKET MUST RETIRE ITS DISTANCE TOO.
                    distance_employment_multiplier=merge(0.d0,&
                        abs(model_fraction_homeless_and_addicted(1)-sud_share_of_homeless),&
                        employment_multiplier_adjuster<=0.d0)
                    write(*,*) "multiple_of_probabilities_of_employment_if_addicted=", &
                        multiple_of_probabilities_of_employment_if_addicted
                    write(*,*) "distance_employment_multiplier=", distance_employment_multiplier

                    ! ================================================
                    ! THE SMI BLOCK AND THE TWO WAGE PENALTIES.
                    !
                    ! Each is guarded on its own adjuster, so a parameter that is
                    ! frozen contributes a zero distance rather than a moment the
                    ! sweep can never satisfy. That failure mode cost a whole
                    ! calibration once: a distance computed from a live moment
                    ! while its parameter could not move means the loop cannot
                    ! terminate however well everything else fits.
                    !
                    ! Signs, stated because a wrong one shows up as a moment
                    ! walking away rather than as an error:
                    !   lambda_m up   -> SMI less persistent -> SMI share of the
                    !                    homeless DOWN
                    !   kappa_uem up  -> employment margins worse -> employment
                    !                    rate given SMI DOWN, so the update ADDS,
                    !                    unlike kappa_ued above whose moment is an
                    !                    unemployment rate and whose update
                    !                    subtracts
                    !   rho_m up      -> smaller penalty -> homeless income UP
                    !   rho_d up      -> smaller penalty -> employed homeless can
                    !                    afford housing -> employed share of the
                    !                    homeless DOWN

                    ! ZETA_DI OWNS THE SMI SHARE OF THE HOMELESS. It was
                    ! lambda_m's moment until 25 August, and lambda_m's update
                    ! below is kept at a zero adjuster rather than deleted so
                    ! that what this loop used to do stays readable. A more
                    ! generous transfer keeps households with SMI housed, so the
                    ! share of the homeless carrying SMI FALLS as zeta_DI rises
                    ! and the update SUBTRACTS the gap.
                    if ((zeta_DI_adjuster>0) .AND. (number_of_smi_states>1) &
                        .AND. (model_mass_homeless_raw(1)>10.d0**(-12))) then

                        zeta_DI=min(max(zeta_DI-zeta_DI_adjuster*&
                            (model_smi_share_of_homeless(1)-smi_share_of_homeless_data),&
                            0.d0),1.d0)

                        ! OWNERSHIP IS READ OFF THE DISTANCE, not off the
                        ! update: calibration_report.pairs() builds the map from
                        ! distance_X = abs(model - target), which is what
                        ! check_alignment judges the table's Set column against.
                        distance_zeta_DI=&
                            abs(model_smi_share_of_homeless(1)-smi_share_of_homeless_data)

                        write(*,*) "zeta_DI ->", zeta_DI, " SMI share of the homeless", &
                            model_smi_share_of_homeless(1), " target", smi_share_of_homeless_data

                    else

                        distance_zeta_DI=0

                    end if

                    if ((lambda_m_adjuster>0) .AND. (number_of_smi_states>1)) then

                        ! THE SAME EMPTY SET PROBLEM AS h_2. With no homeless
                        ! households model_smi_share_of_homeless is set to zero
                        ! by the branch that guards its division, so the gap
                        ! against 0.25 is a fabricated -0.25 and lambda_m is
                        ! driven by a moment that does not exist. Hold it until
                        ! there is a homeless population to measure the share on.
                        if (model_mass_homeless_raw(1)<=10.d0**(-12)) then

                            write(*,*) "lambda_m HELD: no homeless mass, so the SMI share of the homeless"
                            write(*,*) "   is not measurable and lambda_m does not move"

                            distance_lambda_m=1

                            goto 8802

                        end if

                        ! THE FLOOR IS THE PROFILE'S, NOT 0.001. Below
                        ! lambda_m_floor the onset identity has no non negative
                        ! solution, the SMI state empties, and every SMI moment
                        ! reads zero, so the loop cannot recover: the moment stops
                        ! responding to the parameter and the update keeps pushing
                        ! the same way. Stopping at the floor keeps the model
                        ! interpretable and makes the tension visible instead.
                        lambda_m=min(max(lambda_m+lambda_m_adjuster*&
                            (model_smi_share_of_homeless(1)-smi_share_of_homeless_data),&
                            lambda_m_floor),0.5d0)

                        if (lambda_m<=lambda_m_floor+10.d0**(-9)) then

                            write(*,*) "lambda_m IS AT ITS FLOOR", lambda_m_floor, &
                                " and the SMI share of the homeless is", &
                                model_smi_share_of_homeless(1), " against a target of", &
                                smi_share_of_homeless_data
                            write(*,*) "   the profile cannot deliver this moment: the prevalence path, the onset"
                            write(*,*) "   identity and this target are not mutually consistent."

                        end if

                        distance_lambda_m=&
                            abs(model_smi_share_of_homeless(1)-smi_share_of_homeless_data)

                        write(*,*) "lambda_m=", lambda_m, " distance_lambda_m=", distance_lambda_m

8802                    continue

                    else

                        distance_lambda_m=0

                    end if

                    if ((kappa_uem_adjuster>0) .AND. (number_of_smi_states>1)) then

                        ! THE SIGN HERE IS THE OPPOSITE OF ITS NEIGHBOUR'S, and
                        ! that is not a slip. kappa_ued above is moved against an
                        ! UNEMPLOYMENT rate, which rises in the parameter, so its
                        ! update subtracts. kappa_uem is moved against an
                        ! EMPLOYMENT rate, which falls in the parameter, so its
                        ! update must ADD. The block was written by analogy with
                        ! the SUD block and inherited the minus, which drove
                        ! kappa_uem to its floor of one, removed the SMI
                        ! employment effect altogether, and left a distance that
                        ! could never fall below its stopping rule, so the loop
                        ! could not terminate however well anything else fitted.
                        ! THE CEILING WAS 20 AND kappa_uem WALKED INTO IT.
                        ! It reached 17.98 with the employment rate given SMI
                        ! still at 0.68 against a target of 0.30, so three more
                        ! loops would have parked it on the bound with the
                        ! moment untouched and the distance unable to fall.
                        ! A bound a parameter can reach while its moment is
                        ! still wide is indistinguishable, from the loop's
                        ! point of view, from a moment the model cannot hit.
                        ! 40 is not a belief about the penalty's size: it is far
                        ! enough away that reaching it would be evidence, not an
                        ! artefact of where the ceiling was put.
                        !
                        ! RAISED TO 100 on the author's instruction of 25 August,
                        ! for the same reason and with more room. The moment was
                        ! reported to them as close to unreachable on a log-LEVEL
                        ! elasticity of -0.133; in log ODDS the three measured
                        ! points at 1.0, 1.6 and 3.0 are a straight line of slope
                        ! -1.80 and put the answer near 8.5, so neither 40 nor 100
                        ! should ever bind. The point of the headroom is that if
                        ! one of them does bind, that is now a fact about the
                        ! model rather than about this constant.
                        !
                        ! Above kappa = 1/probability_becoming_unemployed, about
                        ! 34 at the current value, sep_1 is clamped at one and
                        ! only the job-finding side still responds. The employment
                        ! rate keeps falling to zero, so the ceiling remains a
                        ! ceiling and not a wall, but the log-odds line bends
                        ! there and a fit taken across it should not be believed.
                        ! THE EMPTY SET PROBLEM, THE SAME ONE lambda_m GUARDS.
                        ! With no homeless mass model_smi_share_of_homeless is set
                        ! to zero by the branch that guards its division, so the
                        ! gap against 0.25 is a fabricated -0.25 and kappa_uem is
                        ! driven by a moment that does not exist.
                        if (model_mass_homeless_raw(1)<=10.d0**(-12)) then

                            write(*,*) "kappa_uem HELD: no homeless mass, so the SMI share"
                            write(*,*) "   of the homeless is not measurable this loop"

                            distance_kappa_uem=1

                        else

                        ! THE GAP IS THE SMI SHARE OF THE HOMELESS NOW, NOT THE
                        ! EMPLOYMENT RATE GIVEN SMI, AND THAT FLIPS THE SIGN.
                        ! The long note above explains why the old sign was a PLUS:
                        ! an employment rate FALLS in this parameter, so closing a
                        ! gap on it means adding. The share of the homeless does
                        ! the opposite -- a bigger penalty costs the ill more jobs,
                        ! which makes them poorer and puts MORE of them on the
                        ! street -- so the share RISES in kappa_uem and the update
                        ! SUBTRACTS, which is what kappa_ued does on the SUD side.
                        cap_old_1=kappa_uem
                        kappa_uem=min(max(kappa_uem-kappa_uem_adjuster*&
                            (model_smi_share_of_homeless(1)-smi_share_of_homeless_data),&
                            1.0d0),100.d0)
                        kappa_uem=cap_step(kappa_uem,cap_old_1)

                        distance_kappa_uem=&
                            abs(model_smi_share_of_homeless(1)-smi_share_of_homeless_data)

                        end if

                        write(*,*) "kappa_uem=", kappa_uem, " distance_kappa_uem=", distance_kappa_uem

                    else

                        distance_kappa_uem=0

                    end if

                    ! ===== kappa_find_smi, THE SMI JOB-FINDING PENALTY =========
                    ! Author, 15 September: "adjust kappa_find_smi to match the
                    ! share of homeless with SMI", and with it "lambdam also
                    ! should be held since Kappa_find_smi is controlling that
                    ! target".
                    !
                    ! IT HAD NO UPDATE BLOCK AT ALL until now -- no adjuster, no
                    ! distance, no gap -- so it could be seeded and never
                    ! calibrated. kappa_uem used to own this moment and is held
                    ! above: ONE MOMENT, ONE INSTRUMENT.
                    !
                    ! THE SIGN. It DIVIDES job finding (find_1=find_1/kappa_find_smi),
                    ! so a larger value means the ill find work less easily, more
                    ! end up on the street, and the SMI share of the homeless
                    ! RISES. A model above target wants this SMALLER, so the
                    ! update SUBTRACTS the gap -- the same convention kappa_uem
                    ! used on this moment and kappa_ued uses on the SUD side.
                    if ((kappa_find_smi_adjuster>0) .AND. (number_of_smi_states>1)) then

                        ! With no homeless mass model_smi_share_of_homeless is
                        ! set to zero by the branch that guards its division, so
                        ! the gap against the target is a fabricated one and the
                        ! parameter would be driven by a moment that does not
                        ! exist. Same guard kappa_uem carries above.
                        if (model_mass_homeless_raw(1)<=10.d0**(-12)) then

                            write(*,*) "kappa_find_smi HELD: no homeless mass, so the"
                            write(*,*) "   SMI share of the homeless is not measurable this loop"

                            distance_kappa_find_smi=1

                        else

                            cap_old_1=kappa_find_smi
                            kappa_find_smi=min(max(kappa_find_smi-kappa_find_smi_adjuster*&
                                (model_smi_share_of_homeless(1)-smi_share_of_homeless_data),&
                                1.0d0),100.d0)
                            kappa_find_smi=cap_step_rel(kappa_find_smi,cap_old_1,&
                                kappa_find_smi_max_rel_step)

                            distance_kappa_find_smi=&
                                abs(model_smi_share_of_homeless(1)-smi_share_of_homeless_data)

                        end if

                        write(*,*) "kappa_find_smi=", kappa_find_smi,&
                            " distance_kappa_find_smi=", distance_kappa_find_smi,&
                            " SMI share of homeless=", model_smi_share_of_homeless(1),&
                            " target=", smi_share_of_homeless_data

                    else

                        distance_kappa_find_smi=0

                    end if

                    ! ------- b_smi_multiple, on the SMI comorbidity ratio -------
                    !
                    ! THE SIGN IS REVERSED FROM EVERY OTHER BRACKET HERE, and the
                    ! plus is not a typo. b enters flow utility as (b+q)^phi_q, so
                    ! the marginal value of the first unit goes like 1/b: a LARGER
                    ! multiple makes the drug worth LESS to an SMI household, they
                    ! use less, and the ratio FALLS. Parameter and moment move in
                    ! OPPOSITE directions, so a model ABOVE target wants the
                    ! parameter RAISED and the update ADDS the gap. CLAUDE.md
                    ! records the same trap on kappa_phi_d_level and warns that
                    ! reading the operator alone gives the opposite direction.
                    if ((b_smi_multiple_adjuster>0) .AND. (number_of_smi_states>1)) then

                        ! Three denominators, and a corner in any one of them
                        ! makes the ratio a fabricated number rather than a large
                        ! one. Same guard kappa_find_smi carries on its homeless
                        ! mass above.
                        if ((xtab_mass_smi(1)<=10.d0**(-12)) .OR. &
                            ((xtab_mass_pop(1)-xtab_mass_smi(1))<=10.d0**(-12)) .OR. &
                            ((xtab_sud_mass_pop(1)-xtab_sud_mass_smi(1))<=10.d0**(-12))) then

                            write(*,*) "b_smi_multiple HELD: the comorbidity ratio is not"
                            write(*,*) "   measurable this loop -- an empty SMI, non-SMI or non-SMI SUD cell"

                            distance_b_smi_multiple=1

                        else

                            sud_smi_ratio_1=(xtab_sud_mass_smi(1)/xtab_mass_smi(1))/&
                                ((xtab_sud_mass_pop(1)-xtab_sud_mass_smi(1))/&
                                (xtab_mass_pop(1)-xtab_mass_smi(1)))

                            cap_old_1=b_smi_multiple
                            b_smi_multiple=min(max(b_smi_multiple+b_smi_multiple_adjuster*&
                                (sud_smi_ratio_1-sud_smi_ratio_data),&
                                10.d0**(-6)),10.d0)
                            b_smi_multiple=cap_step_rel(b_smi_multiple,cap_old_1,&
                                b_smi_multiple_max_rel_step)

                            ! RELATIVE, because the ratio is order 7 and not order
                            ! 0.05 like the shares the other brackets score. An
                            ! absolute distance against a 1e-2 rule would be asking
                            ! for three significant figures on a moment read off a
                            ! distribution.
                            distance_b_smi_multiple=&
                                abs(sud_smi_ratio_1-sud_smi_ratio_data)/sud_smi_ratio_data

                        end if

                        write(*,*) "b_smi_multiple=", b_smi_multiple,&
                            " distance_b_smi_multiple=", distance_b_smi_multiple,&
                            " SUD ratio SMI over non-SMI=", sud_smi_ratio_1,&
                            " target=", sud_smi_ratio_data

                    else

                        distance_b_smi_multiple=0

                    end if


                    ! ================= p_m, THE SMI POPULATION SHARE ============
                    ! smi_onset_level, on the author's instruction of 11 September
                    ! that this be calibrated like every other parameter. Prevalence
                    ! RISES in the onset, so the update subtracts the gap.
                    if (smi_onset_level_adjuster>0) then

                        write(*,*) "model_smi_prevalence(1)=", model_smi_prevalence(1),&
                            " target=", model_smi_prevalence_target(1)
                        write(*,*) "smi_onset_level=", smi_onset_level

                        cap_old_1=smi_onset_level
                        smi_onset_level=max(min(smi_onset_level-&
                            smi_onset_level_adjuster*&
                            (model_smi_prevalence(1)-model_smi_prevalence_target(1)),&
                            1.d0),10.d0**(-8))
                        smi_onset_level=cap_step(smi_onset_level,cap_old_1)

                        distance_smi_onset_level=&
                            abs(model_smi_prevalence(1)-model_smi_prevalence_target(1))

                        write(*,*) "smi_onset_level=", smi_onset_level,&
                            " distance_smi_onset_level=", distance_smi_onset_level

                    else

                        distance_smi_onset_level=0

                    end if

                    ! ========= h_share1, THE YOUNG'S SHARE OF THE HOMELESS ======
                    ! newborn_endowment_scale, NOW TWO-SIDED. Raising it takes the
                    ! youngest off the street, so the share falls in it: a model
                    ! ABOVE target calls for a LARGER endowment and one BELOW target
                    ! for a SMALLER one.
                    !
                    ! IT USED TO BE ONE-SIDED and that is why this moment never moved.
                    ! The rule of 3 September held the endowment whenever the share
                    ! was BELOW target, on the reasoning that the instrument only
                    ! pushes the share DOWN. That is half the instrument: it pushes
                    ! the share down when it RISES, and up when it FALLS, and nothing
                    ! stopped it falling. With band 1 sitting at 0.1885 against a
                    ! target of 0.260 the gate was true at every loop of the full
                    ! calibration, so "ENDOWMENT HELD" printed every loop, the scale
                    ! stayed at 0.464544 from the first loop to the ninth, and h_1
                    ! drifted to +10.9 per cent with its composition uncorrected.
                    !
                    ! The author, 11 September: "Just adjust the newborn endowment
                    ! down to match the hshare1."
                    !
                    ! The update below is UNCHANGED and needs no sign work. The step
                    ! is adjuster*(band1 - target), which is already negative when the
                    ! share is below target, so removing the gate lowers the scale by
                    ! exactly the symmetric amount. cap_step and the 0-to-50 bounds
                    ! still apply in both directions.
                    if (newborn_endowment_adjuster>0) then

                        write(*,*) "share of the homeless in band 1 =",&
                            homelessness_by_age_group(1,1),&
                            " target =", val_hud_share_1(1)
                        write(*,*) "newborn_endowment_scale=", newborn_endowment_scale

                        cap_old_1=newborn_endowment_scale
                        newborn_endowment_scale=max(min(newborn_endowment_scale+&
                            newborn_endowment_adjuster*&
                            (homelessness_by_age_group(1,1)-val_hud_share_1(1)),&
                            50.d0),0.d0)
                        newborn_endowment_scale=&
                            cap_step_rel(newborn_endowment_scale,cap_old_1,&
                            newborn_endowment_max_rel_step)

                        distance_newborn_endowment=&
                            abs(homelessness_by_age_group(1,1)-val_hud_share_1(1))

                        write(*,*) "newborn_endowment_scale=", newborn_endowment_scale,&
                            " distance_newborn_endowment=", distance_newborn_endowment,&
                            merge(" LOWERED: band 1 is below target ",&
                                  " RAISED:  band 1 is above target ",&
                                  homelessness_by_age_group(1,1)<val_hud_share_1(1))

                    else

                        distance_newborn_endowment=0

                    end if

                    if ((rho_m_adjuster>0) .AND. (number_of_smi_states>1) .AND. &
                        (include_rho_m==1)) then

                        rho_m=min(max(rho_m-rho_m_adjuster*&
                            (model_homeless_income_share(1)-homeless_income_share_data),&
                            0.05d0),1.d0)

                        distance_rho_m=&
                            abs(model_homeless_income_share(1)-homeless_income_share_data)

                        write(*,*) "rho_m=", rho_m, " distance_rho_m=", distance_rho_m

                    else

                        distance_rho_m=0

                    end if

                    if ((rho_d_adjuster>0) .AND. (include_rho_d==1)) then

                        rho_d=min(max(rho_d+rho_d_adjuster*&
                            (model_employed_share_of_homeless(1)-employed_share_of_homeless_data),&
                            0.05d0),1.d0)

                        distance_rho_d=&
                            abs(model_employed_share_of_homeless(1)-employed_share_of_homeless_data)

                        write(*,*) "rho_d=", rho_d, " distance_rho_d=", distance_rho_d

                    else

                        distance_rho_d=0

                    end if

                    write(*,*) "model_fraction_homeless(1)=", model_fraction_homeless(1)
                    write(*,*) "size_homelessness=", size_homelessness

                    ! A bracket whose endpoints were priced under different values
                    ! of life is not a bracket. Test for that before using it.
                    ! THE BISECTION BRACKETS ON THE HOMELESSNESS RATE, in a dozen
                    ! places, and h_1 no longer targets that. Re-pointing every one
                    ! of them is a larger edit than this experiment justifies and a
                    ! half-re-pointed bisection would bracket on one moment and step
                    ! on another. Discarding the bracket each loop leaves the
                    ! traverse, which is re-pointed cleanly above.
                    if (h1_targets_emp_homeless==1) then
                        size_homelessness_lo=-1
                        size_homelessness_hi=-1
                        size_homelessness_lo_moment=-1
                        size_homelessness_hi_moment=-1
                    end if

                    if ((size_homelessness_lo>=0) .OR. (size_homelessness_hi>=0)) then

                        if ((value_of_life_at_bracket>0) .AND. &
                            (abs(value_of_life-value_of_life_at_bracket)>&
                            bracket_value_of_life_tolerance*value_of_life_at_bracket)) then

                            write(*,*) "size_homelessness BRACKET DISCARDED: the value of life moved from ",&
                                value_of_life_at_bracket, " to ", value_of_life,&
                                " so its endpoints are not comparable"
                            size_homelessness_lo=-1
                            size_homelessness_hi=-1
                            size_homelessness_lo_moment=-1
                            size_homelessness_hi_moment=-1
                            value_of_life_at_bracket=-1

                        end if

                    end if

                    if ((size_homelessness_lo<0) .AND. (size_homelessness_hi<0)) then

                        value_of_life_at_bracket=value_of_life

                    end if

                    ! Tighten the bracket with what this evaluation just proved,
                    ! unless it proves the bracket itself is stale.
                    if (model_fraction_homeless(1)<fraction_homeless_data) then

                        if (size_homelessness_lo<0) then

                            size_homelessness_lo=size_homelessness
                            size_homelessness_lo_moment=model_fraction_homeless(1)

                        else if ((size_homelessness>size_homelessness_lo) .AND. &
                            (model_fraction_homeless(1)<size_homelessness_lo_moment-10.d0**(-5))) then

                            ! Raised the parameter and homelessness fell.
                            write(*,*) "size_homelessness BRACKET DISCARDED: raised to ",&
                                size_homelessness, " and homelessness fell from ",&
                                size_homelessness_lo_moment, " to ", model_fraction_homeless(1)
                            size_homelessness_lo=-1
                            size_homelessness_hi=-1
                            size_homelessness_lo_moment=-1
                            size_homelessness_hi_moment=-1

                        else if (size_homelessness>size_homelessness_lo) then

                            size_homelessness_lo=size_homelessness
                            size_homelessness_lo_moment=model_fraction_homeless(1)

                        end if

                    else

                        if (size_homelessness_hi<0) then

                            size_homelessness_hi=size_homelessness
                            size_homelessness_hi_moment=model_fraction_homeless(1)

                        else if ((size_homelessness<size_homelessness_hi) .AND. &
                            (model_fraction_homeless(1)>size_homelessness_hi_moment+10.d0**(-5))) then

                            ! Lowered the parameter and homelessness rose.
                            write(*,*) "size_homelessness BRACKET DISCARDED: lowered to ",&
                                size_homelessness, " and homelessness rose from ",&
                                size_homelessness_hi_moment, " to ", model_fraction_homeless(1)
                            size_homelessness_lo=-1
                            size_homelessness_hi=-1
                            size_homelessness_lo_moment=-1
                            size_homelessness_hi_moment=-1

                        else if (size_homelessness<size_homelessness_hi) then

                            size_homelessness_hi=size_homelessness
                            size_homelessness_hi_moment=model_fraction_homeless(1)

                        end if

                    end if

                    if ((size_homelessness_lo>=0) .AND. &
                        (size_homelessness_hi>size_homelessness_lo)) then

                        ! Bisect. This halves the window every equilibrium solve,
                        ! so a window of 0.08 is down to the stopping rule in about
                        ! seven of them however wide the initial bracket was.
                        cap_old_1=size_homelessness
                        size_homelessness=&
                            0.5d0*(size_homelessness_lo+size_homelessness_hi)
                        size_homelessness=cap_step_rel(size_homelessness,cap_old_1,&
                            size_homelessness_max_rel_step)

                        write(*,*) "size_homelessness bisecting in [",&
                            size_homelessness_lo, ",", size_homelessness_hi, "]"

                    else

                        ! No bracket yet, so traverse, which is what the adjuster
                        ! is good at.
                        ! h_1 IS A BAND, NOT A POINT. The author, 16 September: "I think
                        ! that as long as h1 is in the 0.4-1% band we should not adjust it
                        ! unless it improves emp homeless", after earlier saying "if it
                        ! raises homelessness closer to 1% it is ok if emphomlees is
                        ! better too".
                        !
                        ! WHY IT MATTERS. Driving h_1 to the 0.4 per cent POINT drags
                        ! emp_homeless down with it: measured across n03, h_1 went
                        ! 0.0208 -> 0.00386 and emp_homeless fell 0.988 -> 0.087 over
                        ! exactly those blocks, a slope near -22 per unit h_1. The two
                        ! goals are in direct conflict at a point target and are not in
                        ! conflict at a band, because anywhere in [0.004, 0.010] is
                        ! acceptable and the higher end buys a better emp_homeless.
                        !
                        ! INSIDE THE BAND THE GAP IS ZERO, so the bracket holds and h_1
                        ! stops fighting b and emp_homeless. Outside it, the gap is
                        ! measured to the NEARER EDGE rather than to 0.004, so a run
                        ! above the band returns to 1 per cent rather than being driven
                        ! through the band to its floor.
                        !
                        ! h1_band_lo AND h1_band_hi ALREADY EXISTED at their declaration
                        ! and were never read by anything. The band was written down and
                        ! then not implemented; this is the code that uses it.
                        if (h1_targets_emp_homeless==1) then
                            gap_size_homelessness_1=&
                                model_employed_share_of_homeless(1)-employed_share_of_homeless_data
                        else if (model_fraction_homeless(1)>h1_band_hi) then
                            gap_size_homelessness_1=model_fraction_homeless(1)-h1_band_hi
                        else if (model_fraction_homeless(1)<h1_band_lo) then
                            gap_size_homelessness_1=model_fraction_homeless(1)-h1_band_lo
                        else
                            gap_size_homelessness_1=0.d0
                            write(*,*) "h_1 IN BAND: ", model_fraction_homeless(1),&
                                " is inside [", h1_band_lo, ",", h1_band_hi,&
                                "] -- size_homelessness HELD at", size_homelessness
                        end if

                        if (have_gap_size_homelessness==1) then

                            if ((gap_size_homelessness_1*previous_gap_size_homelessness)<0) then

                                size_homelessness_adjuster=max(size_homelessness_adjuster*&
                                    size_homelessness_damping,size_homelessness_adjuster_floor)

                            else if (abs(gap_size_homelessness_1)>&
                                0.5d0*fraction_homeless_data) then

                                ! DAMPING IS A MEMORY OF A DIFFERENT REGIME. The
                                ! adjuster is halved on every sign flip and grown
                                ! by a fifth on every same signed loop, which is
                                ! right beside a solution and wrong far from one:
                                ! after enough flips it stood at 0.067 against a
                                ! gap of 0.0034, a step of 0.0002 on a parameter
                                ! of 0.099, so an eighty five per cent miss moved
                                ! by two parts in a thousand a loop and would
                                ! have taken hundreds of solves.
                                !
                                ! A gap of half the target is not near a solution.
                                ! Re-arm rather than creep, and let the overshoot
                                ! do its job: the first sign flip after it
                                ! establishes the bracket, and the bisection below
                                ! closes the window in about seven solves however
                                ! wide it is. That is what the bracket is for, and
                                ! creeping never reaches it.
                                size_homelessness_adjuster=size_homelessness_adjuster_start

                                write(*,*) "size_homelessness adjuster RE-ARMED: the gap is ", &
                                    gap_size_homelessness_1, " against a target of ", &
                                    fraction_homeless_data

                            else

                                size_homelessness_adjuster=min(size_homelessness_adjuster*&
                                    size_homelessness_growth,size_homelessness_adjuster_start)

                            end if

                        end if

                        previous_gap_size_homelessness=gap_size_homelessness_1
                        have_gap_size_homelessness=1

                        write(*,*) "size_homelessness_adjuster=", size_homelessness_adjuster

                        ! THE LADDER MUST BE STRICTLY INCREASING, and this
                        ! bound is what guarantees it: h_1 is built as
                        ! housing_size(0)*size_homelessness, so a ceiling of 1
                        ! admits h_1 = h_2 exactly, a street worth as much as
                        ! the cheapest room and free, at which point the rung
                        ! above the street buys nothing and the housing
                        ! dimension collapses at the bottom. 0.9 keeps the
                        ! inequality strict and still leaves homelessness as
                        ! attractive as the traverse can need: the current
                        ! value is 0.10, so this binds on nothing today and
                        ! stops the degenerate case if the update ever runs.
                        size_homelessness_step_1=size_homelessness-&
                            size_homelessness_adjuster*gap_size_homelessness_1
                        ! NO TRUST STEP. See the note at value_of_life.
                        ! Homelessness RISES in h_1, so a rate above target wants
                        ! h_1 down -- the minus above -- and cap_step is the
                        ! ceiling.
                        cap_old_1=size_homelessness
                        size_homelessness=max(min(size_homelessness_step_1,0.9d0),&
                            size_homelessness_floor)
                        size_homelessness=cap_step_rel(size_homelessness,cap_old_1,&
                            size_homelessness_max_rel_step)

                        ! THE BAND GUARD. h_1 is no longer fitted to the homelessness
                        ! rate, so nothing else holds it. Nudge 2 per cent a loop when
                        ! it leaves [0.004, 0.01] and SAY SO -- a run that sits on an
                        ! edge is reporting that 46 per cent employed cannot be had
                        ! inside the band.
                        if (h1_targets_emp_homeless==1) then
                            if (model_fraction_homeless(1)<h1_band_lo) then
                                size_homelessness=max(size_homelessness,cap_old_1*1.02d0)
                                write(*,*) "H_1 BAND: rate ", model_fraction_homeless(1),&
                                    " below ", h1_band_lo, " -- raising h_1 to ", size_homelessness
                            else if (model_fraction_homeless(1)>h1_band_hi) then
                                size_homelessness=min(size_homelessness,cap_old_1*0.98d0)
                                write(*,*) "H_1 BAND: rate ", model_fraction_homeless(1),&
                                    " above ", h1_band_hi, " -- lowering h_1 to ", size_homelessness
                            end if
                        end if

                        ! Say so if the traverse has run out of room. At a street
                        ! worth as much as housing_size(0) and free, a model still
                        ! below target is not a failure of this update: nothing in
                        ! the housing ladder makes homelessness attractive, so the
                        ! rental grid or the food floor is what has to move.
                        if ((size_homelessness>=0.9d0) .AND. &
                            (model_fraction_homeless(1)<fraction_homeless_data)) then

                            write(*,*) "size_homelessness IS AT ITS CEILING 1 and homelessness is ",&
                                model_fraction_homeless(1), " against a target of ", fraction_homeless_data
                            write(*,*) "   no bracket exists below the ceiling: the street cannot be",&
                                " made attractive enough through this parameter."

                        end if

                    end if

                    ! GUARDED ON THE ADJUSTER, like every other distance in this
                    ! file. It was written unconditionally, which was harmless
                    ! only while h_1 was calibrated. With h_1 tied to h_2 the
                    ! adjuster is zero, and an unguarded distance on a moment
                    ! nothing can move is the documented way for this loop never
                    ! to terminate -- it would have held the convergence test open
                    ! for ever on the homelessness rate.
                    !
                    ! The homelessness rate is still PRINTED every loop and is
                    ! still the thing h_2 is chosen by hand to hit; it is simply
                    ! not scored, because no parameter in the loop moves it.
                    if (size_homelessness_adjuster>0.d0) then

                        distance_size_homelessness=&
                            abs(model_fraction_homeless(1)-fraction_homeless_data)

                    else

                        distance_size_homelessness=0

                    end if

                    write(*,*) "size_homelessness=", size_homelessness
                                 
                end if
                                        
            end if
                                                                                     
            distance_rental_market(1)=maxval(abs(total_rental_demand(1,:)-total_rental_supply(1,:)))

            ! THE DRUG MARKET.
            !
            ! V is the quantity households actually bought, accumulated over the
            ! distribution in model_drugs_consumed_by_users. The supply price at
            ! that quantity is nu_1 V^(nu_2-1).
            !
            ! In the benchmark nu_1 is whatever puts that price at one, which is
            ! the note's normalisation, so the market clears every loop and the
            ! price never moves. In a counterfactual nu_1 is the benchmark's, so
            ! the price is whatever the supply curve says and the loop iterates
            ! until the price households faced and the price the quantity
            ! implies agree.
            call clear_drug_market(1)

            write(*,*) "rent(1)=", rent(1,:)
            write(*,*) "rental_supply(1)=", total_rental_supply(1,:)
            write(*,*) "rental_demand(1)=", total_rental_demand(1,:)
            write(*,*) "distance_rental_market(1)=", distance_rental_market(1)
                                                                   
            write(*,*) "one market"

            rental_market_adjuster=1
            
            if (re_do_simulation_with_fixed_parameters==5) then
        
                distance_rental_market(1)=maxval((abs(himmelberg_etal_rent_to_price-(rent(1,:)/housing_price(1)))))
                    
                if (fix_rent==0) then
                    rent(1,:)=rent(1,:)+rental_market_adjuster*(himmelberg_etal_rent_to_price-&
                        (rent(1,:)/housing_price(1)))
                end if
                    
            else
            
                rental_market_adjuster=10.d0**(-3)
                            
                distance_rental_market(1)=maxval(abs(total_rental_demand(1,:)-total_rental_supply(1,:)))
                                      
            end if
                                               
            write(*,*) "rent(1)=", rent(1,:)
            write(*,*) "rental_market_adjuster=", rental_market_adjuster
            ! GUARDED 17 September. This is 0/0 whenever nobody owns, which is
            ! the whole of the present calibration -- the homeownership rate is
            ! exactly zero and the invariant PASSES at zero. Under -O3 all three
            ! of these prints read NaN and the run carries on; under the standing
            ! -ffpe-trap=invalid build the first of them is a SIGFPE, which is
            ! where the 13-node verification run died after a clean solve. The
            ! divisions are inside write statements, so the guard changes no
            ! economics and nothing that any moment is computed from.
            write(*,*) "model_mortgages(1)/model_gross_housing_wealth(1)=",&
                model_mortgages(1)/max(model_gross_housing_wealth(1),10.d0**(-14))
            write(*,*) "model_average_rental_unit_size(1)=", model_average_rental_unit_size(1)
            write(*,*) "model_average_owner_occupied_unit_size(1)=", model_average_owner_occupied_unit_size(1)
            write(*,*) "model_average_rental_unit_size(1)/model_average_owner_occupied_unit_size(1)=", &
                model_average_rental_unit_size(1)/model_average_owner_occupied_unit_size(1)
!            write(*,*) "model_fraction_of_homeowners_with_mortgage(1)=", model_fraction_of_homeowners_with_mortgage(1)
                
            if (mortgage_deductibility>0) then
            
                write(*,*) "% govt spending on mortgage interest deductions(1)/model_GDP_incl_imput_rent(1)=", &
                    100*(govt_spending_on_mortgage_interest_deductions(1)/model_GDP_incl_imput_rent(1))
                
            end if
                
            write(*,*) "model_homeownership_rate(1)=", model_homeownership_rate(1)
                                                        
            call cpu_time(simulation_stop_time)
            
            write(*,*) "re_do_simulation_with_fixed_parameters=", re_do_simulation_with_fixed_parameters
            write(*,*) "relative_share_of_housing=", relative_share_of_housing
            write(*,*) "relative_share_of_leisure=", relative_share_of_leisure
            
            if (calibrate_size_of_smallest_house_hhld_can_buy==0) then
            
                write(*,*) "advantage_to_owning=", advantage_to_owning
                
            end if
            
            write(*,*) "discount_factor=", discount_factor
            write(*,*) "discount_factor_on_child=", discount_factor_on_child
                        
            write(*,*) "convexity_of_rental_company=", convexity_of_rental_company(:)
                                    
            write(*,*) "housing_status_grid_expander=", housing_status_grid_expander
                                    
            mass_at_top_financial=0
            
            do i=1,2
                                    
                mass_at_top_financial=mass_at_top_financial+&
                    sum(distribution_stationary(i)%vector_transition_real(1,:,financial_grid_size,:,:,:,:)) 
                    
            end do
                        
            write(*,*) "labor_income_tax_rate=", labor_income_tax_rate
            write(*,*) "utility_improvement,", utility_improvement
            write(*,*) "rental_management_costs=", rental_management_costs(:)
            write(*,*) "smallest_house_size=", smallest_house_size
            write(*,*) "index_of_smallest_house_hhld_can_buy=", index_of_smallest_house_hhld_can_buy
            write(*,*) "housing_size(index_of_smallest_house_hhld_can_buy)=", &
                housing_size(max(min(index_of_smallest_house_hhld_can_buy,housing_status_grid_size-1),lowest_housing_grid_point))
            write(*,*) "size_homelessness=", size_homelessness
            write(*,*) "largest_financial_chosen_in_equilibrium=", largest_financial_chosen_in_equilibrium
            write(*,*) "largest_housing_size_consumed_in_equilibrium=", largest_housing_size_consumed_in_equilibrium
            write(*,*) "smallest_financial_chosen_in_equilibrium=", smallest_financial_chosen_in_equilibrium
            write(*,*) "financial_grid(smallest_financial_chosen_in_equilibrium)=", &
                financial_grid(smallest_financial_chosen_in_equilibrium)
            write(*,*) "fraction of hhlds who make it to the highest net wealth=", mass_at_top_financial/sum_of_distribution
            write(*,*) "fraction_with_largest_housing_size_consumed_in_eqilibrium=", &
                fraction_with_largest_housing_size_consumed_in_eqilibrium
            write(*,*) "fraction_with_smallest_financial_in_eqilibrium=", &
                fraction_with_smallest_financial_in_eqilibrium
            write(*,*) "smallest_rental_relative_to_lowest_income=", smallest_rental_relative_to_lowest_income
                                      
            call initialize_variables_and_grids()                
            call GKKOC_intergenerational_employment_process(1)
            call initialize_financial_grid(1)

            if (re_do_simulation_with_fixed_parameters==0) then

                call set_smallest_house_size()

            end if
            
            distance_average_labor_income=&
                abs(previous_average_labor_income-model_average_labour_income(1))
                
            if (include_vouchers==1) then
                
                distance_median_income=&
                    abs(previous_median_income-median_income(1))
                    
            else
            
                distance_median_income=0
            
            end if
                
            if (threshold_for_food_stamps_as_perc_of_average_net_wealth>100) then
            
                distance_average_net_wealth=0
                
            else
                
                distance_average_net_wealth=&
                    abs(previous_average_net_wealth-model_average_net_wealth(1))
                    
            end if
                        
            model_average_labour_income(1)=&
                weight_on_labor_income*model_average_labour_income(1)+&
                (1-weight_on_labor_income)*previous_average_labor_income
                                
            median_income(1)=weight_on_median_income*median_income(1)+(1-weight_on_median_income)*previous_median_income
                                
            model_average_net_wealth(1)=&
                weight_on_labor_income*model_average_net_wealth(1)+&
                (1-weight_on_labor_income)*previous_average_net_wealth
                                                    
            call function_of_utility_advantage_from_homeowning(1)

            ! THE REFRESH CALL TO govt_revenues_calc WAS HERE AND IS REMOVED.
            !
            ! It ran AFTER the two-pass loop, where accumulating_beta_types is
            ! back to zero, so every guarded reset inside it fired: it wiped the
            ! pooled revenue totals and refilled them from
            ! distribution_stationary, which by then holds only the LAST TYPE
            ! SOLVED. Its denominators -- model_total_efficiency_units and
            ! model_financial -- are accumulated elsewhere and stayed pooled, so
            !
            !     tau_l = one type's revenue / two types' income = HALF
            !
            ! and tau_l is an INTERNAL ADJUSTER TARGET, so the model drove
            ! labor_income_tax_rate up until the halved number reached 0.224 --
            ! toward twice the tax rate the data asks for, faced by every
            ! household. Measured at 0.497 of its one-type value.
            !
            ! WHY REMOVING IT IS THE FIX RATHER THAN REPAIRING IT. The call
            ! cannot be made to accumulate instead of reset: type 1's
            ! distribution no longer exists here, so there is nothing to
            ! accumulate onto and no way to rebuild the pooled object. What it
            ! was for was refreshing revenues against the averages updated a few
            ! lines above. Dropping it leaves every revenue quantity holding the
            ! value the LOOP computed, which is pooled and correct, one outer
            ! iteration stale -- and the next outer iteration re-runs the whole
            ! chain against those same averages anyway. Stale and right beats
            ! fresh and halved.
            !
            ! set_SS_benefits reads nothing govt_revenues_calc produces, checked.
            call set_SS_benefits(1)
            
            if ((zero_elasticity==0) .AND. (infinite_elasticity_of_rental_supply==0)) then
                
                do j=0,have_two_rental_markets
!                        
                    call solve_elasticity_of_rental_housing(1,convexity_of_rental_company(j),j)
                    write(*,*) "convexity_of_rental_company=", convexity_of_rental_company(j)
                    write(*,*) "rental_management_costs=", rental_management_costs(j)
                    
                end do
                
            end if
                                                                                                         
            write(*,*) "loop_count=", loop_count
            
            write(*,*) "model average labour income=", model_average_labour_income(1)
            write(*,*) "model_average_labour_income_tax=", model_average_labour_income_tax(1)
            write(*,*) "model_average_net_wealth=", model_average_net_wealth(1)
            write(*,*) "do_internal_computations=", do_internal_computations
            
            write(*,*) "model_labor_supply/model_total_hours=", model_labor_supply(1)/model_total_hours(1)
            write(*,*) "distance_average_labor_income=", distance_average_labor_income    
            write(*,*) "distance_average_net_wealth=", distance_average_net_wealth  
                        
            write(*,*) "model_homeownership_by_age_group(1,5)=", model_homeownership_by_age_group(1,5)
            write(*,*) "value_of_initial_assets=", value_of_initial_assets
                                    
!            write(*,*) "model_avg_mortgage_spending=", model_avg_mortgage_spending(1)
            write(*,*) "model_avg_housing_spending_owners=", model_avg_housing_spending_owners(1)
            write(*,*) "model_avg_housing_spending_all=", model_avg_housing_spending_all(1)
            write(*,*) "model_avg_housing_spending_renters=", model_avg_housing_spending_renters(1)
            write(*,*) "total_rent_paid/total_renters_income=", 100*(total_rent_paid(1)/max(total_renters_income(1),10.d0**(-14)))
!            write(*,*) "inheritance_amount=", inheritance_amount
            write(*,*) "distance_inheritance_amount=", distance_inheritance_amount
            write(*,*) "average_welfare_of_youngest_cohort=", average_welfare_of_youngest_cohort(1)
            write(*,*) "mass_of_renters_at_housing_spending(1,1)=", mass_of_renters_at_housing_spending(1,1)
            write(*,*) "mass_of_renters_at_housing_spending(1,2)=", mass_of_renters_at_housing_spending(1,2)
            write(*,*) "model_fraction_homeless=", model_fraction_homeless(1)
!            write(*,*) "model_fraction_homeless_owners,", model_fraction_homeless_owners(1)
            write(*,*) "model_fraction_addicted=", model_fraction_addicted(1)
            write(*,*) "model_exprimenters=", model_exprimenters(1)
            ! ONE POINT PER PROCESS, AND IT ENDS HERE.
            !
            ! The foot of the calibration sweep is where b was being stepped, and
            ! that foot is never reached: seven passes ran in an hour, each with
            ! its own solve and its own converged distribution, and not one
            ! printed the announcement sitting three lines under the loop
            ! counter's increment. The tail of that body does not execute, so a
            ! grid indexed there never moves off its first point.
            !
            ! It could not have been clean if it had. re_do_simulation_with_fixed_
            ! parameters does not freeze everything: sd_permanent_productivity was
            ! still being updated pass by pass, and participation at a FIXED b
            ! drifted 0.3326, 0.3244, 0.3327 across three of them, which is the
            ! contamination the sweep exists to avoid.
            !
            ! So a sweep runs ONE point and stops. The distribution has converged
            ! by here (DIST_DONE prints above the loop counter and the moments
            ! below it), addiction_scalar_1 is the b this process was launched at,
            ! and nothing has updated yet. The driver relaunches for the next
            ! point, which costs a solve and buys a curve that is a function of b
            ! and of nothing else.
            ! THE AGE PROFILE PRINTS ABOVE THE SWEEP'S STOP, and that is the whole
            ! reason it sits here rather than with the other moments. A sweep
            ! point writes its row and STOPS, so anything printed below that
            ! branch is never printed by a sweep at all: the curve came back as
            ! six numbers a point with no age distribution behind any of them,
            ! and the one question the curve is being measured to answer -- who
            ! uses at the b that hits the target -- could not be read off it.
            do i=1,9
                write(*,*) "model_drug_use_by_age_group=", model_drug_use_by_age_group(1,i)
            end do
            ! The RATE, not the count, and by single age: the share of the
            ! households alive at each age who use. Printed from the last age
            ! backwards is the wrong way round for reading, so it goes forwards,
            ! and the data age is model age plus twenty five.
            write(*,*) "use rate by single age, model age 1 = data age 26:"
            do i=1,life_span
                if (model_alive_by_age(i)>10.d0**(-14)) then
                    write(*,*) "USE_BY_AGE", i, i+25, model_users_by_age(i)/max(model_alive_by_age(i),10.d0**(-14))
                else
                    write(*,*) "USE_BY_AGE", i, i+25, 0.d0
                end if
            end do

            if (sweep_addiction_scalar==1) then

                call print_all_moments()

                write(*,*) "drug share, weighted by their population shares =",&
                    weighted_drug_share_now(), " target =", drug_spending_share_data

                ! THE VALUE OF LIFE AND WEALTH OVER OUTPUT, WHERE A SWEEP CAN SEE
                ! THEM. Both were computed only inside the parameter update block,
                ! which a sweep skips, so neither had appeared in a single sweep
                ! point: the log carried zero occurrences of either across twelve
                ! of them. They are aleph's moment and beta's, the two the author
                ! asked to be kept near their targets, and a sweep that cannot see
                ! them cannot say whether the pins are right. Both are ratios of
                ! aggregates the distribution pass has already built.
                write(*,*) "model_value_of_life(1)=", model_value_of_life(1),&
                    " over average labour income =",&
                    model_value_of_life(1)/max(model_average_labour_income(1),10.d0**(-12)),&
                    " target =", vsl_data
                write(*,*) "wealth_to_output_model =",&
                    model_total_net_wealth(1)/max(model_GDP_incl_imput_rent(1),10.d0**(-12)),&
                    " target =", wealth_to_output_data
                write(*,*) "labour supply over total hours =",&
                    model_labor_supply(1)/max(model_total_hours(1),10.d0**(-12)),&
                    " target =", avg_labor_supply_data

                open(unit=78,file="B_SWEEP_RAW.tsv",action='write',position='append')
                write(78,'(7(E24.15,A1))') addiction_scalar_1, char(9),&
                    model_exprimenters(1), char(9),&
                    model_total_drug_users(1), char(9),&
                    model_fraction_addicted(1), char(9),&
                    model_avg_income_drug_users(1)/&
                        max(model_average_labour_income(1),10.d0**(-12)), char(9),&
                    model_average_income_addicted(1)/&
                        max(model_average_labour_income(1),10.d0**(-12)), char(9),&
                    weighted_drug_share_now(), char(9)
                close(78)

                write(*,*) "B SWEEP POINT DONE at b=", addiction_scalar_1,&
                    " participation=", model_exprimenters(1)

                ! CONVERGE THE CALIBRATED MODEL'S OWN STATIONARY EQUILIBRIUM
                ! BEFORE THE STATE IS SAVED. The author, 9 September: *"you have
                ! to converge on the actual calibrated model's stationary
                ! equilibrium"*.
                !
                ! WHY THIS EXISTS. The state used to be written here, at one
                ! iterate of the calibration sweep, and that is not an
                ! equilibrium. Its own convergence test said so:
                ! distance_average_labor_income stood at 1.8281e-2 against a
                ! stopping rule of 1e-4, a hundred and eighty-three times its
                ! tolerance. Anything that RE-SOLVED from that state therefore
                ! moved, and two things do: the elasticity block, which found
                ! users +8.67 per cent at an UNCHANGED price, and
                ! long_run_counter_factual, which landed on a different economy
                ! with no policy change at all. Every counterfactual was
                ! measuring the distance between two code paths on top of
                ! whatever the policy did.
                !
                ! WHAT IS AND IS NOT FROZEN. This iterates the EQUILIBRIUM map
                ! only -- value function, distribution, statistics, budget -- and
                ! never re-enters the calibration update block, so no calibrated
                ! parameter moves. That is the distinction the old comment here
                ! was reaching for when it said re_do_simulation_with_fixed_
                ! parameters "does NOT freeze everything": that routine ran the
                ! calibration loop with some parameters pinned, and
                ! sd_permanent_productivity kept moving. This does not run the
                ! calibration loop at all.
                !
                ! The newborn endowment DOES move here, and should: it is
                ! newborn_endowment_scale times model_average_labour_income, set
                ! inside stationary_equilibrium_statistics, so it is an
                ! equilibrium object and belongs inside the fixed point rather
                ! than outside it. Leaving it outside is part of why one more
                ! pass moved participation at all.
                distance_frozen_moments=1

                do frozen_pass_index=1,max_frozen_passes

                    frozen_b_1=model_total_drug_users(1)
                    frozen_d_1=model_fraction_addicted(1)
                    frozen_h_1=model_fraction_homeless(1)
                    frozen_y_1=model_average_labour_income(1)

                    call solve_value_function_and_policy_functions(1)
                    call converge_to_stationary_equilibrium(1)
                    call stationary_equilibrium_statistics(1)
                    call govt_revenues_calc(1)

                    distance_frozen_moments=max(max(&
                        abs(model_total_drug_users(1)-frozen_b_1),&
                        abs(model_fraction_addicted(1)-frozen_d_1)),max(&
                        abs(model_fraction_homeless(1)-frozen_h_1),&
                        abs(model_average_labour_income(1)-frozen_y_1)))

                    write(*,*) "FROZEN PASS", frozen_pass_index,&
                        " b=", model_total_drug_users(1),&
                        " lambda_d=", model_fraction_addicted(1),&
                        " h_1=", model_fraction_homeless(1),&
                        " avg_lab_inc=", model_average_labour_income(1),&
                        " distance=", distance_frozen_moments

                    if (distance_frozen_moments<=stopping_rule_frozen_moments) then

                        write(*,*) "FROZEN CONVERGED after", frozen_pass_index,&
                            "passes, distance=", distance_frozen_moments
                        exit

                    end if

                    ! Stopped improving? Count it, and give up after three in a
                    ! row rather than grinding out the remaining passes at a
                    ! level the solver cannot go below.
                    if ((frozen_pass_index>1) .AND. &
                        (distance_frozen_moments>frozen_stall_ratio*previous_distance_frozen)) then

                        frozen_stall_count=frozen_stall_count+1

                    else

                        frozen_stall_count=0

                    end if

                    previous_distance_frozen=distance_frozen_moments

                    if (frozen_stall_count>=frozen_stall_passes) then

                        write(*,*) "FROZEN STALLED at", distance_frozen_moments,&
                            "after", frozen_pass_index, "passes -- this is the",&
                            "solver's floor, not a fixed point failure"
                        exit

                    end if

                end do

                if (distance_frozen_moments>stopping_rule_frozen_moments) then

                    write(*,*) "FROZEN NOT AT TOLERANCE after", frozen_pass_index,&
                        "passes, distance=", distance_frozen_moments,&
                        " against a rule of", stopping_rule_frozen_moments
                    write(*,*) "FROZEN read the STALLED line above: if it is there,",&
                        " this is the solver's floor and the state is as pinned",&
                        " down as this solver makes it. If it is not there, the",&
                        " loop ran out of passes and the state is NOT a fixed point."

                end if

                call print_all_moments()

                stop

            end if

            write(*,*) "model_fraction_addicted+model_exprimenters=", model_fraction_addicted(1)+model_exprimenters(1)
            write(*,*) "model_exprimenters/model_total_drug_users=", model_exprimenters(1)/max(model_total_drug_users(1),10.d0**(-14))
            write(*,*) "model_fraction_addicted_who_are_homeless,", model_fraction_addicted_who_are_homeless(1)
            write(*,*) "model_addicted_total_addiction_spending_to_total_income=", &
                model_addicted_total_addiction_spending_to_total_income(1)      
            write(*,*) "model_experimenters_total_drug_spending_to_total_income=", &
                model_experimenters_total_drug_spending_to_total_income(1)
            write(*,*) "model_drugs_used_by_users_on_average,", model_drugs_used_by_users_on_average(1)
            write(*,*) "model_treatment_take_up,", model_treatment_take_up(1)
            write(*,*) "model_drugs_consumed_by_users=", model_drugs_consumed_by_users(1)
            write(*,*) "model_drugs_used_by_experimenters_on_average,", model_drugs_used_by_experimenters_on_average(1)
            write(*,*) "model_drugs_used_by_addicts_on_average=", model_drugs_used_by_addicts_on_average(1)
            write(*,*) "model_fraction_homeless_and_addicted,", model_fraction_homeless_and_addicted(1)
            write(*,*) "model_fraction_unemployed=", model_fraction_unemployed(1)
            write(*,*) "model_fraction_of_homeless_unemployed=", model_fraction_of_homeless_unemployed(1)
!            write(*,*) "govt_spending_on_homeless=", govt_spending_on_homeless(1)
            write(*,*) "govt_spending_on_addicts=", govt_spending_on_addicts(1)
!            write(*,*) "govt_spending_on_food_stamps=", govt_spending_on_food_stamps(1)
            write(*,*) "govt_spending_on_food_stamps/model_output=", govt_spending_on_food_stamps(1)/model_output(1)
            write(*,*) "model_fraction_spent_on_addiction,", model_fraction_spent_on_addiction(1)
            write(*,*) "model_fraction_spent_on_addiction_experimenters=", model_fraction_spent_on_addiction_experimenters(1)
            write(*,*) "model_fraction_homeless_recieving_food_stamps=", model_fraction_homeless_recieving_food_stamps(1)
!            write(*,*) "model_food_stamps_share_to_homeless=", model_food_stamps_share_to_homeless(1)
!            write(*,*) "model_fraction_recieving_housing_vouchers=", &
!                model_fraction_recieving_housing_vouchers(1)/sum_of_distribution
            write(*,*) "model_fraction_homeless_by_choice=", model_fraction_homeless_by_choice(1)
            write(*,*) "model_addicted_and_homeless_by_choice=", model_addicted_and_homeless_by_choice(1)
            write(*,*) "model_avg_homeless_income=", model_avg_homeless_income(1)              
            write(*,*) "model_average_income_of_homeless_addicted=", model_average_income_of_homeless_addicted(1)
            write(*,*) "model_avg_homeless_after_tax_income,", model_avg_homeless_after_tax_income(1)
            write(*,*) "rent to income of homeless=", &
                (model_average_rent(1)*model_average_rental_unit_size(1))/max(model_avg_homeless_after_tax_income(1),10.d0**(-14))
            write(*,*) "model_avg_homeless_assets=", model_avg_homeless_assets(1)
            write(*,*) "model_average_assets_addicted_and_homeless=", model_average_assets_addicted_and_homeless(1)
            write(*,*) "relative_share_of_addiction=", relative_share_of_addiction    
!            write(*,*) "addiction_share_of_income_by_employment=", addiction_share_of_income_by_employment(1,:)
            write(*,*) "model_average_spent_on_addiction_by_addicted=", model_average_spent_on_addiction_by_addicted(1)
            write(*,*) "model_fraction_of_homeless_and_addicted_unemployed=", &
                model_fraction_of_homeless_and_addicted_unemployed(1)
            write(*,*) "model_total_net_wealth/model_GDP_incl_imput_rent=", &
                model_total_net_wealth(1)/model_GDP_incl_imput_rent(1)
            write(*,*) "model_fraction_of_homeowners_with_mortgage=", model_fraction_of_homeowners_with_mortgage(1)
            ! THE DELTA_D DIAGNOSTIC, and it is on because delta_d is pinned.
            !
            ! The child SUD ratio is a weighted average of
            ! percent_addicted_by_employment under two newborn distributions,
            ! one shifted down by the penalty and one not. It can therefore only
            ! move as far as THAT PROFILE IS STEEP: if the disorder rate is flat
            ! across productivity, no shift of the distribution changes the
            ! average and delta_d runs to its bound producing a ratio near one,
            ! which is what it does. Printing the profile beside the two
            ! distributions and the ratio they imply says which it is.
            write(*,*) "=== delta_d diagnostic ==="
            write(*,*) "percent_addicted_by_employment=", percent_addicted_by_employment(1,:)
            write(*,*) "mass with the disorder by node=", mass_by_employment(1,:)
            write(*,*) "population by node            =", total_mass_by_employment(1,:)
            ! THE FLOW, beside the stock. The stock above can rise with
            ! productivity because onset does, or because the disorder lasts
            ! longer up there, or because productivity drifts down after onset.
            ! Only the flow says which, and only the budget share says whether
            ! any force in the model tilts use against income.
            write(*,*) "onset hazard by node (flow)  =", onset_hazard_by_employment(1,:)
            write(*,*) "drug quantity by node        =", drug_quantity_by_employment(1,:)
            write(*,*) "consumption by node          =", clean_consumption_by_employment(1,:)
            write(*,*) "DRUG BUDGET SHARE by node    =", drug_quantity_by_employment(1,:)*&
                price_of_addictive_good/max(clean_consumption_by_employment(1,:),10.d0**(-12))
            write(*,*) "newborn prob, clean parent, median node =", newborn_employment_probability(:,(employment_base_size+1)/2,0,1)
            write(*,*) "newborn prob, disordered, median node   =", newborn_employment_probability(:,(employment_base_size+1)/2,1,1)
            write(*,*) "employment_grid               =", employment_grid(1,:)
            write(*,*) "penalty_child_addicted=", penalty_child_addicted
            child_sud_num_1=0
            child_sud_den_1=0
            do child_node_index_1=1,employment_grid_size
                child_sud_num_1=child_sud_num_1+&
                    sum(newborn_parent_share(:,1,1)*newborn_employment_probability(child_node_index_1,:,1,1))/max(sum(newborn_parent_share(:,1,1)),10.d0**(-14))*&
                    percent_addicted_by_employment(1,child_node_index_1)
                child_sud_den_1=child_sud_den_1+&
                    sum(newborn_parent_share(:,0,1)*newborn_employment_probability(child_node_index_1,:,0,1))/max(sum(newborn_parent_share(:,0,1)),10.d0**(-14))*&
                    percent_addicted_by_employment(1,child_node_index_1)
            end do
            write(*,*) "child SUD ratio implied=", child_sud_num_1/max(child_sud_den_1,10.d0**(-12)),&
                " against target", child_sud_ratio_data
            write(*,*) "=== end delta_d diagnostic ==="
!            write(*,*) "model_addiction_by_employment=", model_addiction_by_employment(:)
                        
            do i=1,include_addiction+1
                write(*,*) "welfare_by_addiction,", welfare_by_addiction(1,i)
            end do
            do i=1,include_addiction+1
                write(*,*) "welfare_by_addiction_youngest,", welfare_by_addiction_youngest(1,i)
            end do
            
            write(*,*) "median_income=", median_income(1)
            write(*,*) "distance_median_income=", distance_median_income
!            write(*,*) "percentiles_homeless_income=", percentiles_homeless_income(1,:)
            write(*,*) "percentiles_homeless_income/median_income=", &
                percentiles_homeless_income(1,:)/median_income(1)
            write(*,*) "model_fraction_choose_zero_work=", model_fraction_choose_zero_work(1)
            write(*,*) "model_fraction_choose_little_work=", model_fraction_choose_little_work(1)
            write(*,*) "model_fraction_choose_addiction_when_unemployed=", model_fraction_choose_addiction_when_unemployed(1)
            write(*,*) "model_choose_addiction_when_income_is_low=", model_choose_addiction_when_income_is_low(1)
            write(*,*) "model_fraction_choose_addiction_when_homeless=", model_fraction_choose_addiction_when_homeless(1)
            write(*,*) "model_choose_addiction_when_retired=", model_choose_addiction_when_retired(1)
            write(*,*) "model_fraction_choose_addiction,", model_fraction_choose_addiction(1)
!            write(*,*) "ss_decrease_addicted=", ss_decrease_addicted
!            write(*,*) "unconditional_unemployment_probability(:)=", unconditional_unemployment_probability(:)
!            write(*,*) "model_value_of_life=", model_value_of_life(1)
            write(*,*) "model_value_of_life/model_average_labour_income=", model_value_of_life(1)/model_average_labour_income(1)
            write(*,*) "model_fraction_with_negative_value_of_life=", model_fraction_with_negative_value_of_life(1)
!            write(*,*) "model_fraction_homeless_with_negative_value_of_life=",&
!                model_fraction_homeless_with_negative_value_of_life(1)
!            write(*,*) "model_fraction_addicted_with_negative_value_of_life=", &
!                model_fraction_addicted_with_negative_value_of_life(1)
            write(*,*) "model_largest_negative_value_of_life", model_largest_negative_value_of_life(1)
            write(*,*) "model_eligibles_getting_voucher=", model_eligibles_getting_voucher(1)
            write(*,*) "model_eligibles_getting_voucher_relative_to_pop,", &
                model_eligibles_getting_voucher_relative_to_pop(1)
            write(*,*) "model_addicts_getting_voucher=", model_addicts_getting_voucher(1)
            write(*,*) "model_experimenters_getting_voucher=", model_experimenters_getting_voucher(1)
            write(*,*) "model_drug_users_getting_voucher=", model_drug_users_getting_voucher(1)
            write(*,*) "model_avg_income_experimenters=", model_avg_income_experimenters(1)
            write(*,*) "model_avg_assets_experimenters=", model_avg_assets_experimenters(1)
            write(*,*) "model_age_by_addiction=", model_age_by_addiction(1,:)
                
!            write(*,*) "model_average_assets_homeless_by_addiction(:)=", model_average_assets_homeless_by_addiction(1,:)
!            write(*,*) "model_average_income_homeless_by_addiction(:)=", model_average_income_homeless_by_addiction(1,:)
!            write(*,*) "model_average_income_addicted=", model_average_income_addicted(1)
!            write(*,*) "model_average_assets_addicted=", model_average_assets_addicted(1)
!            write(*,*) "model_age_by_addiction=", model_age_by_addiction(1,:)
!            write(*,*) "welfare_by_homelessness=", welfare_by_homelessness(1,:)
            
!            write(*,*) "welfare_by_age_and_addiction=", welfare_by_age_and_addiction(1,:,0)
!            write(*,*) "welfare_by_age_and_addiction=", welfare_by_age_and_addiction(1,:,include_addiction)
            
            write(*,*) "sum_of_distribution=", sum_of_distribution
            write(*,*) "probability_of_voucher=", probability_of_voucher
            write(*,*) "price_of_addictive_good=", price_of_addictive_good
            write(*,*) "total_rental_demand_segmented=", total_rental_demand_segmented(1,:)
            write(*,*) "model_total_net_wealth/model_output=", model_total_net_wealth(1)/model_output(1)
            write(*,*) "model_net_wealth_owners/model_net_wealth_renters,", &
                model_net_wealth_owners(1)/model_net_wealth_renters(1)
            write(*,*) "model_average_ss_benefits/model_average_labour_income=", &
                model_average_ss_benefits(1)/model_average_labour_income(1)
            write(*,*) "model_homeownership_rate=", model_homeownership_rate(1)
            write(*,*) "model_homeless_2_years_or_more=", model_homeless_2_years_or_more(1)
            write(*,*) "model_homelessness_old=", model_homelessness_old(1)
            write(*,*) "model_profile_of_homeless_old=", model_profile_of_homeless_old(:)
            write(*,*) "increase_in_newborns_bequests=", increase_in_newborns_bequests
            do i=1,5
                write(*,*) "homelessness_by_age_group=", homelessness_by_age_group(1,i)
            end do
            ! SUD BY AGE GROUP, both ways. The RATE is the share of that band
            ! carrying the disorder; the SHARE is that band's part of everyone
            ! who carries it and sums to one, the way the homelessness profile
            ! above does.
            do i=1,5
                write(*,*) "sud_by_age_group band", i, " rate=",&
                    sud_by_age_group(1,i)/max(sud_denom_by_age_group(1,i),10.d0**(-14)),&
                    " share=", sud_by_age_group(1,i)/&
                    max(sum(sud_by_age_group(1,:)),10.d0**(-14)),&
                    " mass=", sud_denom_by_age_group(1,i)
            end do
            write(*,*) "model_fraction_homeless=", model_fraction_homeless(1)
            write(*,*) "model_fraction_addicted=", model_fraction_addicted(1)
            write(*,*) "model_exprimenters=", model_exprimenters(1)
            write(*,*) "model_fraction_addicted+model_exprimenters=", model_fraction_addicted(1)+model_exprimenters(1)
            write(*,*) "model_exprimenters/model_total_drug_users=", model_exprimenters(1)/max(model_total_drug_users(1),10.d0**(-14))
            write(*,*) "model_fraction_addicted_who_are_homeless,", model_fraction_addicted_who_are_homeless(1)
            write(*,*) "model_youngest_net_wealth_share=", model_youngest_net_wealth_share(1)
            write(*,*) "inheritance_amount=", inheritance_amount(1)
            write(*,*) "inheritance_amount=", inheritance_amount(2)
!            write(*,*) "inheritance_amount(1)*total_population_group_1(1))=", &
!                inheritance_amount(1)*total_population_group_1(1)
!            write(*,*) "inheritance_amount(2)*total_population_group_1(2))=", &
!                inheritance_amount(2)*total_population_group_1(2)
                
!            write(*,*) "inheritance_amount(1)*total_population_group_1(1))/&
!                (inheritance_amount(1)*total_population_group_1(1)+inheritance_amount(2)*total_population_group_1(2)))=", &
!                (inheritance_amount(1)*total_population_group_1(1))/&
!                (inheritance_amount(1)*total_population_group_1(1)+inheritance_amount(2)*total_population_group_1(2))
!            write(*,*) "model_bequests-value_of_initial_assets=", model_bequests(1)-value_of_initial_assets
            write(*,*) "model_homeownership_young=", model_homeownership_by_age_group(1,1)
            write(*,*) "model_labor_supply/model_total_hours=", model_labor_supply(1)/model_total_hours(1)
            write(*,*) "mass_of_renters_at_housing_spending=", mass_of_renters_at_housing_spending(1,2)
            write(*,*) "model_fraction_homeless_and_addicted=", model_fraction_homeless_and_addicted(1)
            write(*,*) "model_fraction_unemployed=", model_fraction_unemployed(1)
            write(*,*) "model_addicted_total_addiction_spending_to_total_income=", &
                model_addicted_total_addiction_spending_to_total_income(1)      
            write(*,*) "model_experimenters_total_drug_spending_to_total_income=", &
                model_experimenters_total_drug_spending_to_total_income(1)
            write(*,*) "govt_spending_on_food_stamps/model_output=", govt_spending_on_food_stamps(1)/model_output(1)
            write(*,*) "model_value_of_life/model_average_labour_income=", model_value_of_life(1)/model_average_labour_income(1)
            write(*,*) "model_total_net_wealth/model_output=", model_total_net_wealth(1)/model_output(1)
            write(*,*) "model_eligibles_getting_voucher=", model_eligibles_getting_voucher(1)
            write(*,*) "model_ss_benefits=", model_ss_benefits
            write(*,*) "model_average_labour_income_tax=", model_average_labour_income_tax(1)
            write(*,*) "probability_of_voucher=", probability_of_voucher            
            write(*,*) "model_fraction_addicted_and_unemployed=", model_fraction_addicted_and_unemployed(1)
            
            do i=1,10
!                write(*,*) income_to_avg_income_wide_pdf_1(1,i)
            end do
        
            write(*,*) "model_bequests=", model_bequests(1)
            write(*,*) "model_total_inheritance=", model_total_inheritance(1)
            write(*,*) "model_total_income-model_total_expenditure=", &
                model_output(1)+model_total_investment_income(1)+include_bequests*value_of_initial_assets-&
                (aggregate_consumption(1)+aggregate_spending_on_addiction(1)+&
                aggregate_housing_consumption(1)+aggregate_mortgage_consumption(1)+&
                aggregate_housing_transaction_costs(1)+aggregate_origination_costs(1)+&
                aggregate_prepayment_costs(1)+aggregate_moving_costs(1)+&
                govt_revenues_to_use_in_tests(1)+&
                govt_ss_wasted(1)+(govt_spending_on_homeless(1)+govt_spending_on_addicts(1))+&
                (1-include_property_taxes_in_govt_constraint)*govt_revenues_from_property_tax(1)+&
                aggregate_rent_spending(1)-housing_price(1)*&
                sum(total_rental_demand(1-solve_transition_dynamics,:))*&
                property_tax(1-solve_transition_dynamics))
            write(*,*) "model_homeowners_experimenting=", model_homeowners_experimenting(1)
            write(*,*) "profile_of_chronic_homeless=", profile_of_chronic_homeless(1,:)  
            write(*,*) "model_avg_homeless_income/model_average_labour_income.", &
                model_avg_homeless_income(1)/model_average_labour_income(1)
            write(*,*) "model_avg_income_experimenters/model_average_labour_income.", &
                model_avg_income_experimenters(1)/model_average_labour_income(1)
            write(*,*) "model_average_income_addicted/model_average_labour_income.", &
                model_average_income_addicted(1)/model_average_labour_income(1)
            write(*,*) "model_avg_income_drug_users/model_average_labour_income,", &
                model_avg_income_drug_users(1)/model_average_labour_income(1)
            write(*,*) "model_avg_homeless_assets/model_average_net_wealth.", &
                model_avg_homeless_assets(1)/model_average_net_wealth(1)
            write(*,*) "model_avg_assets_experimenters/model_average_net_wealth.", &
                model_avg_assets_experimenters(1)/model_average_net_wealth(1)
            write(*,*) "model_average_assets_addicted/model_average_net_wealth.", &
                model_average_assets_addicted(1)/model_average_net_wealth(1)
            write(*,*) "model_average_assets_drug_users/model_average_net_wealth,", &
                model_average_assets_drug_users(1)/model_average_net_wealth(1)
            write(*,*) "model_drug_threshold=", model_drug_threshold(1)
            write(*,*) "model_average_drug_spending_experimenters=", model_average_drug_spending_experimenters(1)
            write(*,*) "model_drug_threshold/model_average_drug_spending_experimenters=", &
                model_drug_threshold(1)/max(model_average_drug_spending_experimenters(1),10.d0**(-14))
            write(*,*) "model_fraction_light_users=", model_fraction_light_users(1)
        
!            write(*,*) "model_bequests/model_net_wealth=", model_bequests(1)/model_total_net_wealth(1)
!            write(*,*) "model_bequests=", model_bequests(1) 

!            call stationary_equilibrium_wealth_distribution(1)

!            call stationary_equilibrium_income_bottom_distribution(1)

!            call compute_homelessness_duration(1)
            
!            do i=0,2
!                write(*,*) "homelessness_duration_everyone(1,",i,")=", &
!                    homelessness_duration_everyone(1,i)
!            end do
            
            write(*,*) "file_number=", file_number

            ! THE CHECKPOINT, AND IT USED TO BE MISSING FROM EXACTLY THE LOOP
            ! THAT NEEDED IT.
            !
            ! write_calibration_state and read_calibration_state were written as
            ! a pair, but only the transition simulation ever called the write.
            ! The calibration itself, which is the run that takes days and the
            ! only run anyone ever kills, wrote nothing, so read_calibration_state
            ! sat at the top of this subroutine reading a file that this
            ! subroutine never produced. Both halves are called here now, so a
            ! kill costs one loop instead of all of them.
            call write_calibration_state()
            call write_calibration_distribution()

            ! THE WHOLE MOMENT TABLE, EVERY LOOP.
            !
            ! The author, reading a gaps table with eight of seventeen rows
            ! blank: "why are so many untraced?". Because each bracket prints
            ! whatever its author needed at the time -- most print their own
            ! PARAMETER and not their model MOMENT -- while every moment is
            ! computed in print_all_moments(), which ran only when this do-while
            ! EXITED. On a long run that is the whole run: the 02:46 calibration
            ! reached loop 22 with the block never once printed.
            !
            ! One call here beats adding eleven writes scattered through the
            ! update block, and it cannot drift out of step with the moments it
            ! reports, which is how addiction_onset_base came to be traced under
            ! the stale name onset_at_the_mean_quantity.
            !
            ! IT IS WRITES ONLY. print_all_moments reads aggregates the
            ! distribution pass has already built and computes nothing, so it
            ! costs output and not time.
            ! THE MOMENT TABLE EVERY LOOP, WITHOUT THE COUNTERFACTUAL. See
            ! omega_cf_allowed: this call would otherwise run a second full
            ! solve per loop.
            omega_cf_allowed=0
            call print_all_moments()
            omega_cf_allowed=1

            ! HOW FAR THE ECONOMY MOVED THIS BLOCK, on the four ENGINE.md names.
            ! Relative, because b near 0.08 and welfare near 790 cannot share an
            ! absolute rule. The first block has nothing to compare against and
            ! is reported as 1 so that it can never satisfy the test.
            if (prev_block_b>=0.d0) then

                block_move=max(max(&
                    abs(model_total_drug_users(1)-prev_block_b)/&
                        max(abs(prev_block_b),10.d0**(-12)),&
                    abs(model_fraction_addicted(1)-prev_block_d)/&
                        max(abs(prev_block_d),10.d0**(-12))),max(&
                    abs(model_fraction_homeless(1)-prev_block_h)/&
                        max(abs(prev_block_h),10.d0**(-12)),&
                    abs(model_average_labour_income(1)-prev_block_y)/&
                        max(abs(prev_block_y),10.d0**(-12))))

            else

                block_move=1.d0

            end if

            prev_block_b=model_total_drug_users(1)
            prev_block_d=model_fraction_addicted(1)
            prev_block_h=model_fraction_homeless(1)
            prev_block_y=model_average_labour_income(1)

            write(*,*) "BLOCK MOVE", block_move, " against a rule of",&
                frozen_stop_tolerance, " -- b", model_total_drug_users(1),&
                " lambda_d", model_fraction_addicted(1),&
                " h_1", model_fraction_homeless(1),&
                " y", model_average_labour_income(1)

            if ((frozen_stop_tolerance>0.d0) .AND. &
                (block_move<frozen_stop_tolerance)) then

                write(*,*) "ECONOMY IS STILL: the largest relative move across",&
                    " b, lambda_d, h_1 and average labour income is", block_move,&
                    " which is inside", frozen_stop_tolerance, ". Leaving the",&
                    " calibration loop so the state that gets saved is a fixed",&
                    " point rather than an iterate."

            end if

        end do

        simulation_ended=0
        
        ! THE SECOND CALL TO calculate_homeownership_by_characteristics WAS
        ! HERE AND HAS BEEN REMOVED. The two-pass loop already calls it, once
        ! per type, and its accumulators are guarded so that the second pass
        ! adds to the first. Calling it AGAIN out here, where
        ! accumulating_beta_types is back to zero, made every one of those
        ! guards fire: it wiped the pooled totals and refilled them from
        ! distribution_stationary, which by this point holds only the LAST TYPE
        ! SOLVED. Everything by age -- the homelessness profile, the ownership
        ! rate, renter wealth and income -- was therefore the impatient half's,
        ! reported as the whole population's.
        !
        ! Harmless at one type, which is why it survived. It is exactly the
        ! shape of the other two pooling bugs: a routine written for one pass,
        ! called in a place where the pass count is no longer what it assumes.
        write(*,*) "calculating inequality"
        
        if (use_old_results>=0) then
        
            call stationary_equilibrium_wealth_distribution(1)
            call calculate_gini_coefficient(1)
!            call stationary_equilibrium_income_bottom_distribution(1)
            
        end if
                    
        call save_vars_and_functions(1)

        ! THE CURVE IS BUILT HERE AND NOWHERE ELSE, and AFTER
        ! save_vars_and_functions, because it reads the benchmark policy
        ! functions that call has just written. It evaluates saved policies and
        ! changes nothing the equilibrium saw. calculate_welfare_gains, which
        ! the transition calls, reads the file this writes.
        if (use_old_results==0) then
            call save_welfare_curve(1)
        end if

        write(*,*) "simulation ended"
        write(*,*) "rental_management_costs=", rental_management_costs
        write(*,*) "model_drug_use_by_income_quintile", model_drug_use_by_income_quintile(1,:)
                                        
    end subroutine
    
    subroutine long_run_counter_factual()
    
        use Global_Vars
                    
        implicit none
        
        real(8) :: previous_distance
        integer :: end_loop
        character*1 :: string_used

        ! EVERYTHING calibrating_model DOES BEFORE IT SOLVES, AND THIS PATH DID
        ! NOT. The counterfactual was built for the old workflow, where a
        ! parameter reached the model by being edited into its declaration. It
        ! has never been run with a vector handed in, and it shows: of the
        ! initialisers calibrating_model calls before its first solve, this
        ! subroutine called none of the ones that depend on the vector.
        !
        ! apply_param_handover has exactly ONE caller in the file, inside
        ! calibrating_model, so a counterfactual took all eighty parameters
        ! from the declarations and solved happily.
        !
        ! set_renter_floor is the one that crashed. renter_floor_by_age is
        ! declared =0 and is the LOWER BOUND of the financial loop at 19360, so
        ! with it unset the loop starts at index 0 and reads financial_grid(0),
        ! one before the array. At -O3 that returns whatever precedes the array
        ! in memory: the distribution grew by a factor of 1.4 a sweep to 5.97e31
        ! over 200 sweeps and then segfaulted in addiction_transition. A bounds
        ! checked build named it in one run, which is why that build is standing
        ! practice for anything that opens an array index.
        !
        ! set_files_names is called by the main program BEFORE this subroutine
        ! and keys file_number off two switches the handover supplies, so
        ! counter_VTE_TF would have been written under the benchmark's name.
        !
        ! ORDER MIRRORS calibrating_model at 38383-38424: state, handover, the
        ! tie, the house size, the transfer, the floor. The grids are built
        ! below, after these, exactly as they are there.
        call apply_param_handover()
        call set_files_names()
        call apply_gamma_tie()
        call set_smallest_house_size()
        call set_newborn_age_transfer(transition_length)
        call set_renter_floor(transition_length)

        write(*,*) "CF INIT: file_number=", trim(file_number)
        write(*,*) "CF INIT: old_results=", trim(old_results)
        write(*,*) "CF INIT: renter_floor_by_age(1:5)=", renter_floor_by_age(1:5)
        write(*,*) "CF INIT: smallest_house_size=", smallest_house_size

        ! UNIVERSALITY IS A PROPERTY OF THE VOUCHER RATE, NOT OF THE DRUG TEST.
        !
        ! This used to read `if (voucher_conditional_on_clean==1) then
        ! probability_of_voucher=1`, which tied two independent things together
        ! and made one experiment unrunnable: asking for testing FORCED the
        ! programme universal, so "Treatment First with rationed vouchers" could
        ! not be expressed at all. The author settled it on 8 September.
        !
        ! AND probability_of_voucher IS A THREE-VECTOR, not a scalar: one offer
        ! rate per category -- housed, homeless, homeless and addicted --
        ! built as p, p*increased_prob_if_homeless, p*increased_prob_if_addicted.
        ! At the benchmark's p that is 0.0433 / 0.0087 / 0.0433, so the homeless
        ! without a disorder are offered a voucher at a FIFTH the rate of
        ! everyone else. Setting p to one therefore gives 1.0 / 0.2 / 1.0, which
        ! is not a universal programme; this line is what flattens all three.
        !
        ! Keyed on the old switch it flattened them only for runs that also
        ! asked for testing, so universal HF ran at (1.0, 0.2, 1.0) against
        ! universal TF at (1, 1, 1) and the two arms were not comparable: one
        ! gave the non-disordered homeless five times the access of the other.
        ! Keyed on the rate, "universal" means universal in both.
        !
        ! The testing cost underneath already assumed rationing -- it grosses up
        ! by dividing by probability_of_voucher_benchmark_used_1, a division
        ! that does nothing at a rate of one -- so the formula and the forcing
        ! line contradicted each other.
        if (probability_of_voucher_benchmark_used==1) then

            probability_of_voucher=1

        end if

        if (use_revenues_to_increase_voucher_probability==1) then
            
            if (increased_prob_of_voucher_if_homeless_and_addicted==0) then
            
                increased_prob_of_voucher_if_homeless_1=1 !5.81
                                                
                tax_system_type=3
                                
            else
                            
                tax_system_type=1
                
            end if
            
        elseif (double_voucher_program==1) then
        
            probability_of_voucher=probability_of_voucher_benchmark*2
            
            tax_system_type=1
            
        else
        
            tax_system_type=1
            
        end if
                
        simulation_ended=0
                                    
        call cpu_time(simulation_start_time)
            
        property_tax=property_tax
        
        increase_in_labour_income_tax=0
        
        if (use_old_results==1) then

            call upload_vars(transition_length)
                        
        end if

        if (use_old_results==0) then
        
            model_average_owner_occupied_unit_size(transition_length)=calibrated_stationary_housing_price*0.315

        end if
                
        loop_count=0

        if (use_old_results==0) then
        
            c_1=c_1_calibrated
            c_min=c_min_calibrated
            
            housing_price(transition_length)=calibrated_stationary_housing_price
            
            rent(transition_length,:)=rent_calibrated(:) 
                            
            total_rental_supply(transition_length,:)=total_rental_supply_calibrated(:)
            total_rental_demand(transition_length,:)=total_rental_supply_calibrated(:)
         
            risk_free_rate(transition_length)=calibrated_risk_free_rate
            mortgage_interest_rate(transition_length)=risk_free_rate(transition_length)+mortgage_interest_gap
                        
            model_average_income(transition_length)=average_labor_income_calibrated
            model_average_income_plus_assets(transition_length)=average_labor_income_calibrated
            model_average_income_plus_all_assets(transition_length)=average_labor_income_calibrated
            model_average_labour_income(transition_length)=average_labor_income_calibrated
            model_average_labour_income_by_employment(transition_length,:)=average_labor_income_calibrated
            median_income(transition_length)=median_income_calibrated
            model_average_financial(1)=average_financial_calibrated
            model_average_net_wealth(1)=average_net_wealth_calibrated

        end if
        
        call function_of_utility_advantage_from_homeowning(transition_length)
        
        call allocate_matrix()
                        
        call initialize_variables_and_grids()
        call GKKOC_intergenerational_employment_process(transition_length)
        call initialize_financial_grid(transition_length)

        ! AGAIN AFTER THE GRIDS, exactly as calibrating_model does at 38459-38461:
        ! both of these are functions of the financial grid that has just been
        ! rebuilt, so the values set above are stale by this line.
        call set_newborn_age_transfer(transition_length)
        call set_renter_floor(transition_length)

        ! SOCIAL SECURITY IS THE BENCHMARK'S, PER PRODUCTIVITY, AND IS NOT
        ! RECOMPUTED. The author, 8 September: *"the amount given per
        ! productivity should be held fixed across simulations"*.
        !
        ! upload_vars has just read model_ss_benefits -- one benefit level per
        ! employment node -- from the benchmark's file, and this call used to
        ! overwrite the whole vector from the COUNTERFACTUAL'S own distribution
        ! and its own lifetime earnings. So a policy that changed who works and
        ! how much also changed what retirees receive, and the welfare
        ! comparison carried a pension system that had moved underneath it.
        !
        ! use_old_results is is_counterfactual, so the benchmark still computes
        ! its own schedule and every counterfactual inherits it.
        if (use_old_results==0) then

            call set_SS_benefits(transition_length)

        end if
        
        call initialize_feasible_distribution(transition_length)

        if (use_old_results==0) then
        
            total_housing_demand(transition_length)=calibrated_housing_stock

        end if
        
        call function_of_utility_advantage_from_homeowning(transition_length)
                               
        distance_rental_market(transition_length)=1
        distance_value_function=1
        distance_housing_market(transition_length)=1
          
        do i=1,2
          
            value_function_guess(i)%vector_youngest_real(:,:,:,:,:)=0
            value_function(i)%vector_transition_real(transition_length,:,:,:,:,:,:)=0
            
        end do
                                                           
        ! THE NEWBORN'S INHERITANCE IS THE BENCHMARK'S, AND THE GOVERNMENT TAKES
        ! THE DIFFERENCE. The author, 9 September: *"you keep the newborns
        ! bequests at their benchmark level and the government gets the
        ! difference in the counterfactual"*.
        !
        ! upload_vars has read inheritance_amount from the benchmark's own file
        ! at 33497, a few hundred lines above, and on the current benchmark that
        ! is ZERO at all sixty ages. This block used to overwrite it with a
        ! hard-coded constant, one per arm, of about 0.0133 -- and nothing could
        ! ever revise it, because the update at 42760 is gated on
        ! residual_bequests_to_government==0 and that parameter is 1, so
        ! distance_inheritance_amount is zero on every loop.
        !
        ! inheritance_amount is NOT a warm start for something the loop solves.
        ! It is a transfer, paid as
        !     bequest = employment_grid(age,e)*inheritance_amount(age) + ...
        ! to every household at every age in every period. At 0.0133 against an
        ! average labour income of 0.637 that is 2.1 per cent of average income
        ! a year for sixty years, given to everybody in every counterfactual and
        ! to nobody in the benchmark. It showed up as bequests 0.4923 -> 0.8492
        ! under rationed Treatment First, and since include_bequests=1 with
        ! residual_bequests_to_government=1 puts the residual bequest into
        ! government revenue at full weight, the budget rule returned the
        ! windfall as a 7.7 point cut in the average labour income tax. Two
        ! calibration targets moved in the counterfactual as a result: beta
        ! 3.0018 -> 4.265 and tau_l 0.2241 -> 0.1475.
        !
        ! The null test caught it with NO policy change at all: the
        ! counterfactual path at the benchmark's own switches reached net revenue
        ! 0.9174 against the benchmark's 0.5452 by loop eight, with the tax
        ! already walked to 0.0213 off the benchmark's zero.
        !
        ! The residual-bequests-to-government machinery is left exactly as it
        ! was; it is the half of the author's rule that was already right. Only
        ! the overwrite is gone. The rent, housing price and tax warm starts stay
        ! -- rent and the housing price are pegged inside the loop anyway, and
        ! the tax IS something the loop solves, so a starting guess for it is
        ! legitimate.
        ! THE RENT AND THE HOUSING PRICE START AT THE BENCHMARK'S, NOT AT A
        ! HARD-CODED MULTIPLE OF IT. This block used to open each arm at
        ! rent_calibrated*1.0051 and calibrated_stationary_housing_price*1.002,
        ! stale constants of the same family as the inheritance overwrite that
        ! sat here: written down from a finished run of an older economy and
        ! never revised. They were masked, because fix_rent and
        ! peg_prices_in_counterfactual overwrite both inside the loop -- but a
        ! constant that is only harmless because something downstream happens to
        ! overwrite it is one edit away from being harmful, so it is gone. What
        ! upload_vars imported from the benchmark now stands.
        !
        ! increase_in_labour_income_tax keeps its warm start. It is the one
        ! quantity here the loop genuinely solves for, so a starting guess is a
        ! guess and not an assumption.
        if (partial_equilibrium==0) then
                                    
            if (increased_prob_of_voucher_if_homeless_and_addicted==0) then
                
                if (probability_of_voucher_benchmark_used==1) then
                
                    increase_in_labour_income_tax=-7.3590906975202195E-004
                    
                else
                
                    increase_in_labour_income_tax=1.4488423360367944E-003
                
                end if
                    
            else
                                                    
                increase_in_labour_income_tax=-2.59935794204448567E-003
                        
            end if
                                     
        else
        
            if (compare_to_original_benchmark==0) then
        
                rent(transition_length,:)=1.1193194446996844
                housing_price(transition_length)=12.961085243325376
                increase_in_labour_income_tax=-3.6609417107389751E-003
                
            else
            
                lump_sum_transfer(transition_length)=0                
                rent(transition_length,:)=rent_calibrated(:)*1
                housing_price(transition_length)=calibrated_stationary_housing_price*1
                
            end if
                    
        end if
                      
!        if (adjust_labor_supply==0) then
!        
!            do i=1,2
!        
!                write(string_used,'(i1)') i
!        
!                open(unit=2,file="policy_function_labor_supply"//trim(string_used)//trim(old_results)//".dat",action='read')
!                    read(2,'(F22.20)') policy_function_labor_supply(i)%vector_transition_real(:,:,:,:,:,:,:)
!                close(2)
!                
!            end do
!        
!        end if
        
        write(*,*) "calibrated_stationary_housing_price=", calibrated_stationary_housing_price
        write(*,*) "rent_calibrated=", rent_calibrated
        write(*,*) "total_rental_supply_calibrated=", total_rental_supply_calibrated
        write(*,*) "calibrated_housing_stock=", calibrated_housing_stock
        write(*,*) "c_1_calibrated=", c_1_calibrated
        write(*,*) "c_min_calibrated=", c_min_calibrated
        write(*,*) "cutoff_housing_investment_calibrated=",cutoff_housing_investment_calibrated
        write(*,*) "calibrated_risk_free_rate=", calibrated_risk_free_rate
        write(*,*) "discount_factor=", discount_factor
        write(*,*) "discount_factor_on_child=", discount_factor_on_child
        write(*,*) "minimum_inheritance=", minimum_inheritance
        write(*,*) "size_homelessness=", size_homelessness
        write(*,*) "re_do_simulation_with_fixed_parameters=", re_do_simulation_with_fixed_parameters
        write(*,*) "property_tax(transition_length)=", property_tax(transition_length)
        write(*,*) "rental_management_costs=", rental_management_costs
        write(*,*) "mortgage_interest_rate=", mortgage_interest_rate(transition_length)
        write(*,*) "infinite_elasticity_of_rental_supply=", infinite_elasticity_of_rental_supply
        write(*,*) "lump_sum_transfer=", lump_sum_transfer(1)
        write(*,*) "rent/rent_calibrated=", rent(transition_length,:)/rent_calibrated(:)
        write(*,*) "check_tax_incidence=", check_tax_incidence
        write(*,*) "mortgage_deductibility=", mortgage_deductibility
        write(*,*) "minimum_downpayment=", minimum_downpayment
        write(*,*) "stopping_rule_govt_budget=", stopping_rule_govt_budget
        write(*,*) "stopping_rule_housing_market=", stopping_rule_housing_market
        write(*,*) "stopping_rule_rental_market=", stopping_rule_rental_market
        write(*,*) "increase_in_labour_income_tax=", increase_in_labour_income_tax
        write(*,*) "housing_price/calibrated_stationary_housing_price=", &
            housing_price(transition_length)/calibrated_stationary_housing_price
        write(*,*) "average_owner_occupied_house_size_calibrated=", average_owner_occupied_house_size_calibrated
        write(*,*) "model_ss_benefits=", model_ss_benefits
        write(*,*) "relative_share_of_housing=", relative_share_of_housing
        write(*,*) "relative_share_of_leisure=", relative_share_of_leisure
        write(*,*) "rental_management_costs_calibrated=", rental_management_costs_calibrated
        write(*,*) "convexity_of_rental_company=", convexity_of_rental_company
        write(*,*) "minimum_downpayment_calibrated=", minimum_downpayment_calibrated
        write(*,*) "c_1=", c_1
        write(*,*) "labor_income_tax_rate=", labor_income_tax_rate
        write(*,*) "average_labor_income_calibrated=", average_labor_income_calibrated
        write(*,*) "median_income_calibrated=", median_income_calibrated
        write(*,*) "calibrated_stationary_housing_price=", calibrated_stationary_housing_price
        write(*,*) "rent=", rent(1,:)
        write(*,*) "counter_factual"
        write(*,*) "rent_calibrated(1)=", rent_calibrated(:)
        
        write(*,*) "new_supply/old_supply=", &
            (max(((rent_calibrated*(1.01)-housing_price(1)+(1/(1+risk_free_rate(1)))*&
            (housing_price(1)*(1-housing_depreciation_rate-property_tax(1))))/&
            (rental_management_costs_calibrated*convexity_of_rental_company)),0.d0)**&
            (1/(convexity_of_rental_company-1)))/(max(((rent_calibrated-housing_price(1)+(1/(1+risk_free_rate(1)))*&
            (housing_price(1)*(1-housing_depreciation_rate-property_tax(1))))/&
            (rental_management_costs_calibrated*convexity_of_rental_company)),0.d0)**(1/(convexity_of_rental_company-1)))

        write(*,*) "check.....=", (max(((rent(1,:)-housing_price(transition_length)+(1/(1+risk_free_rate(1)))*&
            (housing_price(transition_length)*(1-housing_depreciation_rate-property_tax(1)-property_tax_on_rental_housing)))/&
            (rental_management_costs_calibrated(:)*convexity_of_rental_company(:))),0.d0)**&
            (1/(convexity_of_rental_company(:)-1)))
            
        write(*,*) "rent_calibrated(1)=", rent_calibrated
        write(*,*) "rental_management_costs_calibrated=", rental_management_costs_calibrated
        write(*,*) "convexity_of_rental_company=", convexity_of_rental_company
        write(*,*) "housing_price(1)=", housing_price(1)
        write(*,*) "risk_free_rate(1)=", risk_free_rate(1)
        write(*,*) "property_tax(1)=", property_tax(1)
        write(*,*) "housing_depreciation_rate=", housing_depreciation_rate
                
        write(*,*) "max_debt_to_income_ratio=", max_debt_to_income_ratio
        write(*,*) "max_debt_to_income_ratio_below_80=", max_debt_to_income_ratio_below_80        
        write(*,*) "do_internal_computations=", do_internal_computations
        write(*,*) "convexity_of_rental_company=", convexity_of_rental_company
        write(*,*) "property_tax_on_rental_housing=", property_tax_on_rental_housing
        write(*,*) "standard_deduction=", standard_deduction
        write(*,*) "personal_exemption=", personal_exemption
        write(*,*) "housing_price=", housing_price(1)
        write(*,*) "rent=", rent(1,:)
        write(*,*) "empirical_housing_supplpy_elasticity=", empirical_housing_supplpy_elasticity
        write(*,*) "convexity_of_rental_company=", convexity_of_rental_company
        write(*,*) "rental_management_costs=", rental_management_costs
        write(*,*) "value_of_initial_assets=", value_of_initial_assets
        write(*,*) "model_ss_benefits=", model_ss_benefits
        write(*,*) "initial_endowment=", initial_endowment
        write(*,*) "model_bequests=", model_bequests(transition_length)
        write(*,*) "lump_sum_transfer=", lump_sum_transfer(transition_length)
        
        write(*,*) "housing_stock=", housing_stock(1)
        
        if (zero_elasticity==0) then
        
            total_rental_supply(1,:)=max(((rent(1,:)-housing_price(1)+(1/(1+risk_free_rate(1)))*&
                (housing_price(1-solve_transition_dynamics)*&
                (1-housing_depreciation_rate-property_tax(1-solve_transition_dynamics)-&
                property_tax_on_rental_housing)))/(rental_management_costs_calibrated(:)*&
                convexity_of_rental_company(:))),0.d0)**(1/(convexity_of_rental_company(:)-1))
                
        else
        
            total_rental_supply(1,:)=total_rental_supply_calibrated(:)
            
        end if
            
        write(*,*) "convexity_of_rental_company(:)=", convexity_of_rental_company(:)
        write(*,*) "rental_management_costs_calibrated(:)=", rental_management_costs_calibrated(:)
        write(*,*) "rent(1,:)=", rent(1,:)
        write(*,*) "total_rental_supply=", total_rental_supply(1,:)
        write(*,*) "total_rental_supply_calibrated=", total_rental_supply_calibrated(:)
        write(*,*) "file_number=", file_number
        write(*,*) "old_results=", old_results
        write(*,*) "average_net_wealth_calibrated=", average_net_wealth_calibrated
        write(*,*) "average_labor_income_by_employment_calibrated=", average_labor_income_by_employment_calibrated
        write(*,*) "model_average_rental_unit_size=", model_average_rental_unit_size(1)
        write(*,*) "max_fraction_of_income_spent_on_housing=", max_fraction_of_income_spent_on_housing
        write(*,*) "max_rent_relative_to_ave=", max_rent_relative_to_ave
        write(*,*) "inheritance_amount=", inheritance_amount
        write(*,*) "total_hours_calibrated=", total_hours_calibrated
        write(*,*) "labor_supply_calibrated=", labor_supply_calibrated
        write(*,*) "model_average_rent=", model_average_rent(1)
        write(*,*) "net_govt_revenue_constraint=", net_govt_revenue_constraint
        write(*,*) "price_of_addictive_good=", price_of_addictive_good
        write(*,*) "addiction_scalar_1=", addiction_scalar_1
        write(*,*) "probability_of_voucher=", probability_of_voucher
        write(*,*) "voucher_probabilities=", voucher_probabilities(0,1,1,:)
        write(*,*) "voucher_probabilities=", voucher_probabilities(1,1,1,:)
        write(*,*) "voucher_probabilities_benchmark=", voucher_probabilities_benchmark(0,1,1,:)
        write(*,*) "voucher_probabilities_benchmark=", voucher_probabilities_benchmark(1,1,1,:)
        write(*,*) "probability_becoming_unemployed_if_addicted=", probability_becoming_unemployed_if_addicted
        write(*,*) "probability_becoming_employed_if_addicted=", probability_becoming_employed_if_addicted
        
        write(*,*) "housing_price/calibrated_stationary_housing_price=", &
            housing_price(transition_length)/calibrated_stationary_housing_price
        write(*,*) "rent/rent_calibrated(1)=", rent(1,:)/rent_calibrated(:)
        write(*,*) "increase_in_labour_income_tax=", increase_in_labour_income_tax
         write(*,*) "inheritance_amount=", inheritance_amount
        
        previous_inheritance_amount=inheritance_amount
        
        previous_distance=0
        end_loop=0
        
!        housing_size(lowest_housing_grid_point)=housing_size(lowest_housing_grid_point)*4
                
        write(*,*) "housing_size=", housing_size(:)
        write(*,*) "model_average_income=", model_average_income(1)
!        write(*,*) "income_cutoffs_of_quintiles=", income_cutoffs_of_quintiles
        write(*,*) "large_negative_num=", large_negative_num
                                      
        write(*,*) "increased_risk_of_death_addicted=", increased_risk_of_death_addicted
        write(*,*) "multiple_of_probabilities_of_employment_if_addicted=", multiple_of_probabilities_of_employment_if_addicted
        write(*,*) "relative_share_of_addiction_2=", relative_share_of_addiction_2
        write(*,*) "relative_share_of_addiction_1=", relative_share_of_addiction_1
        write(*,*) "size_of_penalty=", size_of_penalty
        write(*,*) "drug_threshold_calibrated=", drug_threshold_calibrated
                                      
        ! distance_drug_market IS IN THIS LIST AND WAS NOT. The benchmark's loop
        ! at 38728 has always required it; this one tested the rental market, the
        ! housing market, the budget and inheritance only, so even once
        ! clear_drug_market is called the loop could exit with p_v still moving.
        ! A price that is updated but not converged on is not a cleared market.
        ! AND A CAP, so a run that cannot converge says so instead of spinning.
        ! This loop had none: tf_rationed sat in it for 73 loops on a tolerance
        ! it could not reach, and universal_tf for 47 with the price oscillating,
        ! and in both cases the only thing that ended them was me noticing.
        ! THE COUNTERFACTUAL MUST CONVERGE ITS OWN MOMENTS, NOT ONLY ITS MARKETS.
        ! The author, 9 September: *"i hope you converge on the stationary
        ! equilibrium with the counterfactuals"*.
        !
        ! The test below asks whether rent, housing, the budget, the drug market
        ! and inheritance have settled. It never asks whether b, lambda_d or h_1
        ! have stopped moving, and those are not the same question: the drug
        ! market can clear while participation is still drifting. That is exactly
        ! the trap that caught the tax hold criterion twice -- revenue plateaued
        ! for two loops at 3.2031, 3.2477, 3.2492 while distance_drug_market was
        ! still swinging 0.108, 0.076, 0.096.
        !
        ! The benchmark's own frozen loop measured what this costs: one pass at
        ! frozen parameters moved b by 8.5 per cent, lambda_d by 6.0 and h_1 by
        ! 9.0. A counterfactual free to exit in the same condition is reporting a
        ! policy effect with that much drift inside it.
        distance_counterfactual_moments=1

        do while (((distance_counterfactual_moments>stopping_rule_frozen_moments) .OR. &
            (distance_rental_market(transition_length)>stopping_rule_rental_market) .OR. &
            (distance_housing_market(transition_length)>stopping_rule_housing_market) .OR. &
            (distance_govt_budget>stopping_rule_govt_budget) .OR. &
            (distance_drug_market>stopping_rule_drug_market) .OR. &
            (distance_inheritance_amount>stopping_rule_inheritance_amount) .OR. &
            (loop_count<aftr_how_mny_lps_start_update)) .AND. &
            (loop_count<max_counterfactual_loops))
                                
            call solve_value_function_and_policy_functions(transition_length)
            
            if (loop_count<=1) then
            
                stopping_rule_stationary_distribution=10.d0**(-8)
            
            else
            
                stopping_rule_stationary_distribution=10.d0**(-8)
            
            end if
            
            if (include_addiction==1) then
            
                stopping_rule_stationary_distribution=6*10.d0**(-4)
            
            end if
            
            if ((relative_price_change>1000) .AND. (partial_equilibrium==0)) then
            
                stopping_rule_stationary_distribution=3*10.d0**(-3)
            
            end if
                        
            if ((hold_distribution_fixed==0) .AND. (fixed_to_benchmark_dis==0)) then
        
                call converge_to_stationary_equilibrium(transition_length)
                
            else
            
                do i=1,2
            
                    write(string_used,'(i1)') i
            
                    open(unit=12,file="distribution_stationary"//trim(string_used)//trim(old_results)//".dat",action='read')
                        read(12,'(F30.28)') distribution_stationary(i)%vector_transition_real(1,:,:,:,:,:,:)
                    close(12)
                                    
                end do
                
            end if
            
            call stationary_equilibrium_statistics(transition_length)            
            call stationary_equilibirum_homeownership_rate(transition_length)
            call govt_revenues_calc(transition_length)
            call calculate_welfare_by_characteristics(transition_length)
            call calculate_homeownership_by_characteristics(transition_length)
            call calculate_aggregate_consumption(transition_length)

            ! THE DRUG MARKET, WHICH THE COUNTERFACTUAL WAS NOT CLEARING AT ALL.
            !
            ! clear_drug_market has had an is_counterfactual branch since it was
            ! written -- read the benchmark's supply shifter, hold it fixed, and
            ! move p_v by a secant until nu_1 V^(nu_2-1) equals the price
            ! households faced -- and that branch had NO CALLER. The only call in
            ! the file was at 41409, inside calibrating_model. So a counterfactual
            ! ran with p_v pinned at the benchmark's normalised 1 whatever
            ! quantity it produced, and distance_drug_market stayed at its
            ! declared zero, which is indistinguishable in the log from a market
            ! that cleared. The supply curve was in the model and did nothing.
            !
            ! It goes here because stationary_equilibrium_statistics at 42381 is
            ! what fills model_drugs_consumed_by_users, so V is the quantity this
            ! loop's distribution actually bought.
            call clear_drug_market(transition_length)

            ! HAVE THE MOMENTS STOPPED MOVING? Measured here, after
            ! stationary_equilibrium_statistics has rebuilt them for this loop
            ! and before anything is adjusted for the next one.
            if (loop_count>0) then

                distance_counterfactual_moments=max(max(&
                    abs(model_total_drug_users(transition_length)-previous_cf_b_1),&
                    abs(model_fraction_addicted(transition_length)-previous_cf_d_1)),max(&
                    abs(model_fraction_homeless(transition_length)-previous_cf_h_1),&
                    abs(model_average_labour_income(transition_length)-previous_cf_y_1)))

                write(*,*) "CF MOMENTS distance=", distance_counterfactual_moments,&
                    " b=", model_total_drug_users(transition_length),&
                    " lambda_d=", model_fraction_addicted(transition_length),&
                    " h_1=", model_fraction_homeless(transition_length)

            end if

            previous_cf_b_1=model_total_drug_users(transition_length)
            previous_cf_d_1=model_fraction_addicted(transition_length)
            previous_cf_h_1=model_fraction_homeless(transition_length)
            previous_cf_y_1=model_average_labour_income(transition_length)
            
            if ((include_bequests_in_govt_constraint==0) .AND. &
                (partial_equilibrium==0) .AND. (adjust_inheritance==1) .AND. &
                (residual_bequests_to_government==0)) then
            
                previous_inheritance_amount=inheritance_amount
            
                call calculate_updated_inheritance_amounts(1)
                
                distance_inheritance_amount=maxval((1-include_bequests_in_govt_constraint)*&
                    abs(previous_inheritance_amount-inheritance_amount))
                    
                inheritance_amount=inheritance_amount_weight*inheritance_amount+&
                    (1-inheritance_amount_weight)*previous_inheritance_amount
                  
            else
            
                distance_inheritance_amount=0
                
            end if
                             
            write(*,*) "rent(transition_length)=", rent(transition_length,:)
                    
            if (loop_count>aftr_how_mny_lps_start_update) then
                        
                rental_market_adjuster=0.01
                                    
                if (zero_elasticity==1) then
                
                    total_rental_supply(transition_length,:)=total_rental_supply_calibrated(:)
                    
                end if
                
                distance_rental_market(transition_length)=&
                    (1-partial_equilibrium)*maxval(abs(total_rental_demand(transition_length,:)-&
                    total_rental_supply(transition_length,:)))

                excess_demand_1=total_rental_demand(transition_length,:)-&
                    total_rental_supply(transition_length,:)

                rent_step_1=rent(transition_length,:)+&
                    rental_market_adjuster*excess_demand_1

                if (have_rent_secant==1) then

                    where ((abs(excess_demand_1-previous_excess_demand)>10.d0**(-8)) .AND. &
                        (abs(rent(transition_length,:)-previous_rent)>10.d0**(-10)))

                        rent_step_1=rent(transition_length,:)-excess_demand_1*&
                            (rent(transition_length,:)-previous_rent)/&
                            (excess_demand_1-previous_excess_demand)

                    end where

                end if

                ! Never more than a doubling or a halving in one step, and never
                ! non positive.
                rent_step_1=max(min(rent_step_1,2*rent(transition_length,:)),&
                    rent(transition_length,:)/2)

                previous_rent=rent(transition_length,:)
                previous_excess_demand=excess_demand_1
                have_rent_secant=1

                ! fix_rent GUARDS THIS TOO, AND IT DID NOT. The benchmark pins
                ! the rent -- fix_rent is 1 and rent_calibrated is 1.0 -- but this
                ! line is on the COUNTERFACTUAL path and was guarded only by
                ! loop_count and partial_equilibrium, so a policy experiment moved
                ! its rent by a secant on excess demand while the benchmark it is
                ! compared against could not move its own.
                !
                ! That difference would have entered every welfare number as if it
                ! were policy: a rental price response present in the experiment
                ! and absent from the baseline is not a result of Treatment First,
                ! it is a result of the two paths solving different models.
                !
                ! The author, 14 September: *"the rent is pinned at 1 and does not
                ! need to clear the market at all"*. Pinned means pinned on both
                ! paths.
                if (fix_rent==0) then

                    rent(transition_length,:)=(1-partial_equilibrium)*rent_step_1+&
                        partial_equilibrium*rent(transition_length,:)

                end if
                    
            end if
                                 
            write(*,*) "rent(transition_length)=", rent(transition_length,:)
            write(*,*) "rental_market_adjuster=", rental_market_adjuster
            write(*,*) "distance_rental_market(transition_length)=", distance_rental_market(transition_length)
            write(*,*) "total_rental_supply(:)=", total_rental_supply(transition_length,:)
            write(*,*) "total_rental_demand(:)=", total_rental_demand(transition_length,:)
            write(*,*) "rent/rent_calibrated=", rent(transition_length,:)/rent_calibrated(:)               
            write(*,*) "loop_count=", loop_count
            write(*,*) "adjust_rents=", adjust_rents
            write(*,*) "adjust_house_prices=", adjust_house_prices
            write(*,*) "housing_price(transition_length)=", housing_price(transition_length)
            
            distance_housing_market(transition_length)=adjust_house_prices*(1-check_tax_incidence)*&
                (1-partial_equilibrium)*abs(housing_price(transition_length)-&
                (c_1_calibrated)*(housing_depreciation_rate*total_housing_demand(transition_length))**&
                (1/empirical_housing_supplpy_elasticity))

            ! THE HOUSING PRICE IS PEGGED IN A COUNTERFACTUAL. The author,
            ! 8 September: "why is the housing price different? It should be
            ! pegged to the same value as the benchmark".
            !
            ! WHAT IT WAS DOING. Homeownership is off in this paper, so nobody
            ! owns and P has one job left: pricing rental units through the
            ! management-cost formula. Left free it was solved against the
            ! housing supply curve, so a policy that houses more people bid it
            ! up, and it dragged the rent with it -- which is how a rent that
            ! the design block says never moves came out at 1.0015 rather than 1.
            !
            ! AND IT WAS THE BINDING CONSTRAINT. At loop 59 of the first
            ! counterfactual to get this far, the budget sat at 0.0018 and the
            ! drug market at 0.0020, both inside tolerance, while the housing
            ! market sat at 0.0392 against a 0.02 rule. An hour of solving was
            ! spent converging a price the paper holds fixed.
            !
            ! Pegging it is what makes infinite_elasticity_of_rental_supply mean
            ! what it says: rental supply perfectly elastic AT THE BENCHMARK
            ! PRICE, rather than at whatever price the housing stock implies.
            if ((is_counterfactual==1) .AND. (peg_prices_in_counterfactual==1)) then

                housing_price(transition_length)=calibrated_stationary_housing_price
                distance_housing_market(transition_length)=0

            end if
                
            weight_on_housing_price=(1-check_tax_incidence)*0.02
            
            if (loop_count>=1) then
            
                if (adjust_house_prices==1) then
                
                    housing_price(transition_length)=&
                        (1-partial_equilibrium)*((1-weight_on_housing_price)*housing_price(transition_length)+&
                        weight_on_housing_price*(c_1_calibrated)*(housing_depreciation_rate*&
                        total_housing_demand(transition_length))**(1/empirical_housing_supplpy_elasticity))+&
                        partial_equilibrium*housing_price(transition_length)
                        
                end if
                    
            end if
                
            write(*,*) "housing_price(transition_length)=", housing_price(transition_length)
            write(*,*) "housing_price/calibrated_stationary_housing_price=", &
                housing_price(transition_length)/calibrated_stationary_housing_price
            write(*,*) "housing_stock=", housing_stock(transition_length)
            write(*,*) "total_housing_demand=", total_housing_demand(transition_length)
            write(*,*) "distance_housing_market=", distance_housing_market(transition_length)
                    
            call govt_revenues_calc(transition_length)
            call calculate_welfare(transition_length)

            call calculate_childhood_utility(transition_length)
            call calculate_household_housing_spending(transition_length)
            call frac_of_households_in_support_of_policy(transition_length)
                                    
            distance_govt_budget=adjust_taxes*(1-partial_equilibrium)*&
                abs(net_govt_revenues(transition_length)-net_govt_revenue_constraint)
                                           
            if ((partial_equilibrium==0) .AND. (adjust_taxes==1)) then

                if (loop_count>0) then
                
                    if (use_revenues_to_increase_voucher_probability==1) then
                                        
                        tax_system_type=3
                                                    
                    else
                    
                        tax_system_type=1
                    
                    end if
                
                    if (tax_system_type==1) then
                    
                        write(*,*) "increase_in_labour_income_tax=", increase_in_labour_income_tax

                        tax_gap_1=net_govt_revenues(transition_length)-net_govt_revenue_constraint

                        tax_drift_1=huge(1.d0)
                        if (have_last_revenue_tax==1) then
                            tax_drift_1=abs(net_govt_revenues(transition_length)-last_revenue_seen_tax)
                        end if
                        last_revenue_seen_tax=net_govt_revenues(transition_length)
                        have_last_revenue_tax=1

                        if ((loop_count<=tax_hold_max_loops) .AND. &
                            ((tax_drift_1>tax_hold_drift_tolerance_mult*stopping_rule_govt_budget) .OR. &
                             (distance_drug_market>drug_settled_mult_for_tax*stopping_rule_drug_market))) then

                            ! STILL IN TRANSIT. Record and do not act. Acting here
                            ! is what put the whole cold start into the tax: the
                            ! gap is not yet a fact about the policy.
                            write(*,*) "TAX HELD: drift=", tax_drift_1,&
                                " gap=", tax_gap_1,&
                                " drug=", distance_drug_market

                        else

                            tax_slope_1=0

                            if ((have_tax_secant==1) .AND. &
                                (abs(increase_in_labour_income_tax-secant_tax_level)>10.d0**(-8))) then

                                tax_slope_1=(net_govt_revenues(transition_length)-secant_revenue_tax)/&
                                    (increase_in_labour_income_tax-secant_tax_level)

                            end if

                            ! A usable slope is NEGATIVE: raising lambda cuts the
                            ! tax and so cuts revenue. A positive or tiny one is
                            ! noise off a loop that has not settled, so fall back
                            ! rather than divide by it.
                            if (tax_slope_1<-10.d0**(-4)) then

                                tax_step_1=-tax_step_damping*tax_gap_1/tax_slope_1
                                max_tax_move_1=max_tax_move_secant

                            else

                                tax_step_1=tax_fallback_gain*tax_gap_1
                                max_tax_move_1=max_tax_move_blind

                            end if

                            tax_step_1=max(min(tax_step_1,max_tax_move_1),-max_tax_move_1)

                            secant_revenue_tax=net_govt_revenues(transition_length)
                            secant_tax_level=increase_in_labour_income_tax
                            have_tax_secant=1

                            increase_in_labour_income_tax=increase_in_labour_income_tax+tax_step_1

                            write(*,*) "TAX STEP: slope=", tax_slope_1, " step=", tax_step_1

                        end if

                        write(*,*) "increase_in_labour_income_tax=", increase_in_labour_income_tax
                                            
                    elseif (tax_system_type==2) then
                    
                        write(*,*) "lump_sum_transfer to renters=", lump_sum_transfer(transition_length)

                        lump_sum_transfer(transition_length)=lump_sum_transfer(transition_length)+&
                            0.005*(net_govt_revenues(transition_length)-net_govt_revenue_constraint)

                        write(*,*) "lump_sum_transfer to renters=", lump_sum_transfer(transition_length)
                        
                    elseif (tax_system_type==3) then
        
                        if (increase_vouchers_for_homeless_only==1) then
                        
                            write(*,*) "increased_prob_of_voucher_if_homeless_1=", increased_prob_of_voucher_if_homeless_1

                            increased_prob_of_voucher_if_homeless_1=max(min(increased_prob_of_voucher_if_homeless_1+&
                                10*(net_govt_revenues(transition_length)-net_govt_revenue_constraint),10.d0),0.d0)

                            write(*,*) "increased_prob_of_voucher_if_homeless_1=", increased_prob_of_voucher_if_homeless_1
                        
                        else
                    
                            write(*,*) "probability_of_voucher_benchmark_used_1=", probability_of_voucher_benchmark_used_1

                            ! GAIN 0.3 -> 0.05. At 0.3 the budget iteration
                            ! DIVERGES once an arm moves the economy far enough,
                            ! and it did.
                            !
                            ! MEASURED on the omega_c = 1 plus internalisation
                            ! arm with the drug price pinned at 0.87, so nothing
                            ! else was moving:
                            !   pi_v 0.067534 -> 0.040506  step -0.027028  residual -0.09009
                            !        0.040506 -> 0.150433  step +0.109927  residual +0.36642
                            !        0.150433 -> 0.000000  (clamped)       residual -0.53540
                            ! The residual alternates sign and grows by about
                            ! four a loop, and pi_v hit its floor at zero, where
                            ! the budget cannot clear at all.
                            !
                            ! From those two steps dResidual/dpi_v = 0.45651 /
                            ! (-0.027028) = -16.9, so the multiplier is
                            ! 1 + 0.3*(-16.9) = -4.07 -- magnitude above one,
                            ! sign alternating, which is what was observed.
                            ! Stability needs the gain below 2/16.9 = 0.118.
                            !
                            ! At 0.05 the multiplier is 0.155, contracting fast,
                            ! and it holds even if the sensitivity were twice
                            ! what was measured.
                            !
                            ! WHY IT NEVER SHOWED BEFORE: at the benchmark's own
                            ! drug price the economy is far less budget
                            ! sensitive and 0.3 converged -- the same probe at
                            ! p = 1.00 went 5.4e-2, 9.9e-2, 3.0e-2, 1.7e-2,
                            ! 1.8e-2, 2.8e-4 and settled. The gain was tuned in
                            ! a region the optimal policy arms leave.
                            !
                            ! Unlike the drug price there is no relative step
                            ! clip here, only the bounds at 0 and 1, so the gain
                            ! is what actually governs.
                            probability_of_voucher_benchmark_used_1=max(min(probability_of_voucher_benchmark_used_1+&
                                0.05*(net_govt_revenues(transition_length)-net_govt_revenue_constraint),1.d0),0.d0)

                            ! PERSIST IT, OR recompute_derived_parameters UNDOES IT ON THE
                            ! NEXT LINE AND THE BUDGET NEVER CLEARS.
                            !
                            ! The call to create_unemployment_process a few lines below reaches
                            ! recompute_derived_parameters, which opens its voucher block with
                            !     probability_of_voucher_benchmark_used_1 = probability_of_voucher_benchmark_used
                            ! and then rebuilds probability_of_voucher_benchmark from the MODULE
                            ! value. So the step computed just above was overwritten before the
                            ! economy ever saw it, and the lottery array was rebuilt from the
                            ! unchanged number. The instrument moved on paper and nowhere else.
                            !
                            ! MEASURED, 19 September, on the omega_c = 1 plus internalisation arm:
                            ! the "before" print read 0.06753386 on every block while
                            ! distance_govt_budget GREW, 0.054063 then 0.099053. pi_v took the same
                            ! first step from the same place forever.
                            !
                            ! Writing the module value makes the reset REPRODUCE the new pi_v
                            ! instead of undoing it. Safe against the calibration, which also writes
                            ! this name: this block runs only when
                            ! use_revenues_to_increase_voucher_probability is 1, a compile-time
                            ! parameter set only in a counterfactual build, and an arm freezes every
                            ! adjuster in any case.
                            probability_of_voucher_benchmark_used=probability_of_voucher_benchmark_used_1

                            write(*,*) "probability_of_voucher_benchmark_used=", probability_of_voucher_benchmark_used_1
                                                    
                        end if
                        
                        call create_unemployment_process()
                            
                        write(*,*) "voucher_probabilities=", voucher_probabilities(0,1,1,:)
                        write(*,*) "voucher_probabilities=", voucher_probabilities(1,1,1,:)
                        
                    end if

                end if
                                                    
            end if
                               
            write(*,*) "distance_govt_budget=", distance_govt_budget   
            write(*,*) "net_govt_revenue_constraint=", net_govt_revenue_constraint
            write(*,*) "net_govt_revenues=", net_govt_revenues(transition_length)
            write(*,*) "sum(distribution_stationary(transition_length,:,:,:,:,:))=", sum_of_distribution
                        
            call cpu_time(simulation_stop_time)
            
!            write(*,*) "running for", (simulation_stop_time-simulation_start_time)/3600
            write(*,*) "model_homeownership_rate(transition_length)=", model_homeownership_rate(transition_length)
            write(*,*) "largest_house_size_hhld_can_rent=", largest_house_size_hhld_can_rent
            write(*,*) "index_of_smallest_house_hhld_can_buy=", index_of_smallest_house_hhld_can_buy 
            write(*,*) "do_internal_computations=", do_internal_computations
!            write(*,*) "eta_1=", eta_1
!            write(*,*) "relative_share_of_addiction_1=", relative_share_of_addiction_1
!            write(*,*) "relative_share_of_housing=", relative_share_of_housing_1            
!            write(*,*) "relative_share_of_housing=", relative_share_of_housing_2
!            write(*,*) "relative_share_of_leisure=", relative_share_of_leisure
            write(*,*) "discount_factor=", discount_factor
!            write(*,*) "discount_factor_on_child=", discount_factor_on_child
!            write(*,*) "minimum_inheritance=", minimum_inheritance
            write(*,*) "convexity_of_rental_company=", convexity_of_rental_company
!            write(*,*) "advantage_to_owning=", advantage_to_owning
!            write(*,*) "standard_deduction=", standard_deduction
!            write(*,*) "personal_exemption=", personal_exemption
            write(*,*) "is_counterfactual=", is_counterfactual
            write(*,*) "tax_system_type=", tax_system_type
                        
            if (check_tax_incidence==0) then
                                    
                call function_of_utility_advantage_from_homeowning(transition_length)
                
            end if
                                                            
            if (property_tax_on_rental_housing>0) then
            
                write(*,*) "property_tax_on_rental_housing=", property_tax_on_rental_housing
            
            end if
                     
            write(*,*) "lump_sum_transfer=", lump_sum_transfer(transition_length)
            write(*,*) "increase_in_labour_income_tax=", increase_in_labour_income_tax
            
            if (mortgage_deductibility>0) then
            
                write(*,*) "mortgage_deductibility=", mortgage_deductibility
                write(*,*) "% govt spending on mortgage interest deductions/model_GDP_incl_imput_rent=", &
                    100*(govt_spending_on_mortgage_interest_deductions(transition_length)/&
                    model_GDP_incl_imput_rent(transition_length))
                
            end if
            
            write(*,*) "total_rental_supply(transition_length)/total_rental_supply_calibrated=", &
                total_rental_supply(transition_length,:)/total_rental_supply_calibrated(:)
            
            write(*,*) "model_labor_supply=", model_labor_supply(transition_length)
            write(*,*) "model_total_hours=", model_total_hours(transition_length)
            write(*,*) "model_labor_supply/model_total_hours=", &
                model_labor_supply(transition_length)/model_total_hours(transition_length)
            write(*,*) "model_labor_supply/labor_supply_calibrated=", model_labor_supply(transition_length)/labor_supply_calibrated
            write(*,*) "inheritance_amount(1)=", inheritance_amount(1)
            write(*,*) "distance_inheritance_amount=", distance_inheritance_amount
            write(*,*) "file_number=", file_number
            write(*,*) "old_results=", old_results
            write(*,*) "benchmark_simulation=", benchmark_simulation
            write(*,*) "model_fraction_homeless=", model_fraction_homeless(transition_length)
            write(*,*) "govt_spending_on_housing_vouchers=", govt_spending_on_housing_vouchers(transition_length)
            write(*,*) "govt_spending_on_food_stamps=", govt_spending_on_food_stamps(transition_length)
            write(*,*) "model_fraction_addicted_homeless_no_vouchers=", &
                model_fraction_addicted_homeless_no_vouchers(transition_length)
            write(*,*) "model_fraction_recieving_food_stamps=", &
                model_fraction_recieving_food_stamps(transition_length)/sum_of_distribution
            write(*,*) "model_fraction_recieving_housing_vouchers=", &
                model_fraction_recieving_housing_vouchers(transition_length)/sum_of_distribution
            write(*,*) "model_average_labour_income_tax=", model_average_labour_income_tax(transition_length)
            write(*,*) "model_fraction_homeless_and_addicted=", model_fraction_homeless_and_addicted(transition_length)
!            write(*,*) "model_avg_homeless_income=", model_avg_homeless_income(transition_length)
!            write(*,*) "max_rent_relative_to_ave=", max_rent_relative_to_ave
!            write(*,*) "max_fraction_of_income_spent_on_housing=", max_fraction_of_income_spent_on_housing
            write(*,*) "addiction_share_of_income_by_employment=", addiction_share_of_income_by_employment(transition_length,:)
!            write(*,*) "total_govt_revenues=", total_govt_revenues(transition_length)
            write(*,*) "model_fraction_spent_on_addiction,", model_fraction_spent_on_addiction(1)
            write(*,*) "model_fraction_addicted=", model_fraction_addicted(1)
            write(*,*) "model_exprimenters=", model_exprimenters(1)
            write(*,*) "model_fraction_addicted+model_exprimenters=", model_fraction_addicted(1)+model_exprimenters(1)
            write(*,*) "model_drugs_used_by_users_on_average,", model_drugs_used_by_users_on_average(1)
            write(*,*) "model_treatment_take_up,", model_treatment_take_up(1)
            write(*,*) "model_drugs_consumed_by_users=", model_drugs_consumed_by_users(1)
            write(*,*) "model_drugs_used_by_experimenters_on_average,", model_drugs_used_by_experimenters_on_average(1)
            write(*,*) "model_drugs_used_by_addicts_on_average=", model_drugs_used_by_addicts_on_average(1)
            write(*,*) "model_fraction_unemployed=", model_fraction_unemployed(1)
            write(*,*) "model_eligibles_getting_voucher=", model_eligibles_getting_voucher(1)
                            
            write(*,*) "average_welfare_of_all_cohorts=", average_welfare_of_all_cohorts(1)
            write(*,*) "average_welfare_of_youngest_cohort=", average_welfare_of_youngest_cohort(1)
                               
            do i=1,1+include_addiction
        
                write(*,*) "welfare_by_addiction=", welfare_by_addiction(transition_length,i)
                write(*,*) "welfare_by_addiction_youngest=", welfare_by_addiction_youngest(transition_length,i)
                
            end do
                        
!            write(*,*) "frac_in_support_addicted_youngest,", frac_in_support_addicted_youngest(transition_length)
!            write(*,*) "frac_in_support_addicted,", frac_in_support_addicted(transition_length)
            write(*,*) "price_of_addictive_good=", price_of_addictive_good
            write(*,*) "model_fraction_with_negative_value_of_life=", model_fraction_with_negative_value_of_life(1)
            write(*,*) "model_largest_negative_value_of_life", model_largest_negative_value_of_life(1)
            
!            write(*,*) "model_avg_housing_spending_renters=", model_avg_housing_spending_renters(1)
            write(*,*) "probability_of_voucher=", probability_of_voucher
!            write(*,*) "model_fraction_addicted_who_are_homeless,", model_fraction_addicted_who_are_homeless(1)
            write(*,*) "sum_of_distribution=", sum_of_distribution
!            write(*,*) "model_addicted_and_homeless_by_choice=", model_addicted_and_homeless_by_choice(1)
!            write(*,*) "model_fraction_homeless_by_choice=", model_fraction_homeless_by_choice(1)
!            write(*,*) "model_homeless_2_years_or_more=", model_homeless_2_years_or_more(1)
            write(*,*) "model_addicts_getting_voucher,", model_addicts_getting_voucher(1)
!            write(*,*) "model_homelessness_old=", model_homelessness_old(1)
            write(*,*) "adjust_inheritance=", adjust_inheritance
            write(*,*) "average_labour_income_tax=", model_average_labour_income_tax(1)
!            write(*,*) "use_income_or_income_plus_assets,", use_income_or_income_plus_assets
!            write(*,*) "model_addicts_consuming_no_drugs,", model_addicts_consuming_no_drugs(1)
            write(*,*) "model_age_by_addiction,", model_age_by_addiction(1,:)
            write(*,*) "model_fraction_choose_addiction_when_unemployed=", model_fraction_choose_addiction_when_unemployed(1)
            write(*,*) "model_choose_addiction_when_income_is_low=", model_choose_addiction_when_income_is_low(1)
            write(*,*) "model_fraction_choose_addiction_when_homeless=", model_fraction_choose_addiction_when_homeless(1)
            write(*,*) "model_choose_addiction_when_retired=", model_choose_addiction_when_retired(1)
            
            do i=1,10
!                write(*,*) income_to_avg_income_wide_pdf_1(1,i)
            end do
            
            do i=1,11
            
!                write(*,*) "lowest_welfare_of_addicted", i, "=", lowest_welfare_of_addicted(1,i)
                
            end do
            
            if (compute_welfare_every_loop==1) then
            
                do j=1,1!+include_addiction+include_addiction
                            
                    if (j==1) then
                
                        call calculate_welfare_gains(transition_length,average_welfare_with_childhood(1),j,&
                            welfare_of_gains_by_addiction(j))
                            
                    elseif (j>1) then
                    
                        call calculate_welfare_gains(transition_length,welfare_by_addiction_youngest(1,j-1),j,&
                            welfare_of_gains_by_addiction(j))
                            
                    end if
                    
                end do
                
                do i=1,1 !2+include_addiction
                
                    write(*,*) "welfare_of_gains_by_addiction=", welfare_of_gains_by_addiction(i)
                    
                end do
                
            end if
                                     
        end do
        
        simulation_ended=1
                
        call calculate_homeownership_by_characteristics(transition_length)
        call stationary_equilibrium_statistics(transition_length)            
!        call stationary_equilibirum_homeownership_rate(transition_length)
!        call govt_revenues_calc(transition_length)
!        call calculate_welfare_by_characteristics(transition_length)
!        call calculate_aggregate_consumption(transition_length)
!        call calculate_welfare(1)
        call stationary_equilibrium_wealth_distribution(transition_length)
        call calculate_gini_coefficient(transition_length)
        ! THE SAME MOMENTS BLOCK THE BENCHMARK PRINTS.
        !
        ! print_all_moments is a Global_Vars module procedure, and it had one
        ! caller: the benchmark's sweep stop. So a counterfactual reported
        ! whatever its own scattered write statements happened to carry, and a
        ! comparison against the benchmark had to be assembled by hand out of
        ! two different formats -- with anything the counterfactual did not
        ! print, the age distribution of users among them, simply unavailable.
        !
        ! It runs after convergence and after the final statistics pass, so it
        ! reports the equilibrium rather than an iterate, and it is print-only:
        ! nothing downstream reads what it recomputes.
        write(*,*) "===== COUNTERFACTUAL MOMENTS ====="
        call print_all_moments()
        write(*,*) "===== END OF COUNTERFACTUAL MOMENTS ====="

        call save_vars_and_functions(transition_length)
        
        write(*,*) "model_drug_use_by_income_quintile", model_drug_use_by_income_quintile(transition_length,:)
        
        do j=1,1!+include_addiction+include_addiction
                        
            if (j==1) then
        
                call calculate_welfare_gains(transition_length,average_welfare_with_childhood(1),j,&
                    welfare_of_gains_by_addiction(j))
                    
            elseif (j>1) then
            
                call calculate_welfare_gains(transition_length,welfare_by_addiction_youngest(1,j-1),j,&
                    welfare_of_gains_by_addiction(j))
                    
            end if
            
        end do
        
        do i=1,1 !2+include_addiction
        
            write(*,*) "welfare_of_gains_by_addiction=", welfare_of_gains_by_addiction(i)
            
        end do
        
        write(*,*) "simulation_ended"
                    
    end subroutine
    
    subroutine upload_functions()
    
        use Global_Vars
        
        implicit none
        
        character*1 :: string_used
        
        do i=1,2
            
            write(string_used,'(i1)') i
                                
            open(unit=12,file="distribution_stationary"//trim(string_used)//trim(benchmark_simulation)//".dat",action='read')
                read(12,'(F30.28)') distribution_to_fetch(i)%&
                    vector_real(:,:,:,:,:,0:(1-(i-1))*voucher_state_max_benchmark)
            close(12)
                           
            open(unit=12,file="policy_function_space_lived_in_size"&
                //trim(string_used)//trim(benchmark_simulation)//".dat",action='read')
                read(12,'(F25.20)') policy_function_space_lived_in_size_to_fetch(i)%&
                    vector_real(:,:,:,:,:,0:(1-(i-1))*voucher_state_max_benchmark)
            close(12)
                    
        end do
        
        do i=1,2
                        
            write(string_used,'(i1)') i
                           
            open(unit=1,file="value_function"//trim(string_used)//trim(long_run_simulation)//".dat",action='read')
                read(1,'(F35.13)') value_function(i)%&
                    vector_transition_real(transition_length,:,:,:,:,:,&
                    0:(1-(i-1))*voucher_state_max_benchmark)
            close(1)

            ! WHAT A GRANDFATHERED HOUSEHOLD IS WORTH AT THE TERMINAL DATE.
            !
            ! The terminal steady state has no grandfathered mass -- by T>=60
            ! the exempt cohort is dead -- so the file carries no such slab and
            ! the slot would otherwise stay ZERO. At T>=60 nothing ever reads
            ! it. At a SHORT horizon the cohort is still alive at T and would
            ! read a zero continuation, which would make exemption look
            ! catastrophic and the test worthless.
            !
            ! Filled from the ORDINARY HOLDER, slot 1. That is the right limit:
            ! once conditionality has emptied the using population, being
            ! exempt from it is worth almost nothing, so the two coincide. It
            ! is an explicit modelling choice for short horizons and it is
            ! stated rather than left as an implicit zero.
            if ((grandfather_voucher_states==1) .AND. (i==1)) then

                value_function(i)%vector_transition_real&
                    (transition_length,:,:,:,:,:,voucher_gf)=&
                    value_function(i)%vector_transition_real&
                    (transition_length,:,:,:,:,:,1)

                write(*,*) "TRANSITION GF: terminal value for the grandfathered state &
                    &filled from the ordinary holder"

            end if
                            
            value_function_guess(i)%vector_youngest_real(:,:,:,:,:)=&
                value_function(i)%vector_transition_real(transition_length,1,:,:,:,:,:)

        end do
    
    end subroutine    
    
    subroutine transition_simulation()
    
        use Global_Vars
        
        implicit none
        
        integer :: start_updating_at_loop_number=0
        real(8) :: largest_distance_govt_budget
        real(8) :: house_price_upon_implementation=0.99,slope_of_log_house_price=0.5
        real(8) :: rent_upon_implementation=0.92
        real(8), dimension(0:have_two_rental_markets) :: slope_of_log_rent=-0.1
        real(8) :: slope_of_lump_sum_transfer=0.2,alpha_1         
        ! The exact consumption equivalent for the cohort born at each period,
        ! interpolated off the benchmark's saved welfare curve rather than
        ! converted by hand from utils.
        real(8) :: cev_this_period=0
        ! Reading the measured drug price path seed.
        integer :: seed_iostat_1=0,seed_count_1=0
        real(8) :: seed_value_1=0
        integer :: seed_iostat_2=0,seed_count_2=0
        real(8) :: seed_value_2=0
        ! The three REMAINING equilibrium paths. The transition iterates five
        ! objects per period, not two: the drug price and pi_v have been saved
        ! since 0b1e5ce, but the house price, the rent and the lump-sum transfer
        ! were reconstructed from their level-and-slope guess on every restart,
        ! which threw away every loop of housing and rental clearing the run had
        ! paid for. One counter set serves all three; they are read in turn.
        integer :: seed_iostat_3=0,seed_count_3=0
        real(8) :: seed_value_3=0
        character(len=400) :: seed_line_1=''
        ! The clipped pi_v step and its cap.
        real(8) :: pi_v_step_1=0,pi_v_cap_1=0,pi_v_gap_1=0,pi_v_damped_1=0,pi_v_new_1=0
        ! Its own index, not the module's i, which reslot_distributions uses.
        integer :: keep_i_1
                
        loop_count=0
        
        lump_sum_transfer=0

        ! THE TRANSITION DRIVER HAD NO PROLOGUE AT ALL.
        !
        ! The main program branches three ways on the two compile-time switches
        ! and calls exactly one driver, so with solve_transition_dynamics=1
        ! long_run_counter_factual NEVER RUNS and every line of setup it does
        ! has to be done here instead. None of it was. In particular
        ! apply_param_handover was never called, so a run launched as Treatment
        ! First was not Treatment First and was not even the calibrated
        ! benchmark: it went with each parameter's declared default.
        !
        ! ORDER MIRRORS long_run_counter_factual: handover, names, the tie, the
        ! house size, the transfer, the floor. set_files_names is called AGAIN
        ! here, after the handover, because the main program's own call at the
        ! top ran before any handover value existed and keyed the names off the
        ! declared defaults.
        call apply_param_handover()
        call set_files_names()
        call apply_gamma_tie()
        call set_smallest_house_size()
        call set_newborn_age_transfer(1)
        call set_renter_floor(1)

        write(*,*) "TRANSITION INIT: file_number=", trim(file_number)
        write(*,*) "TRANSITION INIT: old_results=", trim(old_results)
        write(*,*) "TRANSITION INIT: benchmark_simulation=", trim(benchmark_simulation)
        write(*,*) "TRANSITION INIT: long_run_simulation=", trim(long_run_simulation)
        write(*,*) "TRANSITION INIT: transition_length=", transition_length
        write(*,*) "TRANSITION INIT: renter_floor_by_age(1:5)=", renter_floor_by_age(1:5)
        write(*,*) "TRANSITION INIT: smallest_house_size=", smallest_house_size

        ! THE VOUCHER RULE AND THE TAX INSTRUMENT, copied from
        ! long_run_counter_factual. Without these the transition would run the
        ! benchmark's rationed voucher with tax_system_type at its default, so
        ! the reform the path converges to would not be the reform the terminal
        ! steady state was solved under.
        if (probability_of_voucher_benchmark_used==1) then

            probability_of_voucher=1

        end if

        if (use_revenues_to_increase_voucher_probability==1) then

            if (increased_prob_of_voucher_if_homeless_and_addicted==0) then

                increased_prob_of_voucher_if_homeless_1=1

                tax_system_type=3

            else

                tax_system_type=1

            end if

        elseif (double_voucher_program==1) then

            probability_of_voucher=probability_of_voucher_benchmark*2

            tax_system_type=1

        else

            tax_system_type=1

        end if

        simulation_ended=0

        call cpu_time(simulation_start_time)

        increase_in_labour_income_tax=0

        call initialize_variables_and_grids()
                                
        if (use_old_results==1) then
        
            call upload_vars(1)
            call function_of_utility_advantage_from_homeowning(1)     
            
            call allocate_matrix() 
            call upload_functions()

            ! THE GRIDS AND THE FLOOR BEFORE THE DISTRIBUTION, as both working
            ! drivers do it (calibrating_model, long_run_counter_factual).
            !
            ! initialize_feasible_distribution reads financial_grid when it
            ! places the exogenous endowment, and every state loop in it starts
            ! at renter_floor_by_age. Neither existed here: the grid had not
            ! been built and renter_floor_by_age was still at its DECLARED 0,
            ! while the renter array's financial dimension starts at
            ! renter_array_floor, which is negative_financial_grid_size=3 when
            ! unsecured borrowing is off. MEASURED, 19 September: index 0 of
            ! dimension 3 below lower bound 3, in the slot-0 accumulation the
            ! transition branch does.
            call GKKOC_intergenerational_employment_process(1)
            call initialize_financial_grid(1)
            call set_newborn_age_transfer(1)
            call set_renter_floor(1)

            ! CALLED AT 1, NOT AT transition_length.
            !
            ! This routine writes distribution_guess at BOTH time_period and at
            ! the LITERALS 0 and 1 -- the literals are the transition's initial
            ! condition, slot 0 accumulated from distribution_to_fetch and slot
            ! 1 read from the benchmark's file. Called at transition_length it
            ! would slot a windowed distribution to (T-1:T) and then write 0 and
            ! 1 out of bounds.
            !
            ! At 1 the window is (0:1), every literal write lands in range, and
            ! the time_period writes go to slot 1 -- which is exactly what
            ! long_run_counter_factual does, since transition_length is 1 there.
            ! The two drivers become consistent rather than accidentally
            ! different.
            call initialize_feasible_distribution(1)

            ! THE REFORM GRANDFATHERS EVERY HOUSEHOLD HOLDING A VOUCHER.
            !
            ! Applied to the INITIAL CONDITION only, and before the snapshot, so
            ! it is a property of the economy the transition starts from and is
            ! restored with it at the top of every loop. Nothing transitions
            ! into voucher_gf afterwards, so this single move is the whole
            ! cohort for the whole run.
            !
            ! Renters only: the owner array is allocated 0:0 on the voucher
            ! dimension, so there is no state 1 there to move.
            if ((grandfather_voucher_states==1) .AND. (solve_transition_dynamics==1)) then

                write(*,*) "TRANSITION GF: holders before=",&
                    sum(distribution_guess(1)%vector_transition_real&
                    (1-solve_transition_dynamics,:,:,:,:,:,1))

                ! ALL FOUR ARRAYS, not distribution_guess alone.
                !
                ! The first attempt moved the holders in distribution_guess
                ! only, and the T=5 result came back with welfare and h_1
                ! BIT-IDENTICAL to arm 3 while b and lambda_d moved 7 per cent
                ! -- which no pair of distinct policies can produce.
                ! calculate_childhood_utility reads distribution_stationary at
                ! time_period-solve_transition_dynamics, which is slot 0 at
                ! t=1, so the childhood half of the welfare measure never saw
                ! the reform at all.
                !
                ! The initial condition has to be mapped in EVERY array that
                ! carries it, or the run is two different economies depending
                ! on which one a routine happens to read.
                distribution_guess(1)%vector_transition_real&
                    (1-solve_transition_dynamics,:,:,:,:,:,voucher_gf)=&
                    distribution_guess(1)%vector_transition_real&
                    (1-solve_transition_dynamics,:,:,:,:,:,1)
                distribution_guess(1)%vector_transition_real&
                    (1-solve_transition_dynamics,:,:,:,:,:,1)=0

                distribution_stationary(1)%vector_transition_real&
                    (1-solve_transition_dynamics,:,:,:,:,:,voucher_gf)=&
                    distribution_stationary(1)%vector_transition_real&
                    (1-solve_transition_dynamics,:,:,:,:,:,1)
                distribution_stationary(1)%vector_transition_real&
                    (1-solve_transition_dynamics,:,:,:,:,:,1)=0

                ! dist_prev_1 AND dist_prev_2 ARE DELIBERATELY NOT MAPPED.
                !
                ! They are not the initial condition. Their own declaration
                ! says what they are: "two previous sweeps of the distribution,
                ! kept for the Aitken step" -- iteration history, not state.
                !
                ! Mapping them was an OVER-CORRECTION of the previous bug, and
                ! it showed up immediately: the T=5 run produced a one-period
                ! spike at t=1 -- b 0.1127 against 0.0471 at t=2, h_1 0.01153
                ! against 0.00731 -- that vanished by t=2 and never returned. A
                ! policy effect does not appear for one period and disappear.
                ! Injecting grandfathered mass into the Aitken history makes the
                ! FIRST period's distribution converge against a state the
                ! iteration never produced, and the buffers then refill from
                ! real sweeps and the transient washes out.
                !
                ! The rule the two bugs bracket: map every array that HOLDS THE
                ! INITIAL CONDITION, and no array that holds ITERATION STATE.
                ! distribution_guess and distribution_stationary are the former;
                ! these two are the latter.

                write(*,*) "TRANSITION GF: stationary slot-0 mass before/after=",&
                    sum(distribution_stationary(1)%vector_transition_real&
                    (1-solve_transition_dynamics,:,:,:,:,:,1)),&
                    sum(distribution_stationary(1)%vector_transition_real&
                    (1-solve_transition_dynamics,:,:,:,:,:,voucher_gf))

                write(*,*) "TRANSITION GF: grandfathered=",&
                    sum(distribution_guess(1)%vector_transition_real&
                    (1-solve_transition_dynamics,:,:,:,:,:,voucher_gf)),&
                    " left in state 1=",&
                    sum(distribution_guess(1)%vector_transition_real&
                    (1-solve_transition_dynamics,:,:,:,:,:,1))

            end if

            ! SNAPSHOT THE INITIAL CONDITION BEFORE THE WINDOW CAN WALK AWAY.
            ! source= copies the bounds as well as the values, so the keeper
            ! matches whatever this build's grids make a slice.
            if (solve_transition_dynamics==1) then

                do keep_i_1=1,2

                    allocate(init_keep_guess(keep_i_1)%vector_real,&
                        source=distribution_guess(keep_i_1)%&
                        vector_transition_real(1-solve_transition_dynamics,:,:,:,:,:,:))
                    allocate(init_keep_stat(keep_i_1)%vector_real,&
                        source=distribution_stationary(keep_i_1)%&
                        vector_transition_real(1-solve_transition_dynamics,:,:,:,:,:,:))
                    allocate(init_keep_prev1(keep_i_1)%vector_real,&
                        source=dist_prev_1(keep_i_1)%&
                        vector_transition_real(1-solve_transition_dynamics,:,:,:,:,:,:))
                    allocate(init_keep_prev2(keep_i_1)%vector_real,&
                        source=dist_prev_2(keep_i_1)%&
                        vector_transition_real(1-solve_transition_dynamics,:,:,:,:,:,:))

                end do

                init_keep_done=.true.

                write(*,*) "TRANSITION INIT: initial condition kept, mass=",&
                    sum(init_keep_guess(1)%vector_real)+sum(init_keep_guess(2)%vector_real)

            end if
                    
        else
        
            model_average_labour_income(:)=average_labor_income_calibrated
            median_income(:)=median_income_calibrated
            model_average_labour_income_by_employment(:,:)=average_labor_income_calibrated
            
            net_govt_revenues(1)=net_govt_revenue_constraint
                
            housing_stock(1-solve_transition_dynamics)=calibrated_housing_stock
            housing_stock(transition_length)=long_run_housing_stock
                                                
            housing_price(transition_length)=long_run_stationary_housing_price
                
        end if

        ! MOVED FROM ABOVE upload_vars, 19 September. The employment process
        ! routine carries a guard that stops the run when
        ! average_labor_income_by_employment_calibrated is empty, and that array
        ! is filled by upload_vars. Called before the upload it is ALWAYS empty,
        ! so the transition stopped on its own guard the first time it was ever
        ! run:
        !
        !   STOP: average_labor_income_by_employment_calibrated is empty.
        !
        ! The counterfactual driver has the right order already -- upload_vars at
        ! 51367, then this routine at 51410 -- which is why every arm runs and
        ! only the transition stopped. Ordering only; no equation is touched.
        call GKKOC_intergenerational_employment_process(1)
        
        housing_price(1-solve_transition_dynamics)=calibrated_stationary_housing_price
                
        if (use_old_results==1) then
                            
            housing_price(1)=calibrated_stationary_housing_price*house_price_upon_implementation
            
            slope_of_log_house_price=(housing_price(transition_length)-housing_price(1))/(real(transition_length)/real(2))
                                                  
            do time_index=min(2,transition_length),max(transition_length-1,1)
            
                housing_price(time_index)=min(housing_price(1)+&
                    slope_of_log_house_price*(real(time_index)-real(1)),housing_price(transition_length))
                  
            end do
            
        end if

        ! FLATTEN THE INITIAL PRICE PATH, for the reason given at the rent
        ! block below: the first solve must face the same price the loop will
        ! hold it at.
        if (peg_prices_in_counterfactual==1) then

            do time_index=1-solve_transition_dynamics,transition_length
                housing_price(time_index)=calibrated_stationary_housing_price
            end do

        end if
        
        if (use_old_results==0) then
                            
            risk_free_rate(:)=calibrated_risk_free_rate
            mortgage_interest_rate(:)=risk_free_rate+mortgage_interest_gap
            
        end if
                                                            
        call initialize_variables_and_grids()
        call GKKOC_intergenerational_employment_process(1)
        
        if (use_old_results==0) then
                        
            call set_SS_benefits(1)
                         
        end if
                
        if (use_old_results==1) then
         
            total_housing_demand(1-solve_transition_dynamics)=calibrated_housing_stock
            total_housing_demand(transition_length)=long_run_housing_stock
            total_rental_supply(1-solve_transition_dynamics,:)=total_rental_supply_calibrated(:)
            total_rental_demand(1-solve_transition_dynamics,:)=total_rental_supply_calibrated(:)
        
            rent(transition_length,:)=long_run_rent(:)
            
        end if
        
        open(unit=39,file="total_rental_supply"//trim(long_run_simulation)//".dat",action='read')
            read(39,'(F15.12)') total_rental_supply(transition_length,:)
        close(39)
        
        open(unit=40,file="total_profits"//trim(long_run_simulation)//".dat",action='read')
            read(40,'(F15.12)') total_profits(transition_length)
        close(40)
        
        total_rental_demand(transition_length,:)=total_rental_supply(transition_length,:)
        
        rent(1-solve_transition_dynamics,:)=rent_calibrated(:)
        
        model_average_rent(1:transition_length)=rent_calibrated(0)
           
        if (use_old_results==1) then
       
            rent(1,:)=rent_calibrated(:)*rent_upon_implementation
            
            slope_of_log_rent(:)=(rent(transition_length,:)-rent(1,:))/(real(transition_length)/real(2))
                                    
            do time_index=min(2,transition_length),max(transition_length-1,1)
                                                
                rent(time_index,:)=max(rent(1,:)+&
                    slope_of_log_rent(:)*(real(time_index)-real(1)),rent(transition_length,:))
                                                               
                call function_of_utility_advantage_from_homeowning(time_index)
                                    
            end do 
            
        end if

        ! AND FLATTEN THE INITIAL PATH. The block above ramps the rent from
        ! rent_calibrated*rent_upon_implementation to its long-run value; with
        ! the peg on there is nothing to ramp to, and the FIRST value function
        ! solve would otherwise be taken against a path that the loop then
        ! overwrites. Households would have priced one economy and been counted
        ! in another.
        if (peg_prices_in_counterfactual==1) then

            do time_index=1-solve_transition_dynamics,transition_length
                rent(time_index,:)=rent_calibrated(:)
            end do

        end if
        
        lump_sum_transfer(1-solve_transition_dynamics)=0
        
        if (use_old_results==1) then
    
            lump_sum_transfer(1)=0.0002
            
            slope_of_lump_sum_transfer=(lump_sum_transfer(transition_length)-lump_sum_transfer(1))/(transition_length)
                        
            do time_index=min(2,transition_length),max(transition_length-1,1)
                                                
                lump_sum_transfer(time_index)=min(lump_sum_transfer(1)+&
                    slope_of_lump_sum_transfer*(real(time_index)-real(1)),lump_sum_transfer(transition_length))
                    
            end do
            
        end if
        
        call initialize_financial_grid(1)

        ! AGAIN AFTER THE GRIDS, as long_run_counter_factual does: both are
        ! read by every state loop of the path and the grid has just been
        ! rebuilt under them.
        call set_newborn_age_transfer(1)
        call set_renter_floor(1)

        if (use_old_transition_results==1) then
                                
            open(unit=1,file="housing_price_in_transition"//trim(old_transition_resuls)//".txt",action='read')
                read(1,'(F15.12)') housing_price(0:transition_length-25)
            close(1)
            
            open(unit=1,file="housing_price"//trim(long_run_simulation)//".dat",action='read')
                read(1,'(F15.12)') housing_price(transition_length)
            close(1)
            
            housing_price(transition_length-25:transition_length-1)=housing_price(transition_length)
            
            open(unit=1,file="rent_in_transition"//trim(old_transition_resuls)//".txt",action='read')
                read(1,'(F15.12)') rent(0:transition_length-25,:)
            close(1)
                        
            open(unit=1,file="rent"//trim(long_run_simulation)//".dat",action='read')
                read(1,'(F15.12)') rent(transition_length,:)
            close(1)
            
!            rent(transition_length-solve_transition_dynamics*25:&
!                transition_length-solve_transition_dynamics*1,:)=rent(transition_length,:)
                        
            open(unit=1,file="lump_sum_transfer_in_transition"//trim(old_transition_resuls)//".txt",action='read')
                read(1,'(F15.12)') lump_sum_transfer(0:transition_length-25)
            close(1)
            
            open(unit=1,file="lump_sum_transfer"//trim(long_run_simulation)//".dat",action='read')
                read(1,'(F15.12)') lump_sum_transfer(transition_length)
            close(1)
            
            lump_sum_transfer(transition_length-25:transition_Length-1)=lump_sum_transfer(transition_length)
                            
            do time_index=1,transition_length
            
                call function_of_utility_advantage_from_homeowning(time_index)
                        
            end do
                                                                    
        end if
               
        write(*,*) "tax_system_type=", tax_system_type
        write(*,*) "computing tranition"
        
        write(*,*) "total_rental_demand"
        
        do time_index=1-solve_transition_dynamics,transition_length
        
!            write(*,*) sum(total_rental_demand(time_index,:))
            
            total_rental_supply(time_index,:)=total_rental_demand(time_index,:)
        
        end do
                
        write(*,*) "total_rental_supply"
        
        do time_index=1-solve_transition_dynamics,transition_length
        
!            write(*,*) sum(total_rental_supply(time_index,:))
        
        end do
        
        write(*,*) "total_housing_demand"
        
        do time_index=1-solve_transition_dynamics,transition_length
        
!            write(*,*) total_housing_demand(time_index)
        
        end do
        
        write(*,*) "housing_stock"
        
        do time_index=1-solve_transition_dynamics,transition_length
        
!            write(*,*) housing_stock(time_index)
        
        end do
        
        write(*,*) "rent"
        
        do time_index=1-solve_transition_dynamics,transition_length
        
            write(*,*) rent(time_index,:)
        
        end do
        
        write(*,*) "house price"
        
        do time_index=1-solve_transition_dynamics,transition_length
        
            write(*,*) housing_price(time_index)
        
        end do
        
        write(*,*) "lump_sum_transfer"
        
        do time_index=1-solve_transition_dynamics,transition_length
        
            write(*,*) lump_sum_transfer(time_index)
        
        end do
                
        ! THE DRUG PRICE PATH'S INITIAL GUESS, ramped like the housing price
        ! and the rent above it: the benchmark's normalised price the instant
        ! before the reform, the terminal steady state's price at T, linear
        ! between. Before this the scalar simply held the terminal price for
        ! every period, so the reform's whole general-equilibrium price effect
        ! landed at t=1 instead of building as drug use fell -- which biases
        ! exactly the early-period welfare the transition exists to measure.
        price_of_addictive_good_path(1-solve_transition_dynamics)=price_of_addictive_good_benchmark
        price_of_addictive_good_path(transition_length)=price_of_addictive_good

        do time_index=1,max(transition_length-1,1)

            price_of_addictive_good_path(time_index)=&
                price_of_addictive_good_benchmark+&
                (price_of_addictive_good-price_of_addictive_good_benchmark)*&
                real(time_index)/real(max(transition_length-1,1))

        end do

        ! AND OVERRIDE THE RAMP WITH A MEASURED PATH WHERE ONE IS SUPPLIED.
        !
        ! THE RAMP WAS THE WRONG SHAPE AND IT COST A WHOLE LOOP TO FIND OUT.
        ! Its first full loop at T=30 walked the FACED price 0.98929 -> 0.83008
        ! while the market's IMPLIED price sat at 0.777 -> 0.807 the entire way,
        ! never once crossing it. distance_drug_market ran 0.19-0.22 against a
        ! stopping rule of 5e-3, in every one of the 29 periods.
        !
        ! That is not slow convergence, it is a seed in the wrong place, and the
        ! half-a-per-cent-a-loop cap on the price means the seed is most of the
        ! answer: from 0.994 to 0.78 is twenty-one per cent, so about forty
        ! loops, and a transition loop is not four minutes like a steady state's
        ! but closer to three hours.
        !
        ! WHAT THE SHAPE ACTUALLY IS. The implied price is nearly FLAT along the
        ! path and sits BELOW the terminal steady state's 0.83349, because drug
        ! quantity along the path (0.342-0.360) is below the terminal steady
        ! state's 0.377 -- the conditionality bites immediately while the
        ! distribution has not yet adjusted. So the price undershoots and
        ! recovers, which is the author's own reading of 19 September: *"It
        ! drops and rises slowly"*. The ramp asserted the opposite.
        !
        ! WHAT IS SEEDED. The file holds the supply curve evaluated at the
        ! previous run's allocation, period by period -- a MEASURED quantity,
        ! not an elasticity and not a shape I chose. The terminal entry is
        ! pinned to the terminal steady state's cleared price, which is the
        ! transition's boundary condition and is not the previous run's to set.
        !
        ! THE JUSTIFICATION THAT USED TO BE HERE WAS WRONG AND IS RETRACTED.
        ! It read: "over a sixteen per cent walk in the faced price the implied
        ! price moved about one per cent, so the map's slope is small and it is
        ! a contraction". That was never measured. It came from comparing
        ! implied prices ACROSS PERIODS within a single loop, which is not a
        ! price experiment at all, and it gave a slope of -0.19. The slope
        ! MEASURED period by period is -2.25 at t=1 falling to about -7.8 by
        ! t=28, so the map is EXPANSIVE and a raw fixed-point step diverges.
        ! Seeding on that false claim took distance from 0.21730 to 0.48885 and
        ! flipped its sign.
        !
        ! What makes a seed safe is not a contraction, it is that the run's own
        ! per-period secant in previous_price_of_addictive_good_path re-measures
        ! the gap from whatever price it is handed. A seed only has to be closer
        ! than the linear ramp, and the ramp is the thing it replaces.
        !
        ! Absent or short file, the ramp stands and the run says so.
        open(unit=97,file='drug_price_path_seed.txt',status='old',action='read',iostat=seed_iostat_1)

        if (seed_iostat_1==0) then

            ! A '#' LINE MUST NOT END THE READ. save_transition_paths.py writes a
            ! provenance header -- which log, which loop, which periods, and for
            ! a spliced path which loop each period came from -- and the list
            ! read that used to be here would have taken the first '#' as a bad
            ! record, exited, and fallen back to the ramp having read ZERO
            ! entries. It says "entries read= 0" when it does that, so it is not
            ! silent, but it is a whole run seeded on nothing for the sake of a
            ! comment line. Blank lines are skipped for the same reason.
            seed_count_1=0

            do

                read(97,'(A)',iostat=seed_iostat_1) seed_line_1

                if (seed_iostat_1/=0) exit

                seed_line_1=adjustl(seed_line_1)

                if (len_trim(seed_line_1)==0) cycle
                if (seed_line_1(1:1)=='#') cycle

                read(seed_line_1,*,iostat=seed_iostat_1) seed_value_1

                if (seed_iostat_1/=0) exit

                seed_count_1=seed_count_1+1

                if (seed_count_1>max(transition_length-1,1)) then

                    seed_count_1=seed_count_1-1
                    exit

                end if

                price_of_addictive_good_path(seed_count_1)=seed_value_1

            end do

            close(97)

            write(*,*) "DRUG PRICE PATH seeded FROM FILE, entries read=", seed_count_1, &
                " of", max(transition_length-1,1)

            if (seed_count_1<max(transition_length-1,1)) then

                write(*,*) "  SHORT FILE. periods", seed_count_1+1, "to", &
                    max(transition_length-1,1), "keep the ramp."

            end if

        else

            write(*,*) "DRUG PRICE PATH: no drug_price_path_seed.txt, using the linear ramp."

        end if

        previous_price_of_addictive_good_path=price_of_addictive_good_path

        ! PI_V's path starts flat at the value the handover supplied, which is
        ! the terminal steady state's. It is an INSTRUMENT, not a schedule, so
        ! the seed sets only how fast the budget clears, not where it clears --
        ! every period's value is driven by its own budget residual below.
        probability_of_voucher_path=probability_of_voucher_benchmark_used

        ! AND THEN THE SAME SEED THE DRUG PRICE GETS, FOR THE SAME REASON.
        !
        ! pi_v is the budget's instrument and it moves slowly: the step is
        ! 0.05 of the residual, clipped to a quarter of the current pi_v per
        ! period per loop, so a path that has walked away from the benchmark
        ! took several loops to get there and a fresh run pays for all of them
        ! again. At five to eight hours a loop at T=60 that is the difference
        ! between a day and a morning.
        !
        ! The flat start above stands when there is no file, which is the
        ! honest default: pi_v's terminal value is the steady state's and every
        ! period's is driven by its OWN residual, so a flat path is a guess
        ! about speed and not about where the budget clears.
        !
        ! NOTE what this file is NOT allowed to be. A pi_v sitting on the 1e-5
        ! floor or the 1.0 ceiling is the collapse the step clip was added to
        ! stop, and as a column of numbers it looks exactly like a converged
        ! path. save_transition_paths.py refuses to WRITE one; this reader
        ! refuses to USE one, because the two halves get separated.
        open(unit=96,file='pi_v_path_seed.txt',status='old',action='read',iostat=seed_iostat_2)

        if (seed_iostat_2==0) then

            seed_count_2=0

            do

                read(96,'(A)',iostat=seed_iostat_2) seed_line_1

                if (seed_iostat_2/=0) exit

                seed_line_1=adjustl(seed_line_1)

                if (len_trim(seed_line_1)==0) cycle
                if (seed_line_1(1:1)=='#') cycle

                read(seed_line_1,*,iostat=seed_iostat_2) seed_value_2

                if (seed_iostat_2/=0) exit

                if ((seed_value_2<=1.000001d0*10.d0**(-5)) .OR. (seed_value_2>=0.999999d0)) then

                    write(*,*) "PI_V PATH SEED REFUSED: entry", seed_count_2+1, &
                        " is", seed_value_2, " which is on a bound. Keeping the flat start."

                    seed_count_2=0
                    exit

                end if

                seed_count_2=seed_count_2+1

                if (seed_count_2>max(transition_length-1,1)) then

                    seed_count_2=seed_count_2-1
                    exit

                end if

                probability_of_voucher_path(seed_count_2)=seed_value_2

            end do

            close(96)

            if (seed_count_2==0) then

                probability_of_voucher_path=probability_of_voucher_benchmark_used

                write(*,*) "PI_V PATH: seed rejected or empty, flat at", &
                    probability_of_voucher_benchmark_used

            else

                write(*,*) "PI_V PATH seeded FROM FILE, entries read=", seed_count_2, &
                    " of", max(transition_length-1,1)

                if (seed_count_2<max(transition_length-1,1)) then

                    write(*,*) "  SHORT FILE. periods", seed_count_2+1, "to", &
                        max(transition_length-1,1), "keep the flat start."

                end if

            end if

        else

            write(*,*) "PI_V PATH: no pi_v_path_seed.txt, flat at", &
                probability_of_voucher_benchmark_used

        end if

        ! THE OTHER THREE PATHS. Same contract as the two above.
        !
        ! WHY THEY ARE HERE. The housing market, the rental market and the
        ! government budget are cleared period by period exactly as the drug
        ! market is -- housing_price(t), rent(t,:) and lump_sum_transfer(t) are
        ! updated inside the loop off their own distances -- but their GUESS was
        ! rebuilt on every run from a level and a slope
        ! (house_price_upon_implementation, slope_of_log_rent and the rest). So
        ! a restart inherited the drug price and pi_v a previous run had earned
        ! and threw away its housing and rental clearing, which is three of the
        ! four stopping rules. At four hours a loop that is the expensive half.
        !
        ! These are read AFTER the level-and-slope construction above, so the
        ! ramp is what stands when a file is absent, short or refused, exactly
        ! as it does for the drug price.
        !
        ! THE GUARD IS A POSITIVITY TEST, not a bound test. A house price or a
        ! rent at or below zero is not a slow path, it is a broken one, and as a
        ! column of decimals it reads like any other. The transfer takes no such
        ! test: its sign is economics, not a failure.
        open(unit=94,file='house_price_path_seed.txt',status='old',action='read',iostat=seed_iostat_3)

        if (seed_iostat_3==0) then

            seed_count_3=0

            do

                read(94,'(A)',iostat=seed_iostat_3) seed_line_1
                if (seed_iostat_3/=0) exit
                seed_line_1=adjustl(seed_line_1)
                if (len_trim(seed_line_1)==0) cycle
                if (seed_line_1(1:1)=='#') cycle
                read(seed_line_1,*,iostat=seed_iostat_3) seed_value_3
                if (seed_iostat_3/=0) exit

                if (seed_value_3<=0.d0) then

                    write(*,*) "HOUSE PRICE PATH SEED REFUSED: entry", seed_count_3+1, &
                        " is", seed_value_3, " which is not positive. Keeping the ramp."
                    seed_count_3=0
                    exit

                end if

                seed_count_3=seed_count_3+1
                if (seed_count_3>max(transition_length-1,1)) then
                    seed_count_3=seed_count_3-1
                    exit
                end if

                housing_price(seed_count_3)=seed_value_3

            end do

            close(94)

            write(*,*) "HOUSE PRICE PATH: entries read=", seed_count_3, &
                " of", max(transition_length-1,1)

        else

            write(*,*) "HOUSE PRICE PATH: no seed file, ramp stands."

        end if

        open(unit=94,file='rent_path_seed.txt',status='old',action='read',iostat=seed_iostat_3)

        if (seed_iostat_3==0) then

            seed_count_3=0

            do

                read(94,'(A)',iostat=seed_iostat_3) seed_line_1
                if (seed_iostat_3/=0) exit
                seed_line_1=adjustl(seed_line_1)
                if (len_trim(seed_line_1)==0) cycle
                if (seed_line_1(1:1)=='#') cycle
                read(seed_line_1,*,iostat=seed_iostat_3) seed_value_3
                if (seed_iostat_3/=0) exit

                if (seed_value_3<=0.d0) then

                    write(*,*) "RENT PATH SEED REFUSED: entry", seed_count_3+1, &
                        " is", seed_value_3, " which is not positive. Keeping the ramp."
                    seed_count_3=0
                    exit

                end if

                seed_count_3=seed_count_3+1
                if (seed_count_3>max(transition_length-1,1)) then
                    seed_count_3=seed_count_3-1
                    exit
                end if

                rent(seed_count_3,0)=seed_value_3

            end do

            close(94)

            write(*,*) "RENT PATH: entries read=", seed_count_3, &
                " of", max(transition_length-1,1)

        else

            write(*,*) "RENT PATH: no seed file, ramp stands."

        end if

        open(unit=94,file='lump_sum_path_seed.txt',status='old',action='read',iostat=seed_iostat_3)

        if (seed_iostat_3==0) then

            seed_count_3=0

            do

                read(94,'(A)',iostat=seed_iostat_3) seed_line_1
                if (seed_iostat_3/=0) exit
                seed_line_1=adjustl(seed_line_1)
                if (len_trim(seed_line_1)==0) cycle
                if (seed_line_1(1:1)=='#') cycle
                read(seed_line_1,*,iostat=seed_iostat_3) seed_value_3
                if (seed_iostat_3/=0) exit

                seed_count_3=seed_count_3+1
                if (seed_count_3>max(transition_length-1,1)) then
                    seed_count_3=seed_count_3-1
                    exit
                end if

                lump_sum_transfer(seed_count_3)=seed_value_3

            end do

            close(94)

            write(*,*) "LUMP SUM PATH: entries read=", seed_count_3, &
                " of", max(transition_length-1,1)

        else

            write(*,*) "LUMP SUM PATH: no seed file, ramp stands."

        end if

        ! A RESUMED RUN'S LOOP 0 IS NOT A COLD START, SO PI_V UPDATES IN IT.
        !
        ! The gate is loop_count>start_updating_at_loop_number with the counter
        ! starting at 0, so pi_v first moves in LOOP 1. That is right for a cold
        ! start: loop 0's quantities come off a seeded path nobody has re-solved,
        ! and moving the fiscal instrument on that budget residual is moving on
        ! noise.
        !
        ! It is WRONG for a resumed run, and 21 September is the proof. loop_count
        ! resets to zero on every restart, so four runs in one day each died or
        ! were stopped at loop_count=1 -- the platform twice, my own maintenance
        ! window once, an OOM once -- and **pi_v never moved a single time**. The
        ! schedule was being restarted, not just the compute.
        !
        ! The author, 21 September: "You need to start moving piv...".
        !
        ! The test is whether the pi_v PATH came from a file. If it did, some
        ! earlier loop earned it and this loop 0 is that loop's successor, so the
        ! instrument should move in it. seed_count_2 is that test and it is
        ! already computed above: >0 only when entries were read AND passed the
        ! bound guard. A cold start leaves it 0 and the old behaviour stands.
        if (seed_count_2>0) then

            start_updating_at_loop_number=-1

            write(*,*) "PI_V GATE: seeded run, pi_v updates from loop 0 &
                &(start_updating_at_loop_number=-1)"

        else

            write(*,*) "PI_V GATE: cold start, pi_v updates from loop 1 &
                &(start_updating_at_loop_number=0)"

        end if

        write(*,*) "DRUG PRICE PATH seeded: t=0", price_of_addictive_good_path(1-solve_transition_dynamics), &
            " t=1", price_of_addictive_good_path(1), &
            " t=T", price_of_addictive_good_path(transition_length)

        largest_housing_market_distance=1
        largest_rental_market_distance=1
        largest_distance_govt_budget=1
        largest_distance_drug_market=1
        
        simulation_ended=0
        
        write(*,*) "average_owner_occupied_house_size_calibrated=", average_owner_occupied_house_size_calibrated
        write(*,*) "calibrated_stationary_housing_price=", calibrated_stationary_housing_price
        write(*,*) "long_run_stationary_housing_price=", long_run_stationary_housing_price
        write(*,*) "rent_calibrated=", rent_calibrated
        write(*,*) "long_run_rent=", long_run_rent
        write(*,*) "model_ss_benefits=", model_ss_benefits
        write(*,*) "net_govt_revenue_constraint=", net_govt_revenue_constraint
        
        write(*,*) "housing_price(1-solve_transition_dynamics)=", housing_price(1-solve_transition_dynamics)
        write(*,*) "housing_price(transition_length)=", housing_price(transition_length)
        write(*,*) "rent(1-solve_transition_dynamics)=", rent(1-solve_transition_dynamics,:)
        write(*,*) "rent(transition_length)=", rent(transition_length,:)
        write(*,*) "total_rental_demand(1-solve_transition_dynamics)=", &
            total_rental_demand(1-solve_transition_dynamics,:) 
        write(*,*) "total_rental_demand(transition_length)=", &
            total_rental_demand(transition_length,:) 
                                                             
        ! THE DRUG MARKET IS NOW ONE OF THE TESTS. The author asked on
        ! 8 September for it to clear in the counterfactuals "and also the
        ! transition when we run it"; long_run_counter_factual was done that
        ! day and this loop was not. Note that housing and rental are the same
        ! VACUOUS series they are in the arms -- identically zero every loop --
        ! so before this line the do-while was testing the government budget
        ! and nothing else.
            ! THE TRANSITION CLEARS TO A LOOSER TOLERANCE THAN A STEADY STATE,
            ! on the author's instruction, 20 September: "the convergence rule
            ! can be less tight than the long run... it doesn't have to be 100
            ! per cent, it can be a bit looser".
            !
            ! THE REASON IS IN THE WORD "largest". Every one of these four
            ! distances is a MAXIMUM OVER ALL PERIODS, so the same numeric
            ! tolerance is a far stricter object here than in a steady state: at
            ! T=30 the drug market's 5e-3 demands that all twenty-nine periods
            ! clear to 5e-3 SIMULTANEOUSLY, where the benchmark asks it of one
            ! economy. The number looks the same and is not.
            !
            ! A factor of two, applied ONLY when solve_transition_dynamics is 1,
            ! so the steady state and the calibration keep exactly the rules the
            ! archive was produced under. At 0 the factor is 1 and this line is
            ! the old line.
            !
            ! WHAT THE TOLERANCE IS REALLY FOR. These distances are a proxy; the
            ! object the transition exists to produce is the welfare path. The
            ! honest test of whether the tolerance is tight enough is whether
            ! average_welfare_with_childhood has stopped moving between loops --
            ! it is printed every loop at every period, so it costs nothing to
            ! watch, and if it is stable to four digits while a distance is
            ! still drifting, the distance is measuring iteration noise.
            do while ((largest_housing_market_distance>&
                transition_tolerance_factor*stopping_rule_housing_market) .OR. &
            (largest_rental_market_distance>&
                transition_tolerance_factor*stopping_rule_rental_market) .OR. &
            (largest_distance_govt_budget>&
                transition_tolerance_factor*stopping_rule_govt_budget) .OR. &
            (largest_distance_drug_market>&
                transition_tolerance_factor*stopping_rule_drug_market) .OR. (loop_count<1))
            
            write(*,*) "solving value functions"
                        
            do time_index=max(transition_length-1,1),1,-1
            
                ! Re-slot the single-slice policy arrays onto this period before
                ! solving into them. A no-op in a steady state.
                call reslot_policies(time_index)

                ! AND RE-POINT THE DRUG PRICE, which is the same idea applied to
                ! a scalar: the household solving at t must face the price at t.
                ! Held at one value for the whole path, as it was, every cohort
                ! priced the terminal economy from the moment of reform.
                price_of_addictive_good=price_of_addictive_good_path(time_index)

                ! AND RE-POINT PI_V, then REBUILD THE LOTTERY FROM IT.
                !
                ! Both scalars are set, not just one: recompute_derived_parameters
                ! assigns _1 from the module value, and in
                ! create_unemployment_process it runs AFTER the voucher block, so
                ! setting only one leaves the result depending on call ordering.
                ! Setting both removes the dependence.
                !
                ! The rebuild is the part that is easy to omit. voucher_probabilities
                ! is what households actually face, and without rebuilding it the
                ! instrument moves and the lottery does not -- which is exactly the
                ! failure the arm's own pi_v update warns about.
                probability_of_voucher_benchmark_used=probability_of_voucher_path(time_index)
                probability_of_voucher_benchmark_used_1=probability_of_voucher_path(time_index)
                call build_voucher_probabilities()

                call solve_value_function_and_policy_functions(time_index)
                
                do i=1,2
                
                    value_function_guess(i)%vector_youngest_real(:,:,:,:,:)=&
                        value_function(i)%vector_transition_real(time_index+1,1,:,:,:,:,:)
                        
                end do
                            
            end do
            
            ! THE DISTRIBUTION AND STATISTICS PASSES ARE ONE LOOP.
            !
            ! They used to be two, which forced distribution_stationary to hold
            ! every period at once -- 5.85 GB for one array. Merging them lets it
            ! keep two slices, and it halves the recomputation below, since the
            ! policies at t are rebuilt once rather than twice.
            ! See code/stylized/TRANSITION_LESSONS.md.
            write(*,*) "computing distributions and statistics"

            net_govt_revenues(1)=net_govt_revenue_constraint
            net_govt_revenues(transition_length)=net_govt_revenue_constraint
            largest_distance_govt_budget=0
            largest_distance_drug_market=0

            do time_index=1,max(transition_length-1,1)

                ! REBUILD THIS PERIOD'S POLICIES. The backward pass threw them
                ! away -- only one slice exists -- but it kept the whole value
                ! function path, and the solver's continuation read is
                ! value_function(min(time_period+solve_transition_dynamics,
                ! transition_length),...), so re-solving at t reproduces exactly
                ! the policies the backward pass computed. Deterministic, not an
                ! approximation.
                call reslot_policies(time_index)

                ! THE SAME PRICE THE BACKWARD PASS USED AT THIS PERIOD, or the
                ! recompute would not reproduce the policies it is supposed to
                ! reproduce and the forward pass would silently be solving a
                ! different economy from the backward one.
                price_of_addictive_good=price_of_addictive_good_path(time_index)

                ! AND RE-POINT PI_V, then REBUILD THE LOTTERY FROM IT.
                !
                ! Both scalars are set, not just one: recompute_derived_parameters
                ! assigns _1 from the module value, and in
                ! create_unemployment_process it runs AFTER the voucher block, so
                ! setting only one leaves the result depending on call ordering.
                ! Setting both removes the dependence.
                !
                ! The rebuild is the part that is easy to omit. voucher_probabilities
                ! is what households actually face, and without rebuilding it the
                ! instrument moves and the lottery does not -- which is exactly the
                ! failure the arm's own pi_v update warns about.
                probability_of_voucher_benchmark_used=probability_of_voucher_path(time_index)
                probability_of_voucher_benchmark_used_1=probability_of_voucher_path(time_index)
                call build_voucher_probabilities()

                call solve_value_function_and_policy_functions(time_index)

                call reslot_distributions(time_index)

                ! PUT THE INITIAL CONDITION BACK. reslot_distributions has just
                ! zeroed slot 0 on every loop after the first, because a rewind
                ! from (T-2:T-1) to (0:1) is not an advance and copies nothing.
                !
                ! At loop 0 this is a no-op by construction: the window is
                ! already (0:1) there, reslot returns before touching anything,
                ! and the keeper holds exactly what is already in the slot. So
                ! the restore cannot change loop 0's answer, which is the
                ! control this fix is checked against.
                if ((time_index==1) .AND. init_keep_done) then

                    do keep_i_1=1,2

                        distribution_guess(keep_i_1)%&
                            vector_transition_real(1-solve_transition_dynamics,:,:,:,:,:,:)=&
                            init_keep_guess(keep_i_1)%vector_real
                        distribution_stationary(keep_i_1)%&
                            vector_transition_real(1-solve_transition_dynamics,:,:,:,:,:,:)=&
                            init_keep_stat(keep_i_1)%vector_real
                        dist_prev_1(keep_i_1)%&
                            vector_transition_real(1-solve_transition_dynamics,:,:,:,:,:,:)=&
                            init_keep_prev1(keep_i_1)%vector_real
                        dist_prev_2(keep_i_1)%&
                            vector_transition_real(1-solve_transition_dynamics,:,:,:,:,:,:)=&
                            init_keep_prev2(keep_i_1)%vector_real

                    end do

                    write(*,*) "TRANSITION INIT RESTORED loop=", loop_count, " mass=",&
                        sum(distribution_guess(1)%vector_transition_real(1-solve_transition_dynamics,:,:,:,:,:,:))+&
                        sum(distribution_guess(2)%vector_transition_real(1-solve_transition_dynamics,:,:,:,:,:,:))

                end if

                call converge_to_stationary_equilibrium(time_index)

                call stationary_equilibrium_statistics(time_index)
                call stationary_equilibirum_homeownership_rate(time_index)
                call calculate_homeownership_by_characteristics(time_index)
                call govt_revenues_calc(time_index)

                ! THE WELFARE PATH, EVERY LOOP, NOT ONLY AFTER CONVERGENCE.
                !
                ! calculate_welfare was called only in the block AFTER the
                ! convergence do-while, so the one number the transition exists
                ! to produce -- what the cohort alive at the reform gets -- was
                ! invisible until the whole run finished, which is days. It is
                ! also the number whose own convergence is worth watching: a
                ! welfare path still moving between loops means the price and
                ! budget paths underneath it have not settled.
                !
                ! HERE IS THE ONLY PLACE IT CAN GO. calculate_welfare(t) reads
                ! policy_function_labor_supply at t, which is WINDOWED to one
                ! slice, so reslot_policies(t) must already have run; it reads
                ! value_function at t, which the backward pass filled; and it
                ! reads distribution_stationary at t-1, which the previous
                ! iteration wrote and which at t=1 is slot 0, the benchmark
                ! distribution the instant before the reform. All three hold at
                ! this line and nowhere earlier.
                !
                ! t=1 IS THE FIRST THING THE FORWARD PASS COMPUTES, so the
                ! implementation cohort's welfare prints minutes after the
                ! backward pass rather than days after convergence.
                !
                ! Called once per period, not once per beta type, matching how
                ! calibrating_model and long_run_counter_factual call it.
                call calculate_welfare(time_index)

                ! AND THE OTHER TWO PER-PERIOD ROUTINES, MOVED HERE FROM THE
                ! BLOCK AFTER THE CONVERGENCE LOOP.
                !
                ! This is what lets distribution_stationary be WINDOWED. Both
                ! read it: calculate_childhood_utility at t-1, and
                ! frac_of_households_in_support_of_policy at t. Left in a
                ! trailing loop over t=1..T-1 they would need every period of it
                ! alive at once, which is 5.7 GB at T=75 and the reason the
                ! array could not be windowed before.
                !
                ! Here each period's distribution is live exactly when it is
                ! read, so a two-slot window suffices -- the same argument that
                ! merged the distribution and statistics passes.
                call calculate_childhood_utility(time_index)
                call frac_of_households_in_support_of_policy(time_index)

                ! THE NUMBER THE CEV IS ACTUALLY COMPUTED ON.
                !
                ! average_welfare_of_youngest_cohort is the value function at
                ! age 1 -- ADULT life only. On the converged Treatment First
                ! arm that measure carries just 0.51 of the 3.25 per cent CEV;
                ! the other 2.74 lives in CHILDHOOD, which it does not contain.
                ! Reporting the transition on it alone answers a narrower
                ! question than the one asked, and invites comparing it against
                ! a steady-state CEV measured on a different object.
                !
                ! average_welfare_with_childhood is childhood flow plus
                ! beta^25 times that adult value, and it is what
                ! calculate_welfare_gains interpolates the benchmark's saved
                ! curve against. calculate_childhood_utility has just filled it
                ! for this period.
                !
                ! type_1 must be 1: only the whole cohort's curve is saved, and
                ! the routine stops on anything else. time_period is declared
                ! but unused inside it, so the period index is passed for
                ! readability only.
                ! PRINT FIRST, THEN THE CEV. calculate_welfare_gains STOPS the
                ! program when the target is off the saved curve, so placed
                ! ahead of the print it kills the run without ever saying what
                ! the numbers were. MEASURED, 20 September: an 85 minute run
                ! ended on "target welfare is off the saved curve ... target=
                ! 0.000" having printed no welfare line at all, so the zero
                ! itself could not be diagnosed. A routine that can stop must
                ! never sit in front of the diagnostic that would explain it.
                !
                ! The two diagnostics are here to separate the candidates for
                ! that zero in ONE run rather than three:
                !   current_beta_type -- average_welfare_with_childhood is
                !     assigned only under current_beta_type==number_of_beta_types,
                !     so a call site where that does not hold leaves it at zero;
                !   the mass at t-1 -- calculate_childhood_utility skips on
                !     mass_1<=0, so an empty distribution_stationary slot gives
                !     zero too, and that slot is what the windowing touched.
                write(*,*) "TRANSITION WELFARE loop=", loop_count, " t=", time_index, &
                    " with_childhood=", average_welfare_with_childhood(time_index), &
                    " youngest=", average_welfare_of_youngest_cohort(time_index), &
                    " benchmark_youngest=", average_welfare_of_youngest_cohort_calibrated

                ! THE THREE MOMENTS THE WELFARE PATH HAS TO BE ATTRIBUTED TO.
                !
                ! They were computed every period and never printed, so the
                ! first loop's welfare path arrived with no way to say whether
                ! a fall came from homelessness, from continued use, or from
                ! the price -- and the author's question on 19 September was
                ! exactly that. Reconstructing h from mass_homeless over
                ! mass_all works but is a different base from the h_1 the
                ! calibration targets, so the two cannot be compared directly.
                ! These are the calibration's own three, on its own bases.
                write(*,*) "TRANSITION MECH t=", time_index, &
                    " h_1=", model_fraction_homeless(time_index), &
                    " b=", model_total_drug_users(time_index), &
                    " lambda_d=", model_fraction_addicted(time_index), &
                    " p_drug=", price_of_addictive_good_path(time_index), &
                    " pi_v=", probability_of_voucher_path(time_index)

                write(*,*) "TRANSITION WELFARE DIAG t=", time_index, &
                    " current_beta_type=", current_beta_type, &
                    " number_of_beta_types=", number_of_beta_types, &
                    " mass at t-1=", &
                    sum(distribution_stationary(1)%vector_transition_real(time_index-solve_transition_dynamics,:,:,:,:,:,:))+&
                    sum(distribution_stationary(2)%vector_transition_real(time_index-solve_transition_dynamics,:,:,:,:,:,:))

                ! GUARDED. Off the curve it reports rather than halting, so one
                ! bad period cannot destroy a run that has spent an hour and a
                ! half getting there.
                cev_this_period=0

                ! THE CURVE IS LOADED INSIDE calculate_welfare_gains, at its own
                ! open of welfare_curve<vf_simulation>.dat, so testing
                ! welfare_curve_w before the first call reads module arrays still
                ! at their declared zero -- which is why the diagnostic reported
                ! "curve spans 0.0 to 0.0". The curve was never broken; the guard
                ! was looking too early.
                !
                ! Require a positive target always, and apply the band test only
                ! once the curve has actually been read.
                if ((average_welfare_with_childhood(time_index)>0.d0) .AND. &
                    ((welfare_curve_w(welfare_curve_points)<=0.d0) .OR. &
                     ((average_welfare_with_childhood(time_index)>welfare_curve_w(1)) .AND. &
                      (average_welfare_with_childhood(time_index)<welfare_curve_w(welfare_curve_points))))) then

                    call calculate_welfare_gains(time_index,average_welfare_with_childhood(time_index),1,cev_this_period)

                    write(*,*) "TRANSITION CEV t=", time_index, " CEV=", cev_this_period

                else

                    write(*,*) "TRANSITION CEV t=", time_index, " OFF THE CURVE, not computed. target=", &
                        average_welfare_with_childhood(time_index), " curve spans", welfare_curve_w(1), &
                        welfare_curve_w(welfare_curve_points)

                end if

                ! CLEAR THE DRUG MARKET AT THIS PERIOD.
                !
                ! LAST in the period, deliberately: clear_drug_market OVERWRITES
                ! the scalar, so anything after it in this period would be
                ! reading next loop's price against this loop's allocation. The
                ! update lands in the path and takes effect when the backward
                ! pass re-points from it next loop, which is the same lag every
                ! other price in this loop already has.
                !
                ! The previous price is carried per period, not as one scalar,
                ! so the secant inside clear_drug_market compares this period
                ! across LOOPS rather than across periods within a loop.
                previous_price_of_addictive_good=previous_price_of_addictive_good_path(time_index)
                previous_drug_price_gap=previous_drug_price_gap_path(time_index)
                have_drug_price_secant=have_drug_price_secant_path(time_index)

                call clear_drug_market(time_index)

                previous_price_of_addictive_good_path(time_index)=previous_price_of_addictive_good
                previous_drug_price_gap_path(time_index)=previous_drug_price_gap
                have_drug_price_secant_path(time_index)=have_drug_price_secant
                price_of_addictive_good_path(time_index)=price_of_addictive_good

                if (distance_drug_market>largest_distance_drug_market) then

                    largest_distance_drug_market=distance_drug_market

                end if
                            
!                write(*,*) "time_index=", time_index
!                write(*,*) "homeownership_rate=", model_homeownership_rate(time_index)
!                write(*,*) "net_govt_revenues=", net_govt_revenues(time_index)
!                write(*,*) "govt_revenues_from_consumption=", govt_revenues_from_consumption(time_index)
!                write(*,*) "govt_revenues_from_property_tax=", govt_revenues_from_property_tax(time_index)
!                write(*,*) "govt_revenues_from_labour_income=", govt_revenues_from_labour_income(time_index)
!                write(*,*) "govt_spending_on_ss=", govt_spending_on_ss(time_index)
                
                ! MEASURE THE BUDGET EVERY LOOP, INCLUDING LOOP 0.
                !
                ! THE DIAGNOSTIC USED TO SHARE THE INSTRUMENT'S GATE, and that
                ! cost a whole 3.5-hour loop. Nothing about the budget was
                ! printed at loop 0 -- not the residual, not the components --
                ! because the only place either appeared was inside
                ! loop_count>start_updating_at_loop_number. So loop 0 ran to
                ! completion looking healthy on the drug market and the welfare
                ! path while net_govt_revenues sat at ZERO against a constraint
                ! of 6.02, and the first anyone knew of it was pi_v slamming
                ! into its floor on the first step of loop 1.
                !
                ! Measure before you move. The residual and its components now
                ! print on every loop; only the UPDATE stays gated.
                ! CHECKPOINT THE TWO INSTRUMENTS EVERY PERIOD, NOT EVERY LOOP.
                !
                ! The paths were written only at a loop boundary, so a kill mid
                ! loop cost the whole loop. Measured 21 September: the platform
                ! recycles this session about once every thirteen hours, and a
                ! loop is 4.7 hours, so a week of running loses about thirty
                ! hours re-walking ground it had already covered. Writing here
                ! costs two files of 44 lines per period -- nothing against a
                ! 171-second period -- and cuts a kill's cost to one period.
                !
                ! The file therefore holds a MIXED path while a loop is in
                ! flight: periods 1..time_index from this loop, the rest from
                ! the last one. That is exactly what a restart wants, and it is
                ! what the header records so nobody has to guess.
                open(unit=93,file='drug_price_path_seed_out.txt',action='write',status='replace')
                    write(93,*) "# price_of_addictive_good_path, loop", loop_count, &
                        " through period", time_index, "of", max(transition_length-1,1)
                    write(93,*) "# periods after that one are from the previous loop"
                    do keep_i_1=1,max(transition_length-1,1)
                        write(93,'(F30.15)') price_of_addictive_good_path(keep_i_1)
                    end do
                close(93)

                open(unit=93,file='pi_v_path_seed_out.txt',action='write',status='replace')
                    write(93,*) "# probability_of_voucher_path, loop", loop_count, &
                        " through period", time_index, "of", max(transition_length-1,1)
                    write(93,*) "# periods after that one are from the previous loop"
                    do keep_i_1=1,max(transition_length-1,1)
                        write(93,'(F30.15)') probability_of_voucher_path(keep_i_1)
                    end do
                close(93)

                write(*,*) "TRANSITION BUDGET loop=", loop_count, " t=", time_index, &
                    " net_govt_revenues=", net_govt_revenues(time_index), &
                    " constraint=", net_govt_revenue_constraint, &
                    " residual=", net_govt_revenues(time_index)-net_govt_revenue_constraint
                write(*,*) "TRANSITION BUDGET PARTS t=", time_index, &
                    " labour=", govt_revenues_from_labour_income(time_index), &
                    " consumption=", govt_revenues_from_consumption(time_index), &
                    " investment=", govt_revenues_from_investment_income(time_index), &
                    " property=", govt_revenues_from_property_tax(time_index), &
                    " lump_sum=", govt_lump_sum_transfers(time_index), &
                    " total_rev=", total_govt_revenues(time_index)
                write(*,*) "TRANSITION BUDGET SPEND t=", time_index, &
                    " ss=", govt_spending_on_ss(time_index), &
                    " ui=", govt_spending_on_ui(time_index), &
                    " di=", govt_spending_on_di(time_index), &
                    " homeless=", govt_spending_on_homeless(time_index), &
                    " addicts=", govt_spending_on_addicts(time_index), &
                    " food=", govt_spending_on_food_stamps(time_index), &
                    " vouchers=", govt_spending_on_housing_vouchers(time_index), &
                    " vouchers_2=", govt_spending_on_housing_vouchers_2(time_index), &
                    " tests=", govt_spending_on_drug_tests, &
                    " bequests=", model_bequests(time_index), &
                    " inheritance=", model_total_inheritance(time_index)

                ! THE RECOVERY CONTRAST, EVERY PERIOD. The author, 22 September:
                ! "all we need is to see what happens to those whose voucher is
                ! revoked and have SUD...do they recover more or less?" All four
                ! quantities were computed on every period of every transition
                ! and printed on none of them, so the question could not be
                ! answered from the output at all.
                !
                ! HERE AND NOT BESIDE THE BETTER OFF LINE. govt_revenues_calc
                ! divides both hazards by their own SUD masses, and it is called
                ! at time_index earlier in this same pass. Printed before that
                ! divide these are unnormalised accumulators, not hazards.
                !
                ! LEVELS, NOT ONLY THE RATIO. 1.2405 in the unconditional arm
                ! against 1.0422 under conditionality is consistent with the
                ! homeless hazard RISING or the housed one FALLING, and the
                ! ratio alone cannot separate the two. The masses are printed
                ! because the housed-with-SUD group is a leftover under
                ! conditionality and its composition is what makes the ratio
                ! hard to read.
                write(*,*) "TRANSITION RECOVERY t=", time_index, &
                    " recovery_housed=", model_recovery_housed(time_index), &
                    " recovery_homeless=", model_recovery_homeless(time_index), &
                    " sud_mass_housed=", model_sud_mass_housed(time_index), &
                    " sud_mass_homeless=", model_sud_mass_homeless(time_index), &
                    " ratio=", model_recovery_housed(time_index)/ &
                        max(model_recovery_homeless(time_index),10.d0**(-12))

                ! AND THE FAST MARGIN, which is the one the trial can see. One
                ! model period is ONE YEAR -- model age 1 is data age 26 -- so
                ! Milby's 24 weeks is 0.46 of a period and his whole trial fits
                ! inside t=1, where lambda_d is +0.00 per cent by construction
                ! because it is the inherited stock. The stock cannot answer him.
                !
                ! Treatment take up can. A household can enter treatment in the
                ! period the voucher is revoked, and "in treatment" is the
                ! model's nearest state to abstinent-but-still-disordered, which
                ! is what a longest-clean-run-in-24-weeks measures. Normalised
                ! by model_mass_with_sud in govt_revenues_calc, above.
                write(*,*) "TRANSITION TREATMENT t=", time_index, &
                    " take_up=", model_treatment_take_up(time_index), &
                    " mass_with_sud=", model_mass_with_sud(time_index)

                ! Raw masses, rates taken downstream. Nothing here is normalised
                ! in govt_revenues_calc, so unlike the recovery hazards these do
                ! not depend on where in the pass they are read.
                write(*,*) "TRANSITION SMIDRUG t=", time_index, &
                    " mass_smi=", xtab_mass_smi(time_index), &
                    " mass_pop=", xtab_mass_pop(time_index), &
                    " sud_smi=", xtab_sud_mass_smi(time_index), &
                    " sud_pop=", xtab_sud_mass_pop(time_index), &
                    " exp_smi=", xtab_exp_mass_smi(time_index), &
                    " exp_pop=", xtab_exp_mass_pop(time_index)

                ! Milby's arms. rec_* are mass-weighted hazard SUMS, so each arm's
                ! average hazard is rec_/mass_ and the arms are comparable only
                ! after that division.
                write(*,*) "TRANSITION MILBY t=", time_index, &
                    " rec_voucher=", xtab_rec_voucher(time_index), &
                    " mass_voucher=", xtab_mass_voucher(time_index), &
                    " rec_housed_nov=", xtab_rec_housed_nov(time_index), &
                    " mass_housed_nov=", xtab_mass_housed_nov(time_index), &
                    " rec_homeless=", model_recovery_homeless(time_index), &
                    " mass_homeless=", model_sud_mass_homeless(time_index)

                ! WHY VOUCHER SPENDING IS EXACTLY ZERO FROM t=2. Three candidates
                ! and this line separates them in one run:
                !
                !   holders=0                 no mass at voucher_index==1, so the
                !                             forward step is losing the state
                !   holders>0, receiving=0    the state survives and the PAYMENT
                !                             is zero -- calculate_housing_voucher_2
                !                             or the rent it is capped by
                !   holders>0, receiving>0    the state and the payment survive and
                !                             the ACCUMULATOR is at fault
                !
                ! The benchmark spends 0.69016 on vouchers and the long-run TF
                ! steady state spends 0.68484 -- the programme is not cheaper under
                ! conditionality, it re-sorts who holds. The transition pays 0.6394
                ! at t=1 and 0.0000000000000000 at t=2, 3 and 4, and the "surplus"
                ! of 0.69 that the budget then reports is, to three digits, the
                ! whole voucher budget. So this is not the reform saving money.
                !
                ! Note that "tests=" above prints a SCALAR, not a path: there is no
                ! (time_index) on govt_spending_on_drug_tests. Its going to zero
                ! after t=1 is this print's artefact and not a second symptom --
                ! though the budget at 20252 subtracts that same scalar, which is
                ! its own question and a small one at 1.2e-3.
                write(*,*) "TRANSITION VOUCHER DIAG t=", time_index, &
                    " holders=", model_eligible_voucher_holders(time_index), &
                    " receiving=", model_fraction_recieving_housing_vouchers(time_index), &
                    " eligibles_getting=", model_eligibles_getting_voucher(time_index), &
                    " drug_tests=", model_drug_tests(time_index), &
                    " pi_v=", probability_of_voucher_path(time_index), &
                    " rent0=", rent(time_index,0)

                ! WHERE THE MASS ACTUALLY SITS, which is the line that separates
                ! the two remaining candidates. model_mass_by_voucher_state is
                ! accumulated at 18384 over the WHOLE distribution with no
                ! mortgage, amortization or voucher gate on it, so unlike
                ! model_eligible_voucher_holders it is a clean census.
                !
                !   all in NONE      the forward step is dumping every household
                !                    into voucher state 0. Suspect the income
                !                    gate in calculate_future_voucher_index, whose
                !                    default when the test fails is first=second=0.
                !   all in EXCLUDED  every holder is being read as category 3,
                !                    "fails the condition", and barred at
                !                    probability_of_detection. Suspect
                !                    voucher_index_1, which is the CATEGORY index
                !                    in voucher_probabilities(...,voucher_index_1)
                !                    and not a voucher state despite the name.
                !
                ! At t=1 holders=0.2744 and at t=2 holders, receiving,
                ! eligibles_getting and drug_tests are all exactly zero, so the
                ! state is gone rather than unpaid. This says where it went.
                write(*,*) "TRANSITION VOUCHER CENSUS t=", time_index, &
                    " none=", model_mass_by_voucher_state(0), &
                    " holding=", model_mass_by_voucher_state(1), &
                    " excluded=", model_mass_by_voucher_state(2), &
                    " total=", model_mass_by_voucher_state(0)+&
                        model_mass_by_voucher_state(1)+model_mass_by_voucher_state(2)

                write(*,*) "TRANSITION AMORT DIAG t=", time_index, &
                    " renter_voucher_mass_by_amort_used: 0=", diag_amort_mass(0), &
                    " 1=", diag_amort_mass(1), " 2=", diag_amort_mass(2), &
                    " 3plus=", diag_amort_mass(3)

                ! THE FAIR-MARKET-RENT STANDARD, which is the cap the voucher
                ! formula takes a min against:
                !
                !   voucher = min( max(model_average_rent(t)*model_average_rental_unit_size(t)
                !                      - rent_to_income_ratio_vouchers*income, 0),
                !                  max(rent_spending - rent_to_income_ratio_vouchers*income, 0) )
                !
                ! MEASURED at T=30 loop 0: the mass RECEIVING a voucher is flat
                ! (3.0443, 2.9506, 2.8856 at t=1,2,3) while the amount per
                ! recipient falls 56 per cent in one period (0.20800, 0.09094,
                ! 0.08781). A common cap collapsing is the only thing that
                ! halves everyone at once while zeroing nobody -- household
                ! behaviour would zero people out, not scale them.
                !
                ! Backing the standard out of those numbers gives about 0.304 at
                ! t=1 against 0.189 at t=2, a 38 per cent drop, where the
                ! benchmark's own is about 0.311. Both components are path
                ! arrays zeroed at 16222-16223 and accumulated at 16456-16459 in
                ! stationary_equilibrium_statistics -- the SAME routine whose
                ! unguarded division produced tonight's NaN, and the same
                ! product that feeds median_income at 15655. This prints them
                ! rather than inferring them.
                write(*,*) "TRANSITION FMR STANDARD t=", time_index, &
                    " avg_rent=", model_average_rent(time_index), &
                    " avg_unit_size=", model_average_rental_unit_size(time_index), &
                    " product=", model_average_rent(time_index)*model_average_rental_unit_size(time_index), &
                    " ratio=", rent_to_income_ratio_vouchers

                write(*,*) "TRANSITION INCOME GATE t=", time_index, &
                    " holder_renter_mass=", diag_inc_mass, &
                    " passing=", diag_inc_pass, &
                    " mean_income_2=", diag_inc_sum/max(diag_inc_mass,10.d0**(-12)), &
                    " mean_income_1=", diag_inc1_sum/max(diag_inc_mass,10.d0**(-12)), &
                    " threshold=", diag_inc_thresh, &
                    " model_eligibles=", model_eligibles(time_index)

                if (loop_count>start_updating_at_loop_number) then
                                                                
                    distance_govt_budget=adjust_taxes*abs(net_govt_revenues(time_index)-net_govt_revenue_constraint)
                        
                    if (distance_govt_budget>largest_distance_govt_budget) then
                    
                        largest_distance_govt_budget=distance_govt_budget
                        
                    end if

                    ! MOVE PI_V AT THIS PERIOD ON THIS PERIOD'S BUDGET RESIDUAL.
                    !
                    ! Until now the residual was measured, its maximum was put in
                    ! the do-while, and NOTHING moved -- a convergence test with no
                    ! instrument behind it. The author's rule, 19 September: pi_v
                    ! is the instrument clearing the budget each period, which is
                    ! also what long_run_counter_factual does, so both ends of the
                    ! transition now use one fiscal rule instead of two.
                    !
                    ! GAIN 0.05, the arm's, and not chosen freshly. Its comment
                    ! records the measurement behind it: at 0.3 the budget
                    ! iteration DIVERGED once an arm moved the economy far enough,
                    ! with dResidual/dpi_v = -16.9 giving a stability bound of
                    ! 2/16.9 = 0.118, and 0.05 giving a multiplier of 0.155. The
                    ! same comment warns the gain was tuned in a region the
                    ! optimal policy arms leave, so it is worth re-measuring along
                    ! a path the way it was re-measured for arm 3 -- pair each
                    ! step with the printed distance that drove it.
                    !
                    ! AND A STEP CLIP, BECAUSE THE GAIN ALONE DID NOT GOVERN.
                    !
                    ! The comment above ends "there is no relative step clip on
                    ! pi_v, so the gain is what governs". That held while the
                    ! residual stayed in the range the gain was measured on --
                    ! the arm's own probe saw -0.09009, +0.36642, -0.53540. The
                    ! transition's FIRST residual was -6.02, more than ten times
                    ! anything the steady state has ever produced, and at gain
                    ! 0.05 that is a step of -0.30 applied to a pi_v of 0.076:
                    ! straight through zero to the floor, in ONE step, in every
                    ! period. The voucher programme was abolished and the run
                    ! was worthless from that instant.
                    !
                    ! A gain tuned on a residual of 0.5 cannot be trusted on a
                    ! residual of 6. The clip caps the move at a QUARTER of the
                    ! current pi_v per period per loop, which leaves the arm's
                    ! measured behaviour untouched -- its largest step was
                    ! 0.11 on a pi_v of 0.15, well inside a quarter -- and turns
                    ! a wild residual into a slow walk instead of a collapse.
                    !
                    ! THIS CHANGES NO EQUILIBRIUM CONDITION. The fixed point is
                    ! still net_govt_revenues == net_govt_revenue_constraint to
                    ! within the stopping rule; only the path to it changes.
                    ! Same argument as the drug price's trust region.
                    ! AND A SECANT, BECAUSE THE GAIN ALONE IS THE CRUDER OF THE
                    ! TWO INSTRUMENTS SITTING SIDE BY SIDE.
                    !
                    ! clear_drug_market measures its slope from two evaluations
                    ! and steps to the root. pi_v did not: it moved on a fixed
                    ! gain of 0.05 with a clip, which is a bisection-speed walk
                    ! on an instrument whose residual at loop 0 is 0.69 -- about
                    ! eleven per cent of the budget, because TF stops paying
                    ! households that fail the condition and the savings are not
                    ! yet recycled. At a quarter of pi_v per loop that is many
                    ! loops, and a loop at T=60 is five to eight hours.
                    !
                    ! The map is as well behaved as the drug price's and for the
                    ! same reason: raising pi_v hands out more vouchers, which
                    ! raises spending, which LOWERS net revenue, so the residual
                    ! is monotone decreasing in pi_v. A secant on a monotone
                    ! residual is the right instrument.
                    !
                    ! STRUCTURE COPIED FROM clear_drug_market, guards included,
                    ! because those guards were paid for. The secant there
                    ! diverged on universal treatment -- 47 loops, the gap
                    ! GROWING through 0.0198, 0.165, 0.346, 0.520 -- when it was
                    ! differencing a quantity that came out of a distribution
                    ! solved only to 6e-4, so it was extrapolating off numerical
                    ! noise. pi_v differences net_govt_revenues, which comes out
                    ! of the same distribution, so it can do the same thing.
                    !
                    !   default          a damped step, the old gain of 0.05
                    !   secant           only with two usable, distinct points
                    !   guard on growth  if the gap GREW the last step was wrong
                    !                    and its secant is worthless: damp
                    !   trust region     never further than four damped steps
                    !   existing clip    a quarter of pi_v, kept, applied LAST
                    !
                    ! THIS CHANGES NO EQUILIBRIUM CONDITION. The fixed point is
                    ! still net_govt_revenues == net_govt_revenue_constraint to
                    ! within the stopping rule; only the path to it changes.
                    pi_v_gap_1=net_govt_revenues(time_index)-net_govt_revenue_constraint

                    pi_v_damped_1=0.05*pi_v_gap_1

                    pi_v_step_1=pi_v_damped_1

                    if ((have_pi_v_secant_path(time_index)==1) .AND. &
                        (abs(pi_v_gap_1-previous_budget_residual_path(time_index))>10.d0**(-10)) .AND. &
                        (abs(probability_of_voucher_path(time_index)-&
                             previous_probability_of_voucher_path(time_index))>10.d0**(-10))) then

                        if (abs(pi_v_gap_1)>abs(previous_budget_residual_path(time_index))) then

                            pi_v_step_1=pi_v_damped_1

                        else

                            pi_v_step_1=-pi_v_gap_1*&
                                (probability_of_voucher_path(time_index)-&
                                 previous_probability_of_voucher_path(time_index))/&
                                (pi_v_gap_1-previous_budget_residual_path(time_index))

                            pi_v_step_1=max(min(pi_v_step_1,4*abs(pi_v_damped_1)),-4*abs(pi_v_damped_1))

                        end if

                    end if

                    ! The clip stays, and stays LAST. It is what stopped the
                    ! collapse: a residual of -6.02 at gain 0.05 is a step of
                    ! -0.30 on a pi_v of 0.076, straight through zero to the
                    ! floor in one step in every period. A secant can produce a
                    ! step just as large, so it is capped by the same rule.
                    pi_v_cap_1=0.25*probability_of_voucher_path(time_index)
                    pi_v_step_1=max(min(pi_v_step_1,pi_v_cap_1),-pi_v_cap_1)

                    ! Carry the point the NEXT loop differences against. Written
                    ! before pi_v moves, so the pair is (pi_v faced, gap it
                    ! produced) rather than a value and someone else's gap --
                    ! and carried PER PERIOD, because a scalar would difference
                    ! this period's gap against the previous PERIOD's, which is
                    ! not a pi_v experiment. That is the same mistake the drug
                    ! price's secant state was fixed for.
                    previous_probability_of_voucher_path(time_index)=&
                        probability_of_voucher_path(time_index)
                    previous_budget_residual_path(time_index)=pi_v_gap_1
                    have_pi_v_secant_path(time_index)=1

                    pi_v_new_1=max(min(probability_of_voucher_path(time_index)+pi_v_step_1,1.d0),10.d0**(-5))

                    probability_of_voucher_path(time_index)=pi_v_new_1

                    write(*,*) "TRANSITION PI_V loop=", loop_count, " t=", time_index, &
                        " pi_v=", probability_of_voucher_path(time_index), &
                        " budget_residual=", pi_v_gap_1, &
                        " step=", pi_v_step_1, " damped=", pi_v_damped_1, &
                        " secant=", have_pi_v_secant_path(time_index)
                    
                end if

            end do
            
            largest_housing_market_distance=0
                        
            do time_index=1,max(transition_length-1,1)
                        
                housing_stock(time_index)=(1-housing_depreciation_rate)*housing_stock(time_index-solve_transition_dynamics)+&
                    (housing_price(time_index)/c_1_calibrated)**(empirical_housing_supplpy_elasticity)
                                            
                distance_housing_market(time_index)=abs(housing_stock(time_index)-total_housing_demand(time_index))
                                        
                if (distance_housing_market(time_index)>&
                    largest_housing_market_distance) then
                
                    largest_housing_market_distance=distance_housing_market(time_index)
                
                end if
                                                                    
            end do
            
            largest_housing_market_distance=0
            distance_housing_market=0
            
            do time_index=1,max(transition_length-1,1)
                                                                            
                distance_housing_market(time_index)=abs(housing_price(time_index)-&
                    (c_1_calibrated)*(max(total_housing_demand(time_index)-&
                    (1-housing_depreciation_rate)*housing_stock(time_index-solve_transition_dynamics),0.d0))**&
                    (1/empirical_housing_supplpy_elasticity))
                                                
                weight_on_housing_price=0.0001
                                         
                if (distance_housing_market(time_index)>largest_housing_market_distance) then
                
                    largest_housing_market_distance=distance_housing_market(time_index)
                
                end if
                
                ! PEGGED ALONG THE PATH TOO, on the author's instruction of
                ! 8 September: "I also want to keep constant the housing price
                ! and rent in a transition computation".
                !
                ! Same reason as in the long-run counterfactual: homeownership
                ! is off, so P prices rental units and nothing else, and a
                ! reform that houses more people would otherwise bid it up
                ! period by period and drag the rent along with it. A transition
                ! whose prices wander is not comparable with the long-run
                ! counterfactual it is supposed to converge to, which is most of
                ! the point of computing one.
                if (peg_prices_in_counterfactual==1) then

                    housing_price(time_index)=calibrated_stationary_housing_price
                    distance_housing_market(time_index)=0
                    largest_housing_market_distance=0

                elseif (loop_count>start_updating_at_loop_number) then

                    housing_price(time_index)=(1-weight_on_housing_price)*&
                        housing_price(time_index)+weight_on_housing_price*&
                        (c_1_calibrated)*(max(total_housing_demand(time_index)-&
                        (1-housing_depreciation_rate)*housing_stock(time_index-solve_transition_dynamics),0.d0))**&
                        (1/empirical_housing_supplpy_elasticity)

                end if
                                
            end do
            
            largest_rental_market_distance=0
            distance_rental_market=0
            
            do time_index=1,max(transition_length-1,1)
            
                rental_market_adjuster=0.005
                                            
                distance_rental_market(time_index)=maxval(abs(total_rental_demand(time_index,:)-&
                    total_rental_supply(time_index,:)))
                    
                if (distance_rental_market(time_index)>largest_rental_market_distance) then
            
                    largest_rental_market_distance=distance_rental_market(time_index)
            
                end if
                                
                ! AND THE RENT, same instruction. rent_calibrated is the
                ! benchmark's p_r, so the path carries the same rental price as
                ! the benchmark and as the long-run counterfactual it converges
                ! to.
                if (peg_prices_in_counterfactual==1) then

                    rent(time_index,:)=rent_calibrated(:)
                    distance_rental_market(time_index)=0
                    largest_rental_market_distance=0

                elseif (loop_count>start_updating_at_loop_number) then

                    rent(time_index,:)=rent(time_index,:)+&
                        rental_market_adjuster*(total_rental_demand(time_index,:)-total_rental_supply(time_index,:))

                end if
                                                     
                call function_of_utility_advantage_from_homeowning(time_index)
                                                  
            end do
            
            alpha_1=1/(1+risk_free_rate(1))
            
            total_profits(1:transition_length-1)=0
            
            write(*,*) "largest_housing_market_distance=", largest_housing_market_distance
            write(*,*) "largest_rental_market_distance=", largest_rental_market_distance
            write(*,*) "largest_distance_govt_budget=", largest_distance_govt_budget
                                            
            open(unit=1,file="housing_price_in_transition"//trim(file_number)//".txt",action="write",status="replace")
                do i=0,transition_length
                    write(1,'(F15.12)') housing_price(i)
                end do
            close(1)
                            
            open(unit=1,file="rent_in_transition"//trim(file_number)//".txt",action="write",status="replace")
                do i=0,transition_length
                    write(1,'(F15.12)') rent(i,:)
                end do
            close(1)
                
            open(unit=1,file="housing_supply_minus_housing_demand_in_transition"&
                //trim(file_number)//".txt",action="write",status="replace")
                do i=0,transition_length
                    write(1,'(F15.12)') housing_stock(i)-total_housing_demand(i)
                end do
            close(1)
            
            open(unit=1,file="housing_supply_transition"//trim(file_number)//".txt",action="write",status="replace")
                write(1,'(F15.12)') housing_stock(1-solve_transition_dynamics:transition_length)
            close(1)
            
            open(unit=1,file="rental_supply_minus_rental_demand_in_transition"&
                //trim(file_number)//".txt",action="write",status="replace")
                do i=0,transition_length
                    if (i==0) then
                        write(1,'(F15.12)') 0.d0
                    elseif ((i>0) .AND. (i<transition_length)) then
                        write(1,'(F15.12)') total_rental_supply(i,:)-total_rental_demand(i,:)
                    else
                        write(1,'(F15.12)') 0.d0
                    end if
                end do
            close(1)
            
            open(unit=3,file="net_govt_rev_in_transition"//trim(file_number)//".txt",action="write",status="replace")
                write(3,'(F15.12)') net_govt_revenues(1:transition_length-1)
            close(3)
                                            
            open(unit=2,file="lump_sum_transfer_in_transition"//trim(file_number)//".txt",action="write",status="replace")
                do i=0,transition_length 
                    write(2,'(F15.12)') lump_sum_transfer(i)
                end do                    
            close(2)
            
            open(unit=2,file="homeownership_in_transition"//trim(file_number)//".txt",action="write",status="replace")
                write(2,'(F10.8)') model_homeownership_rate(1:transition_length-1)
            close(2)
            
            open(unit=2,file="homeownership_1st_period_in_transition"//trim(file_number)//".txt",action="write",status="replace")
                write(2,'(F10.8)') homeownership_by_age(1,:)
            close(2)
            
            open(unit=2,file="homeownership_2nd_period_in_transition"//trim(file_number)//".txt",action="write",status="replace")
                write(2,'(F10.8)') homeownership_by_age(2,:)
            close(2)            
            
            open(unit=2,file="model_average_rental_unit_size_in_transition"&
                //trim(file_number)//".txt",action="write",status="replace")
                write(2,'(F10.8)') model_average_rental_unit_size(1:transition_length-1)
            close(2)
            
            open(unit=2,file="model_average_owner_occupied_unit_size_in_transition"&
                //trim(file_number)//".txt",action="write",status="replace")
                write(2,'(F10.8)') model_average_owner_occupied_unit_size(1:transition_length-1)
            close(2)
            
            open(unit=2,file="total_constrcution_profits_in_transition"//trim(file_number)//&
                ".text",action="write",status="replace")
                write(2,'(F20.15)') total_constrcution_profits
            close(2)
            
            open(unit=2,file="total_rental_company_profits_in_transition"//trim(file_number)//&
                ".text",action="write",status="replace")
                write(2,'(F20.15)') total_rental_company_profits
            close(2)
            
            open(unit=2,file="total_rental_supply_in_transition"//trim(file_number)//".text",action="write",status="replace")
                write(2,'(F20.15)') total_rental_supply
            close(2)
            
            open(unit=2,file="total_rental_demand_in_transition"//trim(file_number)//".text",action="write",status="replace")
                write(2,'(F20.15)') total_rental_demand
            close(2)
            
            open(unit=2,file="total_profits_in_transition"//trim(file_number)//".text",action="write",status="replace")
                write(2,'(F20.15)') total_profits
            close(2)
                                                                          
            open(unit=3,file="distance"//trim(file_number)//".txt",action="write",status="replace")
            
                write(3,*) "loop_count=", loop_count
                write(3,*) "largest_housing_market_distance=",largest_housing_market_distance
                write(3,*) "largest_rental_market_distance=", largest_rental_market_distance
                write(3,*) "largest_distance_govt_budget=", largest_distance_govt_budget
                write(3,*) "tax_system_type=", tax_system_type
                                
            close(3)
                            
            ! SAVE THE INSTRUMENT PATHS EVERY LOOP.
            !
            ! The two paths the transition iterates per period are the drug
            ! price and pi_v. Until now neither survived the run that produced
            ! it: the T=30 secant roots had to be reconstructed out of a log by
            ! hand, and run directories are gitignored, so a container that died
            ! took the path with it. Writing them every loop means a kill costs
            ! the loop in progress rather than the whole run.
            !
            ! WRITTEN TO *_out.txt, NOT OVER THE SEED FILES THIS RUN READ.
            ! Overwriting the input would make a restart inherit this run's last
            ! loop automatically, which is what you want when the loop was good
            ! and a catastrophe when it was not -- t30_loop1_pivcollapse is the
            ! case: pi_v through zero to its floor in one step in every period,
            ! h_1 at NaN, and as a file 29 plausible decimals. Promoting an
            ! _out file to a seed is therefore a deliberate copy, and
            ! save_transition_paths.py's guards are what it should be read with.
            !
            ! h_1 is written for the same loop and IS NOT AN INSTRUMENT. Nothing
            ! reads it back; homelessness is an outcome of the distribution and
            ! has no slot to be put into. It is here to score a restart against.
            open(unit=95,file='drug_price_path_seed_out.txt',action='write',status='replace')

                write(95,*) "# price_of_addictive_good_path after loop", loop_count
                write(95,*) "# the price FACED, not a step onto the measured gap"
                write(95,*) "# periods 1 to", max(transition_length-1,1)

                do time_index=1,max(transition_length-1,1)

                    write(95,'(F30.15)') price_of_addictive_good_path(time_index)

                end do

            close(95)

            open(unit=95,file='pi_v_path_seed_out.txt',action='write',status='replace')

                write(95,*) "# probability_of_voucher_path after loop", loop_count
                write(95,*) "# periods 1 to", max(transition_length-1,1)

                do time_index=1,max(transition_length-1,1)

                    write(95,'(F30.15)') probability_of_voucher_path(time_index)

                end do

            close(95)

            open(unit=95,file='h1_path_reference_out.txt',action='write',status='replace')

                write(95,*) "# model_fraction_homeless after loop", loop_count
                write(95,*) "# A REFERENCE, NOT AN INPUT. Nothing reads this back."
                write(95,*) "# periods 1 to", max(transition_length-1,1)

                do time_index=1,max(transition_length-1,1)

                    write(95,'(F30.15)') model_fraction_homeless(time_index)

                end do

            close(95)

            ! AND THE THREE THAT CLEAR THE OTHER MARKETS.
            !
            ! housing_price, rent and lump_sum_transfer are iterated per period
            ! exactly as the two above are, and three of the four stopping rules
            ! are theirs. Saving only the drug price and pi_v meant a restart
            ! re-earned the housing and rental clearing from a level-and-slope
            ! ramp every time, which is most of what a loop buys.
            open(unit=95,file='house_price_path_seed_out.txt',action='write',status='replace')

                write(95,*) "# housing_price after loop", loop_count
                write(95,*) "# periods 1 to", max(transition_length-1,1)

                do time_index=1,max(transition_length-1,1)

                    write(95,'(F30.15)') housing_price(time_index)

                end do

            close(95)

            open(unit=95,file='rent_path_seed_out.txt',action='write',status='replace')

                write(95,*) "# rent(:,0) after loop", loop_count
                write(95,*) "# periods 1 to", max(transition_length-1,1)

                do time_index=1,max(transition_length-1,1)

                    write(95,'(F30.15)') rent(time_index,0)

                end do

            close(95)

            open(unit=95,file='lump_sum_path_seed_out.txt',action='write',status='replace')

                write(95,*) "# lump_sum_transfer after loop", loop_count
                write(95,*) "# periods 1 to", max(transition_length-1,1)

                do time_index=1,max(transition_length-1,1)

                    write(95,'(F30.15)') lump_sum_transfer(time_index)

                end do

            close(95)

            write(*,*) "TRANSITION PATHS SAVED after loop", loop_count, &
                " periods=", max(transition_length-1,1)

            loop_count=loop_count+1
            
            write(*,*) "loop_count=", loop_count

            ! A DISTANCE THAT IS NOT A NUMBER MUST NOT READ AS CONVERGED.
            !
            ! Every stopping test in the sweep is of the form distance > rule,
            ! and NaN > anything is FALSE in Fortran, so a moment that came back
            ! 0/0 silently satisfies its own convergence test and takes the sweep
            ! with it. That is not hypothetical: the discount factor was driven
            ! by a mortgage share that is 0/0 once ownership is off, and the
            ! sweep read the resulting NaN as a parameter that had converged
            ! while the parameter itself had been set to zero. The employment
            ! penalty for a disorder did the same thing through an employment
            ! rate of the homeless computed on an empty set.
            !
            ! Forcing a NaN distance to one keeps the sweep open and puts the
            ! name of the offending moment in the log, which is the difference
            ! between a wrong answer and a visible failure. It is deliberately
            ! placed here, after every update block, so it catches whatever the
            ! moment came from rather than each site having to guard itself.
            if (distance_addiction_scalar .NE. distance_addiction_scalar) then
                write(*,*) "NaN DISTANCE: distance_addiction_scalar, forced to 1 so the sweep cannot mistake it for convergence"
                distance_addiction_scalar=1
            end if
            if (distance_advantage_to_owning .NE. distance_advantage_to_owning) then
                write(*,*) "NaN DISTANCE: distance_advantage_to_owning, forced to 1 so the sweep cannot mistake it for convergence"
                distance_advantage_to_owning=1
            end if
            if (distance_average_labor_income .NE. distance_average_labor_income) then
                write(*,*) "NaN DISTANCE: distance_average_labor_income, forced to 1 so the sweep cannot mistake it for convergence"
                distance_average_labor_income=1
            end if
            if (distance_average_net_wealth .NE. distance_average_net_wealth) then
                write(*,*) "NaN DISTANCE: distance_average_net_wealth, forced to 1 so the sweep cannot mistake it for convergence"
                distance_average_net_wealth=1
            end if
            if (distance_convexity_of_rental_company .NE. distance_convexity_of_rental_company) then
                write(*,*) "NaN DISTANCE: distance_convexity_of_rental_company, forced to 1 so the sweep cannot mistake it for convergence"
                distance_convexity_of_rental_company=1
            end if
            if (distance_discount_factor .NE. distance_discount_factor) then
                write(*,*) "NaN DISTANCE: distance_discount_factor, forced to 1 so the sweep cannot mistake it for convergence"
                distance_discount_factor=1
            end if
            if (distance_discount_factor_on_child .NE. distance_discount_factor_on_child) then
                write(*,*) "NaN DISTANCE: distance_discount_factor_on_child, forced to 1 so the sweep cannot mistake it for convergence"
                distance_discount_factor_on_child=1
            end if
            if (distance_drug_market .NE. distance_drug_market) then
                write(*,*) "NaN DISTANCE: distance_drug_market, forced to 1 so the sweep cannot mistake it for convergence"
                distance_drug_market=1
            end if
            if (distance_drug_threshold .NE. distance_drug_threshold) then
                write(*,*) "NaN DISTANCE: distance_drug_threshold, forced to 1 so the sweep cannot mistake it for convergence"
                distance_drug_threshold=1
            end if
            if (distance_employment_multiplier .NE. distance_employment_multiplier) then
                write(*,*) "NaN DISTANCE: distance_employment_multiplier, forced to 1 so the sweep cannot mistake it for convergence"
                distance_employment_multiplier=1
            end if
            if (distance_fixed_cost_to_moving .NE. distance_fixed_cost_to_moving) then
                write(*,*) "NaN DISTANCE: distance_fixed_cost_to_moving, forced to 1 so the sweep cannot mistake it for convergence"
                distance_fixed_cost_to_moving=1
            end if
            if (distance_housing_status_grid_expander .NE. distance_housing_status_grid_expander) then
                write(*,*) "NaN DISTANCE: distance_housing_status_grid_expander, forced to 1 so the sweep cannot mistake it for convergence"
                distance_housing_status_grid_expander=1
            end if
            if (distance_inheritance_amount .NE. distance_inheritance_amount) then
                write(*,*) "NaN DISTANCE: distance_inheritance_amount, forced to 1 so the sweep cannot mistake it for convergence"
                distance_inheritance_amount=1
            end if
            if (distance_kappa_find_smi .NE. distance_kappa_find_smi) then
                write(*,*) "NaN DISTANCE: distance_kappa_find_smi, forced to 1 so the sweep cannot mistake it for convergence"
                distance_kappa_find_smi=1
            end if
            if (distance_b_smi_multiple .NE. distance_b_smi_multiple) then
                write(*,*) "NaN DISTANCE: distance_b_smi_multiple, forced to 1 so the sweep cannot mistake it for convergence"
                distance_b_smi_multiple=1
            end if

            if (distance_kappa_uem .NE. distance_kappa_uem) then
                write(*,*) "NaN DISTANCE: distance_kappa_uem, forced to 1 so the sweep cannot mistake it for convergence"
                distance_kappa_uem=1
            end if
            if (distance_lambda_addiction .NE. distance_lambda_addiction) then
                write(*,*) "NaN DISTANCE: distance_lambda_addiction, forced to 1 so the sweep cannot mistake it for convergence"
                distance_lambda_addiction=1
            end if
            if (distance_lambda_m .NE. distance_lambda_m) then
                write(*,*) "NaN DISTANCE: distance_lambda_m, forced to 1 so the sweep cannot mistake it for convergence"
                distance_lambda_m=1
            end if
            if (distance_largest_house_size .NE. distance_largest_house_size) then
                write(*,*) "NaN DISTANCE: distance_largest_house_size, forced to 1 so the sweep cannot mistake it for convergence"
                distance_largest_house_size=1
            end if
            if (distance_max_food_cost .NE. distance_max_food_cost) then
                write(*,*) "NaN DISTANCE: distance_max_food_cost, forced to 1 so the sweep cannot mistake it for convergence"
                distance_max_food_cost=1
            end if
            if (distance_median_income .NE. distance_median_income) then
                write(*,*) "NaN DISTANCE: distance_median_income, forced to 1 so the sweep cannot mistake it for convergence"
                distance_median_income=1
            end if
            if (distance_minimum_inheritance .NE. distance_minimum_inheritance) then
                write(*,*) "NaN DISTANCE: distance_minimum_inheritance, forced to 1 so the sweep cannot mistake it for convergence"
                distance_minimum_inheritance=1
            end if
            if (distance_mu_homeless .NE. distance_mu_homeless) then
                write(*,*) "NaN DISTANCE: distance_mu_homeless, forced to 1 so the sweep cannot mistake it for convergence"
                distance_mu_homeless=1
            end if
            if (distance_probability_of_becoming_addicted .NE. distance_probability_of_becoming_addicted) then
                write(*,*) "NaN DISTANCE: distance_probability_of_becoming_addicted, forced to 1 so the sweep cannot mistake it for convergence"
                distance_probability_of_becoming_addicted=1
            end if
            if (distance_relative_share_of_addiction_1 .NE. distance_relative_share_of_addiction_1) then
                write(*,*) "NaN DISTANCE: distance_relative_share_of_addiction_1, forced to 1 so the sweep cannot mistake it for convergence"
                distance_relative_share_of_addiction_1=1
            end if
            if (distance_relative_share_of_housing .NE. distance_relative_share_of_housing) then
                write(*,*) "NaN DISTANCE: distance_relative_share_of_housing, forced to 1 so the sweep cannot mistake it for convergence"
                distance_relative_share_of_housing=1
            end if
            if (distance_relative_share_of_leisure .NE. distance_relative_share_of_leisure) then
                write(*,*) "NaN DISTANCE: distance_relative_share_of_leisure, forced to 1 so the sweep cannot mistake it for convergence"
                distance_relative_share_of_leisure=1
            end if
            if (distance_rent_to_price .NE. distance_rent_to_price) then
                write(*,*) "NaN DISTANCE: distance_rent_to_price, forced to 1 so the sweep cannot mistake it for convergence"
                distance_rent_to_price=1
            end if
            if (distance_rho_d .NE. distance_rho_d) then
                write(*,*) "NaN DISTANCE: distance_rho_d, forced to 1 so the sweep cannot mistake it for convergence"
                distance_rho_d=1
            end if
            if (distance_rho_m .NE. distance_rho_m) then
                write(*,*) "NaN DISTANCE: distance_rho_m, forced to 1 so the sweep cannot mistake it for convergence"
                distance_rho_m=1
            end if
            if (distance_separation_rate .NE. distance_separation_rate) then
                write(*,*) "NaN DISTANCE: distance_separation_rate, forced to 1 so the sweep cannot mistake it for convergence"
                distance_separation_rate=1
            end if
            if (distance_size_homelessness .NE. distance_size_homelessness) then
                write(*,*) "NaN DISTANCE: distance_size_homelessness, forced to 1 so the sweep cannot mistake it for convergence"
                distance_size_homelessness=1
            end if
            if (distance_smallest_house_size .NE. distance_smallest_house_size) then
                write(*,*) "NaN DISTANCE: distance_smallest_house_size, forced to 1 so the sweep cannot mistake it for convergence"
                distance_smallest_house_size=1
            end if
            if (distance_standard_deduction .NE. distance_standard_deduction) then
                write(*,*) "NaN DISTANCE: distance_standard_deduction, forced to 1 so the sweep cannot mistake it for convergence"
                distance_standard_deduction=1
            end if
            if (distance_utility_cost_of_treatment .NE. distance_utility_cost_of_treatment) then
                write(*,*) "NaN DISTANCE: distance_utility_cost_of_treatment, forced to 1 so the sweep cannot mistake it for convergence"
                distance_utility_cost_of_treatment=1
            end if
            if (distance_value_of_life .NE. distance_value_of_life) then
                write(*,*) "NaN DISTANCE: distance_value_of_life, forced to 1 so the sweep cannot mistake it for convergence"
                distance_value_of_life=1
            end if
            if (distance_voucher_probability .NE. distance_voucher_probability) then
                write(*,*) "NaN DISTANCE: distance_voucher_probability, forced to 1 so the sweep cannot mistake it for convergence"
                distance_voucher_probability=1
            end if
            if (distance_weight_on_child .NE. distance_weight_on_child) then
                write(*,*) "NaN DISTANCE: distance_weight_on_child, forced to 1 so the sweep cannot mistake it for convergence"
                distance_weight_on_child=1
            end if
            if (distance_penalty_child_addicted .NE. distance_penalty_child_addicted) then
                write(*,*) "NaN DISTANCE: distance_penalty_child_addicted, forced to 1 so the sweep cannot mistake it for convergence"
                distance_penalty_child_addicted=1
            end if
            if (distance_sd_permanent_productivity .NE. distance_sd_permanent_productivity) then
                write(*,*) "NaN DISTANCE: distance_sd_permanent_productivity, forced to 1 so the sweep cannot mistake it for convergence"
                distance_sd_permanent_productivity=1
            end if

            if (distance_labor_income_tax_rate .NE. distance_labor_income_tax_rate) then
                write(*,*) "NaN DISTANCE: distance_labor_income_tax_rate, forced to 1 so the sweep cannot mistake it for convergence"
                distance_labor_income_tax_rate=1
            end if
            ! WHICH TERMS ARE STILL HOLDING THE LOOP OPEN. See
            ! report_convergence_terms: print only, and the one place a held
            ! parameter's distance is visible.
            call report_convergence_terms()

            ! Everything the update block moved this loop, on disk before the
            ! next one starts.
            call write_calibration_state()

            ! One complete backward induction has now filled the policy, so the
            ! next loop can search around it. A resumed run starts cold, which
            ! is correct: the array is not on disk and a stale one would be
            ! worse than none.
            if (warm_start_asset_search==1) then

                warm_start_ready=1

            end if

            ! THE TRAILING PER-PERIOD LOOP IS GONE. All three routines now
            ! run inside the forward pass, where each period's distribution is
            ! live as it is read. Keeping them here would hold
            ! distribution_stationary open across the whole path and defeat the
            ! windowing. The series they fill are small time-vectors and survive
            ! the loop, so the write below is unchanged.
            
            open(unit=1,file="welfare_in_transition_youngest"//trim(file_number)//".txt",action="write",status="replace")
                write(1,'(F19.12)') average_welfare_of_youngest_cohort(1:transition_length-1)
            close(1)
            
            open(unit=1,file="welfare_in_transition_everyone"//trim(file_number)//".txt",action="write",status="replace")
                write(1,'(F19.12)') average_welfare_of_all_cohorts(1:transition_length-1)
            close(1)
            
            open(unit=2,file="support_in_transition"//trim(file_number)//".txt",action="write",status="replace")
                write(2,'(F14.12)') frac_in_support(1:transition_length-1)
            close(2)
                        
        end do
        
        simulation_ended=2
        
    end subroutine